/// Idempotent statements replayed after the incremental column additions:
/// sync-state index group, session tab id index, `browser_sync_cursors`
/// creation, and the schema version stamp. Every statement is guarded with
/// `IF NOT EXISTS` / `OR REPLACE`, so platforms execute them unconditionally
/// on every open without further introspection.
const BROWSER_STORAGE_SCHEMA_MIGRATION_IDEMPOTENT_STATEMENTS: &[&str] = &[
    "CREATE INDEX IF NOT EXISTS idx_browser_session_tabs_tab_id ON browser_session_tabs(session_id, tab_id)",
    "CREATE INDEX IF NOT EXISTS idx_browser_history_pages_sync_state ON browser_history_pages(sync_state, updated_at DESC)",
    "CREATE INDEX IF NOT EXISTS idx_browser_history_visits_sync_state ON browser_history_visits(sync_state, visited_at DESC)",
    "CREATE INDEX IF NOT EXISTS idx_browser_bookmark_folders_sync_state ON browser_bookmark_folders(sync_state, updated_at DESC)",
    "CREATE INDEX IF NOT EXISTS idx_browser_bookmarks_sync_state ON browser_bookmarks(sync_state, updated_at DESC)",
    "CREATE INDEX IF NOT EXISTS idx_browser_sessions_sync_state ON browser_sessions(sync_state, updated_at DESC)",
    "CREATE INDEX IF NOT EXISTS idx_browser_session_tabs_sync_state ON browser_session_tabs(sync_state, updated_at DESC)",
    r#"
CREATE TABLE IF NOT EXISTS browser_sync_cursors (
    scope TEXT NOT NULL DEFAULT 'default',
    collection TEXT NOT NULL,
    cursor TEXT NOT NULL DEFAULT '',
    last_synced_at INTEGER,
    updated_at INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (scope, collection)
)
"#,
    "CREATE INDEX IF NOT EXISTS idx_browser_sync_cursors_updated ON browser_sync_cursors(updated_at DESC)",
    "INSERT OR REPLACE INTO browser_schema_meta (key, value) VALUES ('browser_storage_schema_version', '6')",
];

