pub const BROWSER_STORAGE_SYNC_SQL: BrowserStorageSyncSql = BrowserStorageSyncSql {
    select_dirty_history_pages: r#"
SELECT 'historyPage' AS record_type, address AS record_id, sync_revision, sync_state, origin_device_id, updated_at, deleted_at,
       address, title, visit_count, last_visited_at, created_at, favicon
FROM browser_history_pages
WHERE sync_state <> 'synced' OR last_synced_at IS NULL OR updated_at > last_synced_at
ORDER BY updated_at ASC
LIMIT ?
"#,
    select_dirty_history_visits: r#"
SELECT 'historyVisit' AS record_type, id AS record_id, sync_revision, sync_state, origin_device_id, visited_at AS updated_at, deleted_at,
       id, address, title, visited_at, transition
FROM browser_history_visits
WHERE sync_state <> 'synced' OR last_synced_at IS NULL OR visited_at > last_synced_at
ORDER BY visited_at ASC
LIMIT ?
"#,
    select_dirty_bookmark_folders: r#"
SELECT 'bookmarkFolder' AS record_type, id AS record_id, sync_revision, sync_state, origin_device_id, updated_at, deleted_at,
       id, parent_id, title, sort_order, created_at
FROM browser_bookmark_folders
WHERE sync_state <> 'synced' OR last_synced_at IS NULL OR updated_at > last_synced_at
ORDER BY updated_at ASC
LIMIT ?
"#,
    select_dirty_bookmarks: r#"
SELECT 'bookmark' AS record_type, id AS record_id, sync_revision, sync_state, origin_device_id, updated_at, deleted_at,
       id, folder_id, title, address, created_at, sort_order, favicon, owner_kind, owner_id, is_deleted
FROM browser_bookmarks
WHERE sync_state <> 'synced' OR last_synced_at IS NULL OR updated_at > last_synced_at
ORDER BY updated_at ASC
LIMIT ?
"#,
    select_dirty_sessions: r#"
	SELECT 'session' AS record_type, id AS record_id, sync_revision, sync_state, origin_device_id, updated_at, deleted_at,
	       id, active_tab_index, owner_kind, owner_id, surface_kind, surface_id, created_at
	FROM browser_sessions
WHERE sync_state <> 'synced' OR last_synced_at IS NULL OR updated_at > last_synced_at
ORDER BY updated_at ASC
LIMIT ?
"#,
    select_dirty_session_tabs: r#"
SELECT 'sessionTab' AS record_type, session_id || ':' || COALESCE(NULLIF(tab_id, ''), CAST(tab_index AS TEXT)) AS record_id, sync_revision, sync_state, origin_device_id, updated_at, deleted_at,
       session_id, tab_index, tab_id, title, address, created_at
FROM browser_session_tabs
WHERE sync_state <> 'synced' OR last_synced_at IS NULL OR updated_at > last_synced_at
ORDER BY updated_at ASC
LIMIT ?
"#,
    apply_remote_history_page: r#"
INSERT INTO browser_history_pages (
    address, title, visit_count, last_visited_at, created_at, updated_at, favicon,
    sync_state, sync_revision, origin_device_id, last_synced_at, deleted_at
)
VALUES (?, ?, ?, ?, ?, ?, ?, 'synced', ?, ?, ?, ?)
ON CONFLICT(address) DO UPDATE SET
    title = excluded.title,
    visit_count = excluded.visit_count,
    last_visited_at = excluded.last_visited_at,
    created_at = MIN(browser_history_pages.created_at, excluded.created_at),
    updated_at = excluded.updated_at,
    favicon = COALESCE(excluded.favicon, browser_history_pages.favicon),
    sync_state = 'synced',
    sync_revision = excluded.sync_revision,
    origin_device_id = excluded.origin_device_id,
    last_synced_at = excluded.last_synced_at,
    deleted_at = excluded.deleted_at
WHERE browser_history_pages.sync_state = 'synced'
  AND browser_history_pages.sync_revision <= excluded.sync_revision
"#,
    apply_remote_history_visit: r#"
INSERT INTO browser_history_visits (
    id, address, title, visited_at, transition,
    sync_state, sync_revision, origin_device_id, last_synced_at, deleted_at
)
VALUES (?, ?, ?, ?, ?, 'synced', ?, ?, ?, ?)
ON CONFLICT(id) DO UPDATE SET
    address = excluded.address,
    title = excluded.title,
    visited_at = excluded.visited_at,
    transition = excluded.transition,
    sync_state = 'synced',
    sync_revision = excluded.sync_revision,
    origin_device_id = excluded.origin_device_id,
    last_synced_at = excluded.last_synced_at,
    deleted_at = excluded.deleted_at
WHERE browser_history_visits.sync_state = 'synced'
  AND browser_history_visits.sync_revision <= excluded.sync_revision
"#,
    apply_remote_bookmark_folder: r#"
INSERT INTO browser_bookmark_folders (
    id, parent_id, title, sort_order, created_at, updated_at,
    sync_state, sync_revision, origin_device_id, last_synced_at, deleted_at
)
VALUES (?, ?, ?, ?, ?, ?, 'synced', ?, ?, ?, ?)
ON CONFLICT(id) DO UPDATE SET
    parent_id = excluded.parent_id,
    title = excluded.title,
    sort_order = excluded.sort_order,
    created_at = MIN(browser_bookmark_folders.created_at, excluded.created_at),
    updated_at = excluded.updated_at,
    sync_state = 'synced',
    sync_revision = excluded.sync_revision,
    origin_device_id = excluded.origin_device_id,
    last_synced_at = excluded.last_synced_at,
    deleted_at = excluded.deleted_at
WHERE browser_bookmark_folders.sync_state = 'synced'
  AND browser_bookmark_folders.sync_revision <= excluded.sync_revision
"#,
    apply_remote_bookmark: r#"
INSERT INTO browser_bookmarks (
    id, folder_id, title, address, created_at, updated_at, sort_order, favicon, owner_kind, owner_id, is_deleted,
    sync_state, sync_revision, origin_device_id, last_synced_at, deleted_at
)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'synced', ?, ?, ?, ?)
ON CONFLICT(id) DO UPDATE SET
    folder_id = excluded.folder_id,
    title = excluded.title,
    address = excluded.address,
    created_at = MIN(browser_bookmarks.created_at, excluded.created_at),
    updated_at = excluded.updated_at,
    sort_order = excluded.sort_order,
    favicon = COALESCE(excluded.favicon, browser_bookmarks.favicon),
    owner_kind = excluded.owner_kind,
    owner_id = excluded.owner_id,
    is_deleted = excluded.is_deleted,
    sync_state = 'synced',
    sync_revision = excluded.sync_revision,
    origin_device_id = excluded.origin_device_id,
    last_synced_at = excluded.last_synced_at,
    deleted_at = excluded.deleted_at
WHERE browser_bookmarks.sync_state = 'synced'
  AND browser_bookmarks.sync_revision <= excluded.sync_revision
"#,
    apply_remote_session: r#"
	INSERT INTO browser_sessions (
	    id, active_tab_index, owner_kind, owner_id, surface_kind, surface_id, created_at, updated_at,
	    sync_state, sync_revision, origin_device_id, last_synced_at, deleted_at
	)
	VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'synced', ?, ?, ?, ?)
	ON CONFLICT(id) DO UPDATE SET
	    active_tab_index = excluded.active_tab_index,
	    owner_kind = excluded.owner_kind,
	    owner_id = excluded.owner_id,
	    surface_kind = excluded.surface_kind,
	    surface_id = excluded.surface_id,
	    created_at = MIN(browser_sessions.created_at, excluded.created_at),
	    updated_at = excluded.updated_at,
    sync_state = 'synced',
    sync_revision = excluded.sync_revision,
    origin_device_id = excluded.origin_device_id,
    last_synced_at = excluded.last_synced_at,
    deleted_at = excluded.deleted_at
WHERE browser_sessions.sync_state = 'synced'
  AND browser_sessions.sync_revision <= excluded.sync_revision
"#,
    apply_remote_session_tab: r#"
INSERT INTO browser_session_tabs (
    session_id, tab_index, tab_id, title, address, created_at, updated_at,
    sync_state, sync_revision, origin_device_id, last_synced_at, deleted_at
)
VALUES (?, ?, ?, ?, ?, ?, ?, 'synced', ?, ?, ?, ?)
ON CONFLICT(session_id, tab_index) DO UPDATE SET
    tab_id = excluded.tab_id,
    title = excluded.title,
    address = excluded.address,
    created_at = MIN(browser_session_tabs.created_at, excluded.created_at),
    updated_at = excluded.updated_at,
    sync_state = 'synced',
    sync_revision = excluded.sync_revision,
    origin_device_id = excluded.origin_device_id,
    last_synced_at = excluded.last_synced_at,
    deleted_at = excluded.deleted_at
WHERE browser_session_tabs.sync_state = 'synced'
  AND browser_session_tabs.sync_revision <= excluded.sync_revision
"#,
    mark_history_page_synced: "UPDATE browser_history_pages SET sync_state = 'synced', sync_revision = MAX(sync_revision, ?), last_synced_at = ?, origin_device_id = COALESCE(NULLIF(origin_device_id, ''), ?) WHERE address = ? AND sync_revision <= ?",
    mark_history_visit_synced: "UPDATE browser_history_visits SET sync_state = 'synced', sync_revision = MAX(sync_revision, ?), last_synced_at = ?, origin_device_id = COALESCE(NULLIF(origin_device_id, ''), ?) WHERE id = ? AND sync_revision <= ?",
    mark_bookmark_folder_synced: "UPDATE browser_bookmark_folders SET sync_state = 'synced', sync_revision = MAX(sync_revision, ?), last_synced_at = ?, origin_device_id = COALESCE(NULLIF(origin_device_id, ''), ?) WHERE id = ? AND sync_revision <= ?",
    mark_bookmark_synced: "UPDATE browser_bookmarks SET sync_state = 'synced', sync_revision = MAX(sync_revision, ?), last_synced_at = ?, origin_device_id = COALESCE(NULLIF(origin_device_id, ''), ?) WHERE id = ? AND sync_revision <= ?",
    mark_session_synced: "UPDATE browser_sessions SET sync_state = 'synced', sync_revision = MAX(sync_revision, ?), last_synced_at = ?, origin_device_id = COALESCE(NULLIF(origin_device_id, ''), ?) WHERE id = ? AND sync_revision <= ?",
    mark_session_tab_synced: "UPDATE browser_session_tabs SET sync_state = 'synced', sync_revision = MAX(sync_revision, ?), last_synced_at = ?, origin_device_id = COALESCE(NULLIF(origin_device_id, ''), ?) WHERE session_id || ':' || COALESCE(NULLIF(tab_id, ''), CAST(tab_index AS TEXT)) = ? AND sync_revision <= ?",
    upsert_sync_cursor: r#"
INSERT INTO browser_sync_cursors (scope, collection, cursor, last_synced_at, updated_at)
VALUES (?, ?, ?, ?, ?)
ON CONFLICT(scope, collection) DO UPDATE SET
    cursor = excluded.cursor,
    last_synced_at = excluded.last_synced_at,
    updated_at = excluded.updated_at
"#,
    select_sync_cursor: "SELECT cursor, last_synced_at FROM browser_sync_cursors WHERE scope = ? AND collection = ?",
};

