pub const BROWSER_STORAGE_SYNC_SERVER_SQL: BrowserStorageSyncServerSql =
    BrowserStorageSyncServerSql {
        server_revision_param_rule: "execute allocateServerRevision, then prepend returned serverRevision to merge operation params",
        remote_select_cursor_rule: "cursor is the last accepted serverRevision for the collection; empty cursor is treated as 0",
        allocate_server_revision: r#"
INSERT INTO browser_sync_server_revisions (
    scope, collection, record_type, record_id,
    origin_device_id, client_sync_revision, created_at
)
VALUES (?, ?, ?, ?, ?, ?, ?)
RETURNING revision
"#,
        upsert_device_cursor: r#"
INSERT INTO browser_sync_server_device_cursors (
    scope, device_id, collection, cursor, last_synced_at, updated_at
)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT(scope, device_id, collection) DO UPDATE SET
    cursor = excluded.cursor,
    last_synced_at = excluded.last_synced_at,
    updated_at = excluded.updated_at
"#,
        select_device_cursors: r#"
SELECT collection, cursor, last_synced_at
FROM browser_sync_server_device_cursors
WHERE scope = ? AND device_id = ?
ORDER BY collection ASC
"#,
        merge_pushed_history_page: r#"
INSERT INTO browser_sync_server_history_pages (
    scope, address, title, visit_count, last_visited_at, created_at, updated_at, favicon,
    origin_device_id, client_sync_revision, server_revision, deleted_at
)
VALUES (?2, ?4, ?8, ?9, ?10, ?11, ?6, ?12, ?3, ?5, ?1, ?7)
ON CONFLICT(scope, address) DO UPDATE SET
    title = CASE WHEN excluded.deleted_at IS NULL THEN excluded.title ELSE browser_sync_server_history_pages.title END,
    visit_count = CASE WHEN excluded.deleted_at IS NULL THEN MAX(browser_sync_server_history_pages.visit_count, excluded.visit_count) ELSE browser_sync_server_history_pages.visit_count END,
    last_visited_at = CASE WHEN excluded.deleted_at IS NULL THEN MAX(browser_sync_server_history_pages.last_visited_at, excluded.last_visited_at) ELSE browser_sync_server_history_pages.last_visited_at END,
    created_at = MIN(browser_sync_server_history_pages.created_at, excluded.created_at),
    updated_at = MAX(browser_sync_server_history_pages.updated_at, excluded.updated_at),
    favicon = COALESCE(excluded.favicon, browser_sync_server_history_pages.favicon),
    origin_device_id = excluded.origin_device_id,
    client_sync_revision = excluded.client_sync_revision,
    server_revision = excluded.server_revision,
    deleted_at = excluded.deleted_at
WHERE browser_sync_server_history_pages.server_revision < excluded.server_revision
"#,
        merge_pushed_history_visit: r#"
INSERT INTO browser_sync_server_history_visits (
    scope, id, address, title, visited_at, transition,
    origin_device_id, client_sync_revision, server_revision, deleted_at
)
VALUES (?2, ?4, ?8, ?9, ?10, ?11, ?3, ?5, ?1, ?7)
ON CONFLICT(scope, id) DO UPDATE SET
    address = excluded.address,
    title = excluded.title,
    visited_at = excluded.visited_at,
    transition = excluded.transition,
    origin_device_id = excluded.origin_device_id,
    client_sync_revision = excluded.client_sync_revision,
    server_revision = excluded.server_revision,
    deleted_at = excluded.deleted_at
WHERE browser_sync_server_history_visits.server_revision < excluded.server_revision
"#,
        merge_pushed_bookmark_folder: r#"
INSERT INTO browser_sync_server_bookmark_folders (
    scope, id, parent_id, title, sort_order, created_at, updated_at,
    origin_device_id, client_sync_revision, server_revision, deleted_at
)
VALUES (?2, ?4, ?8, ?9, ?10, ?11, ?6, ?3, ?5, ?1, ?7)
ON CONFLICT(scope, id) DO UPDATE SET
    parent_id = excluded.parent_id,
    title = excluded.title,
    sort_order = excluded.sort_order,
    created_at = MIN(browser_sync_server_bookmark_folders.created_at, excluded.created_at),
    updated_at = MAX(browser_sync_server_bookmark_folders.updated_at, excluded.updated_at),
    origin_device_id = excluded.origin_device_id,
    client_sync_revision = excluded.client_sync_revision,
    server_revision = excluded.server_revision,
    deleted_at = excluded.deleted_at
WHERE browser_sync_server_bookmark_folders.server_revision < excluded.server_revision
"#,
        merge_pushed_bookmark: r#"
INSERT INTO browser_sync_server_bookmarks (
    scope, id, folder_id, title, address, created_at, updated_at, sort_order, favicon, owner_kind, owner_id, is_deleted,
    origin_device_id, client_sync_revision, server_revision, deleted_at
)
VALUES (?2, ?4, ?8, ?9, ?10, ?11, ?6, ?12, ?13, ?14, ?15, ?16, ?3, ?5, ?1, ?7)
ON CONFLICT(scope, id) DO UPDATE SET
    folder_id = excluded.folder_id,
    title = excluded.title,
    address = excluded.address,
    created_at = MIN(browser_sync_server_bookmarks.created_at, excluded.created_at),
    updated_at = MAX(browser_sync_server_bookmarks.updated_at, excluded.updated_at),
    sort_order = excluded.sort_order,
    favicon = COALESCE(excluded.favicon, browser_sync_server_bookmarks.favicon),
    owner_kind = excluded.owner_kind,
    owner_id = excluded.owner_id,
    is_deleted = CASE WHEN excluded.deleted_at IS NOT NULL THEN 1 ELSE excluded.is_deleted END,
    origin_device_id = excluded.origin_device_id,
    client_sync_revision = excluded.client_sync_revision,
    server_revision = excluded.server_revision,
    deleted_at = excluded.deleted_at
WHERE browser_sync_server_bookmarks.server_revision < excluded.server_revision
"#,
        merge_pushed_session: r#"
	INSERT INTO browser_sync_server_sessions (
	    scope, id, active_tab_index, owner_kind, owner_id, surface_kind, surface_id, created_at, updated_at,
	    origin_device_id, client_sync_revision, server_revision, deleted_at
	)
	VALUES (?2, ?4, ?8, ?9, ?10, ?11, ?12, ?13, ?6, ?3, ?5, ?1, ?7)
	ON CONFLICT(scope, id) DO UPDATE SET
	    active_tab_index = excluded.active_tab_index,
	    owner_kind = excluded.owner_kind,
	    owner_id = excluded.owner_id,
	    surface_kind = excluded.surface_kind,
	    surface_id = excluded.surface_id,
	    created_at = MIN(browser_sync_server_sessions.created_at, excluded.created_at),
	    updated_at = MAX(browser_sync_server_sessions.updated_at, excluded.updated_at),
    origin_device_id = excluded.origin_device_id,
    client_sync_revision = excluded.client_sync_revision,
    server_revision = excluded.server_revision,
    deleted_at = excluded.deleted_at
WHERE browser_sync_server_sessions.server_revision < excluded.server_revision
"#,
        merge_pushed_session_tab: r#"
INSERT INTO browser_sync_server_session_tabs (
    scope, session_id, tab_index, tab_id, title, address, created_at, updated_at,
    origin_device_id, client_sync_revision, server_revision, deleted_at
)
VALUES (?2, ?8, ?9, ?10, ?11, ?12, ?13, ?6, ?3, ?5, ?1, ?7)
ON CONFLICT(scope, session_id, tab_id) DO UPDATE SET
    tab_index = excluded.tab_index,
    title = excluded.title,
    address = excluded.address,
    created_at = MIN(browser_sync_server_session_tabs.created_at, excluded.created_at),
    updated_at = MAX(browser_sync_server_session_tabs.updated_at, excluded.updated_at),
    origin_device_id = excluded.origin_device_id,
    client_sync_revision = excluded.client_sync_revision,
    server_revision = excluded.server_revision,
    deleted_at = excluded.deleted_at
WHERE browser_sync_server_session_tabs.server_revision < excluded.server_revision
"#,
        select_remote_history_pages: r#"
SELECT 'historyPage' AS record_type, address AS record_id, server_revision AS sync_revision, 'remote' AS sync_state, origin_device_id, updated_at, deleted_at,
       address, title, visit_count, last_visited_at, created_at, favicon
FROM browser_sync_server_history_pages
WHERE scope = ? AND server_revision > CAST(COALESCE(NULLIF(?, ''), '0') AS INTEGER) AND origin_device_id <> ?
ORDER BY server_revision ASC
LIMIT ?
"#,
        select_remote_history_visits: r#"
SELECT 'historyVisit' AS record_type, id AS record_id, server_revision AS sync_revision, 'remote' AS sync_state, origin_device_id, visited_at AS updated_at, deleted_at,
       id, address, title, visited_at, transition
FROM browser_sync_server_history_visits
WHERE scope = ? AND server_revision > CAST(COALESCE(NULLIF(?, ''), '0') AS INTEGER) AND origin_device_id <> ?
ORDER BY server_revision ASC
LIMIT ?
"#,
        select_remote_bookmark_folders: r#"
SELECT 'bookmarkFolder' AS record_type, id AS record_id, server_revision AS sync_revision, 'remote' AS sync_state, origin_device_id, updated_at, deleted_at,
       id, parent_id, title, sort_order, created_at
FROM browser_sync_server_bookmark_folders
WHERE scope = ? AND server_revision > CAST(COALESCE(NULLIF(?, ''), '0') AS INTEGER) AND origin_device_id <> ?
ORDER BY server_revision ASC
LIMIT ?
"#,
        select_remote_bookmarks: r#"
SELECT 'bookmark' AS record_type, id AS record_id, server_revision AS sync_revision, 'remote' AS sync_state, origin_device_id, updated_at, deleted_at,
       id, folder_id, title, address, created_at, sort_order, favicon, owner_kind, owner_id, is_deleted
FROM browser_sync_server_bookmarks
WHERE scope = ? AND server_revision > CAST(COALESCE(NULLIF(?, ''), '0') AS INTEGER) AND origin_device_id <> ?
ORDER BY server_revision ASC
LIMIT ?
"#,
        select_remote_sessions: r#"
	SELECT 'session' AS record_type, id AS record_id, server_revision AS sync_revision, 'remote' AS sync_state, origin_device_id, updated_at, deleted_at,
	       id, active_tab_index, owner_kind, owner_id, surface_kind, surface_id, created_at
	FROM browser_sync_server_sessions
WHERE scope = ? AND server_revision > CAST(COALESCE(NULLIF(?, ''), '0') AS INTEGER) AND origin_device_id <> ?
ORDER BY server_revision ASC
LIMIT ?
"#,
        select_remote_session_tabs: r#"
SELECT 'sessionTab' AS record_type, session_id || ':' || tab_id AS record_id, server_revision AS sync_revision, 'remote' AS sync_state, origin_device_id, updated_at, deleted_at,
       session_id, tab_index, tab_id, title, address, created_at
FROM browser_sync_server_session_tabs
WHERE scope = ? AND server_revision > CAST(COALESCE(NULLIF(?, ''), '0') AS INTEGER) AND origin_device_id <> ?
ORDER BY server_revision ASC
LIMIT ?
"#,
    };

