pub type BrowserStorageSyncCloudStoreFuture<'a, T> =
    Pin<Box<dyn Future<Output = BrowserStorageSyncCloudStoreResult<T>> + Send + 'a>>;

/// Provider-neutral object store boundary for browser sync cloud adapters.
///
/// OpenDAL, iCloud/CloudKit, Google Drive, OneDrive, local folder sync, and test
/// stores should implement this trait instead of leaking provider SDK concepts
/// into the merge/snapshot engine.
pub trait BrowserStorageSyncCloudStore {
    fn capabilities(&self) -> BrowserStorageSyncCloudStoreCapabilities;

    fn list<'a>(
        &'a self,
        prefix: &'a str,
        page: Option<BrowserStorageSyncCloudListPage>,
    ) -> BrowserStorageSyncCloudStoreFuture<'a, BrowserStorageSyncCloudListResult>;

    fn read<'a>(
        &'a self,
        path: &'a str,
    ) -> BrowserStorageSyncCloudStoreFuture<'a, Option<BrowserStorageSyncCloudObject>>;

    fn write<'a>(
        &'a self,
        request: BrowserStorageSyncCloudWriteRequest<'a>,
    ) -> BrowserStorageSyncCloudStoreFuture<'a, BrowserStorageSyncCloudWriteReceipt>;

    fn delete<'a>(
        &'a self,
        request: BrowserStorageSyncCloudDeleteRequest<'a>,
    ) -> BrowserStorageSyncCloudStoreFuture<'a, BrowserStorageSyncCloudDeleteReceipt>;
}

