pub fn browser_storage_canonicalize_addresses_json(addresses_json: &str) -> String {
    let Some(addresses) = parse_browser_storage_address_inputs(addresses_json) else {
        return "null".to_string();
    };
    let results = addresses
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .map(|address| browser_storage_canonicalize_address(&address))
        .collect::<Vec<_>>();
    let canonicalization_summary = browser_storage_address_canonicalization_summary(&results);
    serialize_json(&BrowserStorageAddressCanonicalizationBatch {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        policy: BROWSER_STORAGE_ADDRESS_CANONICALIZATION_POLICY.to_string(),
        canonicalization_summary,
        results,
    })
}

