/// Adjudicate one applied sync cycle response into the platform-facing result
/// envelope. The native side only executes the remote apply plan and the safe
/// post-remote ack batch, then feeds the raw execution outputs back here so
/// the envelope fields (`cursorAckDeferred`, `ackApplied`, embedded plan and
/// remote apply summary) are derived by one Rust implementation on every
/// platform. Any invalid input returns "null".
pub fn browser_storage_sync_client_cycle_apply_result_json(
    response_json: &str,
    remote_apply_result_json: &str,
    ack_applied: bool,
) -> String {
    let cycle_plan_json = browser_storage_sync_client_cycle_plan_json(response_json);
    let cycle_plan = match serde_json::from_str::<Value>(&cycle_plan_json) {
        Ok(value) if value.is_object() => value,
        _ => return "null".to_string(),
    };
    let remote_operation_count = cycle_plan
        .pointer("/remoteApplyPlan/operations")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    let remote_apply_result = if remote_operation_count == 0 {
        Value::Null
    } else {
        match serde_json::from_str::<Value>(remote_apply_result_json) {
            Ok(value) if value.is_object() => value,
            _ => return "null".to_string(),
        }
    };
    let ack_json = browser_storage_sync_client_ack_batch_after_remote_apply_json(
        response_json,
        remote_apply_result_json,
    );
    let ack = match serde_json::from_str::<Value>(&ack_json) {
        Ok(value) if value.is_object() => value,
        _ => return "null".to_string(),
    };
    let acked_cursor_count = ack
        .get("cursors")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    let response_ack_cursor_count = serde_json::from_str::<Value>(response_json)
        .ok()
        .as_ref()
        .and_then(|response| response.pointer("/ackBatch/cursors"))
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);

    serialize_json(&json!({
        "version": cycle_plan.get("version").cloned().unwrap_or(Value::Null),
        "storageSchemaVersion": cycle_plan
            .get("storageSchemaVersion")
            .cloned()
            .unwrap_or(Value::Null),
        "scope": cycle_plan.get("scope").cloned().unwrap_or(Value::Null),
        "deviceId": cycle_plan.get("deviceId").cloned().unwrap_or(Value::Null),
        "generatedAtUnixSeconds": cycle_plan
            .get("generatedAtUnixSeconds")
            .cloned()
            .unwrap_or(Value::Null),
        "action": cycle_plan.get("action").cloned().unwrap_or(Value::Null),
        "ackApplied": ack_applied,
        "cursorAckDeferred": acked_cursor_count < response_ack_cursor_count,
        "remoteApplyResult": remote_apply_result,
        "cyclePlan": cycle_plan,
    }))
}

