pub fn browser_storage_address_canonicalization_policy(
) -> BrowserStorageAddressCanonicalizationPolicy {
    BrowserStorageAddressCanonicalizationPolicy {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        policy: BROWSER_STORAGE_ADDRESS_CANONICALIZATION_POLICY.to_string(),
        max_address_length: MAX_SYNC_URL_LENGTH,
        accepted_external_schemes: vec![
            "http".to_string(),
            "https".to_string(),
            "file".to_string(),
        ],
        accepted_internal_addresses: vec![
            HOME_ADDRESS.to_string(),
            HISTORY_ADDRESS.to_string(),
            BOOKMARKS_ADDRESS.to_string(),
        ],
        accepted_session_schemes: vec!["about".to_string()],
        canonical_rules: vec![
            "Trim surrounding whitespace before storage.".to_string(),
            "Lowercase URL scheme and host through the shared URL parser.".to_string(),
            "Remove default ports for http and https.".to_string(),
            "Strip username/password userinfo before persisting or syncing browser addresses.".to_string(),
            "Drop a lone empty query or fragment separator so a trailing '?' or '#' does not create a distinct stored address.".to_string(),
            "Lowercase the whole about: address because the about scheme and its well-known tokens are case-insensitive.".to_string(),
            "Preserve path, query, and fragment because they may identify distinct browser destinations.".to_string(),
            "Reject addresses without a storage-safe scheme; native address-bar search/input expansion stays platform-owned.".to_string(),
            "Return canonicalizationSummary counts and address groups so product diagnostics do not rescan result rows per platform.".to_string(),
        ],
        applies_to_collections: vec![
            "historyPages".to_string(),
            "historyVisits".to_string(),
            "bookmarks".to_string(),
            "sessionTabs".to_string(),
        ],
    }
}

pub fn browser_storage_bookmark_folder_tree_integrity_policy(
) -> BrowserStorageBookmarkFolderTreeIntegrityPolicy {
    BrowserStorageBookmarkFolderTreeIntegrityPolicy {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        policy: BROWSER_STORAGE_BOOKMARK_FOLDER_TREE_INTEGRITY_POLICY.to_string(),
        max_folder_count: MAX_BROWSER_STORAGE_SYNC_RECORDS,
        accepted_input_shapes: vec![
            "bookmark folder array".to_string(),
            "object with folders array".to_string(),
            "object with currentFolders plus candidateFolders arrays".to_string(),
            "sync batch-like object with records containing bookmarkFolder payloads".to_string(),
        ],
        integrity_rules: vec![
            "Normalize folder ids with the shared sync id policy.".to_string(),
            "Treat self-parent as no parent before graph validation.".to_string(),
            "Ignore deleted folders when building the active parent graph.".to_string(),
            "Treat missing parents as partial-batch references rather than local integrity failures.".to_string(),
            "Reject active parent cycles as a whole batched plan before native SQLite apply.".to_string(),
            "Return integrityAction and integrityReason diagnostics on each normalized folder so platforms do not rederive active-graph, tombstone, partial-parent, or cycle explanations.".to_string(),
            "Return integritySummary counts and id groups so product diagnostics do not rescan normalized folders per platform.".to_string(),
        ],
        applies_to_collections: vec!["bookmarkFolders".to_string(), "bookmarks".to_string()],
    }
}

pub fn browser_storage_bookmark_restore_placement_policy(
) -> BrowserStorageBookmarkRestorePlacementPolicy {
    BrowserStorageBookmarkRestorePlacementPolicy {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        policy: BROWSER_STORAGE_BOOKMARK_RESTORE_PLACEMENT_POLICY.to_string(),
        accepted_input_shapes: vec![
            "object with bookmarks plus optional folders array".to_string(),
            "object with currentBookmarks/candidateBookmarks plus optional currentFolders/candidateFolders arrays".to_string(),
            "sync batch-like object with records containing bookmark and bookmarkFolder payloads"
                .to_string(),
        ],
        placement_rules: vec![
            "Normalize bookmark ids, folder ids, addresses, titles, sort order, and owner metadata with the shared storage policy.".to_string(),
            "Resolve duplicate bookmark ids with a deterministic delete/restore state timestamp: active rows use updatedAtUnixSeconds, tombstones use deletedAtUnixSeconds when available or updatedAtUnixSeconds otherwise, and equal timestamps keep later input order.".to_string(),
            "Preserve previous deletion/folder state and stale-state diagnostics when a newer delete or restore wins.".to_string(),
            "Use the Rust bookmark-folder tree integrity policy to decide which folders are available for active bookmark placement.".to_string(),
            "When a restored or active bookmark points at a deleted, rejected, or missing folder, resolve it to the root folder by setting resolvedFolderId to null before native SQLite apply.".to_string(),
            "Bookmark tombstones are preserved for diagnostics but do not claim an active folder placement.".to_string(),
            "Return placementReason, stateConflictReason, stateConflicts, and stateConflictSummary diagnostics so platforms do not rederive folder fallback or delete/restore timestamp explanations.".to_string(),
            "Bookmark list disclosure, selection, drag/drop affordances, and conflict presentation remain platform/product-owned.".to_string(),
        ],
        applies_to_collections: vec!["bookmarkFolders".to_string(), "bookmarks".to_string()],
    }
}

pub fn browser_storage_bookmark_ownership_policy() -> BrowserStorageBookmarkOwnershipPolicy {
    BrowserStorageBookmarkOwnershipPolicy {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        policy: BROWSER_STORAGE_BOOKMARK_OWNERSHIP_POLICY.to_string(),
        max_bookmark_count: MAX_BROWSER_STORAGE_SYNC_RECORDS,
        accepted_input_shapes: vec![
            "bookmark array".to_string(),
            "object with bookmarks array".to_string(),
            "object with currentBookmarks plus candidateBookmarks arrays".to_string(),
            "sync batch-like object with records containing bookmark payloads".to_string(),
        ],
        ownership_rules: vec![
            "Normalize bookmark ids, addresses, titles, folder ids, sort order, favicon, ownerKind, and ownerId with the shared browser storage policy.".to_string(),
            "Overlay duplicate bookmark ids by taking the last normalized item in the batch before address ownership is resolved.".to_string(),
            "Group active and tombstoned bookmarks by canonical address so current v6 address-unique stores and future multi-source stores make the same retained-source decision.".to_string(),
            "`user` owned bookmarks represent durable native/user bookmarks and outrank `tab` owned bookmark state for the same canonical address.".to_string(),
            "When the same address has multiple active bookmarks with the same owner priority, keep the newest updatedAtUnixSeconds and use createdAtUnixSeconds plus bookmark id as deterministic tie-breakers.".to_string(),
            "A tab-owned unstar/delete tombstone for an address does not hide an active user-owned bookmark for the same address; it remains a source tombstone only.".to_string(),
            "Return retentionReason, suppressedBookmarkIds, and ownershipSummary diagnostics so platforms do not rederive same-address source-resolution counts or winner groups.".to_string(),
            "Native SQLite writes, v7 multi-source schema changes, source-label UI, and conflict presentation remain platform/product-owned.".to_string(),
        ],
        applies_to_collections: vec!["bookmarks".to_string()],
    }
}

