pub fn browser_storage_schema_statements() -> Vec<&'static str> {
    BROWSER_STORAGE_SCHEMA_STATEMENTS.to_vec()
}

/// One ordered incremental column addition of the browser storage schema
/// migration plan. `statement` is the complete `ALTER TABLE … ADD COLUMN …`
/// literal; platforms only gate it behind a `PRAGMA table_info` column check
/// and execute it verbatim.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BrowserStorageSchemaMigrationColumn {
    pub table: String,
    pub column: String,
    pub statement: String,
}

/// Deterministic migration plan that upgrades any legacy browser storage
/// database to the current schema version. `add_columns` must be applied in
/// order (each gated on column absence); `idempotent_statements` are safe to
/// execute unconditionally afterwards. Platforms own introspection and
/// transaction execution only — all DDL literals live here.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct BrowserStorageSchemaMigrationPlan {
    pub schema_version: u32,
    pub add_columns: Vec<BrowserStorageSchemaMigrationColumn>,
    pub idempotent_statements: Vec<String>,
}

pub fn browser_storage_schema_migration_plan() -> BrowserStorageSchemaMigrationPlan {
    BrowserStorageSchemaMigrationPlan {
        schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        add_columns: BROWSER_STORAGE_SCHEMA_MIGRATION_ADD_COLUMNS
            .iter()
            .map(
                |(table, column, definition)| BrowserStorageSchemaMigrationColumn {
                    table: (*table).to_string(),
                    column: (*column).to_string(),
                    statement: format!("ALTER TABLE {table} ADD COLUMN {column} {definition}"),
                },
            )
            .collect(),
        idempotent_statements: BROWSER_STORAGE_SCHEMA_MIGRATION_IDEMPOTENT_STATEMENTS
            .iter()
            .map(|statement| statement.trim().to_string())
            .collect(),
    }
}

