pub fn normalize_history_snapshot(
    snapshot: Option<BrowserHistorySnapshot>,
) -> BrowserHistorySnapshot {
    let Some(snapshot) = snapshot else {
        return empty_history_snapshot();
    };

    let mut items = snapshot
        .items
        .into_iter()
        .filter_map(normalize_history_item)
        .collect::<Vec<_>>();
    dedupe_latest_by_address(
        &mut items,
        |item| &item.address,
        |item| item.visited_at_unix_seconds,
    );
    items.sort_by(|left, right| {
        right
            .visited_at_unix_seconds
            .cmp(&left.visited_at_unix_seconds)
    });
    items.truncate(MAX_HISTORY_ITEMS);

    BrowserHistorySnapshot {
        version: BROWSER_DATA_SCHEMA_VERSION,
        items,
    }
}

pub fn normalize_bookmark_snapshot(
    snapshot: Option<BrowserBookmarkSnapshot>,
) -> BrowserBookmarkSnapshot {
    let Some(snapshot) = snapshot else {
        return empty_bookmark_snapshot();
    };

    let mut items = snapshot
        .items
        .into_iter()
        .filter_map(normalize_bookmark_item)
        .collect::<Vec<_>>();
    dedupe_latest_by_address(
        &mut items,
        |item| &item.address,
        |item| item.created_at_unix_seconds,
    );
    items.sort_by(|left, right| {
        right
            .created_at_unix_seconds
            .cmp(&left.created_at_unix_seconds)
    });
    items.truncate(MAX_BOOKMARK_ITEMS);

    BrowserBookmarkSnapshot {
        version: BROWSER_DATA_SCHEMA_VERSION,
        items,
    }
}

pub fn normalize_session_snapshot(
    snapshot: Option<BrowserSessionSnapshot>,
) -> Option<BrowserSessionSnapshot> {
    let snapshot = snapshot?;
    let tabs = snapshot
        .tabs
        .into_iter()
        .take(MAX_SESSION_TABS)
        .enumerate()
        .filter_map(|(index, tab)| normalize_session_tab(index, tab))
        .collect::<Vec<_>>();

    if tabs.is_empty() {
        return None;
    }

    let active_tab_index = snapshot
        .active_tab_index
        .clamp(0, tabs.len().saturating_sub(1) as i32);

    Some(BrowserSessionSnapshot {
        version: BROWSER_DATA_SCHEMA_VERSION,
        active_tab_index,
        tabs,
    })
}

pub fn empty_browser_storage_sync_batch(
    scope: &str,
    device_id: &str,
    generated_at_unix_seconds: i64,
) -> BrowserStorageSyncBatch {
    BrowserStorageSyncBatch {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        generated_at_unix_seconds: normalize_unix_seconds(generated_at_unix_seconds),
        records: Vec::new(),
        cursors: Vec::new(),
    }
}

fn supports_browser_storage_schema_version(storage_schema_version: u32) -> bool {
    storage_schema_version == BROWSER_STORAGE_SCHEMA_VERSION
}

pub fn normalize_browser_storage_sync_batch(
    batch: Option<BrowserStorageSyncBatch>,
) -> Option<BrowserStorageSyncBatch> {
    let batch = batch?;
    if !supports_browser_storage_schema_version(batch.storage_schema_version) {
        return None;
    }

    let mut records = batch
        .records
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .filter_map(normalize_browser_storage_sync_record)
        .collect::<Vec<_>>();

    records.sort_by(|left, right| {
        left.updated_at_unix_seconds
            .cmp(&right.updated_at_unix_seconds)
            .then_with(|| {
                left.payload
                    .collection_order()
                    .cmp(&right.payload.collection_order())
            })
            .then_with(|| left.record_id.cmp(&right.record_id))
    });

    let generated_at_unix_seconds = normalize_unix_seconds(batch.generated_at_unix_seconds);
    let cursors = batch
        .cursors
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .filter_map(|cursor| {
            normalize_browser_storage_sync_cursor(cursor, generated_at_unix_seconds)
        })
        .collect::<Vec<_>>();

    Some(BrowserStorageSyncBatch {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: normalize_sync_text(&batch.scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(&batch.device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        generated_at_unix_seconds,
        records,
        cursors,
    })
}

pub fn browser_storage_sync_batch_from_dirty_rows(
    scope: &str,
    device_id: &str,
    generated_at_unix_seconds: i64,
    rows: Option<Vec<Value>>,
) -> Option<BrowserStorageSyncBatch> {
    let rows = rows?;
    let records = rows
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .filter_map(browser_storage_sync_record_from_dirty_row)
        .collect::<Vec<_>>();
    let generated_at_unix_seconds = normalize_unix_seconds(generated_at_unix_seconds);
    let cursors =
        browser_storage_sync_remote_cursors_from_records(&records, generated_at_unix_seconds);

    normalize_browser_storage_sync_batch(Some(BrowserStorageSyncBatch {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: scope.to_string(),
        device_id: device_id.to_string(),
        generated_at_unix_seconds,
        records,
        cursors,
    }))
}

pub fn normalize_browser_storage_sync_ack_batch(
    ack: Option<BrowserStorageSyncAckBatch>,
) -> Option<BrowserStorageSyncAckBatch> {
    let ack = ack?;
    if !supports_browser_storage_schema_version(ack.storage_schema_version) {
        return None;
    }

    let synced_at = normalize_unix_seconds(ack.synced_at_unix_seconds);
    let records = ack
        .records
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .filter_map(normalize_browser_storage_sync_ack_record)
        .collect::<Vec<_>>();
    let cursors = ack
        .cursors
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .filter_map(|cursor| normalize_browser_storage_sync_cursor(cursor, synced_at))
        .collect::<Vec<_>>();

    Some(BrowserStorageSyncAckBatch {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: normalize_sync_text(&ack.scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(&ack.device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        synced_at_unix_seconds: synced_at,
        records,
        cursors,
    })
}

pub fn browser_storage_sync_push_request(
    batch: Option<BrowserStorageSyncBatch>,
) -> Option<BrowserStorageSyncPushRequest> {
    let batch = normalize_browser_storage_sync_batch(batch)?;
    Some(BrowserStorageSyncPushRequest {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        request_type: "push".to_string(),
        scope: batch.scope.clone(),
        device_id: batch.device_id.clone(),
        generated_at_unix_seconds: batch.generated_at_unix_seconds,
        push_batch: batch,
    })
}

pub fn normalize_browser_storage_sync_push_request(
    request: Option<BrowserStorageSyncPushRequest>,
) -> Option<BrowserStorageSyncPushRequest> {
    let request = request?;
    if !supports_browser_storage_schema_version(request.storage_schema_version) {
        return None;
    }

    let scope = normalize_sync_text(&request.scope, "default", MAX_SYNC_ID_LENGTH);
    let device_id = normalize_sync_text(&request.device_id, "unknown-device", MAX_SYNC_ID_LENGTH);
    let generated_at = normalize_unix_seconds(request.generated_at_unix_seconds);
    let mut push_batch = normalize_browser_storage_sync_batch(Some(request.push_batch))?;
    push_batch.scope = scope.clone();
    push_batch.device_id = device_id.clone();
    push_batch.generated_at_unix_seconds = generated_at;

    Some(BrowserStorageSyncPushRequest {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        request_type: "push".to_string(),
        scope,
        device_id,
        generated_at_unix_seconds: generated_at,
        push_batch,
    })
}

pub fn browser_storage_sync_pull_request(
    scope: &str,
    device_id: &str,
    generated_at_unix_seconds: i64,
    cursors: Option<Vec<BrowserStorageSyncCursorUpdate>>,
    max_records_per_collection: u32,
) -> Option<BrowserStorageSyncPullRequest> {
    let generated_at = normalize_unix_seconds(generated_at_unix_seconds);
    let cursors = cursors?;
    let cursors = cursors
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .filter_map(|cursor| normalize_browser_storage_sync_cursor(cursor, generated_at))
        .collect::<Vec<_>>();

    Some(BrowserStorageSyncPullRequest {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        request_type: "pull".to_string(),
        scope: normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        generated_at_unix_seconds: generated_at,
        max_records_per_collection: normalize_sync_pull_limit(max_records_per_collection),
        cursors,
    })
}

pub fn browser_storage_sync_cycle_response(
    remote_batch: Option<BrowserStorageSyncBatch>,
    ack: Option<BrowserStorageSyncAckBatch>,
) -> Option<BrowserStorageSyncCycleResponse> {
    let remote_batch = normalize_browser_storage_sync_batch(remote_batch)?;
    let mut ack_batch = normalize_browser_storage_sync_ack_batch(ack)?;
    if remote_batch.scope != ack_batch.scope || remote_batch.device_id != ack_batch.device_id {
        return None;
    }
    let generated_at = remote_batch
        .generated_at_unix_seconds
        .max(ack_batch.synced_at_unix_seconds);
    ack_batch.cursors = merge_browser_storage_sync_cursors(
        ack_batch.cursors,
        remote_batch.cursors.clone(),
        generated_at,
    );

    Some(BrowserStorageSyncCycleResponse {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        response_type: "syncCycle".to_string(),
        scope: ack_batch.scope.clone(),
        device_id: ack_batch.device_id.clone(),
        generated_at_unix_seconds: generated_at,
        remote_batch,
        ack_batch,
    })
}

pub fn normalize_browser_storage_sync_cycle_response(
    response: Option<BrowserStorageSyncCycleResponse>,
) -> Option<BrowserStorageSyncCycleResponse> {
    let response = response?;
    if !supports_browser_storage_schema_version(response.storage_schema_version) {
        return None;
    }

    browser_storage_sync_cycle_response(Some(response.remote_batch), Some(response.ack_batch))
}

pub fn browser_storage_sync_client_cycle_plan(
    response: Option<BrowserStorageSyncCycleResponse>,
) -> Option<BrowserStorageSyncClientCyclePlan> {
    let response = normalize_browser_storage_sync_cycle_response(response)?;
    let remote_apply_plan =
        browser_storage_sync_remote_apply_plan(Some(response.remote_batch.clone()))?;
    let ack_plan = browser_storage_sync_ack_plan(Some(response.ack_batch.clone()))?;
    let remote_count = remote_apply_plan.operations.len();
    let ack_count = ack_plan.operations.len();
    let action = match (remote_count, ack_count) {
        (0, 0) => "noop",
        (0, _) => "applyAck",
        (_, 0) => "applyRemote",
        (_, _) => "applyRemoteThenAck",
    };

    Some(BrowserStorageSyncClientCyclePlan {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: response.scope,
        device_id: response.device_id,
        generated_at_unix_seconds: response.generated_at_unix_seconds,
        action: action.to_string(),
        steps: browser_storage_sync_client_cycle_steps(remote_count, ack_count),
        remote_apply_plan,
        ack_plan,
    })
}

pub fn browser_storage_sync_client_ack_batch_after_remote_apply(
    response: Option<BrowserStorageSyncCycleResponse>,
    remote_apply_result: Option<BrowserStorageSyncApplyResultSummary>,
) -> Option<BrowserStorageSyncAckBatch> {
    let response = normalize_browser_storage_sync_cycle_response(response)?;
    let mut ack_batch = response.ack_batch;
    let remote_operation_count =
        browser_storage_sync_remote_apply_plan(Some(response.remote_batch))?
            .operations
            .len();

    if remote_operation_count == 0 {
        return Some(ack_batch);
    }

    let remote_apply_result = remote_apply_result?;
    let scope = normalize_sync_text(&remote_apply_result.scope, "default", MAX_SYNC_ID_LENGTH);
    let device_id = normalize_sync_text(
        &remote_apply_result.device_id,
        "unknown-device",
        MAX_SYNC_ID_LENGTH,
    );

    if scope != ack_batch.scope || device_id != ack_batch.device_id {
        return None;
    }

    if remote_apply_result.failed_count > 0 {
        ack_batch.cursors.clear();
    }

    Some(ack_batch)
}

