fn browser_storage_sync_cloud_provider_adapter_plan_value(
    adapter_snapshot: &Value,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudProviderAdapterPlan> {
    if !adapter_snapshot.is_object() {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let preflight = browser_storage_sync_cloud_provider_adapter_preflight_snapshot(
        adapter_snapshot,
        observed_at,
    );
    let provider_kind = browser_storage_sync_cloud_provider_snapshot_string(
        adapter_snapshot,
        &["providerKind", "provider"],
    )
    .or_else(|| {
        preflight
            .capabilities
            .as_ref()
            .map(|capabilities| capabilities.provider_kind.clone())
    })
    .map(|provider_kind| {
        normalize_sync_text(&provider_kind, "unknownProvider", MAX_SYNC_TEXT_LENGTH)
    })
    .unwrap_or_else(|| "unknownProvider".to_string());
    let adapter_family = browser_storage_sync_cloud_provider_snapshot_string(
        adapter_snapshot,
        &["adapterFamily", "adapterKind", "family"],
    )
    .map(|family| normalize_sync_text(&family, "", MAX_SYNC_TEXT_LENGTH))
    .filter(|family| !family.is_empty())
    .unwrap_or_else(|| browser_storage_sync_cloud_provider_adapter_family(&provider_kind));
    let root_path = preflight
        .capabilities
        .as_ref()
        .map(|capabilities| capabilities.root_path.clone())
        .or_else(|| {
            browser_storage_sync_cloud_provider_snapshot_string(
                adapter_snapshot,
                &["rootPath", "providerRootPath"],
            )
        })
        .unwrap_or_default();
    let normalized_root_path = normalize_cloud_store_root_path(&root_path);
    let root_matches = browser_storage_sync_cloud_root_path_matches_contract(&normalized_root_path);
    let capability_blocked = preflight.should_block_sync
        || matches!(
            preflight.classification.as_str(),
            "providerContractInvalid"
                | "providerSetupRequired"
                | "providerLimitTooSmall"
                | "providerConflictUnsafe"
        );

    let mut blocked_reasons = preflight.missing_required_capabilities.clone();
    let mut warnings = preflight.warnings.clone();
    if !preflight.degraded_capabilities.is_empty() {
        warnings.push(format!(
            "Adapter will emulate degraded capabilities: {}.",
            preflight.degraded_capabilities.join(", ")
        ));
    }
    if !root_matches {
        browser_storage_sync_cloud_cycle_collect_reason(&mut blocked_reasons, Some("rootPath"));
        warnings.push(format!(
            "Adapter rootPath must resolve to {BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH}."
        ));
    }
    if preflight.snapshot_missing {
        browser_storage_sync_cloud_cycle_collect_reason(
            &mut blocked_reasons,
            Some("adapterSnapshotIncomplete"),
        );
        warnings.push(
            "Provider adapter snapshot must include capabilities or capabilityPreflight before production sync starts."
                .to_string(),
        );
    }

    let test_fixture = browser_storage_sync_cloud_provider_adapter_is_test_fixture(
        &provider_kind,
        &adapter_family,
    );
    let classification = if preflight.snapshot_missing {
        "adapterSnapshotIncomplete"
    } else if !root_matches || preflight.classification == "providerSetupRequired" {
        "providerSetupRequired"
    } else if capability_blocked {
        preflight.classification.as_str()
    } else if preflight.requires_adapter_emulation {
        "degraded"
    } else {
        "ready"
    }
    .to_string();
    let should_block_sync = matches!(
        classification.as_str(),
        "adapterSnapshotIncomplete"
            | "providerContractInvalid"
            | "providerSetupRequired"
            | "providerLimitTooSmall"
            | "providerConflictUnsafe"
    );
    let should_allow_sync = !should_block_sync;
    let requires_provider_setup = classification == "providerSetupRequired";
    let requires_adapter_emulation = preflight.requires_adapter_emulation && should_allow_sync;
    let production_ready = should_allow_sync && !test_fixture;
    if test_fixture {
        warnings.push(
            "This adapter family is suitable for tests or local probes but is not a production cloud provider."
                .to_string(),
        );
    }

    blocked_reasons.sort();
    blocked_reasons.dedup();
    warnings.sort();
    warnings.dedup();

    let (root_path_action, provider_action, user_action) =
        browser_storage_sync_cloud_provider_adapter_actions(
            &classification,
            requires_adapter_emulation,
            test_fixture,
        );

    Some(BrowserStorageSyncCloudProviderAdapterPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudProviderAdapterPlan".to_string(),
        observed_at_unix_seconds: observed_at,
        provider_kind,
        adapter_family,
        root_path,
        normalized_root_path,
        capability_classification: preflight.classification,
        classification,
        production_ready,
        should_allow_sync,
        should_block_sync,
        requires_provider_setup,
        requires_adapter_emulation,
        root_path_action,
        provider_action,
        user_action,
        path_mapping_policy:
            "Map provider-specific handles onto stable slash-separated object keys under Actro/BrowserSync; keep provider ids and local absolute paths in metadata only."
                .to_string(),
        operation_boundary:
            "Execute provider SDK IO in coarse native/provider rounds and pass batched bytes, revisions, receipts, or errors to Rust planners; do not add per-object cross-FFI provider calls."
                .to_string(),
        object_layout: browser_storage_sync_cloud_layout(),
        required_objects: browser_storage_sync_cloud_provider_adapter_required_objects(),
        required_prefixes: browser_storage_sync_cloud_provider_adapter_required_prefixes(),
        operation_groups: browser_storage_sync_cloud_provider_adapter_operation_groups(),
        blocked_reasons,
        warnings,
        result_policy:
            "Classify provider adapter object-space readiness, root mapping, production suitability, and coarse IO boundaries while leaving concrete cloud SDK calls, auth/session prompts, and OS scheduling platform-owned."
                .to_string(),
    })
}

pub fn browser_storage_sync_cloud_provider_connection_contract() -> Value {
    json!({
        "version": BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        "storageSchemaVersion": BROWSER_STORAGE_SCHEMA_VERSION,
        "cloudDataModelVersion": BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        "contractName": "BrowserStorageSyncCloudProviderConnectionStatus",
        "planType": "cloudProviderConnectionStatusPolicy",
        "purpose": "Normalize provider account/session readiness, local device membership readiness, cloud-store capability readiness, and provider recovery actions before cloud-file sync starts.",
        "inputSnapshotFields": [
            {
                "name": "providerKind",
                "required": true,
                "description": "Provider adapter family or concrete provider, such as localFolder, googleDrive, iCloudDrive, cloudKit, oneDrive, or opendal."
            },
            {
                "name": "providerAccountId",
                "required": false,
                "description": "Provider-owned account or storage identity. It is diagnostic only; Actro has no first-party browser-sync account registry."
            },
            {
                "name": "connectionState",
                "required": true,
                "values": ["connected", "connecting", "disconnected", "error"],
                "description": "Platform/provider session state. Provider SDK prompts and token refresh remain native."
            },
            {
                "name": "credentialState",
                "required": true,
                "values": ["available", "missing", "expired", "revoked", "unknown"],
                "description": "Secure local provider credential/session state, not a Rust-owned token."
            },
            {
                "name": "cloudStoreReady",
                "required": false,
                "description": "Whether the selected provider adapter can access the Actro browser sync root. Can be derived from capabilityPreflight."
            },
            {
                "name": "capabilityPreflight",
                "required": false,
                "description": "Optional BrowserStorageSyncCloudStoreCapabilityPreflightPlan output. Rust reuses its classification and actions."
            },
            {
                "name": "membershipStatus",
                "required": false,
                "values": ["active", "missing", "revoked", "unknown"],
                "description": "Local device membership in manifest.json and devices/<device-id>.json."
            },
            {
                "name": "lastProviderErrorKind",
                "required": false,
                "values": ["auth", "quota", "network", "rateLimited", "permission", "unsupported", "storage", "invalidDocument"],
                "description": "Provider adapter error kind from the last connection, preflight, membership, or sync attempt."
            }
        ],
        "classifications": [
            "ready",
            "providerNotSelected",
            "signInRequired",
            "authExpired",
            "storageSetupRequired",
            "quotaExceeded",
            "providerUnavailable",
            "adapterUnsupported",
            "membershipRequired",
            "recoveryRequired"
        ],
        "policyBoundary": "Rust owns status classification and scheduler/provider/user action names. Platforms own OAuth, system account prompts, secure credential storage, provider SDK execution, and user-facing wording.",
        "productConstraint": "No Actro product server allocates provider account or device membership; shared cloud files plus Rust-planned manifest/device documents are the browser sync substrate."
    })
}

pub fn browser_storage_sync_cloud_provider_error_policy() -> Value {
    json!({
        "version": BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        "storageSchemaVersion": BROWSER_STORAGE_SCHEMA_VERSION,
        "cloudDataModelVersion": BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        "contractName": "BrowserStorageSyncCloudProviderErrorPolicy",
        "planType": "cloudProviderErrorClassification",
        "purpose": "Normalize provider SDK, OpenDAL, Apple native, and platform-native errors into shared cloud sync retry, reread, and recovery actions without moving provider IO into Rust.",
        "inputShapes": [
            {
                "name": "errors",
                "description": "Preferred batch field. Each item can include operationIndex, operationType, path, errorKind/kind/providerErrorKind, providerStatusCode/statusCode/httpStatus, providerErrorCode/code, message/errorMessage, and retryable."
            },
            {
                "name": "operationResults",
                "description": "Provider read/write/delete result batches are also accepted; successful results are ignored and failed results are normalized."
            },
            {
                "name": "singleError",
                "description": "A single object with errorKind/statusCode/message is treated as a one-error batch."
            }
        ],
        "canonicalErrorKinds": [
            "unauthorized",
            "quotaExceeded",
            "rateLimited",
            "network",
            "conflict",
            "notFound",
            "storage",
            "invalidPath",
            "unsupported",
            "cloudDocumentInvalid",
            "providerFailure"
        ],
        "classifications": [
            "ready",
            "authExpired",
            "quotaExceeded",
            "recoveryRequired",
            "adapterUnsupported",
            "storageSetupRequired",
            "cloudStateRereadRequired",
            "providerUnavailable",
            "providerRecoveryRequired"
        ],
        "policyBoundary": "Provider adapters execute concrete SDK calls in coarse native/provider rounds and pass failed operations to Rust as a batch. Rust owns canonical error kinds, retry/reread/recovery actions, and scheduler/provider/user action names.",
        "productConstraint": "Provider errors are classified for user-owned cloud files only; this must not introduce an Actro-operated browser sync service or first-party provider account registry."
    })
}

pub fn browser_storage_sync_cloud_store_capability_preflight(
    capabilities_json: &str,
    observed_at_unix_seconds: i64,
) -> BrowserStorageSyncCloudStoreCapabilityPreflightPlan {
    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let Some(capabilities) = parse_browser_storage_sync_cloud_store_capabilities(capabilities_json)
    else {
        return browser_storage_sync_cloud_store_capability_preflight_plan(
            observed_at,
            None,
            "providerContractInvalid",
            "recoverProviderAdapter",
            "fixProviderCapabilityAdapter",
            "none",
            vec!["capabilitiesJson".to_string()],
            Vec::new(),
            vec!["Provider adapter did not return a valid BrowserStorageSyncCloudStoreCapabilities object.".to_string()],
        );
    };
    let capabilities = normalize_browser_storage_sync_cloud_store_capabilities(capabilities);
    let mut missing_required_capabilities = Vec::new();
    let mut degraded_capabilities = Vec::new();
    let mut warnings = Vec::new();

    if !browser_storage_sync_cloud_root_path_matches_contract(&capabilities.root_path) {
        missing_required_capabilities.push("rootPath".to_string());
        warnings.push(format!(
            "Provider rootPath must resolve to {BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH}."
        ));
    }
    if !capabilities.supports_conditional_write {
        missing_required_capabilities.push("supportsConditionalWrite".to_string());
        warnings.push(
            "Cloud sync needs optimistic provider writes so conflicts can be reread and merged through Rust."
                .to_string(),
        );
    }
    if browser_storage_sync_cloud_revision_kind_is_none(&capabilities.revision_kind) {
        missing_required_capabilities.push("revisionKind".to_string());
        warnings.push(
            "Provider revision metadata must be available for expectedRevision conflict checks."
                .to_string(),
        );
    }
    if let Some(max_object_bytes) = capabilities.max_object_bytes {
        if max_object_bytes < MIN_BROWSER_STORAGE_SYNC_CLOUD_OBJECT_BYTES {
            missing_required_capabilities.push("maxObjectBytes".to_string());
            warnings.push(format!(
                "Provider maxObjectBytes must be at least {MIN_BROWSER_STORAGE_SYNC_CLOUD_OBJECT_BYTES} for browser sync log and snapshot objects."
            ));
        }
    }

    if !capabilities.supports_prefix_list {
        degraded_capabilities.push("supportsPrefixList".to_string());
        warnings.push(
            "Provider adapter must emulate prefix listing under the Actro browser sync root."
                .to_string(),
        );
    }
    if !capabilities.supports_paged_list {
        degraded_capabilities.push("supportsPagedList".to_string());
        warnings.push(
            "Provider adapter may need to list complete log prefixes before returning Rust-planned pages."
                .to_string(),
        );
    }
    if !capabilities.supports_conditional_delete {
        degraded_capabilities.push("supportsConditionalDelete".to_string());
        warnings.push(
            "Old log cleanup may be best-effort without conditional delete support.".to_string(),
        );
    }
    if !capabilities.supports_app_folder {
        degraded_capabilities.push("supportsAppFolder".to_string());
        warnings.push(
            "Provider setup must choose or create an Actro browser sync folder without app-folder isolation."
                .to_string(),
        );
    }
    if !capabilities.supports_read_if_changed {
        degraded_capabilities.push("supportsReadIfChanged".to_string());
        warnings.push(
            "Provider adapter may reread full objects when checking for cloud changes.".to_string(),
        );
    }

    if missing_required_capabilities
        .iter()
        .any(|capability| capability == "rootPath")
    {
        return browser_storage_sync_cloud_store_capability_preflight_plan(
            observed_at,
            Some(capabilities),
            "providerSetupRequired",
            "configureCloudProviderRoot",
            "exposeActroBrowserSyncRoot",
            "chooseProviderFolder",
            missing_required_capabilities,
            degraded_capabilities,
            warnings,
        );
    }
    if missing_required_capabilities
        .iter()
        .any(|capability| capability == "maxObjectBytes")
    {
        return browser_storage_sync_cloud_store_capability_preflight_plan(
            observed_at,
            Some(capabilities),
            "providerLimitTooSmall",
            "chooseDifferentProviderOrReduceSyncBatchSize",
            "increaseProviderObjectSizeLimit",
            "chooseProviderWithLargerFiles",
            missing_required_capabilities,
            degraded_capabilities,
            warnings,
        );
    }
    if !missing_required_capabilities.is_empty() {
        return browser_storage_sync_cloud_store_capability_preflight_plan(
            observed_at,
            Some(capabilities),
            "providerConflictUnsafe",
            "chooseDifferentProviderOrAdapter",
            "enableOptimisticRevisionWrites",
            "chooseProviderSupportingRevisions",
            missing_required_capabilities,
            degraded_capabilities,
            warnings,
        );
    }
    if !degraded_capabilities.is_empty() {
        return browser_storage_sync_cloud_store_capability_preflight_plan(
            observed_at,
            Some(capabilities),
            "degraded",
            "continueWithProviderAdapterEmulation",
            "emulateMissingCapabilities",
            "none",
            missing_required_capabilities,
            degraded_capabilities,
            warnings,
        );
    }

    browser_storage_sync_cloud_store_capability_preflight_plan(
        observed_at,
        Some(capabilities),
        "ready",
        "continueCloudSync",
        "none",
        "none",
        missing_required_capabilities,
        degraded_capabilities,
        warnings,
    )
}

fn browser_storage_sync_cloud_provider_connection_status_policy_value(
    provider_snapshot: &Value,
    retry_attempt: u32,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudProviderConnectionStatusPolicy> {
    if !provider_snapshot.is_object() {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let provider_kind = browser_storage_sync_cloud_provider_snapshot_string(
        provider_snapshot,
        &["providerKind", "provider"],
    )
    .or_else(|| {
        provider_snapshot
            .pointer("/capabilityPreflight/providerKind")
            .and_then(Value::as_str)
            .map(str::to_string)
    })
    .map(|provider_kind| {
        normalize_sync_text(&provider_kind, "unknownProvider", MAX_SYNC_TEXT_LENGTH)
    })
    .unwrap_or_else(|| "unknownProvider".to_string());
    let provider_account_id = browser_storage_sync_cloud_provider_snapshot_string(
        provider_snapshot,
        &["providerAccountId", "accountId"],
    )
    .map(|account_id| normalize_sync_text(&account_id, "", MAX_SYNC_ID_LENGTH))
    .filter(|account_id| !account_id.is_empty());
    let scope = browser_storage_sync_cloud_provider_snapshot_string(provider_snapshot, &["scope"])
        .map(|scope| normalize_sync_text(&scope, "default", MAX_SYNC_ID_LENGTH))
        .unwrap_or_else(|| "default".to_string());
    let device_id =
        browser_storage_sync_cloud_provider_snapshot_string(provider_snapshot, &["deviceId"])
            .map(|device_id| normalize_sync_text(&device_id, "unknown-device", MAX_SYNC_ID_LENGTH))
            .unwrap_or_else(|| "unknown-device".to_string());
    let connection_state = browser_storage_sync_cloud_provider_connection_state(
        browser_storage_sync_cloud_provider_snapshot_string(
            provider_snapshot,
            &["connectionState"],
        )
        .as_deref(),
    );
    let credential_state = browser_storage_sync_cloud_provider_credential_state(
        browser_storage_sync_cloud_provider_snapshot_string(
            provider_snapshot,
            &["credentialState"],
        )
        .as_deref(),
    );
    let membership_status = browser_storage_sync_cloud_provider_membership_status(
        browser_storage_sync_cloud_provider_snapshot_string(
            provider_snapshot,
            &["membershipStatus"],
        )
        .as_deref(),
    );
    let last_provider_error_kind = browser_storage_sync_cloud_provider_snapshot_string(
        provider_snapshot,
        &[
            "lastProviderErrorKind",
            "providerErrorKind",
            "lastErrorKind",
        ],
    )
    .map(|error_kind| normalize_sync_text(&error_kind, "", MAX_SYNC_TEXT_LENGTH))
    .filter(|error_kind| !error_kind.is_empty());
    let capability_classification = provider_snapshot
        .pointer("/capabilityPreflight/classification")
        .and_then(Value::as_str)
        .map(|classification| normalize_sync_text(classification, "", MAX_SYNC_TEXT_LENGTH))
        .filter(|classification| !classification.is_empty());
    let capability_should_block = provider_snapshot
        .pointer("/capabilityPreflight/shouldBlockSync")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let capability_should_allow = provider_snapshot
        .pointer("/capabilityPreflight/shouldAllowSync")
        .and_then(Value::as_bool);
    let connected =
        browser_storage_sync_cloud_provider_snapshot_bool(provider_snapshot, &["connected"])
            .unwrap_or_else(|| connection_state == "connected");
    let credentials_available = browser_storage_sync_cloud_provider_snapshot_bool(
        provider_snapshot,
        &["credentialsAvailable", "hasCredentials"],
    )
    .unwrap_or_else(|| credential_state == "available");
    let cloud_store_ready = browser_storage_sync_cloud_provider_snapshot_bool(
        provider_snapshot,
        &["cloudStoreReady", "storeReady", "rootPathReady"],
    )
    .unwrap_or_else(|| {
        capability_should_allow.unwrap_or_else(|| {
            capability_classification
                .as_deref()
                .map(|classification| matches!(classification, "ready" | "degraded"))
                .unwrap_or(false)
        })
    });
    let membership_ready =
        browser_storage_sync_cloud_provider_snapshot_bool(provider_snapshot, &["membershipReady"])
            .unwrap_or_else(|| membership_status == "active");
    let requires_user_action = provider_snapshot
        .get("requiresUserAction")
        .and_then(Value::as_bool)
        .unwrap_or(false);

    let mut diagnostic_reasons = Vec::new();
    browser_storage_sync_cloud_provider_collect_snapshot_reasons(
        provider_snapshot,
        &mut diagnostic_reasons,
    );
    if browser_storage_sync_cloud_provider_is_unknown(&provider_kind) {
        browser_storage_sync_cloud_cycle_collect_reason(
            &mut diagnostic_reasons,
            Some("providerNotSelected"),
        );
    }
    if provider_account_id.is_none() && provider_kind != "localFolder" {
        browser_storage_sync_cloud_cycle_collect_reason(
            &mut diagnostic_reasons,
            Some("providerAccountMissing"),
        );
    }
    if !connected {
        browser_storage_sync_cloud_provider_collect_connection_reason(
            &connection_state,
            &mut diagnostic_reasons,
        );
    }
    if !credentials_available {
        browser_storage_sync_cloud_provider_collect_credential_reason(
            &credential_state,
            &mut diagnostic_reasons,
        );
    }
    if !cloud_store_ready {
        browser_storage_sync_cloud_cycle_collect_reason(
            &mut diagnostic_reasons,
            Some("cloudStoreNotReady"),
        );
    }
    if !membership_ready {
        browser_storage_sync_cloud_provider_collect_membership_reason(
            &membership_status,
            &mut diagnostic_reasons,
        );
    }
    if capability_should_block {
        browser_storage_sync_cloud_cycle_collect_reason(
            &mut diagnostic_reasons,
            Some("capabilityPreflightBlocked"),
        );
    }
    if requires_user_action {
        browser_storage_sync_cloud_cycle_collect_reason(
            &mut diagnostic_reasons,
            Some("requiresUserAction"),
        );
    }
    if let Some(error_kind) = last_provider_error_kind.as_deref() {
        browser_storage_sync_cloud_cycle_collect_reason(&mut diagnostic_reasons, Some(error_kind));
    }
    if let Some(classification) = capability_classification.as_deref() {
        browser_storage_sync_cloud_cycle_collect_reason(
            &mut diagnostic_reasons,
            Some(classification),
        );
    }

    diagnostic_reasons.sort();
    diagnostic_reasons.dedup();

    let classification = browser_storage_sync_cloud_provider_connection_classification(
        &provider_kind,
        &connection_state,
        &credential_state,
        connected,
        credentials_available,
        cloud_store_ready,
        membership_ready,
        last_provider_error_kind.as_deref(),
        capability_classification.as_deref(),
        capability_should_block,
    );
    let should_retry = classification == "providerUnavailable" && !requires_user_action;
    let retry_attempt = retry_attempt.min(16);
    let retry_delay_seconds = if should_retry {
        Some(browser_storage_sync_retry_delay_seconds(retry_attempt))
    } else {
        None
    };
    let (scheduler_action, provider_action, user_action, telemetry_level, reset_retry_attempt) =
        browser_storage_sync_cloud_provider_connection_actions(&classification, should_retry);
    let should_attempt_membership = classification == "membershipRequired";
    let should_attempt_sync = classification == "ready";

    Some(BrowserStorageSyncCloudProviderConnectionStatusPolicy {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudProviderConnectionStatusPolicy".to_string(),
        observed_at_unix_seconds: observed_at,
        scope,
        device_id,
        provider_kind,
        provider_account_id,
        connection_state,
        credential_state,
        membership_status,
        classification,
        connected,
        credentials_available,
        cloud_store_ready,
        membership_ready,
        should_attempt_membership,
        should_attempt_sync,
        should_retry,
        scheduler_action,
        provider_action,
        user_action,
        telemetry_level,
        retry_attempt,
        retry_delay_seconds,
        retry_delay_ceiling_seconds: BROWSER_STORAGE_SYNC_RETRY_MAX_SECONDS,
        retry_jitter_percent: BROWSER_STORAGE_SYNC_RETRY_JITTER_PERCENT,
        reset_retry_attempt,
        diagnostic_reasons,
        result_policy:
            "Classify provider account/session, cloud-store readiness, and cloud membership readiness before browser sync starts without moving OAuth, secure credential storage, provider SDK IO, or UI wording into Rust."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_provider_error_classification_value(
    provider_errors: &Value,
    retry_attempt: u32,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudProviderErrorClassificationPlan> {
    if !provider_errors.is_object() && !provider_errors.is_array() {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let provider_kind = browser_storage_sync_cloud_provider_error_batch_string(
        provider_errors,
        &["providerKind", "provider"],
    )
    .map(|provider_kind| {
        normalize_sync_text(&provider_kind, "unknownProvider", MAX_SYNC_TEXT_LENGTH)
    })
    .unwrap_or_else(|| "unknownProvider".to_string());
    let source_plan_type = provider_errors
        .get("planType")
        .and_then(Value::as_str)
        .map(|plan_type| normalize_sync_text(plan_type, "providerErrorBatch", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "providerErrorBatch".to_string());

    let error_values = browser_storage_sync_cloud_provider_error_batch_items(provider_errors);
    let errors = error_values
        .iter()
        .enumerate()
        .filter_map(|(index, error)| {
            browser_storage_sync_cloud_provider_error_classification(error, index as u32)
        })
        .collect::<Vec<_>>();

    let mut diagnostic_reasons = BTreeSet::new();
    for error in &errors {
        diagnostic_reasons.insert(error.diagnostic_reason.clone());
    }

    let failed_count = errors.len().min(u32::MAX as usize) as u32;
    let retryable_failure_count = errors
        .iter()
        .filter(|error| error.retryable)
        .count()
        .min(u32::MAX as usize) as u32;
    let conflict_count = errors
        .iter()
        .filter(|error| error.canonical_error_kind == "conflict")
        .count()
        .min(u32::MAX as usize) as u32;
    let auth_failure_count = errors
        .iter()
        .filter(|error| error.canonical_error_kind == "unauthorized")
        .count()
        .min(u32::MAX as usize) as u32;
    let quota_failure_count = errors
        .iter()
        .filter(|error| error.canonical_error_kind == "quotaExceeded")
        .count()
        .min(u32::MAX as usize) as u32;
    let should_reread_cloud = errors.iter().any(|error| error.should_reread_cloud);
    let requires_user_action = errors.iter().any(|error| error.requires_user_action);

    let classification = browser_storage_sync_cloud_provider_error_batch_classification(&errors);
    let retry_attempt = retry_attempt.min(16);
    let should_retry = browser_storage_sync_cloud_provider_error_batch_should_retry(
        &classification,
        retryable_failure_count,
        should_reread_cloud,
        requires_user_action,
    );
    let retry_delay_seconds = if classification == "providerUnavailable" && should_retry {
        Some(browser_storage_sync_retry_delay_seconds(retry_attempt))
    } else {
        None
    };
    let (scheduler_action, provider_action, user_action, telemetry_level, reset_retry_attempt) =
        browser_storage_sync_cloud_provider_error_batch_actions(
            &classification,
            should_retry,
            should_reread_cloud,
        );
    let requires_provider_recovery =
        browser_storage_sync_cloud_provider_error_requires_recovery(&classification);

    Some(BrowserStorageSyncCloudProviderErrorClassificationPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudProviderErrorClassification".to_string(),
        observed_at_unix_seconds: observed_at,
        provider_kind,
        source_plan_type,
        operation_count: error_values.len().min(u32::MAX as usize) as u32,
        failed_count,
        retryable_failure_count,
        conflict_count,
        auth_failure_count,
        quota_failure_count,
        classification,
        should_retry,
        should_reread_cloud,
        requires_provider_recovery,
        requires_user_action,
        scheduler_action,
        provider_action,
        user_action,
        telemetry_level,
        retry_attempt,
        retry_delay_seconds,
        retry_delay_ceiling_seconds: BROWSER_STORAGE_SYNC_RETRY_MAX_SECONDS,
        retry_jitter_percent: BROWSER_STORAGE_SYNC_RETRY_JITTER_PERCENT,
        reset_retry_attempt,
        errors,
        diagnostic_reasons: diagnostic_reasons.into_iter().collect(),
        result_policy:
            "Classify provider SDK/OpenDAL/native error batches into canonical cloud sync retry, reread, and provider-recovery actions while leaving concrete SDK IO, OAuth prompts, secure storage, and UI copy platform-owned."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_provider_error_classification(
    error: &Value,
    fallback_index: u32,
) -> Option<BrowserStorageSyncCloudProviderErrorClassification> {
    if !error.is_object() {
        return None;
    }
    if error
        .get("success")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        && browser_storage_sync_cloud_provider_error_explicit_kind(error).is_none()
    {
        return None;
    }

    let operation_index = browser_storage_sync_cloud_provider_error_u32(
        error,
        &["operationIndex", "operation_index", "index"],
    )
    .unwrap_or(fallback_index);
    let operation_type = browser_storage_sync_cloud_provider_error_string(
        error,
        &["operationType", "operation", "type"],
    )
    .map(|operation_type| {
        normalize_sync_text(&operation_type, "providerOperation", MAX_SYNC_TEXT_LENGTH)
    })
    .unwrap_or_else(|| "providerOperation".to_string());
    let path = browser_storage_sync_cloud_provider_error_string(error, &["path", "objectPath"])
        .map(|path| normalize_sync_text(&path, "", MAX_SYNC_URL_LENGTH))
        .filter(|path| !path.is_empty());
    let source_error_kind = browser_storage_sync_cloud_provider_error_explicit_kind(error)
        .map(|kind| normalize_sync_text(&kind, "", MAX_SYNC_TEXT_LENGTH))
        .filter(|kind| !kind.is_empty());
    let provider_status_code = browser_storage_sync_cloud_provider_error_i64(
        error,
        &["providerStatusCode", "statusCode", "httpStatus", "status"],
    );
    let provider_error_code = browser_storage_sync_cloud_provider_error_string(
        error,
        &["providerErrorCode", "errorCode", "code"],
    )
    .map(|code| normalize_sync_text(&code, "", MAX_SYNC_TEXT_LENGTH))
    .filter(|code| !code.is_empty());
    let message = browser_storage_sync_cloud_provider_error_string(
        error,
        &["message", "errorMessage", "providerMessage"],
    )
    .map(|message| normalize_sync_text(&message, "", MAX_SYNC_URL_LENGTH))
    .filter(|message| !message.is_empty());

    let canonical_error_kind = browser_storage_sync_cloud_provider_error_canonical_kind(error);
    let retryable = error
        .get("retryable")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| {
            browser_storage_sync_cloud_provider_error_kind_default_retryable(
                &canonical_error_kind,
                &operation_type,
            )
        });
    let should_reread_cloud =
        browser_storage_sync_cloud_provider_error_should_reread(&canonical_error_kind);
    let requires_user_action =
        browser_storage_sync_cloud_provider_error_kind_requires_user_action(&canonical_error_kind);
    let requires_provider_recovery =
        browser_storage_sync_cloud_provider_error_kind_requires_provider_recovery(
            &canonical_error_kind,
            retryable,
        );
    let action = browser_storage_sync_cloud_provider_error_action(
        &canonical_error_kind,
        retryable,
        should_reread_cloud,
    );
    let diagnostic_reason =
        browser_storage_sync_cloud_provider_error_diagnostic_reason(&canonical_error_kind);

    Some(BrowserStorageSyncCloudProviderErrorClassification {
        operation_index,
        operation_type,
        path,
        source_error_kind,
        canonical_error_kind,
        provider_status_code,
        provider_error_code,
        message,
        retryable,
        should_reread_cloud,
        requires_provider_recovery,
        requires_user_action,
        action,
        diagnostic_reason,
    })
}

fn browser_storage_sync_cloud_provider_error_batch_items(provider_errors: &Value) -> Vec<Value> {
    let mut items = Vec::new();
    browser_storage_sync_cloud_provider_error_collect_items(provider_errors, &mut items);
    if items.len() > MAX_BROWSER_STORAGE_SYNC_RECORDS {
        items.truncate(MAX_BROWSER_STORAGE_SYNC_RECORDS);
    }
    items
}

fn browser_storage_sync_cloud_provider_error_collect_items(value: &Value, items: &mut Vec<Value>) {
    if items.len() >= MAX_BROWSER_STORAGE_SYNC_RECORDS {
        return;
    }

    if let Some(array) = value.as_array() {
        for item in array {
            browser_storage_sync_cloud_provider_error_collect_array_item(item, items);
            if items.len() >= MAX_BROWSER_STORAGE_SYNC_RECORDS {
                break;
            }
        }
        return;
    }

    let Some(object) = value.as_object() else {
        return;
    };

    for key in [
        "errors",
        "providerErrors",
        "operationErrors",
        "failedOperations",
        "issues",
    ] {
        if let Some(array) = object.get(key).and_then(Value::as_array) {
            for item in array {
                browser_storage_sync_cloud_provider_error_collect_array_item(item, items);
                if items.len() >= MAX_BROWSER_STORAGE_SYNC_RECORDS {
                    return;
                }
            }
        }
    }

    for key in [
        "operationResults",
        "readResults",
        "writeResults",
        "deleteResults",
    ] {
        if let Some(array) = object.get(key).and_then(Value::as_array) {
            for item in array {
                if browser_storage_sync_cloud_provider_error_is_failed_operation_result(item) {
                    items.push(item.clone());
                    if items.len() >= MAX_BROWSER_STORAGE_SYNC_RECORDS {
                        return;
                    }
                }
            }
        }
    }

    if browser_storage_sync_cloud_provider_error_is_direct_item(value) {
        items.push(value.clone());
        if items.len() >= MAX_BROWSER_STORAGE_SYNC_RECORDS {
            return;
        }
    }

    for key in [
        "source",
        "round",
        "roundResult",
        "cycleRound",
        "pushRound",
        "pullRound",
        "membershipRound",
        "compactionRound",
        "cleanupRound",
        "recoverySnapshotRound",
        "resultPlan",
    ] {
        if let Some(nested) = object.get(key) {
            browser_storage_sync_cloud_provider_error_collect_items(nested, items);
            if items.len() >= MAX_BROWSER_STORAGE_SYNC_RECORDS {
                return;
            }
        }
    }
}

fn browser_storage_sync_cloud_provider_error_collect_array_item(
    item: &Value,
    items: &mut Vec<Value>,
) {
    if items.len() >= MAX_BROWSER_STORAGE_SYNC_RECORDS {
        return;
    }
    if browser_storage_sync_cloud_provider_error_is_direct_item(item)
        || browser_storage_sync_cloud_provider_error_is_failed_operation_result(item)
    {
        items.push(item.clone());
    } else if item.is_object() || item.is_array() {
        browser_storage_sync_cloud_provider_error_collect_items(item, items);
    }
}

fn browser_storage_sync_cloud_provider_error_is_failed_operation_result(value: &Value) -> bool {
    let Some(object) = value.as_object() else {
        return false;
    };
    if object
        .get("success")
        .and_then(Value::as_bool)
        .map(|success| !success)
        .unwrap_or(false)
    {
        return true;
    }
    browser_storage_sync_cloud_provider_error_is_direct_item(value)
}

fn browser_storage_sync_cloud_provider_error_is_direct_item(value: &Value) -> bool {
    value.is_object()
        && (browser_storage_sync_cloud_provider_error_explicit_kind(value).is_some()
            || browser_storage_sync_cloud_provider_error_i64(
                value,
                &["providerStatusCode", "statusCode", "httpStatus", "status"],
            )
            .is_some()
            || browser_storage_sync_cloud_provider_error_string(
                value,
                &["providerErrorCode", "errorCode", "code"],
            )
            .is_some())
}

fn browser_storage_sync_cloud_provider_error_batch_classification(
    errors: &[BrowserStorageSyncCloudProviderErrorClassification],
) -> String {
    if errors.is_empty() {
        return "ready".to_string();
    }
    let has_kind = |kind: &str| {
        errors
            .iter()
            .any(|error| error.canonical_error_kind == kind)
    };
    if has_kind("unauthorized") {
        return "authExpired".to_string();
    }
    if has_kind("quotaExceeded") {
        return "quotaExceeded".to_string();
    }
    if has_kind("cloudDocumentInvalid") {
        return "recoveryRequired".to_string();
    }
    if has_kind("unsupported") || has_kind("invalidPath") {
        return "adapterUnsupported".to_string();
    }
    if has_kind("storage") {
        return "storageSetupRequired".to_string();
    }
    if has_kind("conflict") || has_kind("notFound") {
        return "cloudStateRereadRequired".to_string();
    }
    if has_kind("network") || has_kind("rateLimited") || errors.iter().any(|error| error.retryable)
    {
        return "providerUnavailable".to_string();
    }
    "providerRecoveryRequired".to_string()
}

fn browser_storage_sync_cloud_provider_error_batch_should_retry(
    classification: &str,
    retryable_failure_count: u32,
    should_reread_cloud: bool,
    requires_user_action: bool,
) -> bool {
    if requires_user_action {
        return false;
    }
    matches!(
        classification,
        "cloudStateRereadRequired" | "providerUnavailable"
    ) && (retryable_failure_count > 0 || should_reread_cloud)
}

fn browser_storage_sync_cloud_provider_error_requires_recovery(classification: &str) -> bool {
    matches!(
        classification,
        "authExpired"
            | "quotaExceeded"
            | "recoveryRequired"
            | "adapterUnsupported"
            | "storageSetupRequired"
            | "providerRecoveryRequired"
    )
}

fn browser_storage_sync_cloud_provider_error_batch_actions(
    classification: &str,
    should_retry: bool,
    should_reread_cloud: bool,
) -> (String, String, String, String, bool) {
    let actions = match classification {
        "ready" => ("idle", "none", "none", "info", true),
        "authExpired" => (
            "waitForProviderCredentials",
            "reconnectProvider",
            "reconnectProvider",
            "warning",
            false,
        ),
        "quotaExceeded" => (
            "waitForProviderStorage",
            "freeCloudStorageOrReduceRetention",
            "freeCloudStorageOrReduceRetention",
            "warning",
            false,
        ),
        "recoveryRequired" => (
            "stopUntilCloudRepair",
            "recoverCloudDocument",
            "recoverCloudData",
            "error",
            false,
        ),
        "adapterUnsupported" => (
            "stopUntilProviderFix",
            "fixProviderAdapter",
            "reportProviderIssue",
            "error",
            false,
        ),
        "storageSetupRequired" => (
            "waitForProviderStorage",
            "configureProviderStorage",
            "chooseProviderFolder",
            "warning",
            false,
        ),
        "cloudStateRereadRequired" if should_reread_cloud => {
            ("runCloudReread", "rereadCloudState", "none", "info", false)
        }
        "providerUnavailable" if should_retry => (
            "scheduleRetry",
            "retryProviderOperation",
            "none",
            "warning",
            false,
        ),
        _ => (
            "stopUntilProviderRecovery",
            "recoverProvider",
            "reviewSyncStatus",
            "warning",
            false,
        ),
    };
    (
        actions.0.to_string(),
        actions.1.to_string(),
        actions.2.to_string(),
        actions.3.to_string(),
        actions.4,
    )
}

fn browser_storage_sync_cloud_provider_error_canonical_kind(error: &Value) -> String {
    let explicit = browser_storage_sync_cloud_provider_error_explicit_kind(error);
    let provider_code = browser_storage_sync_cloud_provider_error_string(
        error,
        &["providerErrorCode", "errorCode", "code"],
    );
    for candidate in [explicit.as_deref(), provider_code.as_deref()]
        .into_iter()
        .flatten()
    {
        let canonical =
            browser_storage_sync_cloud_provider_error_canonical_kind_from_text(candidate);
        if canonical != "providerFailure" {
            return canonical;
        }
    }

    if let Some(status_code) = browser_storage_sync_cloud_provider_error_i64(
        error,
        &["providerStatusCode", "statusCode", "httpStatus", "status"],
    ) {
        return browser_storage_sync_cloud_provider_error_canonical_kind_from_status(status_code);
    }

    explicit
        .as_deref()
        .map(browser_storage_sync_cloud_provider_error_canonical_kind_from_text)
        .unwrap_or_else(|| "providerFailure".to_string())
}

fn browser_storage_sync_cloud_provider_error_canonical_kind_from_status(
    status_code: i64,
) -> String {
    match status_code {
        401 | 403 => "unauthorized",
        404 => "notFound",
        408 => "network",
        409 | 412 => "conflict",
        413 | 507 => "quotaExceeded",
        429 => "rateLimited",
        500..=599 => "network",
        400 => "invalidPath",
        _ => "providerFailure",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_error_canonical_kind_from_text(kind: &str) -> String {
    let compact = kind
        .trim()
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect::<String>();
    let mapped = match compact.as_str() {
        "auth" | "authrequired" | "unauthorized" | "forbidden" | "credentialexpired"
        | "credentialrevoked" | "tokenexpired" | "invalidgrant" => "unauthorized",
        "quota" | "quotaexceeded" | "insufficientstorage" | "storagequotaexceeded" => {
            "quotaExceeded"
        }
        "ratelimited" | "toomanyrequests" | "throttled" | "throttle" => "rateLimited",
        "network"
        | "transport"
        | "timeout"
        | "offline"
        | "providerunavailable"
        | "serviceunavailable"
        | "temporarilyunavailable" => "network",
        "conflict" | "revisionmismatch" | "preconditionfailed" | "etagmismatch" => "conflict",
        "notfound" | "missing" | "missingobject" | "filenotfound" => "notFound",
        "storage" | "permission" | "rootpathmissing" | "providersetuprequired" => "storage",
        "invalidpath" | "pathtraversal" | "pathoutsideactroroot" => "invalidPath",
        "unsupported" | "adapterunsupported" | "providerunsupported" => "unsupported",
        "invaliddocument"
        | "invalidclouddocument"
        | "clouddocumentinvalid"
        | "recoveryrequired"
        | "corrupt"
        | "parseerror" => "cloudDocumentInvalid",
        "provider" | "providerfailure" => "providerFailure",
        _ => return normalize_cloud_error_kind(kind),
    };
    mapped.to_string()
}

fn browser_storage_sync_cloud_provider_error_kind_default_retryable(
    kind: &str,
    operation_type: &str,
) -> bool {
    matches!(kind, "conflict" | "network" | "rateLimited")
        || (kind == "notFound" && operation_type != "deleteLog")
}

fn browser_storage_sync_cloud_provider_error_should_reread(kind: &str) -> bool {
    matches!(kind, "conflict" | "notFound")
}

fn browser_storage_sync_cloud_provider_error_kind_requires_user_action(kind: &str) -> bool {
    matches!(kind, "unauthorized" | "quotaExceeded" | "storage")
}

fn browser_storage_sync_cloud_provider_error_kind_requires_provider_recovery(
    kind: &str,
    retryable: bool,
) -> bool {
    matches!(
        kind,
        "unauthorized"
            | "quotaExceeded"
            | "storage"
            | "invalidPath"
            | "unsupported"
            | "cloudDocumentInvalid"
    ) || (kind == "providerFailure" && !retryable)
}

fn browser_storage_sync_cloud_provider_error_action(
    kind: &str,
    retryable: bool,
    should_reread_cloud: bool,
) -> String {
    if should_reread_cloud {
        return "rereadCloudAndReplan".to_string();
    }
    match kind {
        "unauthorized" => "reconnectProvider",
        "quotaExceeded" => "freeCloudStorageOrReduceRetention",
        "rateLimited" | "network" => "retryProviderOperation",
        "storage" => "configureProviderStorage",
        "invalidPath" | "unsupported" => "fixProviderAdapter",
        "cloudDocumentInvalid" => "recoverCloudDocument",
        _ if retryable => "retryProviderOperation",
        _ => "recoverProvider",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_error_diagnostic_reason(kind: &str) -> String {
    match kind {
        "cloudDocumentInvalid" => "invalidCloudDocument",
        "storage" => "providerSetupRequired",
        other => other,
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_error_explicit_kind(error: &Value) -> Option<String> {
    browser_storage_sync_cloud_provider_error_string(
        error,
        &[
            "canonicalErrorKind",
            "errorKind",
            "kind",
            "providerErrorKind",
            "lastProviderErrorKind",
            "planningErrorKind",
            "reason",
        ],
    )
}

fn browser_storage_sync_cloud_provider_error_batch_string(
    value: &Value,
    keys: &[&str],
) -> Option<String> {
    keys.iter()
        .find_map(|key| value.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn browser_storage_sync_cloud_provider_error_string(
    value: &Value,
    keys: &[&str],
) -> Option<String> {
    keys.iter()
        .find_map(|key| value.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn browser_storage_sync_cloud_provider_error_i64(value: &Value, keys: &[&str]) -> Option<i64> {
    keys.iter().find_map(|key| {
        value
            .get(*key)
            .and_then(|value| value.as_i64().or_else(|| value.as_str()?.parse().ok()))
    })
}

fn browser_storage_sync_cloud_provider_error_u32(value: &Value, keys: &[&str]) -> Option<u32> {
    browser_storage_sync_cloud_provider_error_i64(value, keys)
        .and_then(|value| u32::try_from(value.max(0)).ok())
}

fn browser_storage_sync_cloud_provider_snapshot_string(
    provider_snapshot: &Value,
    keys: &[&str],
) -> Option<String> {
    keys.iter()
        .find_map(|key| provider_snapshot.get(*key).and_then(Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn browser_storage_sync_cloud_provider_snapshot_bool(
    provider_snapshot: &Value,
    keys: &[&str],
) -> Option<bool> {
    keys.iter()
        .find_map(|key| provider_snapshot.get(*key).and_then(Value::as_bool))
}

fn browser_storage_sync_cloud_provider_connection_state(state: Option<&str>) -> String {
    match state.unwrap_or("disconnected").trim() {
        "connected" | "ready" | "available" => "connected",
        "connecting" | "authorizing" | "refreshing" => "connecting",
        "error" | "failed" => "error",
        "notSelected" => "notSelected",
        _ => "disconnected",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_credential_state(state: Option<&str>) -> String {
    match state.unwrap_or("missing").trim() {
        "available" | "valid" | "fresh" => "available",
        "expired" | "stale" => "expired",
        "revoked" | "denied" => "revoked",
        "unknown" => "unknown",
        _ => "missing",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_membership_status(status: Option<&str>) -> String {
    match status.unwrap_or("unknown").trim() {
        "active" | "joined" => "active",
        "missing" | "notJoined" => "missing",
        "revoked" | "disabled" => "revoked",
        _ => "unknown",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_is_unknown(provider_kind: &str) -> bool {
    matches!(
        provider_kind,
        "" | "unknownProvider" | "none" | "notSelected"
    )
}

fn browser_storage_sync_cloud_provider_collect_snapshot_reasons(
    provider_snapshot: &Value,
    diagnostic_reasons: &mut Vec<String>,
) {
    if let Some(reasons) = provider_snapshot
        .get("diagnosticReasons")
        .and_then(Value::as_array)
    {
        for reason in reasons.iter().filter_map(Value::as_str) {
            browser_storage_sync_cloud_cycle_collect_reason(diagnostic_reasons, Some(reason));
        }
    }
    for pointer in [
        "/capabilityPreflight/missingRequiredCapabilities",
        "/capabilityPreflight/degradedCapabilities",
    ] {
        if let Some(reasons) = provider_snapshot.pointer(pointer).and_then(Value::as_array) {
            for reason in reasons.iter().filter_map(Value::as_str) {
                browser_storage_sync_cloud_cycle_collect_reason(diagnostic_reasons, Some(reason));
            }
        }
    }
}

fn browser_storage_sync_cloud_provider_collect_connection_reason(
    connection_state: &str,
    diagnostic_reasons: &mut Vec<String>,
) {
    let reason = match connection_state {
        "connecting" => "providerConnectionInProgress",
        "error" => "providerConnectionFailed",
        "notSelected" => "providerNotSelected",
        _ => "providerDisconnected",
    };
    browser_storage_sync_cloud_cycle_collect_reason(diagnostic_reasons, Some(reason));
}

fn browser_storage_sync_cloud_provider_collect_credential_reason(
    credential_state: &str,
    diagnostic_reasons: &mut Vec<String>,
) {
    let reason = match credential_state {
        "expired" => "credentialExpired",
        "revoked" => "credentialRevoked",
        "unknown" => "credentialUnknown",
        _ => "credentialMissing",
    };
    browser_storage_sync_cloud_cycle_collect_reason(diagnostic_reasons, Some(reason));
}

fn browser_storage_sync_cloud_provider_collect_membership_reason(
    membership_status: &str,
    diagnostic_reasons: &mut Vec<String>,
) {
    let reason = match membership_status {
        "revoked" => "deviceMembershipRevoked",
        "missing" => "deviceMembershipMissing",
        _ => "deviceMembershipUnknown",
    };
    browser_storage_sync_cloud_cycle_collect_reason(diagnostic_reasons, Some(reason));
}

#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_provider_connection_classification(
    provider_kind: &str,
    connection_state: &str,
    credential_state: &str,
    connected: bool,
    credentials_available: bool,
    cloud_store_ready: bool,
    membership_ready: bool,
    last_provider_error_kind: Option<&str>,
    capability_classification: Option<&str>,
    capability_should_block: bool,
) -> String {
    if browser_storage_sync_cloud_provider_is_unknown(provider_kind) {
        return "providerNotSelected".to_string();
    }
    if browser_storage_sync_cloud_provider_error_is_auth(last_provider_error_kind)
        || matches!(credential_state, "expired" | "revoked")
    {
        return "authExpired".to_string();
    }
    if !credentials_available || matches!(connection_state, "disconnected" | "notSelected") {
        return "signInRequired".to_string();
    }
    if browser_storage_sync_cloud_provider_error_matches(
        last_provider_error_kind,
        &["quota", "providerQuotaExceeded"],
    ) || capability_classification == Some("providerLimitTooSmall")
    {
        return "quotaExceeded".to_string();
    }
    if browser_storage_sync_cloud_provider_error_matches(
        last_provider_error_kind,
        &["unsupported", "adapterUnsupported", "providerUnsupported"],
    ) || matches!(
        capability_classification,
        Some("providerContractInvalid" | "providerConflictUnsafe")
    ) {
        return "adapterUnsupported".to_string();
    }
    if browser_storage_sync_cloud_provider_error_matches(
        last_provider_error_kind,
        &[
            "invalidDocument",
            "cloudDocumentInvalid",
            "recoveryRequired",
        ],
    ) {
        return "recoveryRequired".to_string();
    }
    if browser_storage_sync_cloud_provider_error_matches(
        last_provider_error_kind,
        &[
            "network",
            "rateLimited",
            "providerUnavailable",
            "timeout",
            "offline",
        ],
    ) || connection_state == "connecting"
    {
        return "providerUnavailable".to_string();
    }
    if !cloud_store_ready
        || capability_should_block
        || capability_classification == Some("providerSetupRequired")
        || browser_storage_sync_cloud_provider_error_matches(
            last_provider_error_kind,
            &["storage", "permission", "rootPathMissing"],
        )
    {
        return "storageSetupRequired".to_string();
    }
    if !connected || connection_state == "error" {
        return "providerUnavailable".to_string();
    }
    if !membership_ready {
        return "membershipRequired".to_string();
    }
    "ready".to_string()
}

fn browser_storage_sync_cloud_provider_error_is_auth(error_kind: Option<&str>) -> bool {
    browser_storage_sync_cloud_provider_error_matches(
        error_kind,
        &[
            "auth",
            "unauthorized",
            "forbidden",
            "credentialExpired",
            "credentialRevoked",
        ],
    )
}

fn browser_storage_sync_cloud_provider_error_matches(
    error_kind: Option<&str>,
    candidates: &[&str],
) -> bool {
    error_kind
        .map(|error_kind| {
            candidates
                .iter()
                .any(|candidate| error_kind.eq_ignore_ascii_case(candidate))
        })
        .unwrap_or(false)
}

fn browser_storage_sync_cloud_provider_connection_actions(
    classification: &str,
    should_retry: bool,
) -> (String, String, String, String, bool) {
    let (scheduler_action, provider_action, user_action, telemetry_level, reset_retry_attempt) =
        match classification {
            "ready" => ("idle", "none", "none", "info", true),
            "providerNotSelected" => (
                "waitForProviderSelection",
                "selectProvider",
                "chooseSyncProvider",
                "warning",
                false,
            ),
            "signInRequired" => (
                "waitForProviderCredentials",
                "connectProvider",
                "connectProvider",
                "warning",
                false,
            ),
            "authExpired" => (
                "waitForProviderCredentials",
                "reconnectProvider",
                "reconnectProvider",
                "warning",
                false,
            ),
            "storageSetupRequired" => (
                "waitForProviderStorage",
                "configureProviderStorage",
                "chooseProviderFolder",
                "warning",
                false,
            ),
            "quotaExceeded" => (
                "waitForProviderStorage",
                "freeCloudStorageOrReduceRetention",
                "freeCloudStorageOrReduceRetention",
                "warning",
                false,
            ),
            "adapterUnsupported" => (
                "stopUntilProviderFix",
                "reportProviderBug",
                "reportProviderIssue",
                "error",
                false,
            ),
            "membershipRequired" => (
                "runCloudMembership",
                "writeCloudMembership",
                "none",
                "info",
                true,
            ),
            "recoveryRequired" => (
                "stopUntilCloudRepair",
                "recoverCloudDocument",
                "recoverCloudData",
                "error",
                false,
            ),
            "providerUnavailable" if should_retry => (
                "scheduleRetry",
                "retryProviderConnection",
                "none",
                "warning",
                false,
            ),
            _ => (
                "stopUntilProviderRecovery",
                "recoverProvider",
                "reviewSyncStatus",
                "warning",
                false,
            ),
        };

    (
        scheduler_action.to_string(),
        provider_action.to_string(),
        user_action.to_string(),
        telemetry_level.to_string(),
        reset_retry_attempt,
    )
}

#[derive(Debug, Clone)]
struct BrowserStorageSyncCloudProviderAdapterPreflightSnapshot {
    capabilities: Option<BrowserStorageSyncCloudStoreCapabilities>,
    classification: String,
    should_block_sync: bool,
    requires_adapter_emulation: bool,
    missing_required_capabilities: Vec<String>,
    degraded_capabilities: Vec<String>,
    warnings: Vec<String>,
    snapshot_missing: bool,
}

fn browser_storage_sync_cloud_provider_adapter_preflight_snapshot(
    adapter_snapshot: &Value,
    observed_at_unix_seconds: i64,
) -> BrowserStorageSyncCloudProviderAdapterPreflightSnapshot {
    let explicit_preflight = if adapter_snapshot
        .get("planType")
        .and_then(Value::as_str)
        .map(|plan_type| plan_type == "cloudStoreCapabilityPreflight")
        .unwrap_or(false)
    {
        Some(adapter_snapshot)
    } else {
        adapter_snapshot.get("capabilityPreflight")
    };

    if let Some(preflight) = explicit_preflight {
        let capabilities =
            browser_storage_sync_cloud_provider_adapter_capabilities_from_value(preflight)
                .or_else(|| {
                    browser_storage_sync_cloud_provider_adapter_capabilities_from_value(
                        adapter_snapshot,
                    )
                })
                .map(normalize_browser_storage_sync_cloud_store_capabilities);
        let classification = preflight
            .get("classification")
            .and_then(Value::as_str)
            .map(|classification| {
                normalize_sync_text(
                    classification,
                    "providerContractInvalid",
                    MAX_SYNC_TEXT_LENGTH,
                )
            })
            .unwrap_or_else(|| "providerContractInvalid".to_string());
        let should_block_sync = preflight
            .get("shouldBlockSync")
            .and_then(Value::as_bool)
            .unwrap_or(matches!(
                classification.as_str(),
                "providerContractInvalid"
                    | "providerSetupRequired"
                    | "providerLimitTooSmall"
                    | "providerConflictUnsafe"
            ));
        let requires_adapter_emulation = preflight
            .get("requiresAdapterEmulation")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        return BrowserStorageSyncCloudProviderAdapterPreflightSnapshot {
            capabilities,
            classification,
            should_block_sync,
            requires_adapter_emulation,
            missing_required_capabilities: browser_storage_sync_cloud_provider_adapter_string_array(
                preflight.get("missingRequiredCapabilities"),
            ),
            degraded_capabilities: browser_storage_sync_cloud_provider_adapter_string_array(
                preflight.get("degradedCapabilities"),
            ),
            warnings: browser_storage_sync_cloud_provider_adapter_string_array(
                preflight.get("warnings"),
            ),
            snapshot_missing: false,
        };
    }

    if let Some(capabilities) =
        browser_storage_sync_cloud_provider_adapter_capabilities_from_value(adapter_snapshot)
    {
        let plan = browser_storage_sync_cloud_store_capability_preflight(
            &serialize_json(&capabilities),
            observed_at_unix_seconds,
        );
        return BrowserStorageSyncCloudProviderAdapterPreflightSnapshot {
            capabilities: plan.capabilities,
            classification: plan.classification,
            should_block_sync: plan.should_block_sync,
            requires_adapter_emulation: plan.requires_adapter_emulation,
            missing_required_capabilities: plan.missing_required_capabilities,
            degraded_capabilities: plan.degraded_capabilities,
            warnings: plan.warnings,
            snapshot_missing: false,
        };
    }

    BrowserStorageSyncCloudProviderAdapterPreflightSnapshot {
        capabilities: None,
        classification: "adapterSnapshotIncomplete".to_string(),
        should_block_sync: true,
        requires_adapter_emulation: false,
        missing_required_capabilities: vec!["capabilities".to_string()],
        degraded_capabilities: Vec::new(),
        warnings: vec![
            "Adapter snapshot did not include capabilities or capabilityPreflight.".to_string(),
        ],
        snapshot_missing: true,
    }
}

fn browser_storage_sync_cloud_provider_adapter_capabilities_from_value(
    value: &Value,
) -> Option<BrowserStorageSyncCloudStoreCapabilities> {
    serde_json::from_value::<BrowserStorageSyncCloudStoreCapabilities>(value.clone())
        .ok()
        .or_else(|| {
            value.get("capabilities").and_then(|capabilities| {
                serde_json::from_value::<BrowserStorageSyncCloudStoreCapabilities>(
                    capabilities.clone(),
                )
                .ok()
            })
        })
        .or_else(|| {
            value
                .get("cloudStoreCapabilities")
                .and_then(|capabilities| {
                    serde_json::from_value::<BrowserStorageSyncCloudStoreCapabilities>(
                        capabilities.clone(),
                    )
                    .ok()
                })
        })
        .or_else(|| {
            value
                .pointer("/capabilityPreflight/capabilities")
                .and_then(|capabilities| {
                    serde_json::from_value::<BrowserStorageSyncCloudStoreCapabilities>(
                        capabilities.clone(),
                    )
                    .ok()
                })
        })
}

fn browser_storage_sync_cloud_provider_adapter_string_array(value: Option<&Value>) -> Vec<String> {
    let Some(values) = value.and_then(Value::as_array) else {
        return Vec::new();
    };
    let mut result = values
        .iter()
        .filter_map(Value::as_str)
        .map(|value| normalize_sync_text(value, "", MAX_SYNC_TEXT_LENGTH))
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>();
    result.sort();
    result.dedup();
    result
}

fn browser_storage_sync_cloud_provider_adapter_family(provider_kind: &str) -> String {
    let compact = provider_kind
        .trim()
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect::<String>();
    match compact.as_str() {
        "icloud" | "iclouddrive" | "cloudkit" => "appleNative",
        "google" | "googledrive" | "onedrive" | "dropbox" => "platformNative",
        "opendal" | "webdav" | "s3" | "gcs" | "azblob" => "opendal",
        "localfolder" => "localFolder",
        "memory" | "test" | "testfixture" => "testFixture",
        _ => "platformNative",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_adapter_is_test_fixture(
    provider_kind: &str,
    adapter_family: &str,
) -> bool {
    let provider = provider_kind.trim().to_ascii_lowercase();
    let family = adapter_family.trim().to_ascii_lowercase();
    provider == "memory" || family == "testfixture" || family == "memory"
}

fn browser_storage_sync_cloud_provider_adapter_actions(
    classification: &str,
    requires_adapter_emulation: bool,
    test_fixture: bool,
) -> (String, String, String) {
    if test_fixture && classification == "ready" {
        return (
            "useForTestsOnly".to_string(),
            "keepOutOfProductionProviderList".to_string(),
            "none".to_string(),
        );
    }
    match classification {
        "ready" => (
            "useActroBrowserSyncRoot".to_string(),
            "continueProviderSync".to_string(),
            "none".to_string(),
        ),
        "degraded" if requires_adapter_emulation => (
            "useActroBrowserSyncRoot".to_string(),
            "enableAdapterEmulation".to_string(),
            "none".to_string(),
        ),
        "providerSetupRequired" => (
            "configureActroBrowserSyncRoot".to_string(),
            "exposeActroBrowserSyncRoot".to_string(),
            "chooseProviderFolder".to_string(),
        ),
        "providerLimitTooSmall" => (
            "useDifferentProviderRoot".to_string(),
            "increaseProviderObjectSizeLimit".to_string(),
            "chooseProviderWithLargerFiles".to_string(),
        ),
        "providerConflictUnsafe" => (
            "stopBeforeProviderWrites".to_string(),
            "enableOptimisticRevisionWrites".to_string(),
            "chooseProviderSupportingRevisions".to_string(),
        ),
        "adapterSnapshotIncomplete" => (
            "collectProviderCapabilities".to_string(),
            "returnCapabilitySnapshot".to_string(),
            "none".to_string(),
        ),
        _ => (
            "stopBeforeProviderWrites".to_string(),
            "fixProviderAdapter".to_string(),
            "reviewSyncProvider".to_string(),
        ),
    }
}

