pub fn browser_storage_sync_cloud_cycle_client_plan(
    cycle_round: Option<BrowserStorageSyncCloudCycleRoundResult>,
) -> Option<BrowserStorageSyncCloudCycleClientPlan> {
    let mut cycle_round = cycle_round?;
    cycle_round.client_plan.take().or_else(|| {
        browser_storage_sync_cloud_cycle_client_plan_from_parts(
            &cycle_round.scope,
            &cycle_round.device_id,
            cycle_round.generated_at_unix_seconds,
            cycle_round.push_round.as_ref(),
            cycle_round.pull_round.as_ref(),
            cycle_round.completed,
            cycle_round.should_ack_local,
            cycle_round.should_apply_remote,
            cycle_round.should_reread,
            cycle_round.should_retry,
            &cycle_round.client_action,
            cycle_round.planning_error_kind.as_deref(),
        )
    })
}

