/// Adjudicate the native execution of one cloud cycle client plan into the
/// platform-facing result envelope. `step_results_json` is the
/// execution-ordered `[{stepType, success, error}]` array collected by the
/// native side, which may stop early after a failed required step;
/// `remote_apply_result_json` is the summary returned by the remote apply
/// execution ("null" when the applyRemoteBatch step did not run). Rust
/// completes each step with `required` / `operationCount` from the plan,
/// derives `failedStep` / `applied` / `ackApplied` / `remoteApplied`, and
/// owns the canonical step error wording. Any invalid input returns "null".
pub fn browser_storage_sync_cloud_cycle_client_apply_result_json(
    cycle_round_json: &str,
    step_results_json: &str,
    remote_apply_result_json: &str,
) -> String {
    let client_plan_json = browser_storage_sync_cloud_cycle_client_plan_json(cycle_round_json);
    let client_plan = match serde_json::from_str::<Value>(&client_plan_json) {
        Ok(value) if value.is_object() => value,
        _ => return "null".to_string(),
    };
    let cycle_round = match serde_json::from_str::<Value>(cycle_round_json) {
        Ok(value) if value.is_object() => value,
        _ => return "null".to_string(),
    };
    let executed_steps = match serde_json::from_str::<Value>(step_results_json) {
        Ok(Value::Array(steps)) => steps,
        _ => return "null".to_string(),
    };
    let plan_steps = client_plan
        .get("steps")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    if executed_steps.len() > plan_steps.len() {
        return "null".to_string();
    }
    let has_ack_plan = client_plan
        .get("ackPlan")
        .map(Value::is_object)
        .unwrap_or(false);
    let has_remote_apply_plan = client_plan
        .get("remoteApplyPlan")
        .map(Value::is_object)
        .unwrap_or(false);
    let remote_apply_result = serde_json::from_str::<Value>(remote_apply_result_json)
        .ok()
        .filter(Value::is_object)
        .unwrap_or(Value::Null);
    let remote_failed_count = remote_apply_result
        .get("failedCount")
        .and_then(Value::as_i64)
        .unwrap_or(0);

    let mut step_results = Vec::new();
    let mut ack_applied = false;
    let mut remote_applied = false;
    let mut remote_apply_executed = false;
    let mut failed_step = String::new();

    for (index, executed) in executed_steps.iter().enumerate() {
        let executed = match executed.as_object() {
            Some(object) => object,
            None => return "null".to_string(),
        };
        let plan_step = &plan_steps[index];
        let step_type = plan_step
            .get("stepType")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        if executed
            .get("stepType")
            .and_then(Value::as_str)
            .map(|executed_step_type| executed_step_type != step_type)
            .unwrap_or(true)
        {
            return "null".to_string();
        }
        let required = plan_step
            .get("required")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        let operation_count = plan_step
            .get("operationCount")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        let executed_success = match executed.get("success").and_then(Value::as_bool) {
            Some(success) => success,
            None => return "null".to_string(),
        };
        let executed_error = executed
            .get("error")
            .and_then(Value::as_str)
            .map(ToString::to_string);

        let (success, error) = match step_type.as_str() {
            "applyLocalAck" => {
                if !has_ack_plan {
                    (false, Some("missing ackPlan".to_string()))
                } else if executed_success {
                    ack_applied = true;
                    (true, None)
                } else {
                    (false, Some("ack plan execution failed".to_string()))
                }
            }
            "applyRemoteBatch" => {
                remote_apply_executed = true;
                if !has_remote_apply_plan {
                    (false, Some("missing remoteApplyPlan".to_string()))
                } else if !remote_apply_result.is_object() {
                    (
                        false,
                        Some("remote apply plan execution failed".to_string()),
                    )
                } else if remote_failed_count > 0 {
                    (
                        false,
                        Some("remote apply result contains failures".to_string()),
                    )
                } else if executed_success {
                    remote_applied = true;
                    (true, None)
                } else {
                    (false, executed_error)
                }
            }
            _ => {
                if executed_success {
                    (executed_success, None)
                } else {
                    (executed_success, executed_error)
                }
            }
        };

        step_results.push(json!({
            "stepType": step_type,
            "operationCount": operation_count,
            "required": required,
            "success": success,
            "error": error,
        }));

        if !success && required {
            failed_step = step_type;
            break;
        }
    }

    let envelope_remote_apply_result = if remote_apply_executed {
        remote_apply_result
    } else {
        Value::Null
    };

    serialize_json(&json!({
        "version": client_plan.get("version").cloned().unwrap_or(Value::Null),
        "storageSchemaVersion": client_plan
            .get("storageSchemaVersion")
            .cloned()
            .unwrap_or(Value::Null),
        "cloudDataModelVersion": client_plan
            .get("cloudDataModelVersion")
            .cloned()
            .unwrap_or(Value::Null),
        "scope": client_plan.get("scope").cloned().unwrap_or(Value::Null),
        "deviceId": client_plan.get("deviceId").cloned().unwrap_or(Value::Null),
        "generatedAtUnixSeconds": client_plan
            .get("generatedAtUnixSeconds")
            .cloned()
            .unwrap_or(Value::Null),
        "action": client_plan.get("action").cloned().unwrap_or(Value::Null),
        "applied": failed_step.is_empty(),
        "ackApplied": ack_applied,
        "remoteApplied": remote_applied,
        "failedStep": failed_step,
        "remoteApplyResult": envelope_remote_apply_result,
        "stepResults": step_results,
        "cycleRound": cycle_round,
        "clientPlan": client_plan,
    }))
}

