pub fn browser_storage_sync_cycle_request_plan(
    base_url: &str,
    access_token: &str,
    request: Option<BrowserStorageSyncPushRequest>,
    cursors: Option<Vec<BrowserStorageSyncCursorUpdate>>,
) -> Option<BrowserStorageSyncCycleRequestPlan> {
    let request = normalize_browser_storage_sync_push_request(request)?;
    let generated_at = request.generated_at_unix_seconds;
    let cursors = cursors?
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
        .filter_map(|cursor| normalize_browser_storage_sync_cursor(cursor, generated_at))
        .collect::<Vec<_>>();
    let access_token = normalize_sync_access_token(access_token)?;
    let body_json = serde_json::to_string(&json!({
        "pushRequest": request,
        "cursors": cursors,
    }))
    .ok()?;

    Some(BrowserStorageSyncCycleRequestPlan {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        endpoint_type: "syncCycle".to_string(),
        method: "POST".to_string(),
        path: BROWSER_STORAGE_SYNC_TRANSPORT_CYCLE_PATH.to_string(),
        url: browser_storage_sync_url(base_url, BROWSER_STORAGE_SYNC_TRANSPORT_CYCLE_PATH),
        headers: vec![
            sync_request_header(
                BROWSER_STORAGE_SYNC_AUTHORIZATION_HEADER,
                &format!("Bearer {access_token}"),
            ),
            sync_request_header(BROWSER_STORAGE_SYNC_ACCOUNT_HEADER, &request.scope),
            sync_request_header(BROWSER_STORAGE_SYNC_DEVICE_HEADER, &request.device_id),
            sync_request_header("Content-Type", BROWSER_STORAGE_SYNC_CONTENT_TYPE),
            sync_request_header("Accept", BROWSER_STORAGE_SYNC_CONTENT_TYPE),
        ],
        body_json,
        success_status: 200,
        response_contract: "BrowserStorageSyncCycleResponse".to_string(),
        result_classifier: "browserStorageSyncCycleTransportResultJson".to_string(),
        success_apply_action: "applySyncCycleResponse".to_string(),
    })
}

pub fn browser_storage_sync_cycle_transport_result(
    status_code: i32,
    response_json: &str,
    error_message: &str,
) -> BrowserStorageSyncTransportResult {
    let endpoint_type = "syncCycle".to_string();
    let normalized_error = normalize_optional_sync_text(
        (!error_message.trim().is_empty()).then(|| error_message.to_string()),
        MAX_SYNC_TEXT_LENGTH,
    );

    if (200..=299).contains(&status_code) {
        let normalized_response = normalize_browser_storage_sync_cycle_response_json(response_json);
        if normalized_response == "null" {
            return sync_transport_result(
                endpoint_type,
                status_code,
                "protocolError",
                false,
                "discardResponse",
                None,
                normalized_error,
            );
        }

        return sync_transport_result(
            endpoint_type,
            status_code,
            "success",
            false,
            "buildClientCyclePlan",
            serde_json::from_str(&normalized_response).ok(),
            None,
        );
    }

    let (classification, should_retry, client_action) = match status_code {
        i32::MIN..=0 => ("transportError", true, "retryWithBackoff"),
        401 | 403 => ("authRequired", false, "refreshDeviceCredentials"),
        408 | 425 | 429 => ("retryableBackoff", true, "retryWithBackoff"),
        409 | 412 => ("syncPreconditionFailed", false, "pullThenRetry"),
        426 => ("clientUpgradeRequired", false, "upgradeClient"),
        500..=599 => ("serverUnavailable", true, "retryWithBackoff"),
        400..=499 => ("clientRequestRejected", false, "discardResponse"),
        _ => ("unexpectedStatus", false, "discardResponse"),
    };

    sync_transport_result(
        endpoint_type,
        status_code,
        classification,
        should_retry,
        client_action,
        None,
        normalized_error,
    )
}

pub fn browser_storage_sync_status_policy(
    classification: &str,
    should_retry: bool,
    client_action: &str,
    retry_attempt: u32,
) -> BrowserStorageSyncStatusPolicy {
    let classification = normalize_sync_text(classification, "unknown", MAX_SYNC_TEXT_LENGTH);
    let should_retry = should_retry || browser_storage_sync_classification_retries(&classification);
    let client_action = normalize_sync_text(
        client_action,
        default_browser_storage_sync_client_action(&classification, should_retry),
        MAX_SYNC_TEXT_LENGTH,
    );
    let retry_attempt = retry_attempt.min(16);
    let retry_delay_seconds = if should_retry {
        Some(browser_storage_sync_retry_delay_seconds(retry_attempt))
    } else {
        None
    };
    let (scheduler_action, credential_action, user_action, telemetry_level, reset_retry_attempt) =
        match classification.as_str() {
            "success" => ("idle", "none", "none", "info", true),
            "credentialsUnavailable" => (
                "waitForCredentials",
                "refreshUserSession",
                "signIn",
                "info",
                false,
            ),
            "authRequired" => (
                "waitForCredentials",
                "refreshDeviceCredentials",
                "reconnectDevice",
                "warning",
                false,
            ),
            "transportError" | "retryableBackoff" | "serverUnavailable" => {
                ("scheduleRetry", "none", "none", "warning", false)
            }
            "syncPreconditionFailed" => ("pullThenRetry", "none", "none", "info", false),
            "clientUpgradeRequired" => (
                "stopUntilClientUpdate",
                "none",
                "upgradeClient",
                "error",
                false,
            ),
            "clientPlanUnavailable" => ("skipCycle", "none", "none", "info", false),
            "protocolError" => ("discardResponse", "none", "none", "error", false),
            "clientRequestRejected" | "unexpectedStatus" => {
                ("discardResponse", "none", "none", "warning", false)
            }
            _ if should_retry => ("scheduleRetry", "none", "none", "warning", false),
            _ => ("stopUntilNextChange", "none", "none", "warning", false),
        };

    BrowserStorageSyncStatusPolicy {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        classification,
        should_retry,
        client_action,
        scheduler_action: scheduler_action.to_string(),
        credential_action: credential_action.to_string(),
        user_action: user_action.to_string(),
        telemetry_level: telemetry_level.to_string(),
        retry_attempt,
        retry_delay_seconds,
        retry_delay_ceiling_seconds: BROWSER_STORAGE_SYNC_RETRY_MAX_SECONDS,
        retry_jitter_percent: BROWSER_STORAGE_SYNC_RETRY_JITTER_PERCENT,
        reset_retry_attempt,
    }
}

pub fn browser_storage_sync_schedule_state(
    status_policy_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncScheduleState> {
    let policy = serde_json::from_str::<BrowserStorageSyncStatusPolicy>(status_policy_json).ok()?;
    let policy = browser_storage_sync_status_policy(
        &policy.classification,
        policy.should_retry,
        &policy.client_action,
        policy.retry_attempt,
    );
    let next_run_delay_seconds = match policy.scheduler_action.as_str() {
        "scheduleRetry" => policy.retry_delay_seconds,
        "pullThenRetry" => Some(0),
        _ => None,
    };
    let next_run_at_unix_seconds = next_run_delay_seconds
        .map(|delay| observed_at_unix_seconds.saturating_add(i64::from(delay)));
    let next_retry_attempt = if policy.should_retry {
        policy.retry_attempt.saturating_add(1).min(16)
    } else {
        0
    };
    let requires_user_action = matches!(
        policy.user_action.as_str(),
        "signIn" | "reconnectDevice" | "upgradeClient"
    );

    Some(BrowserStorageSyncScheduleState {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        endpoint_type: "syncCycle".to_string(),
        observed_at_unix_seconds,
        classification: policy.classification,
        should_retry: policy.should_retry,
        client_action: policy.client_action,
        scheduler_action: policy.scheduler_action.clone(),
        credential_action: policy.credential_action,
        user_action: policy.user_action,
        telemetry_level: policy.telemetry_level,
        retry_attempt: policy.retry_attempt,
        next_retry_attempt,
        next_run_delay_seconds,
        next_run_at_unix_seconds,
        reset_retry_attempt: policy.reset_retry_attempt,
        waiting_for_credentials: policy.scheduler_action == "waitForCredentials",
        requires_user_action,
    })
}

pub fn browser_storage_sync_scheduler_status(
    snapshot: Option<BrowserStorageSyncSchedulerStatusSnapshot>,
) -> Option<BrowserStorageSyncSchedulerStatus> {
    let snapshot = snapshot?;
    let last_result = snapshot
        .last_result_json
        .as_deref()
        .and_then(browser_storage_sync_scheduler_last_result);
    let last_classification = last_result
        .as_ref()
        .and_then(|result| result.get("classification"))
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);

    Some(BrowserStorageSyncSchedulerStatus {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        status: browser_storage_sync_scheduler_status_name(&snapshot).to_string(),
        scheduler_action: normalize_sync_text(
            &snapshot.scheduler_action,
            "idle",
            MAX_SYNC_TEXT_LENGTH,
        ),
        retry_attempt: snapshot.retry_attempt,
        next_run_delay_seconds: snapshot.next_run_delay_seconds,
        next_run_at_unix_seconds: snapshot.next_run_at_unix_seconds,
        waiting_for_credentials: snapshot.waiting_for_credentials,
        requires_user_action: snapshot.requires_user_action,
        pending_run_scheduled: snapshot.pending_run_scheduled,
        last_classification,
        last_result,
    })
}

pub fn browser_storage_sync_ack_plan(
    ack: Option<BrowserStorageSyncAckBatch>,
) -> Option<BrowserStorageSyncExecutionPlan> {
    let ack = normalize_browser_storage_sync_ack_batch(ack)?;
    let scope = ack.scope;
    let device_id = ack.device_id;
    let synced_at = ack.synced_at_unix_seconds;
    let mut operations = Vec::new();

    for record in ack
        .records
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
    {
        if let Some(operation) =
            browser_storage_sync_mark_synced_operation(record, &device_id, synced_at)
        {
            operations.push(operation);
        }
    }

    for cursor in ack
        .cursors
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
    {
        if let Some(operation) = browser_storage_sync_cursor_operation(cursor, &scope, synced_at) {
            operations.push(operation);
        }
    }

    Some(BrowserStorageSyncExecutionPlan {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope,
        device_id,
        generated_at_unix_seconds: synced_at,
        operations,
    })
}

pub fn browser_storage_sync_remote_apply_plan(
    batch: Option<BrowserStorageSyncBatch>,
) -> Option<BrowserStorageSyncExecutionPlan> {
    let mut batch = normalize_browser_storage_sync_batch(batch)?;
    let folder_depths = browser_storage_sync_bookmark_folder_depths(&batch.records);
    batch.records.sort_by(|left, right| {
        browser_storage_sync_apply_order(left, &folder_depths)
            .cmp(&browser_storage_sync_apply_order(right, &folder_depths))
    });

    let synced_at = batch.generated_at_unix_seconds;
    let operations = batch
        .records
        .into_iter()
        .filter_map(|record| browser_storage_sync_remote_apply_operation(record, synced_at))
        .collect::<Vec<_>>();

    Some(BrowserStorageSyncExecutionPlan {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: batch.scope,
        device_id: batch.device_id,
        generated_at_unix_seconds: synced_at,
        operations,
    })
}

pub fn browser_storage_sync_remote_apply_result(
    plan: Option<BrowserStorageSyncExecutionPlan>,
    results: Option<BrowserStorageSyncExecutionResultBatch>,
) -> Option<BrowserStorageSyncApplyResultSummary> {
    let plan = plan?;
    let results = results?;
    if !supports_browser_storage_schema_version(plan.storage_schema_version)
        || !supports_browser_storage_schema_version(results.storage_schema_version)
    {
        return None;
    }

    let generated_at = normalize_unix_seconds(results.generated_at_unix_seconds);
    let mut applied_count = 0;
    let mut skipped_count = 0;
    let mut failures = Vec::new();
    let mut conflicts = Vec::new();
    let mut seen = vec![false; plan.operations.len()];

    for result in results
        .results
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
    {
        let Some(operation) = plan.operations.get(result.operation_index) else {
            failures.push(BrowserStorageSyncApplyResultIssue {
                operation_index: result.operation_index,
                statement_key: String::new(),
                collection: String::new(),
                record_type: None,
                record_id: None,
                reason: "unknownOperationIndex".to_string(),
                message: result.error.and_then(|error| {
                    normalize_optional_sync_text(Some(error), MAX_SYNC_TEXT_LENGTH)
                }),
            });
            continue;
        };
        seen[result.operation_index] = true;

        if let Some(error) = normalize_optional_sync_text(result.error, MAX_SYNC_TEXT_LENGTH) {
            failures.push(browser_storage_sync_apply_issue(
                result.operation_index,
                operation,
                "executionError",
                Some(error),
            ));
        } else if result.rows_affected > 0 {
            applied_count += 1;
        } else if operation.conflict_policy.as_deref()
            == Some(BROWSER_STORAGE_SYNC_REMOTE_APPLY_CONFLICT_POLICY)
        {
            skipped_count += 1;
            conflicts.push(browser_storage_sync_apply_issue(
                result.operation_index,
                operation,
                BROWSER_STORAGE_SYNC_REMOTE_APPLY_CONFLICT_REASON,
                None,
            ));
        } else {
            skipped_count += 1;
        }
    }

    for (operation_index, operation) in plan.operations.iter().enumerate() {
        if !seen[operation_index] {
            failures.push(browser_storage_sync_apply_issue(
                operation_index,
                operation,
                "missingResult",
                None,
            ));
        }
    }

    Some(BrowserStorageSyncApplyResultSummary {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: normalize_sync_text(&plan.scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(&plan.device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        generated_at_unix_seconds: generated_at,
        applied_count,
        skipped_count,
        failed_count: failures.len(),
        conflicts,
        failures,
    })
}

pub fn browser_storage_sync_server_merge_plan(
    request: Option<BrowserStorageSyncPushRequest>,
) -> Option<BrowserStorageSyncExecutionPlan> {
    let request = normalize_browser_storage_sync_push_request(request)?;
    let mut batch = request.push_batch;
    let folder_depths = browser_storage_sync_bookmark_folder_depths(&batch.records);
    batch.records.sort_by(|left, right| {
        browser_storage_sync_apply_order(left, &folder_depths)
            .cmp(&browser_storage_sync_apply_order(right, &folder_depths))
    });

    let operations = batch
        .records
        .into_iter()
        .filter_map(|record| {
            browser_storage_sync_server_merge_operation(record, &request.scope, &request.device_id)
        })
        .collect::<Vec<_>>();

    Some(BrowserStorageSyncExecutionPlan {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: request.scope,
        device_id: request.device_id,
        generated_at_unix_seconds: request.generated_at_unix_seconds,
        operations,
    })
}

pub fn browser_storage_sync_server_merge_result(
    plan: Option<BrowserStorageSyncExecutionPlan>,
    results: Option<BrowserStorageSyncExecutionResultBatch>,
) -> Option<BrowserStorageSyncServerMergeResultSummary> {
    let plan = plan?;
    let results = results?;
    if !supports_browser_storage_schema_version(plan.storage_schema_version)
        || !supports_browser_storage_schema_version(results.storage_schema_version)
    {
        return None;
    }

    let generated_at = normalize_unix_seconds(results.generated_at_unix_seconds);
    let cursors = results.cursors;
    let mut accepted_records = Vec::new();
    let mut skipped_count = 0;
    let mut rejected = Vec::new();
    let mut failures = Vec::new();
    let mut seen = vec![false; plan.operations.len()];

    for result in results
        .results
        .into_iter()
        .take(MAX_BROWSER_STORAGE_SYNC_RECORDS)
    {
        let Some(operation) = plan.operations.get(result.operation_index) else {
            failures.push(BrowserStorageSyncApplyResultIssue {
                operation_index: result.operation_index,
                statement_key: String::new(),
                collection: String::new(),
                record_type: None,
                record_id: None,
                reason: "unknownOperationIndex".to_string(),
                message: result.error.and_then(|error| {
                    normalize_optional_sync_text(Some(error), MAX_SYNC_TEXT_LENGTH)
                }),
            });
            continue;
        };
        seen[result.operation_index] = true;

        if let Some(error) = normalize_optional_sync_text(result.error, MAX_SYNC_TEXT_LENGTH) {
            failures.push(browser_storage_sync_apply_issue(
                result.operation_index,
                operation,
                "executionError",
                Some(error),
            ));
        } else if result.rows_affected > 0 {
            match browser_storage_sync_ack_record_from_server_merge_operation(
                operation,
                result.sync_revision,
            ) {
                Some(record) => accepted_records.push(record),
                None => failures.push(browser_storage_sync_apply_issue(
                    result.operation_index,
                    operation,
                    "invalidAckRecord",
                    None,
                )),
            }
        } else {
            skipped_count += 1;
            rejected.push(browser_storage_sync_apply_issue(
                result.operation_index,
                operation,
                BROWSER_STORAGE_SYNC_SERVER_MERGE_REJECTED_REASON,
                None,
            ));
        }
    }

    for (operation_index, operation) in plan.operations.iter().enumerate() {
        if !seen[operation_index] {
            failures.push(browser_storage_sync_apply_issue(
                operation_index,
                operation,
                "missingResult",
                None,
            ));
        }
    }

    let ack_batch = normalize_browser_storage_sync_ack_batch(Some(BrowserStorageSyncAckBatch {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: plan.scope.clone(),
        device_id: plan.device_id.clone(),
        synced_at_unix_seconds: generated_at,
        records: accepted_records,
        cursors,
    }))?;

    Some(BrowserStorageSyncServerMergeResultSummary {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: normalize_sync_text(&plan.scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(&plan.device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        generated_at_unix_seconds: generated_at,
        accepted_count: ack_batch.records.len(),
        skipped_count,
        failed_count: failures.len(),
        ack_batch,
        rejected,
        failures,
    })
}

fn browser_storage_sync_remote_cursors_from_records(
    records: &[BrowserStorageSyncRecord],
    generated_at_unix_seconds: i64,
) -> Vec<BrowserStorageSyncCursorUpdate> {
    let mut max_revision_by_collection = BTreeMap::<String, i64>::new();
    for record in records {
        if record.sync_state != "remote" {
            continue;
        }
        let collection = record.payload.record_type().collection().to_string();
        max_revision_by_collection
            .entry(collection)
            .and_modify(|revision| *revision = (*revision).max(record.sync_revision))
            .or_insert(record.sync_revision);
    }

    max_revision_by_collection
        .into_iter()
        .map(|(collection, revision)| BrowserStorageSyncCursorUpdate {
            collection,
            cursor: revision.max(0).to_string(),
            last_synced_at_unix_seconds: Some(generated_at_unix_seconds),
        })
        .collect()
}

fn merge_browser_storage_sync_cursors(
    first: Vec<BrowserStorageSyncCursorUpdate>,
    second: Vec<BrowserStorageSyncCursorUpdate>,
    fallback_synced_at: i64,
) -> Vec<BrowserStorageSyncCursorUpdate> {
    let mut merged = BTreeMap::<String, BrowserStorageSyncCursorUpdate>::new();
    for cursor in first.into_iter().chain(second) {
        let Some(cursor) = normalize_browser_storage_sync_cursor(cursor, fallback_synced_at) else {
            continue;
        };
        merged
            .entry(cursor.collection.clone())
            .and_modify(|existing| {
                if should_replace_sync_cursor(existing, &cursor) {
                    *existing = cursor.clone();
                }
            })
            .or_insert(cursor);
    }
    merged.into_values().collect()
}

fn should_replace_sync_cursor(
    existing: &BrowserStorageSyncCursorUpdate,
    candidate: &BrowserStorageSyncCursorUpdate,
) -> bool {
    let existing_revision = existing.cursor.parse::<i64>().ok();
    let candidate_revision = candidate.cursor.parse::<i64>().ok();
    match (existing_revision, candidate_revision) {
        (Some(existing), Some(candidate)) => candidate >= existing,
        _ => {
            candidate.last_synced_at_unix_seconds.unwrap_or_default()
                >= existing.last_synced_at_unix_seconds.unwrap_or_default()
        }
    }
}

fn browser_storage_sync_client_cycle_steps(
    remote_operation_count: usize,
    ack_operation_count: usize,
) -> Vec<BrowserStorageSyncClientCycleStep> {
    let mut steps = Vec::new();
    if remote_operation_count > 0 {
        steps.push(BrowserStorageSyncClientCycleStep {
            step_type: "applyRemoteBatch".to_string(),
            operation_count: remote_operation_count,
            required: false,
            step_reason: None,
            failure_action:
                "keep conflicting local rows dirty, report failures, ack accepted push records, and defer pull cursors when remote apply has hard failures"
                    .to_string(),
        });
    }
    if ack_operation_count > 0 {
        steps.push(BrowserStorageSyncClientCycleStep {
            step_type: "applyAckBatchAndCursors".to_string(),
            operation_count: ack_operation_count,
            required: true,
            step_reason: None,
            failure_action:
                "keep accepted local rows dirty and retry the sync cycle before advancing UI state"
                    .to_string(),
        });
    }
    steps
}

