fn supports_browser_storage_sync_cloud_data_model_version(version: u32) -> bool {
    version == BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION
}

pub fn browser_storage_sync_cloud_compatibility_status(
    document_kind: &str,
    document_json: &str,
    observed_at_unix_seconds: i64,
) -> BrowserStorageSyncCloudCompatibilityStatus {
    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let mut document_kind = normalize_browser_storage_sync_cloud_document_kind(document_kind);
    let trimmed = document_json.trim();
    let default_policy = browser_storage_sync_cloud_compatibility_policy();

    if trimmed.is_empty() || trimmed == "null" {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            None,
            None,
            default_policy,
            "cloudDocumentInvalid",
            "recoverCloudDocument",
            "none",
            "recoverCloudData",
            "missingDocument",
        );
    }

    let value = match serde_json::from_str::<Value>(trimmed) {
        Ok(value) if value.is_object() => value,
        _ => {
            return browser_storage_sync_cloud_compatibility_status_result(
                document_kind,
                observed_at,
                None,
                None,
                default_policy,
                "cloudDocumentInvalid",
                "recoverCloudDocument",
                "none",
                "recoverCloudData",
                "invalidJson",
            );
        }
    };

    if document_kind == "unknown" {
        document_kind = infer_browser_storage_sync_cloud_document_kind(&value);
    }

    let document_storage_schema_version = json_u32_field(&value, "storageSchemaVersion");
    let document_cloud_data_model_version = json_u32_field(&value, "cloudDataModelVersion")
        .or_else(|| json_u32_field(&value, "version"));
    let compatibility_policy =
        match browser_storage_sync_cloud_document_compatibility_policy(&document_kind, &value) {
            Some(policy) => policy,
            None => {
                return browser_storage_sync_cloud_compatibility_status_result(
                    document_kind,
                    observed_at,
                    document_storage_schema_version,
                    document_cloud_data_model_version,
                    default_policy,
                    "cloudDocumentInvalid",
                    "recoverCloudDocument",
                    "none",
                    "recoverCloudData",
                    "invalidCompatibilityPolicy",
                );
            }
        };

    let Some(storage_schema_version) = document_storage_schema_version else {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            None,
            document_cloud_data_model_version,
            compatibility_policy,
            "cloudDocumentInvalid",
            "recoverCloudDocument",
            "none",
            "recoverCloudData",
            "missingStorageSchemaVersion",
        );
    };
    let Some(cloud_data_model_version) = document_cloud_data_model_version else {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            document_storage_schema_version,
            None,
            compatibility_policy,
            "cloudDocumentInvalid",
            "recoverCloudDocument",
            "none",
            "recoverCloudData",
            "missingCloudDataModelVersion",
        );
    };

    if storage_schema_version > BROWSER_STORAGE_SCHEMA_VERSION {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            document_storage_schema_version,
            document_cloud_data_model_version,
            compatibility_policy,
            "clientUpgradeRequired",
            "upgradeClient",
            "none",
            "upgradeClient",
            "storageSchemaTooNew",
        );
    }
    if cloud_data_model_version > BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            document_storage_schema_version,
            document_cloud_data_model_version,
            compatibility_policy,
            "clientUpgradeRequired",
            "upgradeClient",
            "none",
            "upgradeClient",
            "cloudDataModelTooNew",
        );
    }
    if compatibility_policy.min_storage_schema_version > BROWSER_STORAGE_SCHEMA_VERSION
        || compatibility_policy.min_cloud_data_model_version
            > BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION
    {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            document_storage_schema_version,
            document_cloud_data_model_version,
            compatibility_policy,
            "clientUpgradeRequired",
            "upgradeClient",
            "none",
            "upgradeClient",
            "clientBelowCloudMinimum",
        );
    }

    if storage_schema_version < BROWSER_STORAGE_SCHEMA_VERSION {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            document_storage_schema_version,
            document_cloud_data_model_version,
            compatibility_policy,
            "cloudDataMigrationRequired",
            "migrateCloudData",
            "none",
            "migrateCloudData",
            "storageSchemaTooOld",
        );
    }
    if cloud_data_model_version < BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            document_storage_schema_version,
            document_cloud_data_model_version,
            compatibility_policy,
            "cloudDataMigrationRequired",
            "migrateCloudData",
            "none",
            "migrateCloudData",
            "cloudDataModelTooOld",
        );
    }
    if compatibility_policy.max_storage_schema_version < BROWSER_STORAGE_SCHEMA_VERSION
        || compatibility_policy.max_cloud_data_model_version
            < BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION
    {
        return browser_storage_sync_cloud_compatibility_status_result(
            document_kind,
            observed_at,
            document_storage_schema_version,
            document_cloud_data_model_version,
            compatibility_policy,
            "cloudDataMigrationRequired",
            "migrateCloudData",
            "none",
            "migrateCloudData",
            "clientAboveCloudMaximum",
        );
    }

    browser_storage_sync_cloud_compatibility_status_result(
        document_kind,
        observed_at,
        document_storage_schema_version,
        document_cloud_data_model_version,
        compatibility_policy,
        "compatible",
        "continueCloudSync",
        "continueProviderSync",
        "none",
        "compatible",
    )
}

pub fn browser_storage_sync_cloud_compatibility_preflight(
    documents_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudCompatibilityPreflightPlan> {
    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let documents = parse_browser_storage_sync_cloud_compatibility_documents(documents_json)?;
    let mut document_statuses = Vec::with_capacity(documents.len());
    let mut compatible_count = 0u32;
    let mut blocked_count = 0u32;
    let mut client_upgrade_required_count = 0u32;
    let mut cloud_data_migration_required_count = 0u32;
    let mut cloud_document_invalid_count = 0u32;
    let mut requires_user_action = false;

    for (index, document) in documents.iter().enumerate() {
        let status = browser_storage_sync_cloud_compatibility_status(
            &document.document_kind,
            &document.document_json,
            observed_at,
        );

        if status.compatible {
            compatible_count = compatible_count.saturating_add(1);
        } else {
            blocked_count = blocked_count.saturating_add(1);
        }

        match status.classification.as_str() {
            "clientUpgradeRequired" => {
                client_upgrade_required_count = client_upgrade_required_count.saturating_add(1);
            }
            "cloudDataMigrationRequired" => {
                cloud_data_migration_required_count =
                    cloud_data_migration_required_count.saturating_add(1);
            }
            "cloudDocumentInvalid" => {
                cloud_document_invalid_count = cloud_document_invalid_count.saturating_add(1);
            }
            _ => {}
        }

        requires_user_action |= status.requires_user_action;
        document_statuses.push(
            BrowserStorageSyncCloudCompatibilityPreflightDocumentStatus {
                document_index: u32::try_from(index).unwrap_or(u32::MAX),
                path: document.path.clone(),
                status,
            },
        );
    }

    let compatible = blocked_count == 0;
    let (classification, client_action, provider_action, user_action, reason) =
        if client_upgrade_required_count > 0 {
            (
                "clientUpgradeRequired",
                "upgradeClient",
                "none",
                "upgradeClient",
                "clientUpgradeRequired",
            )
        } else if cloud_data_migration_required_count > 0 {
            (
                "cloudDataMigrationRequired",
                "migrateCloudData",
                "none",
                "migrateCloudData",
                "cloudDataMigrationRequired",
            )
        } else if cloud_document_invalid_count > 0 {
            (
                "cloudDocumentInvalid",
                "recoverCloudDocument",
                "none",
                "recoverCloudData",
                "cloudDocumentInvalid",
            )
        } else {
            (
                "compatible",
                "continueCloudSync",
                "continueProviderSync",
                "none",
                "compatible",
            )
        };

    Some(BrowserStorageSyncCloudCompatibilityPreflightPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudCompatibilityPreflight".to_string(),
        observed_at_unix_seconds: observed_at,
        document_count: u32::try_from(document_statuses.len()).unwrap_or(u32::MAX),
        compatible_count,
        blocked_count,
        client_upgrade_required_count,
        cloud_data_migration_required_count,
        cloud_document_invalid_count,
        compatible,
        should_continue: compatible,
        should_read: compatible,
        should_write: compatible,
        should_block_sync: !compatible,
        requires_user_action,
        classification: classification.to_string(),
        client_action: client_action.to_string(),
        provider_action: provider_action.to_string(),
        user_action: user_action.to_string(),
        reason: reason.to_string(),
        documents: document_statuses,
        result_policy:
            "Preflight a batch of provider-read browser sync cloud documents before adapters normalize, read, write, or merge them. Compatible batches may continue; any newer file blocks for client upgrade; older files block for explicit cloud-data migration; invalid files block for cloud recovery."
                .to_string(),
    })
}

pub fn browser_storage_sync_cloud_schema_rollout_plan(
    compatibility_preflight_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudSchemaRolloutPlan> {
    let trimmed = compatibility_preflight_json.trim();
    if trimmed.is_empty() || trimmed == "null" {
        return None;
    }
    let value = serde_json::from_str::<Value>(trimmed).ok()?;
    if !value.is_object() {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let compatibility_classification = json_string_field(&value, "classification")
        .map(|classification| normalize_sync_text(&classification, "unknown", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "unknown".to_string());
    let document_count = json_u32_field(&value, "documentCount").unwrap_or(0);
    let blocked_count = json_u32_field(&value, "blockedCount").unwrap_or(0);
    let client_upgrade_required_count =
        json_u32_field(&value, "clientUpgradeRequiredCount").unwrap_or(0);
    let cloud_data_migration_required_count =
        json_u32_field(&value, "cloudDataMigrationRequiredCount").unwrap_or(0);
    let cloud_document_invalid_count =
        json_u32_field(&value, "cloudDocumentInvalidCount").unwrap_or(0);

    let (
        classification,
        phase,
        client_action,
        provider_action,
        user_action,
        scheduler_action,
        telemetry_level,
    ) = if client_upgrade_required_count > 0
        || compatibility_classification == "clientUpgradeRequired"
    {
        (
            "clientUpgradeRequired",
            "clientUpgrade",
            "upgradeClient",
            "none",
            "upgradeClient",
            "stopUntilClientUpdate",
            "error",
        )
    } else if cloud_data_migration_required_count > 0
        || compatibility_classification == "cloudDataMigrationRequired"
    {
        (
            "cloudDataMigrationRequired",
            "cloudMigration",
            "migrateCloudData",
            "prepareCloudFileMigration",
            "migrateCloudData",
            "stopUntilCloudMigration",
            "warning",
        )
    } else if cloud_document_invalid_count > 0
        || compatibility_classification == "cloudDocumentInvalid"
        || blocked_count > 0
    {
        (
            "cloudDocumentInvalid",
            "cloudRepair",
            "recoverCloudDocument",
            "recoverCloudDocument",
            "recoverCloudData",
            "stopUntilCloudRepair",
            "error",
        )
    } else if compatibility_classification == "compatible" {
        (
            "ready",
            "currentSchema",
            "continueCloudSync",
            "continueProviderSync",
            "none",
            "idle",
            "info",
        )
    } else {
        (
            "cloudCompatibilityUnknown",
            "preflightRequired",
            "preflightCloudCompatibility",
            "readCloudMetadata",
            "reviewSyncStatus",
            "stopUntilCloudPreflight",
            "warning",
        )
    };

    let should_block_sync = !matches!(classification, "ready");
    let requires_client_upgrade = classification == "clientUpgradeRequired";
    let requires_cloud_migration = classification == "cloudDataMigrationRequired";
    let requires_cloud_repair = classification == "cloudDocumentInvalid";
    let requires_user_action = browser_storage_sync_cloud_cycle_requires_user_action(user_action);
    let mut diagnostic_reasons = BTreeSet::new();
    browser_storage_sync_cloud_schema_rollout_collect_document_reasons(
        &mut diagnostic_reasons,
        &value,
    );
    if diagnostic_reasons.is_empty() && classification != "ready" {
        diagnostic_reasons.insert(classification.to_string());
    }

    let rollout_steps = browser_storage_sync_cloud_schema_rollout_steps(
        classification,
        document_count,
        client_upgrade_required_count,
        cloud_data_migration_required_count,
        cloud_document_invalid_count,
    );

    Some(BrowserStorageSyncCloudSchemaRolloutPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudSchemaRolloutPlan".to_string(),
        observed_at_unix_seconds: observed_at,
        rollout_mode: "strictCurrentSchema".to_string(),
        compatibility_window: "currentOnly".to_string(),
        current_storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        current_cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        min_supported_storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        max_supported_storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        min_supported_cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        max_supported_cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        supports_n_minus_one_read: false,
        supports_n_minus_one_write: false,
        compatibility_classification,
        classification: classification.to_string(),
        phase: phase.to_string(),
        client_action: client_action.to_string(),
        provider_action: provider_action.to_string(),
        user_action: user_action.to_string(),
        scheduler_action: scheduler_action.to_string(),
        telemetry_level: telemetry_level.to_string(),
        should_allow_read: !should_block_sync,
        should_allow_write: !should_block_sync,
        should_block_sync,
        requires_user_action,
        requires_client_upgrade,
        requires_cloud_migration,
        requires_cloud_repair,
        should_start_cloud_migration: requires_cloud_migration,
        can_auto_migrate_cloud_files: false,
        document_count,
        blocked_count,
        client_upgrade_required_count,
        cloud_data_migration_required_count,
        cloud_document_invalid_count,
        diagnostic_reasons: diagnostic_reasons.into_iter().collect(),
        rollout_steps,
        result_policy:
            "Plan client/cloud-file schema rollout from the Rust-owned cloud compatibility preflight. The current policy is strict-current-schema: no N-1 cloud-file read/write window is enabled, older files require an explicit migration playbook, newer files require a client upgrade, and invalid files require cloud repair before provider sync continues."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_schema_rollout_collect_document_reasons(
    reasons: &mut BTreeSet<String>,
    preflight: &Value,
) {
    let Some(documents) = preflight.get("documents").and_then(Value::as_array) else {
        return;
    };
    for document in documents {
        let Some(status) = document.get("status").filter(|value| value.is_object()) else {
            continue;
        };
        if let Some(reason) = json_string_field(status, "reason")
            .and_then(|reason| normalize_optional_sync_text(Some(reason), MAX_SYNC_TEXT_LENGTH))
            .filter(|reason| !matches!(reason.as_str(), "compatible" | "ready" | "none"))
        {
            reasons.insert(reason);
        }
        if let Some(classification) = json_string_field(status, "classification")
            .and_then(|classification| {
                normalize_optional_sync_text(Some(classification), MAX_SYNC_TEXT_LENGTH)
            })
            .filter(|classification| {
                !matches!(classification.as_str(), "compatible" | "ready" | "none")
            })
        {
            reasons.insert(classification);
        }
    }
}

fn browser_storage_sync_cloud_schema_rollout_steps(
    classification: &str,
    document_count: u32,
    client_upgrade_required_count: u32,
    cloud_data_migration_required_count: u32,
    cloud_document_invalid_count: u32,
) -> Vec<String> {
    match classification {
        "ready" => vec![
            "continueProviderReadWrite".to_string(),
            "preserveCurrentCloudSchemaWindow".to_string(),
        ],
        "clientUpgradeRequired" => vec![
            "stopCloudReadWrite".to_string(),
            format!("upgradeClientFor{client_upgrade_required_count}CloudDocuments"),
            "retryCompatibilityPreflightAfterUpgrade".to_string(),
        ],
        "cloudDataMigrationRequired" => vec![
            "stopCloudReadWrite".to_string(),
            format!(
                "prepareExplicitMigrationFor{cloud_data_migration_required_count}CloudDocuments"
            ),
            "rerunCompatibilityPreflightAfterMigration".to_string(),
        ],
        "cloudDocumentInvalid" => vec![
            "stopCloudReadWrite".to_string(),
            format!("repairOrRestore{cloud_document_invalid_count}CloudDocuments"),
            "rerunCompatibilityPreflightAfterRepair".to_string(),
        ],
        _ => vec![
            "runCompatibilityPreflight".to_string(),
            format!("inspect{document_count}CloudDocuments").to_string(),
        ],
    }
}

pub fn browser_storage_sync_cloud_schema_migration_playbook(
    schema_rollout_plan_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudSchemaMigrationPlaybook> {
    let trimmed = schema_rollout_plan_json.trim();
    if trimmed.is_empty() || trimmed == "null" {
        return None;
    }
    let value = serde_json::from_str::<Value>(trimmed).ok()?;
    if !value.is_object() {
        return None;
    }

    let source_plan_type = json_string_field(&value, "planType")
        .map(|plan_type| normalize_sync_text(&plan_type, "unknown", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "unknown".to_string());
    if source_plan_type != "cloudSchemaRolloutPlan" {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let rollout_classification = json_string_field(&value, "classification")
        .map(|classification| normalize_sync_text(&classification, "unknown", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "unknown".to_string());
    let compatibility_window = json_string_field(&value, "compatibilityWindow")
        .map(|window| normalize_sync_text(&window, "currentOnly", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "currentOnly".to_string());
    let blocked_count = json_u32_field(&value, "blockedCount").unwrap_or(0);
    let migration_document_count =
        json_u32_field(&value, "cloudDataMigrationRequiredCount").unwrap_or(0);
    let repair_document_count = json_u32_field(&value, "cloudDocumentInvalidCount").unwrap_or(0);
    let client_upgrade_document_count =
        json_u32_field(&value, "clientUpgradeRequiredCount").unwrap_or(0);
    let affected_document_count = if rollout_classification == "ready" {
        0
    } else {
        blocked_count.max(
            migration_document_count
                .saturating_add(repair_document_count)
                .saturating_add(client_upgrade_document_count),
        )
    };
    let can_auto_migrate_cloud_files =
        json_bool_field(&value, "canAutoMigrateCloudFiles").unwrap_or(false);

    let (
        classification,
        phase,
        migration_mode,
        client_action,
        provider_action,
        user_action,
        scheduler_action,
        telemetry_level,
    ) = match rollout_classification.as_str() {
        "ready" => (
            "noMigrationRequired",
            "currentSchema",
            "none",
            "continueCloudSync",
            "continueProviderSync",
            "none",
            "idle",
            "info",
        ),
        "clientUpgradeRequired" => (
            "clientUpgradeRequired",
            "clientUpgrade",
            "blockedUntilClientUpgrade",
            "upgradeClient",
            "holdProviderWrites",
            "upgradeClient",
            "stopUntilClientUpdate",
            "error",
        ),
        "cloudDataMigrationRequired" => (
            "explicitMigrationRequired",
            "cloudMigrationPreparation",
            "explicitManualMigration",
            "prepareCloudSchemaMigration",
            "snapshotCloudFiles",
            "migrateCloudData",
            "stopUntilCloudMigration",
            "warning",
        ),
        "cloudDocumentInvalid" => (
            "cloudRepairRequired",
            "cloudRepairPreparation",
            "explicitRepairOrRestore",
            "prepareCloudRepair",
            "snapshotInvalidCloudFiles",
            "recoverCloudData",
            "stopUntilCloudRepair",
            "error",
        ),
        _ => (
            "preflightRequired",
            "preflightRequired",
            "unknown",
            "preflightCloudCompatibility",
            "readCloudMetadata",
            "reviewSyncStatus",
            "stopUntilCloudPreflight",
            "warning",
        ),
    };

    let requires_client_upgrade = classification == "clientUpgradeRequired";
    let requires_cloud_migration = classification == "explicitMigrationRequired";
    let requires_cloud_repair = classification == "cloudRepairRequired";
    let should_start_migration = requires_cloud_migration;
    let should_allow_normal_sync = classification == "noMigrationRequired";
    let should_freeze_provider_writes = !should_allow_normal_sync;
    let should_allow_migration_reads = matches!(
        classification,
        "explicitMigrationRequired" | "cloudRepairRequired"
    );
    let should_allow_migration_writes = false;
    let requires_provider_backup = matches!(
        classification,
        "explicitMigrationRequired" | "cloudRepairRequired"
    );
    let requires_post_migration_preflight = !should_allow_normal_sync;
    let requires_user_action = browser_storage_sync_cloud_cycle_requires_user_action(user_action);
    let diagnostic_reasons =
        browser_storage_sync_cloud_schema_migration_diagnostic_reasons(&value, classification);

    Some(BrowserStorageSyncCloudSchemaMigrationPlaybook {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudSchemaMigrationPlaybook".to_string(),
        observed_at_unix_seconds: observed_at,
        source_plan_type,
        rollout_classification,
        classification: classification.to_string(),
        phase: phase.to_string(),
        migration_mode: migration_mode.to_string(),
        compatibility_window,
        current_storage_schema_version: json_u32_field(&value, "currentStorageSchemaVersion")
            .unwrap_or(BROWSER_STORAGE_SCHEMA_VERSION),
        target_storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        current_cloud_data_model_version: json_u32_field(&value, "currentCloudDataModelVersion")
            .unwrap_or(BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION),
        target_cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        affected_document_count,
        migration_document_count,
        repair_document_count,
        client_upgrade_document_count,
        should_start_migration,
        should_freeze_provider_writes,
        should_allow_normal_sync,
        should_allow_migration_reads,
        should_allow_migration_writes,
        requires_provider_backup,
        requires_post_migration_preflight,
        requires_user_action,
        requires_client_upgrade,
        requires_cloud_migration,
        requires_cloud_repair,
        can_auto_execute_migration: false,
        can_auto_migrate_cloud_files,
        client_action: client_action.to_string(),
        provider_action: provider_action.to_string(),
        user_action: user_action.to_string(),
        scheduler_action: scheduler_action.to_string(),
        telemetry_level: telemetry_level.to_string(),
        prerequisite_steps: browser_storage_sync_cloud_schema_migration_prerequisite_steps(
            classification,
        ),
        migration_steps: browser_storage_sync_cloud_schema_migration_steps(
            classification,
            migration_document_count,
            repair_document_count,
        ),
        validation_steps: browser_storage_sync_cloud_schema_migration_validation_steps(
            classification,
        ),
        rollback_steps: browser_storage_sync_cloud_schema_migration_rollback_steps(
            classification,
        ),
        diagnostic_reasons,
        result_policy:
            "Plan the explicit client/cloud-file schema migration playbook from a Rust-owned rollout plan. The current policy never auto-writes migrated cloud files: blocked providers freeze normal sync writes, snapshot affected files first, run a version-specific migrator or repair flow outside provider SDK details, then rerun compatibility preflight before normal sync resumes."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_schema_migration_diagnostic_reasons(
    rollout_plan: &Value,
    classification: &str,
) -> Vec<String> {
    let mut reasons = Vec::new();
    if let Some(values) = rollout_plan
        .get("diagnosticReasons")
        .and_then(Value::as_array)
    {
        for value in values {
            let Some(reason) = value.as_str().and_then(|reason| {
                normalize_optional_sync_text(Some(reason.to_string()), MAX_SYNC_TEXT_LENGTH)
            }) else {
                continue;
            };
            if !matches!(reason.as_str(), "compatible" | "ready" | "none")
                && !reasons.contains(&reason)
            {
                reasons.push(reason);
            }
        }
    }
    if reasons.is_empty() && classification != "noMigrationRequired" {
        reasons.push(classification.to_string());
    }
    reasons
}

fn browser_storage_sync_cloud_schema_migration_prerequisite_steps(
    classification: &str,
) -> Vec<String> {
    match classification {
        "noMigrationRequired" => vec!["none".to_string()],
        "clientUpgradeRequired" => vec![
            "stopCloudReadWrite".to_string(),
            "upgradeClientBeforeMigration".to_string(),
        ],
        "explicitMigrationRequired" => vec![
            "stopCloudReadWrite".to_string(),
            "freezeNormalProviderWrites".to_string(),
            "snapshotAffectedCloudDocuments".to_string(),
            "prepareVersionSpecificMigrator".to_string(),
        ],
        "cloudRepairRequired" => vec![
            "stopCloudReadWrite".to_string(),
            "freezeNormalProviderWrites".to_string(),
            "snapshotInvalidCloudDocuments".to_string(),
            "chooseRepairOrRestoreSource".to_string(),
        ],
        _ => vec![
            "runCompatibilityPreflight".to_string(),
            "buildSchemaRolloutPlan".to_string(),
        ],
    }
}

fn browser_storage_sync_cloud_schema_migration_steps(
    classification: &str,
    migration_document_count: u32,
    repair_document_count: u32,
) -> Vec<String> {
    match classification {
        "noMigrationRequired" => vec!["continueProviderReadWrite".to_string()],
        "explicitMigrationRequired" => vec![
            "readAffectedCloudDocuments".to_string(),
            format!("prepareExplicitMigrationFor{migration_document_count}CloudDocuments"),
            "writeMigratedDocumentsOnlyAfterUserConfirmation".to_string(),
        ],
        "cloudRepairRequired" => vec![
            "readInvalidCloudDocuments".to_string(),
            format!("repairOrRestore{repair_document_count}CloudDocuments"),
            "writeRepairedDocumentsOnlyAfterUserConfirmation".to_string(),
        ],
        _ => Vec::new(),
    }
}

fn browser_storage_sync_cloud_schema_migration_validation_steps(
    classification: &str,
) -> Vec<String> {
    match classification {
        "noMigrationRequired" => vec!["preserveCurrentSchemaWindow".to_string()],
        "clientUpgradeRequired" => vec!["rerunCompatibilityPreflightAfterUpgrade".to_string()],
        "explicitMigrationRequired" => vec![
            "rerunCompatibilityPreflightAfterMigration".to_string(),
            "rebuildSchemaRolloutPlanAfterMigration".to_string(),
            "resumeSyncOnlyWhenRolloutIsReady".to_string(),
        ],
        "cloudRepairRequired" => vec![
            "rerunCompatibilityPreflightAfterRepair".to_string(),
            "rebuildSchemaRolloutPlanAfterRepair".to_string(),
            "resumeSyncOnlyWhenRolloutIsReady".to_string(),
        ],
        _ => vec!["rerunCompatibilityPreflight".to_string()],
    }
}

fn browser_storage_sync_cloud_schema_migration_rollback_steps(classification: &str) -> Vec<String> {
    match classification {
        "explicitMigrationRequired" | "cloudRepairRequired" => vec![
            "restoreProviderBackupOnFailure".to_string(),
            "keepSyncBlockedUntilValidationPasses".to_string(),
        ],
        "clientUpgradeRequired" => {
            vec!["keepSyncBlockedUntilCompatibleClientRuns".to_string()]
        }
        _ => Vec::new(),
    }
}

pub fn browser_storage_sync_cloud_recovery_snapshot_plan(
    schema_migration_playbook_json: &str,
    compatibility_preflight_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudRecoverySnapshotPlan> {
    let playbook = serde_json::from_str::<Value>(schema_migration_playbook_json.trim()).ok()?;
    if json_string_field(&playbook, "planType").as_deref() != Some("cloudSchemaMigrationPlaybook") {
        return None;
    }
    let preflight = serde_json::from_str::<Value>(compatibility_preflight_json.trim()).ok()?;
    if json_string_field(&preflight, "planType").as_deref() != Some("cloudCompatibilityPreflight") {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let source_plan_type = json_string_field(&playbook, "planType")
        .map(|plan_type| normalize_sync_text(&plan_type, "unknown", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "unknown".to_string());
    let source_classification = json_string_field(&playbook, "classification")
        .map(|classification| {
            normalize_sync_text(&classification, "preflightRequired", MAX_SYNC_TEXT_LENGTH)
        })
        .unwrap_or_else(|| "preflightRequired".to_string());
    let requires_provider_backup =
        json_bool_field(&playbook, "requiresProviderBackup").unwrap_or(false);
    let requires_user_action = json_bool_field(&playbook, "requiresUserAction").unwrap_or(false);
    let migration_document_count = json_u32_field(&playbook, "migrationDocumentCount").unwrap_or(0);
    let repair_document_count = json_u32_field(&playbook, "repairDocumentCount").unwrap_or(0);
    let client_upgrade_document_count =
        json_u32_field(&playbook, "clientUpgradeDocumentCount").unwrap_or(0);

    let snapshot_mode = match source_classification.as_str() {
        "explicitMigrationRequired" => "cloudMigration",
        "cloudRepairRequired" => "cloudRepair",
        "clientUpgradeRequired" => "clientUpgrade",
        "noMigrationRequired" => "none",
        _ => "preflightRequired",
    };
    let snapshot_root_path =
        browser_storage_sync_cloud_recovery_snapshot_root_path(observed_at, snapshot_mode);

    let mut operations = Vec::new();
    let mut skipped_documents = Vec::new();
    let mut seen_sources = BTreeSet::new();

    if requires_provider_backup {
        let documents = preflight
            .get("documents")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        for document in documents {
            let document_index = json_u32_field(&document, "documentIndex").unwrap_or_else(|| {
                u32::try_from(operations.len() + skipped_documents.len()).unwrap_or(u32::MAX)
            });
            let status = document.get("status").filter(|value| value.is_object());
            let classification = status
                .and_then(|status| json_string_field(status, "classification"))
                .map(|classification| {
                    normalize_sync_text(&classification, "unknown", MAX_SYNC_TEXT_LENGTH)
                })
                .unwrap_or_else(|| "unknown".to_string());
            let document_kind = status
                .and_then(|status| json_string_field(status, "documentKind"))
                .map(|kind| normalize_browser_storage_sync_cloud_document_kind(&kind))
                .unwrap_or_else(|| "unknown".to_string());
            let source_path = json_string_field(&document, "path")
                .map(|path| normalize_sync_text(&path, "", MAX_SYNC_URL_LENGTH))
                .unwrap_or_default();

            if !browser_storage_sync_cloud_recovery_snapshot_should_include(
                snapshot_mode,
                &classification,
            ) {
                continue;
            }

            let Ok(source_path) =
                browser_storage_sync_cloud_validate_store_object_path(&source_path)
            else {
                skipped_documents.push(BrowserStorageSyncCloudRecoverySnapshotSkippedDocument {
                    document_index,
                    source_path,
                    document_kind,
                    classification,
                    skip_reason: "unsafeOrMissingSourcePath".to_string(),
                });
                continue;
            };

            if !seen_sources.insert(source_path.clone()) {
                skipped_documents.push(BrowserStorageSyncCloudRecoverySnapshotSkippedDocument {
                    document_index,
                    source_path,
                    document_kind,
                    classification,
                    skip_reason: "duplicateSourcePath".to_string(),
                });
                continue;
            }

            let Some(snapshot_path) = browser_storage_sync_cloud_recovery_snapshot_path(
                &snapshot_root_path,
                &source_path,
            ) else {
                skipped_documents.push(BrowserStorageSyncCloudRecoverySnapshotSkippedDocument {
                    document_index,
                    source_path,
                    document_kind,
                    classification,
                    skip_reason: "snapshotPathUnavailable".to_string(),
                });
                continue;
            };

            operations.push(BrowserStorageSyncCloudRecoverySnapshotOperation {
                operation_index: u32::try_from(operations.len()).unwrap_or(u32::MAX),
                operation_type: "writeRecoveryCopy".to_string(),
                source_document_index: document_index,
                source_path,
                snapshot_path,
                document_kind,
                classification,
                snapshot_reason: match snapshot_mode {
                    "cloudMigration" => "snapshotBeforeCloudMigration",
                    "cloudRepair" => "snapshotBeforeCloudRepair",
                    _ => "snapshotBeforeCloudRecovery",
                }
                .to_string(),
                required: true,
                read_reason: "readSourceCloudDocumentForRecoverySnapshot".to_string(),
                write_reason: "writeRecoverySnapshotCopy".to_string(),
                conflict_action: "chooseNewRecoverySnapshotPathAndRetry".to_string(),
            });
        }
    }

    let should_snapshot = requires_provider_backup && !operations.is_empty();
    let (client_action, provider_action, user_action, scheduler_action) = if should_snapshot {
        (
            "snapshotCloudFiles",
            "writeRecoverySnapshots",
            "reviewCloudRecoverySnapshot",
            "stopUntilRecoverySnapshotCompletes",
        )
    } else {
        match source_classification.as_str() {
            "noMigrationRequired" => ("continueCloudSync", "continueProviderSync", "none", "idle"),
            "clientUpgradeRequired" => (
                "upgradeClient",
                "holdProviderWrites",
                "upgradeClient",
                "stopUntilClientUpdate",
            ),
            "explicitMigrationRequired" => (
                "prepareCloudSchemaMigration",
                "reviewMissingRecoverySnapshotSources",
                "migrateCloudData",
                "stopUntilCloudMigration",
            ),
            "cloudRepairRequired" => (
                "prepareCloudRepair",
                "reviewMissingRecoverySnapshotSources",
                "recoverCloudData",
                "stopUntilCloudRepair",
            ),
            _ => (
                "preflightCloudCompatibility",
                "readCloudMetadata",
                "reviewSyncStatus",
                "stopUntilCloudPreflight",
            ),
        }
    };

    Some(BrowserStorageSyncCloudRecoverySnapshotPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudRecoverySnapshotPlan".to_string(),
        observed_at_unix_seconds: observed_at,
        source_plan_type,
        source_classification,
        snapshot_mode: snapshot_mode.to_string(),
        snapshot_root_path,
        should_snapshot,
        requires_provider_backup,
        requires_user_action,
        operation_count: u32::try_from(operations.len()).unwrap_or(u32::MAX),
        skipped_document_count: u32::try_from(skipped_documents.len()).unwrap_or(u32::MAX),
        migration_document_count,
        repair_document_count,
        client_upgrade_document_count,
        client_action: client_action.to_string(),
        provider_action: provider_action.to_string(),
        user_action: user_action.to_string(),
        scheduler_action: scheduler_action.to_string(),
        operations,
        skipped_documents,
        result_policy:
            "Plan provider-executed recovery snapshots for cloud files before explicit migration or repair. Rust chooses the affected source documents and deterministic recovery paths in one batch; provider adapters execute read/write copies through their existing object-store layer, then rerun compatibility preflight before normal sync resumes."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_recovery_snapshot_should_include(
    snapshot_mode: &str,
    classification: &str,
) -> bool {
    match snapshot_mode {
        "cloudMigration" => classification == "cloudDataMigrationRequired",
        "cloudRepair" => classification == "cloudDocumentInvalid",
        _ => false,
    }
}

fn browser_storage_sync_cloud_recovery_snapshot_root_path(
    observed_at_unix_seconds: i64,
    snapshot_mode: &str,
) -> String {
    let mode = match snapshot_mode {
        "cloudMigration" => "migration",
        "cloudRepair" => "repair",
        "clientUpgrade" => "client-upgrade",
        "none" => "none",
        _ => "preflight",
    };
    format!(
        "{}{:012}-{}",
        BROWSER_STORAGE_SYNC_CLOUD_RECOVERY_PREFIX,
        normalize_unix_seconds(observed_at_unix_seconds),
        mode
    )
}

fn browser_storage_sync_cloud_recovery_snapshot_path(
    snapshot_root_path: &str,
    source_path: &str,
) -> Option<String> {
    let source_path = browser_storage_sync_cloud_validate_store_object_path(source_path).ok()?;
    let source_suffix =
        source_path.strip_prefix(&format!("{BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH}/"))?;
    let snapshot_path = format!("{snapshot_root_path}/{source_suffix}");
    browser_storage_sync_cloud_validate_store_object_path(&snapshot_path).ok()
}

pub fn browser_storage_sync_cloud_recovery_snapshot_result_plan(
    recovery_snapshot_plan: Option<BrowserStorageSyncCloudRecoverySnapshotPlan>,
    write_results: Option<Vec<BrowserStorageSyncCloudWriteOperationResult>>,
    generated_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudRecoverySnapshotResultPlan> {
    let recovery_snapshot_plan = recovery_snapshot_plan?;
    if recovery_snapshot_plan.plan_type != "cloudRecoverySnapshotPlan"
        || !supports_browser_storage_schema_version(recovery_snapshot_plan.storage_schema_version)
        || !supports_browser_storage_sync_cloud_data_model_version(
            recovery_snapshot_plan.cloud_data_model_version,
        )
    {
        return None;
    }

    let generated_at = normalize_unix_seconds(generated_at_unix_seconds)
        .max(recovery_snapshot_plan.observed_at_unix_seconds);
    let write_results = write_results?;
    let results_by_index = write_results
        .into_iter()
        .map(|result| (result.operation_index, result))
        .collect::<BTreeMap<_, _>>();

    let mut succeeded_count = 0_u32;
    let mut failed_count = 0_u32;
    let mut conflict_count = 0_u32;
    let mut retryable_failure_count = 0_u32;
    let mut successful_snapshot_paths = Vec::new();
    let mut issues = Vec::new();

    for operation in &recovery_snapshot_plan.operations {
        match results_by_index.get(&operation.operation_index) {
            Some(result)
                if browser_storage_sync_cloud_recovery_snapshot_result_matches_operation(
                    result, operation,
                ) && result.success =>
            {
                succeeded_count = succeeded_count.saturating_add(1);
                successful_snapshot_paths.push(operation.snapshot_path.clone());
            }
            Some(result)
                if !browser_storage_sync_cloud_recovery_snapshot_result_matches_operation(
                    result, operation,
                ) =>
            {
                failed_count = failed_count.saturating_add(1);
                issues.push(browser_storage_sync_cloud_recovery_snapshot_result_issue(
                    operation,
                    "invalidResult",
                    Some(
                        "Provider result path or operation type does not match the planned recovery snapshot copy.",
                    ),
                    false,
                ));
            }
            Some(result) => {
                let reason = browser_storage_sync_cloud_write_result_reason(result);
                let retryable =
                    browser_storage_sync_cloud_write_result_is_retryable(result, &reason);
                if reason == "conflict" {
                    conflict_count = conflict_count.saturating_add(1);
                }
                if retryable {
                    retryable_failure_count = retryable_failure_count.saturating_add(1);
                }
                failed_count = failed_count.saturating_add(1);
                issues.push(browser_storage_sync_cloud_recovery_snapshot_result_issue(
                    operation,
                    &reason,
                    result.error_message.as_deref(),
                    retryable,
                ));
            }
            None => {
                failed_count = failed_count.saturating_add(1);
                retryable_failure_count = retryable_failure_count.saturating_add(1);
                issues.push(browser_storage_sync_cloud_recovery_snapshot_result_issue(
                    operation,
                    "missingResult",
                    Some(
                        "Provider adapter did not report a result for this planned recovery snapshot copy.",
                    ),
                    true,
                ));
            }
        }
    }

    let operation_count = recovery_snapshot_plan
        .operations
        .len()
        .min(u32::MAX as usize) as u32;
    let snapshot_requested = recovery_snapshot_plan.requires_provider_backup && operation_count > 0;
    let completed = if snapshot_requested {
        failed_count == 0 && succeeded_count == operation_count
    } else {
        !recovery_snapshot_plan.requires_provider_backup
    };
    let any_success = succeeded_count > 0;
    let has_provider_recovery_issue = issues
        .iter()
        .any(|issue| issue.reason == "unauthorized" || issue.reason == "quotaExceeded");
    let has_missing_source_issue = issues.iter().any(|issue| issue.reason == "notFound");
    let should_reread = snapshot_requested
        && !completed
        && (conflict_count > 0 || any_success || has_missing_source_issue);
    let should_retry = snapshot_requested
        && !completed
        && (retryable_failure_count > 0 || conflict_count > 0)
        && !has_provider_recovery_issue
        && !has_missing_source_issue;
    let client_action = browser_storage_sync_cloud_recovery_snapshot_result_client_action(
        &recovery_snapshot_plan,
        snapshot_requested,
        completed,
        should_reread,
        should_retry,
        &issues,
    );
    let provider_action = browser_storage_sync_cloud_recovery_snapshot_result_provider_action(
        &client_action,
        &recovery_snapshot_plan,
    );
    let user_action = browser_storage_sync_cloud_recovery_snapshot_result_user_action(
        &client_action,
        &recovery_snapshot_plan,
    );
    let scheduler_action = browser_storage_sync_cloud_recovery_snapshot_result_scheduler_action(
        &client_action,
        &recovery_snapshot_plan,
    );
    let reread_operations = if should_reread {
        browser_storage_sync_cloud_recovery_snapshot_result_reread_operations(
            &recovery_snapshot_plan,
        )
    } else {
        Vec::new()
    };

    Some(BrowserStorageSyncCloudRecoverySnapshotResultPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudRecoverySnapshotResult".to_string(),
        source_plan_type: recovery_snapshot_plan.plan_type,
        source_classification: recovery_snapshot_plan.source_classification,
        snapshot_mode: recovery_snapshot_plan.snapshot_mode,
        snapshot_root_path: recovery_snapshot_plan.snapshot_root_path,
        generated_at_unix_seconds: generated_at,
        snapshot_requested,
        completed,
        should_reread,
        should_retry,
        operation_count,
        succeeded_count,
        failed_count,
        conflict_count,
        retryable_failure_count,
        client_action,
        provider_action,
        user_action,
        scheduler_action,
        successful_snapshot_paths,
        issues,
        reread_operations,
        result_policy:
            "Treat cloud migration or repair recovery snapshots as complete only after every Rust-planned writeRecoveryCopy operation succeeds. On conflicts or partial copies, reread affected cloud files and rebuild the snapshot plan before retrying; provider SDK IO and the actual migration/repair writes remain platform-owned."
                .to_string(),
    })
}

#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_compatibility_status_result(
    document_kind: String,
    observed_at_unix_seconds: i64,
    document_storage_schema_version: Option<u32>,
    document_cloud_data_model_version: Option<u32>,
    compatibility_policy: BrowserStorageSyncCloudCompatibilityPolicy,
    classification: &str,
    client_action: &str,
    provider_action: &str,
    user_action: &str,
    reason: &str,
) -> BrowserStorageSyncCloudCompatibilityStatus {
    let compatible = classification == "compatible";
    BrowserStorageSyncCloudCompatibilityStatus {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudCompatibilityStatus".to_string(),
        document_kind,
        observed_at_unix_seconds,
        compatible,
        should_read: compatible,
        should_write: compatible,
        should_block_sync: !compatible,
        requires_user_action: user_action != "none",
        classification: classification.to_string(),
        client_action: client_action.to_string(),
        provider_action: provider_action.to_string(),
        user_action: user_action.to_string(),
        reason: reason.to_string(),
        document_storage_schema_version,
        document_cloud_data_model_version,
        expected_storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        expected_cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        compatibility_policy,
        result_policy:
            "Gate cloud-drive browser sync documents before provider adapters normalize, read, or write them. Compatible documents may continue; newer formats require a client upgrade; older formats require explicit cloud-data migration; invalid documents require cloud recovery."
                .to_string(),
    }
}

fn browser_storage_sync_cloud_document_compatibility_policy(
    document_kind: &str,
    value: &Value,
) -> Option<BrowserStorageSyncCloudCompatibilityPolicy> {
    if document_kind != "manifest" {
        return Some(browser_storage_sync_cloud_compatibility_policy());
    }
    let value = value.get("compatibility")?;
    let policy =
        serde_json::from_value::<BrowserStorageSyncCloudCompatibilityPolicy>(value.clone()).ok()?;
    Some(BrowserStorageSyncCloudCompatibilityPolicy {
        min_storage_schema_version: policy.min_storage_schema_version,
        max_storage_schema_version: policy.max_storage_schema_version,
        min_cloud_data_model_version: policy.min_cloud_data_model_version,
        max_cloud_data_model_version: policy.max_cloud_data_model_version,
        unsupported_client_action: normalize_sync_text(
            &policy.unsupported_client_action,
            "upgradeClient",
            MAX_SYNC_TEXT_LENGTH,
        ),
    })
}

fn parse_browser_storage_sync_cloud_store_capabilities(
    capabilities_json: &str,
) -> Option<BrowserStorageSyncCloudStoreCapabilities> {
    let trimmed = capabilities_json.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Ok(capabilities) =
        serde_json::from_str::<BrowserStorageSyncCloudStoreCapabilities>(trimmed)
    {
        return Some(capabilities);
    }
    let value = serde_json::from_str::<Value>(trimmed).ok()?;
    value
        .get("capabilities")
        .and_then(|capabilities| {
            serde_json::from_value::<BrowserStorageSyncCloudStoreCapabilities>(capabilities.clone())
                .ok()
        })
        .or_else(|| {
            value
                .get("cloudStoreCapabilities")
                .and_then(|capabilities| {
                    serde_json::from_value::<BrowserStorageSyncCloudStoreCapabilities>(
                        capabilities.clone(),
                    )
                    .ok()
                })
        })
}

fn normalize_browser_storage_sync_cloud_store_capabilities(
    capabilities: BrowserStorageSyncCloudStoreCapabilities,
) -> BrowserStorageSyncCloudStoreCapabilities {
    BrowserStorageSyncCloudStoreCapabilities {
        provider_kind: normalize_sync_text(
            &capabilities.provider_kind,
            "unknown",
            MAX_SYNC_TEXT_LENGTH,
        )
        .to_ascii_lowercase(),
        root_path: normalize_cloud_store_root_path(&capabilities.root_path),
        revision_kind: normalize_sync_text(
            &capabilities.revision_kind,
            "none",
            MAX_SYNC_TEXT_LENGTH,
        )
        .to_ascii_lowercase(),
        supports_prefix_list: capabilities.supports_prefix_list,
        supports_paged_list: capabilities.supports_paged_list,
        supports_conditional_write: capabilities.supports_conditional_write,
        supports_conditional_delete: capabilities.supports_conditional_delete,
        supports_read_if_changed: capabilities.supports_read_if_changed,
        supports_atomic_rename: capabilities.supports_atomic_rename,
        supports_app_folder: capabilities.supports_app_folder,
        background_sync: normalize_sync_text(
            &capabilities.background_sync,
            "unknown",
            MAX_SYNC_TEXT_LENGTH,
        ),
        conflict_resolution: normalize_sync_text(
            &capabilities.conflict_resolution,
            "unknown",
            MAX_SYNC_TEXT_LENGTH,
        ),
        max_object_bytes: capabilities.max_object_bytes,
        max_page_size: capabilities.max_page_size,
    }
}

fn normalize_cloud_store_root_path(path: &str) -> String {
    let normalized = path.trim().replace('\\', "/");
    let normalized = normalized
        .split('/')
        .filter(|part| !part.trim().is_empty() && *part != ".")
        .collect::<Vec<_>>()
        .join("/");
    normalize_sync_text(
        &normalized,
        BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH,
        MAX_SYNC_TEXT_LENGTH,
    )
}

fn browser_storage_sync_cloud_root_path_matches_contract(root_path: &str) -> bool {
    let root_path = normalize_cloud_store_root_path(root_path).to_ascii_lowercase();
    let expected = BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH.to_ascii_lowercase();
    root_path == expected || root_path.ends_with(&format!("/{expected}"))
}

fn browser_storage_sync_cloud_revision_kind_is_none(revision_kind: &str) -> bool {
    let compact = revision_kind
        .trim()
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect::<String>();
    compact.is_empty() || matches!(compact.as_str(), "none" | "unknown" | "unsupported")
}

#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_store_capability_preflight_plan(
    observed_at_unix_seconds: i64,
    capabilities: Option<BrowserStorageSyncCloudStoreCapabilities>,
    classification: &str,
    client_action: &str,
    provider_action: &str,
    user_action: &str,
    mut missing_required_capabilities: Vec<String>,
    mut degraded_capabilities: Vec<String>,
    mut warnings: Vec<String>,
) -> BrowserStorageSyncCloudStoreCapabilityPreflightPlan {
    missing_required_capabilities.sort();
    missing_required_capabilities.dedup();
    degraded_capabilities.sort();
    degraded_capabilities.dedup();
    warnings.sort();
    warnings.dedup();

    let compatible = !matches!(
        classification,
        "providerContractInvalid"
            | "providerSetupRequired"
            | "providerLimitTooSmall"
            | "providerConflictUnsafe"
    );
    let requires_user_action = user_action != "none";
    let requires_adapter_emulation = !degraded_capabilities.is_empty();
    let provider_kind = capabilities
        .as_ref()
        .map(|capabilities| capabilities.provider_kind.clone())
        .unwrap_or_else(|| "unknown".to_string());
    let root_path = capabilities
        .as_ref()
        .map(|capabilities| capabilities.root_path.clone())
        .unwrap_or_default();
    let revision_kind = capabilities
        .as_ref()
        .map(|capabilities| capabilities.revision_kind.clone())
        .unwrap_or_else(|| "none".to_string());

    BrowserStorageSyncCloudStoreCapabilityPreflightPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudStoreCapabilityPreflight".to_string(),
        observed_at_unix_seconds,
        provider_kind,
        root_path,
        revision_kind,
        compatible,
        should_allow_sync: compatible,
        should_block_sync: !compatible,
        requires_user_action,
        requires_adapter_emulation,
        classification: classification.to_string(),
        client_action: client_action.to_string(),
        provider_action: provider_action.to_string(),
        user_action: user_action.to_string(),
        missing_required_capabilities,
        degraded_capabilities,
        warnings,
        capabilities,
        required_min_object_bytes: MIN_BROWSER_STORAGE_SYNC_CLOUD_OBJECT_BYTES,
        result_policy:
            "Preflight provider-neutral cloud store capabilities before concrete adapters start browser sync. Rust owns the safety gate for optimistic revisions, Actro root-path setup, object-size limits, and adapter-emulation warnings while provider SDK calls and account UI stay platform-owned."
                .to_string(),
    }
}

fn normalize_browser_storage_sync_cloud_document_kind(kind: &str) -> String {
    let compact = kind
        .trim()
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect::<String>();
    match compact.as_str() {
        "manifest" | "cloudmanifest" => "manifest",
        "device" | "devicedocument" | "clouddevice" => "device",
        "log" | "logobject" | "cloudlog" => "log",
        "snapshot" | "snapshotobject" | "cloudsnapshot" => "snapshot",
        _ => "unknown",
    }
    .to_string()
}

fn infer_browser_storage_sync_cloud_document_kind(value: &Value) -> String {
    if value.get("compatibility").is_some()
        || (value.get("devices").is_some() && value.get("collections").is_some())
    {
        return "manifest".to_string();
    }
    if value.get("batch").is_some() && value.get("sequence").is_some() {
        return "log".to_string();
    }
    if value.get("records").is_some() && value.get("highWatermarks").is_some() {
        return "snapshot".to_string();
    }
    if value.get("deviceId").is_some() && value.get("platform").is_some() {
        return "device".to_string();
    }
    "unknown".to_string()
}

fn json_u32_field(value: &Value, field: &str) -> Option<u32> {
    value
        .get(field)
        .and_then(Value::as_u64)
        .and_then(|version| u32::try_from(version).ok())
}

fn json_i64_field(value: &Value, field: &str) -> Option<i64> {
    value.get(field).and_then(|value| {
        value
            .as_i64()
            .or_else(|| value.as_u64().and_then(|number| i64::try_from(number).ok()))
    })
}

fn json_bool_field(value: &Value, field: &str) -> Option<bool> {
    value.get(field).and_then(Value::as_bool)
}

fn json_string_field(value: &Value, field: &str) -> Option<String> {
    value.get(field).and_then(Value::as_str).map(str::to_string)
}

fn browser_storage_sync_cloud_membership_plan_request(
    request_json: &str,
) -> Option<BrowserStorageSyncCloudMembershipPlanRequest> {
    let value = serde_json::from_str::<Value>(request_json.trim()).ok()?;
    let scope = normalize_sync_text(
        &json_string_field(&value, "scope").unwrap_or_default(),
        "default",
        MAX_SYNC_ID_LENGTH,
    );
    let actor_device_id = normalize_required_sync_id(
        &json_string_field(&value, "actorDeviceId")
            .or_else(|| json_string_field(&value, "actorDeviceID"))
            .unwrap_or_default(),
    )?;
    let member_device_id = normalize_required_sync_id(
        &json_string_field(&value, "memberDeviceId")
            .or_else(|| json_string_field(&value, "memberDeviceID"))
            .or_else(|| json_string_field(&value, "deviceId"))
            .or_else(|| json_string_field(&value, "deviceID"))
            .unwrap_or_else(|| actor_device_id.clone()),
    )?;
    let membership_action = normalize_browser_storage_sync_cloud_membership_action(
        &json_string_field(&value, "membershipAction")
            .or_else(|| json_string_field(&value, "action"))
            .unwrap_or_default(),
    )?;

    Some(BrowserStorageSyncCloudMembershipPlanRequest {
        manifest_json: browser_storage_sync_cloud_request_document_json(
            &value,
            "manifestJson",
            "manifest",
        )
        .unwrap_or_default(),
        manifest_revision: json_string_field(&value, "manifestRevision").unwrap_or_default(),
        device_json: browser_storage_sync_cloud_request_document_json(
            &value,
            "deviceJson",
            "device",
        )
        .unwrap_or_default(),
        device_revision: json_string_field(&value, "deviceRevision").unwrap_or_default(),
        scope,
        actor_device_id,
        member_device_id,
        display_name: json_string_field(&value, "displayName").unwrap_or_default(),
        platform: json_string_field(&value, "platform").unwrap_or_default(),
        app_version: json_string_field(&value, "appVersion").unwrap_or_default(),
        membership_action,
        generated_at_unix_seconds: json_i64_field(&value, "generatedAtUnixSeconds").unwrap_or(0),
    })
}

fn browser_storage_sync_cloud_request_document_json(
    value: &Value,
    json_field: &str,
    object_field: &str,
) -> Option<String> {
    value
        .get(json_field)
        .and_then(value_to_document_json)
        .or_else(|| value.get(object_field).and_then(value_to_document_json))
}

fn normalize_browser_storage_sync_cloud_membership_action(action: &str) -> Option<String> {
    match action.trim().to_ascii_lowercase().as_str() {
        "join" | "connect" | "activate" | "active" => Some("join".to_string()),
        "revoke" | "disconnect" | "remove" | "deactivate" | "revoked" => Some("revoke".to_string()),
        _ => None,
    }
}

fn parse_browser_storage_sync_cloud_compatibility_documents(
    documents_json: &str,
) -> Option<Vec<BrowserStorageSyncCloudCompatibilityDocumentInput>> {
    let trimmed = documents_json.trim();
    if trimmed.is_empty() {
        return Some(Vec::new());
    }

    let value = serde_json::from_str::<Value>(trimmed).ok()?;
    match value {
        Value::Array(items) => items
            .iter()
            .map(browser_storage_sync_cloud_compatibility_document_from_value)
            .collect(),
        Value::Object(_) => {
            if let Some(documents) = value.get("documents") {
                let documents = documents.as_array()?;
                return documents
                    .iter()
                    .map(browser_storage_sync_cloud_compatibility_document_from_value)
                    .collect();
            }
            browser_storage_sync_cloud_compatibility_document_from_value(&value)
                .map(|document| vec![document])
        }
        _ => None,
    }
}

fn browser_storage_sync_cloud_compatibility_document_from_value(
    value: &Value,
) -> Option<BrowserStorageSyncCloudCompatibilityDocumentInput> {
    if !value.is_object() {
        return Some(BrowserStorageSyncCloudCompatibilityDocumentInput {
            document_kind: "unknown".to_string(),
            path: String::new(),
            document_json: value_to_document_json(value)?,
        });
    }

    let path = json_string_field(value, "path")
        .map(|path| normalize_sync_text(&path, "", MAX_SYNC_URL_LENGTH))
        .unwrap_or_default();
    let explicit_kind = json_string_field(value, "documentKind")
        .or_else(|| json_string_field(value, "kind"))
        .unwrap_or_default();
    let mut document_kind = normalize_browser_storage_sync_cloud_document_kind(&explicit_kind);
    if document_kind == "unknown" && !path.is_empty() {
        document_kind = browser_storage_sync_cloud_document_kind_from_path(&path);
    }

    let document_json = browser_storage_sync_cloud_compatibility_document_json_from_value(value)
        .unwrap_or_else(|| "null".to_string());

    Some(BrowserStorageSyncCloudCompatibilityDocumentInput {
        document_kind,
        path,
        document_json,
    })
}

fn browser_storage_sync_cloud_compatibility_document_json_from_value(
    value: &Value,
) -> Option<String> {
    for field in ["documentJson", "document", "json"] {
        if let Some(document_value) = value.get(field) {
            return value_to_document_json(document_value);
        }
    }

    if value.get("version").is_some() || value.get("storageSchemaVersion").is_some() {
        return value_to_document_json(value);
    }

    None
}

fn value_to_document_json(value: &Value) -> Option<String> {
    match value {
        Value::String(text) => Some(text.clone()),
        Value::Object(_) | Value::Array(_) | Value::Null | Value::Bool(_) | Value::Number(_) => {
            Some(serialize_json(value))
        }
    }
}

fn browser_storage_sync_cloud_document_kind_from_path(path: &str) -> String {
    let path = path.trim().replace('\\', "/");
    let path = path.trim_start_matches('/').to_ascii_lowercase();
    let manifest_path = BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH.to_ascii_lowercase();
    let devices_prefix = BROWSER_STORAGE_SYNC_CLOUD_DEVICES_PREFIX.to_ascii_lowercase();
    let logs_prefix = BROWSER_STORAGE_SYNC_CLOUD_LOGS_PREFIX.to_ascii_lowercase();
    let snapshots_prefix = BROWSER_STORAGE_SYNC_CLOUD_SNAPSHOTS_PREFIX.to_ascii_lowercase();

    if path == manifest_path || path.ends_with("/manifest.json") {
        return "manifest".to_string();
    }
    if (path.starts_with(&devices_prefix)
        || path.starts_with("devices/")
        || path.contains("/devices/"))
        && path.ends_with(".json")
    {
        return "device".to_string();
    }
    if path.starts_with(&logs_prefix) || path.starts_with("logs/") || path.contains("/logs/") {
        return "log".to_string();
    }
    if path.starts_with(&snapshots_prefix)
        || path.starts_with("snapshots/")
        || path.contains("/snapshots/")
    {
        return "snapshot".to_string();
    }
    "unknown".to_string()
}

fn browser_storage_sync_cloud_device_path(device_id: &str) -> String {
    format!(
        "{}{}.json",
        BROWSER_STORAGE_SYNC_CLOUD_DEVICES_PREFIX,
        normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH)
    )
}

fn browser_storage_sync_cloud_log_path(collection: &str, device_id: &str, sequence: i64) -> String {
    format!(
        "{}{}/{}-{:016}.json",
        BROWSER_STORAGE_SYNC_CLOUD_LOGS_PREFIX,
        collection,
        normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        sequence.max(0)
    )
}

fn browser_storage_sync_cloud_logs_prefix(collection: &str) -> String {
    format!("{BROWSER_STORAGE_SYNC_CLOUD_LOGS_PREFIX}{collection}/")
}

fn browser_storage_sync_cloud_snapshot_path(collection: &str) -> String {
    format!("{BROWSER_STORAGE_SYNC_CLOUD_SNAPSHOTS_PREFIX}{collection}.json")
}

fn browser_storage_sync_cloud_collection_from_snapshot_path(path: &str) -> Option<String> {
    let collection = path
        .strip_prefix(BROWSER_STORAGE_SYNC_CLOUD_SNAPSHOTS_PREFIX)?
        .strip_suffix(".json")?;
    normalize_optional_sync_text(Some(collection.to_string()), MAX_SYNC_TEXT_LENGTH)
}

fn browser_storage_sync_cloud_collection_from_log_path(path: &str) -> Option<String> {
    let rest = path.strip_prefix(BROWSER_STORAGE_SYNC_CLOUD_LOGS_PREFIX)?;
    let collection = rest.split('/').next()?;
    normalize_optional_sync_text(Some(collection.to_string()), MAX_SYNC_TEXT_LENGTH)
}

fn browser_storage_sync_cloud_empty_collection_state(
    collection: &str,
    updated_at_unix_seconds: i64,
) -> BrowserStorageSyncCloudCollectionState {
    BrowserStorageSyncCloudCollectionState {
        collection: collection.to_string(),
        latest_log_sequence: 0,
        latest_log_path: None,
        snapshot_path: browser_storage_sync_cloud_snapshot_path(collection),
        snapshot_revision: 0,
        high_watermark_cursor: String::new(),
        updated_at_unix_seconds,
    }
}

fn normalize_browser_storage_sync_cloud_manifest_device(
    device: BrowserStorageSyncCloudManifestDevice,
    fallback_updated_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudManifestDevice> {
    let device_id = normalize_required_sync_id(&device.device_id)?;
    Some(BrowserStorageSyncCloudManifestDevice {
        device_id: device_id.clone(),
        status: normalize_browser_storage_sync_cloud_device_status(&device.status),
        device_path: browser_storage_sync_cloud_device_path(&device_id),
        added_at_unix_seconds: normalize_unix_seconds(device.added_at_unix_seconds),
        updated_at_unix_seconds: normalize_unix_seconds(device.updated_at_unix_seconds)
            .max(fallback_updated_at_unix_seconds),
        last_seen_at_unix_seconds: device.last_seen_at_unix_seconds.map(normalize_unix_seconds),
    })
}

fn normalize_browser_storage_sync_cloud_collection_state(
    state: BrowserStorageSyncCloudCollectionState,
    fallback_updated_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudCollectionState> {
    let collection = normalize_sync_collection(&state.collection)?;
    let latest_log_sequence = state.latest_log_sequence.max(0);
    let latest_log_path = normalize_optional_sync_text(state.latest_log_path, MAX_SYNC_URL_LENGTH);
    let high_watermark_cursor =
        normalize_sync_text(&state.high_watermark_cursor, "", MAX_SYNC_TEXT_LENGTH);

    Some(BrowserStorageSyncCloudCollectionState {
        collection: collection.clone(),
        latest_log_sequence,
        latest_log_path,
        snapshot_path: browser_storage_sync_cloud_snapshot_path(&collection),
        snapshot_revision: state.snapshot_revision.max(0),
        high_watermark_cursor,
        updated_at_unix_seconds: normalize_unix_seconds(state.updated_at_unix_seconds)
            .max(fallback_updated_at_unix_seconds),
    })
}

fn normalize_browser_storage_sync_cloud_device_status(status: &str) -> String {
    match status.trim() {
        BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_REVOKED => {
            BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_REVOKED.to_string()
        }
        _ => BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE.to_string(),
    }
}

fn filter_browser_storage_sync_batch_to_collection(
    batch: BrowserStorageSyncBatch,
    collection: &str,
) -> Option<BrowserStorageSyncBatch> {
    let mut batch = normalize_browser_storage_sync_batch(Some(batch))?;
    batch
        .records
        .retain(|record| record.payload.record_type().collection() == collection);
    batch
        .cursors
        .retain(|cursor| cursor.collection == collection);
    Some(batch)
}

fn parse_optional_browser_storage_sync_cloud_manifest(
    manifest_json: &str,
) -> Option<Option<BrowserStorageSyncCloudManifest>> {
    let trimmed = manifest_json.trim();
    if trimmed.is_empty() || trimmed == "null" {
        return Some(None);
    }
    serde_json::from_str::<BrowserStorageSyncCloudManifest>(trimmed)
        .ok()
        .map(Some)
}

