fn parse_browser_storage_sync_cloud_read_results(
    results_json: &str,
) -> Option<Vec<BrowserStorageSyncCloudReadOperationResult>> {
    let trimmed = results_json.trim();
    if trimmed.is_empty() {
        return Some(Vec::new());
    }
    if let Ok(results) =
        serde_json::from_str::<Vec<BrowserStorageSyncCloudReadOperationResult>>(trimmed)
    {
        return Some(results);
    }
    let value = serde_json::from_str::<Value>(trimmed).ok()?;
    serde_json::from_value::<Vec<BrowserStorageSyncCloudReadOperationResult>>(
        value.get("readResults")?.clone(),
    )
    .ok()
}

