fn browser_storage_sync_cloud_default_device_document(
    scope: &str,
    device_id: &str,
    generated_at_unix_seconds: i64,
) -> BrowserStorageSyncCloudDeviceDocument {
    BrowserStorageSyncCloudDeviceDocument {
        version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        display_name: "Actro Device".to_string(),
        platform: "unknown".to_string(),
        app_version: None,
        status: BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE.to_string(),
        added_at_unix_seconds: generated_at_unix_seconds,
        updated_at_unix_seconds: generated_at_unix_seconds,
        last_seen_at_unix_seconds: Some(generated_at_unix_seconds),
        capabilities: Vec::new(),
    }
}

fn browser_storage_sync_cloud_push_device_document(
    device: Option<BrowserStorageSyncCloudDeviceDocument>,
    scope: &str,
    device_id: &str,
    generated_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudDeviceDocument> {
    let generated_at = normalize_unix_seconds(generated_at_unix_seconds);
    let mut device = match device {
        Some(device) => normalize_browser_storage_sync_cloud_device_document(
            Some(device),
            scope,
            device_id,
            generated_at,
        )?,
        None => browser_storage_sync_cloud_default_device_document(scope, device_id, generated_at),
    };
    device.scope = normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH);
    device.device_id = normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH);
    device.status = BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE.to_string();
    device.updated_at_unix_seconds = device.updated_at_unix_seconds.max(generated_at);
    device.last_seen_at_unix_seconds = Some(generated_at);
    Some(device)
}

#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_membership_device_document(
    device: Option<BrowserStorageSyncCloudDeviceDocument>,
    scope: &str,
    device_id: &str,
    status: &str,
    display_name: &str,
    platform: &str,
    app_version: &str,
    generated_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudDeviceDocument> {
    let generated_at = normalize_unix_seconds(generated_at_unix_seconds);
    let normalized_status = normalize_browser_storage_sync_cloud_device_status(status);
    let mut device = match device {
        Some(device) => normalize_browser_storage_sync_cloud_device_document(
            Some(device),
            scope,
            device_id,
            generated_at,
        )?,
        None => browser_storage_sync_cloud_default_device_document(scope, device_id, generated_at),
    };
    if normalized_status == BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE
        && device.status == BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_REVOKED
    {
        return None;
    }

    device.scope = normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH);
    device.device_id = normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH);
    if let Some(display_name) =
        normalize_optional_sync_text(Some(display_name.to_string()), MAX_TITLE_LENGTH)
    {
        device.display_name = display_name;
    }
    if let Some(platform) =
        normalize_optional_sync_text(Some(platform.to_string()), MAX_SYNC_TEXT_LENGTH)
    {
        device.platform = platform.to_ascii_lowercase();
    }
    if let Some(app_version) =
        normalize_optional_sync_text(Some(app_version.to_string()), MAX_SYNC_TEXT_LENGTH)
    {
        device.app_version = Some(app_version);
    }
    device.status = normalized_status;
    device.updated_at_unix_seconds = device.updated_at_unix_seconds.max(generated_at);
    if device.status == BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE {
        device.last_seen_at_unix_seconds = Some(generated_at);
    }
    Some(device)
}

fn browser_storage_sync_cloud_upsert_active_manifest_device(
    manifest: &mut BrowserStorageSyncCloudManifest,
    device_id: &str,
    generated_at_unix_seconds: i64,
) -> Option<()> {
    let device_id = normalize_required_sync_id(device_id)?;
    let generated_at = normalize_unix_seconds(generated_at_unix_seconds);
    if let Some(device) = manifest
        .devices
        .iter_mut()
        .find(|device| device.device_id == device_id)
    {
        if device.status == BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_REVOKED {
            return None;
        }
        device.status = BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE.to_string();
        device.device_path = browser_storage_sync_cloud_device_path(&device_id);
        device.updated_at_unix_seconds = device.updated_at_unix_seconds.max(generated_at);
        device.last_seen_at_unix_seconds = Some(generated_at);
    } else {
        manifest
            .devices
            .push(BrowserStorageSyncCloudManifestDevice {
                device_id: device_id.clone(),
                status: BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE.to_string(),
                device_path: browser_storage_sync_cloud_device_path(&device_id),
                added_at_unix_seconds: generated_at,
                updated_at_unix_seconds: generated_at,
                last_seen_at_unix_seconds: Some(generated_at),
            });
    }
    manifest
        .devices
        .sort_by(|left, right| left.device_id.cmp(&right.device_id));
    manifest
        .devices
        .dedup_by(|left, right| left.device_id == right.device_id);
    Some(())
}

fn browser_storage_sync_cloud_set_manifest_device_status(
    manifest: &mut BrowserStorageSyncCloudManifest,
    device_id: &str,
    status: &str,
    generated_at_unix_seconds: i64,
) -> Option<()> {
    let device_id = normalize_required_sync_id(device_id)?;
    let status = normalize_browser_storage_sync_cloud_device_status(status);
    let generated_at = normalize_unix_seconds(generated_at_unix_seconds);
    if let Some(device) = manifest
        .devices
        .iter_mut()
        .find(|device| device.device_id == device_id)
    {
        device.status = status;
        device.device_path = browser_storage_sync_cloud_device_path(&device_id);
        device.updated_at_unix_seconds = device.updated_at_unix_seconds.max(generated_at);
        if device.status == BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_ACTIVE {
            device.last_seen_at_unix_seconds = Some(generated_at);
        }
    } else {
        manifest
            .devices
            .push(BrowserStorageSyncCloudManifestDevice {
                device_id: device_id.clone(),
                status,
                device_path: browser_storage_sync_cloud_device_path(&device_id),
                added_at_unix_seconds: generated_at,
                updated_at_unix_seconds: generated_at,
                last_seen_at_unix_seconds: None,
            });
    }
    manifest
        .devices
        .sort_by(|left, right| left.device_id.cmp(&right.device_id));
    manifest
        .devices
        .dedup_by(|left, right| left.device_id == right.device_id);
    Some(())
}

fn browser_storage_sync_cloud_touched_collections(batch: &BrowserStorageSyncBatch) -> Vec<String> {
    BrowserStorageSyncRecordType::all()
        .iter()
        .map(|record_type| record_type.collection())
        .filter(|collection| {
            batch
                .records
                .iter()
                .any(|record| record.payload.record_type().collection() == *collection)
                || batch
                    .cursors
                    .iter()
                    .any(|cursor| cursor.collection == *collection)
        })
        .map(|collection| collection.to_string())
        .collect()
}

fn browser_storage_sync_cloud_collection_index(
    manifest: &mut BrowserStorageSyncCloudManifest,
    collection: &str,
    generated_at_unix_seconds: i64,
) -> usize {
    if let Some(index) = manifest
        .collections
        .iter()
        .position(|state| state.collection == collection)
    {
        return index;
    }
    manifest
        .collections
        .push(browser_storage_sync_cloud_empty_collection_state(
            collection,
            generated_at_unix_seconds,
        ));
    manifest.collections.len() - 1
}

fn browser_storage_sync_cloud_cursor_for_collection(
    batch: &BrowserStorageSyncBatch,
    collection: &str,
) -> Option<String> {
    batch
        .cursors
        .iter()
        .rev()
        .find(|cursor| cursor.collection == collection)
        .map(|cursor| cursor.cursor.clone())
}

fn browser_storage_sync_cloud_local_cursor_for_collection(
    cursors: &[BrowserStorageSyncCursorUpdate],
    collection: &str,
) -> Option<String> {
    cursors
        .iter()
        .rev()
        .find(|cursor| cursor.collection == collection)
        .map(|cursor| cursor.cursor.clone())
}

fn browser_storage_sync_cloud_manifest_device_is_revoked(
    manifest: &BrowserStorageSyncCloudManifest,
    device_id: &str,
) -> bool {
    manifest.devices.iter().any(|device| {
        device.device_id == device_id
            && device.status == BROWSER_STORAGE_SYNC_CLOUD_DEVICE_STATUS_REVOKED
    })
}

fn browser_storage_sync_cloud_collection_is_current(
    manifest: &BrowserStorageSyncCloudManifest,
    cursors: &[BrowserStorageSyncCursorUpdate],
    collection: &str,
) -> bool {
    let local_cursor = browser_storage_sync_cloud_local_cursor_for_collection(cursors, collection)
        .unwrap_or_default();
    if local_cursor.is_empty() {
        return false;
    }
    manifest
        .collections
        .iter()
        .find(|state| state.collection == collection)
        .map(|state| {
            !state.high_watermark_cursor.is_empty() && state.high_watermark_cursor == local_cursor
        })
        .unwrap_or(false)
}

fn normalize_browser_storage_sync_cloud_log_list_limit(limit: u32) -> u32 {
    let max = MAX_BROWSER_STORAGE_SYNC_RECORDS as u32;
    if limit == 0 {
        DEFAULT_SYNC_PULL_LIMIT.min(max)
    } else {
        limit.min(max).max(1)
    }
}

fn normalize_provider_revision(revision: &str) -> Option<String> {
    let revision = revision.trim();
    if revision.is_empty() {
        None
    } else {
        Some(revision.chars().take(MAX_SYNC_URL_LENGTH).collect())
    }
}

fn browser_storage_sync_cloud_memory_list(
    store: &BrowserStorageSyncMemoryCloudStore,
    prefix: &str,
    page: Option<BrowserStorageSyncCloudListPage>,
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudListResult> {
    let prefix = browser_storage_sync_cloud_validate_store_prefix(prefix)?;
    let page = page.unwrap_or(BrowserStorageSyncCloudListPage {
        cursor: None,
        limit: None,
    });
    let cursor = page.cursor.as_deref().and_then(normalize_provider_revision);
    let limit = normalize_browser_storage_sync_cloud_log_list_limit(page.limit.unwrap_or(0));
    let state = store
        .state
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let mut objects = Vec::new();
    let mut next_cursor = None;
    for (path, object) in state
        .objects
        .iter()
        .filter(|(path, _)| path.starts_with(&prefix))
    {
        if cursor
            .as_deref()
            .map(|cursor| path.as_str() <= cursor)
            .unwrap_or(false)
        {
            continue;
        }
        if objects.len() >= limit as usize {
            next_cursor = objects
                .last()
                .map(|metadata: &BrowserStorageSyncCloudObjectMetadata| metadata.path.clone());
            break;
        }
        objects.push(object.metadata.clone());
    }
    Ok(BrowserStorageSyncCloudListResult {
        prefix,
        objects,
        next_cursor,
    })
}

fn browser_storage_sync_cloud_memory_read(
    store: &BrowserStorageSyncMemoryCloudStore,
    path: &str,
) -> BrowserStorageSyncCloudStoreResult<Option<BrowserStorageSyncCloudObject>> {
    let path = browser_storage_sync_cloud_validate_store_object_path(path)?;
    Ok(store
        .state
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .objects
        .get(&path)
        .cloned())
}

fn browser_storage_sync_cloud_memory_write(
    store: &BrowserStorageSyncMemoryCloudStore,
    request: BrowserStorageSyncCloudWriteRequest<'_>,
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudWriteReceipt> {
    let path = browser_storage_sync_cloud_validate_store_object_path(request.path)?;
    let expected_revision = request
        .expected_revision
        .and_then(normalize_provider_revision);
    let content_type = request
        .content_type
        .and_then(normalize_provider_revision)
        .or_else(|| Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON.to_string()));
    let mut state = store
        .state
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let existing_revision = state
        .objects
        .get(&path)
        .and_then(|object| object.metadata.revision.clone());
    if expected_revision.is_some() && expected_revision != existing_revision {
        return Err(BrowserStorageSyncCloudStoreError::conflict(format!(
            "memory cloud store revision mismatch for {path}",
        )));
    }
    let created = !state.objects.contains_key(&path);
    let replaced = !created;
    let revision = BrowserStorageSyncMemoryCloudStore::next_revision(&mut state);
    let mut provider_metadata = BTreeMap::new();
    provider_metadata.insert("providerKind".to_string(), "memory".to_string());
    let metadata = BrowserStorageSyncCloudObjectMetadata {
        path: path.clone(),
        revision: Some(revision),
        content_type,
        content_hash: Some(browser_storage_sync_cloud_memory_content_hash(
            request.bytes,
        )),
        size_bytes: Some(request.bytes.len().min(u64::MAX as usize) as u64),
        modified_at_unix_seconds: None,
        provider_metadata,
    };
    state.objects.insert(
        path,
        BrowserStorageSyncCloudObject {
            bytes: request.bytes.to_vec(),
            metadata: metadata.clone(),
        },
    );
    Ok(BrowserStorageSyncCloudWriteReceipt {
        metadata,
        created,
        replaced,
    })
}

fn browser_storage_sync_cloud_memory_delete(
    store: &BrowserStorageSyncMemoryCloudStore,
    request: BrowserStorageSyncCloudDeleteRequest<'_>,
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudDeleteReceipt> {
    let path = browser_storage_sync_cloud_validate_store_object_path(request.path)?;
    let expected_revision = request
        .expected_revision
        .and_then(normalize_provider_revision);
    let mut state = store
        .state
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let existing_revision = state
        .objects
        .get(&path)
        .and_then(|object| object.metadata.revision.clone());
    if expected_revision.is_some() && expected_revision != existing_revision {
        return Err(BrowserStorageSyncCloudStoreError::conflict(format!(
            "memory cloud store delete revision mismatch for {path}",
        )));
    }
    let deleted = state.objects.remove(&path).is_some();
    let revision = if deleted {
        Some(BrowserStorageSyncMemoryCloudStore::next_revision(
            &mut state,
        ))
    } else {
        None
    };
    Ok(BrowserStorageSyncCloudDeleteReceipt {
        path,
        deleted,
        revision,
    })
}

fn browser_storage_sync_cloud_local_folder_list(
    store: &BrowserStorageSyncLocalFolderCloudStore,
    prefix: &str,
    page: Option<BrowserStorageSyncCloudListPage>,
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudListResult> {
    let prefix = browser_storage_sync_cloud_validate_store_prefix(prefix)?;
    let page = page.unwrap_or(BrowserStorageSyncCloudListPage {
        cursor: None,
        limit: None,
    });
    let cursor = page.cursor.as_deref().and_then(normalize_provider_revision);
    let limit = normalize_browser_storage_sync_cloud_log_list_limit(page.limit.unwrap_or(0));
    let _guard = store
        .operation_lock
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let mut files = browser_storage_sync_cloud_local_folder_files(store.root_dir())?;
    files.sort();

    let mut objects = Vec::new();
    let mut next_cursor = None;
    for (cloud_path, file_path) in files
        .into_iter()
        .filter(|(path, _)| path.starts_with(&prefix))
    {
        if cursor
            .as_deref()
            .map(|cursor| cloud_path.as_str() <= cursor)
            .unwrap_or(false)
        {
            continue;
        }
        if objects.len() >= limit as usize {
            next_cursor = objects
                .last()
                .map(|metadata: &BrowserStorageSyncCloudObjectMetadata| metadata.path.clone());
            break;
        }
        objects.push(browser_storage_sync_cloud_local_folder_metadata(
            &cloud_path,
            &file_path,
        )?);
    }

    Ok(BrowserStorageSyncCloudListResult {
        prefix,
        objects,
        next_cursor,
    })
}

fn browser_storage_sync_cloud_local_folder_read(
    store: &BrowserStorageSyncLocalFolderCloudStore,
    path: &str,
) -> BrowserStorageSyncCloudStoreResult<Option<BrowserStorageSyncCloudObject>> {
    let (cloud_path, file_path) =
        browser_storage_sync_cloud_local_folder_fs_path(store.root_dir(), path)?;
    let _guard = store
        .operation_lock
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if !file_path.exists() {
        return Ok(None);
    }
    let bytes = fs::read(&file_path).map_err(|error| {
        browser_storage_sync_cloud_local_folder_io_error("read", &cloud_path, error)
    })?;
    let metadata = browser_storage_sync_cloud_local_folder_metadata_from_bytes(
        &cloud_path,
        &file_path,
        &bytes,
    )?;
    Ok(Some(BrowserStorageSyncCloudObject { bytes, metadata }))
}

fn browser_storage_sync_cloud_local_folder_write(
    store: &BrowserStorageSyncLocalFolderCloudStore,
    request: BrowserStorageSyncCloudWriteRequest<'_>,
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudWriteReceipt> {
    let (cloud_path, file_path) =
        browser_storage_sync_cloud_local_folder_fs_path(store.root_dir(), request.path)?;
    let expected_revision = request
        .expected_revision
        .and_then(normalize_provider_revision);
    let _guard = store
        .operation_lock
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let existing_revision = if file_path.exists() {
        Some(browser_storage_sync_cloud_local_folder_metadata(
            &cloud_path,
            &file_path,
        )?)
        .and_then(|metadata| metadata.revision)
    } else {
        None
    };
    if expected_revision.is_some() && expected_revision != existing_revision {
        return Err(BrowserStorageSyncCloudStoreError::conflict(format!(
            "local folder cloud store revision mismatch for {cloud_path}",
        )));
    }

    if let Some(parent) = file_path.parent() {
        fs::create_dir_all(parent).map_err(|error| {
            browser_storage_sync_cloud_local_folder_io_error("createParent", &cloud_path, error)
        })?;
    }
    let created = !file_path.exists();
    fs::write(&file_path, request.bytes).map_err(|error| {
        browser_storage_sync_cloud_local_folder_io_error("write", &cloud_path, error)
    })?;
    let metadata = browser_storage_sync_cloud_local_folder_metadata_from_bytes(
        &cloud_path,
        &file_path,
        request.bytes,
    )?;

    Ok(BrowserStorageSyncCloudWriteReceipt {
        metadata,
        created,
        replaced: !created,
    })
}

fn browser_storage_sync_cloud_local_folder_delete(
    store: &BrowserStorageSyncLocalFolderCloudStore,
    request: BrowserStorageSyncCloudDeleteRequest<'_>,
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudDeleteReceipt> {
    let (cloud_path, file_path) =
        browser_storage_sync_cloud_local_folder_fs_path(store.root_dir(), request.path)?;
    let expected_revision = request
        .expected_revision
        .and_then(normalize_provider_revision);
    let _guard = store
        .operation_lock
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let existing_revision = if file_path.exists() {
        Some(browser_storage_sync_cloud_local_folder_metadata(
            &cloud_path,
            &file_path,
        )?)
        .and_then(|metadata| metadata.revision)
    } else {
        None
    };
    if expected_revision.is_some() && expected_revision != existing_revision {
        return Err(BrowserStorageSyncCloudStoreError::conflict(format!(
            "local folder cloud store delete revision mismatch for {cloud_path}",
        )));
    }
    let deleted = if file_path.exists() {
        fs::remove_file(&file_path).map_err(|error| {
            browser_storage_sync_cloud_local_folder_io_error("delete", &cloud_path, error)
        })?;
        true
    } else {
        false
    };
    let revision = if deleted {
        existing_revision.map(|revision| format!("deleted:{revision}"))
    } else {
        None
    };

    Ok(BrowserStorageSyncCloudDeleteReceipt {
        path: cloud_path,
        deleted,
        revision,
    })
}

fn browser_storage_sync_cloud_local_folder_fs_path(
    root_dir: &Path,
    path: &str,
) -> BrowserStorageSyncCloudStoreResult<(String, PathBuf)> {
    let cloud_path = browser_storage_sync_cloud_validate_store_object_path(path)?;
    let mut file_path = root_dir.to_path_buf();
    for segment in cloud_path.split('/') {
        file_path.push(segment);
    }
    Ok((cloud_path, file_path))
}

fn browser_storage_sync_cloud_local_folder_files(
    root_dir: &Path,
) -> BrowserStorageSyncCloudStoreResult<Vec<(String, PathBuf)>> {
    let mut files = Vec::new();
    if !root_dir.exists() {
        return Ok(files);
    }
    browser_storage_sync_cloud_local_folder_collect_files(root_dir, root_dir, &mut files)?;
    Ok(files)
}

fn browser_storage_sync_cloud_local_folder_collect_files(
    root_dir: &Path,
    directory: &Path,
    files: &mut Vec<(String, PathBuf)>,
) -> BrowserStorageSyncCloudStoreResult<()> {
    let entries = fs::read_dir(directory).map_err(|error| {
        browser_storage_sync_cloud_local_folder_io_error(
            "list",
            &directory.to_string_lossy(),
            error,
        )
    })?;
    for entry in entries {
        let entry = entry.map_err(|error| {
            browser_storage_sync_cloud_local_folder_io_error(
                "list",
                &directory.to_string_lossy(),
                error,
            )
        })?;
        let path = entry.path();
        let file_type = entry.file_type().map_err(|error| {
            browser_storage_sync_cloud_local_folder_io_error("list", &path.to_string_lossy(), error)
        })?;
        if file_type.is_dir() {
            browser_storage_sync_cloud_local_folder_collect_files(root_dir, &path, files)?;
        } else if file_type.is_file() {
            let relative = match path.strip_prefix(root_dir) {
                Ok(relative) => relative,
                Err(_) => continue,
            };
            let cloud_path = relative.to_string_lossy().replace('\\', "/");
            if browser_storage_sync_cloud_validate_store_object_path(&cloud_path).is_ok() {
                files.push((cloud_path, path));
            }
        }
    }
    Ok(())
}

fn browser_storage_sync_cloud_local_folder_metadata(
    cloud_path: &str,
    file_path: &Path,
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudObjectMetadata> {
    let bytes = fs::read(file_path).map_err(|error| {
        browser_storage_sync_cloud_local_folder_io_error("metadata", cloud_path, error)
    })?;
    browser_storage_sync_cloud_local_folder_metadata_from_bytes(cloud_path, file_path, &bytes)
}

fn browser_storage_sync_cloud_local_folder_metadata_from_bytes(
    cloud_path: &str,
    file_path: &Path,
    bytes: &[u8],
) -> BrowserStorageSyncCloudStoreResult<BrowserStorageSyncCloudObjectMetadata> {
    let fs_metadata = fs::metadata(file_path).map_err(|error| {
        browser_storage_sync_cloud_local_folder_io_error("metadata", cloud_path, error)
    })?;
    let content_hash = browser_storage_sync_cloud_memory_content_hash(bytes);
    let mut provider_metadata = BTreeMap::new();
    provider_metadata.insert("providerKind".to_string(), "localFolder".to_string());
    provider_metadata.insert("revisionKind".to_string(), "contentHash".to_string());

    Ok(BrowserStorageSyncCloudObjectMetadata {
        path: browser_storage_sync_cloud_validate_store_object_path(cloud_path)?,
        revision: Some(content_hash.clone()),
        content_type: Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON.to_string()),
        content_hash: Some(content_hash),
        size_bytes: Some(bytes.len().min(u64::MAX as usize) as u64),
        modified_at_unix_seconds: fs_metadata
            .modified()
            .ok()
            .and_then(|modified| modified.duration_since(std::time::UNIX_EPOCH).ok())
            .map(|duration| duration.as_secs().min(i64::MAX as u64) as i64),
        provider_metadata,
    })
}

fn browser_storage_sync_cloud_local_folder_io_error(
    action: &str,
    path: &str,
    error: std::io::Error,
) -> BrowserStorageSyncCloudStoreError {
    let (kind, retryable) = match error.kind() {
        std::io::ErrorKind::NotFound => (BrowserStorageSyncCloudStoreErrorKind::NotFound, true),
        std::io::ErrorKind::PermissionDenied => {
            (BrowserStorageSyncCloudStoreErrorKind::Unauthorized, false)
        }
        std::io::ErrorKind::Interrupted
        | std::io::ErrorKind::TimedOut
        | std::io::ErrorKind::WouldBlock => (BrowserStorageSyncCloudStoreErrorKind::Network, true),
        _ => (BrowserStorageSyncCloudStoreErrorKind::Provider, true),
    };
    BrowserStorageSyncCloudStoreError::new(
        kind,
        format!("local folder cloud store {action} failed for {path}: {error}"),
        retryable,
    )
}

fn browser_storage_sync_cloud_validate_store_object_path(
    path: &str,
) -> BrowserStorageSyncCloudStoreResult<String> {
    let path = browser_storage_sync_cloud_normalize_store_path(path)?;
    if path == BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH || path.ends_with('/') {
        return Err(BrowserStorageSyncCloudStoreError::invalid_path(
            "Cloud object path must identify a file under the Actro browser sync root.",
        ));
    }
    Ok(path)
}

fn browser_storage_sync_cloud_validate_store_prefix(
    prefix: &str,
) -> BrowserStorageSyncCloudStoreResult<String> {
    let prefix = prefix.trim().replace('\\', "/");
    let has_trailing_slash = prefix.ends_with('/');
    let normalized = browser_storage_sync_cloud_normalize_store_path(prefix.trim_end_matches('/'))?;
    if has_trailing_slash && normalized != BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH {
        Ok(format!("{normalized}/"))
    } else {
        Ok(normalized)
    }
}

fn browser_storage_sync_cloud_normalize_store_path(
    path: &str,
) -> BrowserStorageSyncCloudStoreResult<String> {
    let path = path.trim().replace('\\', "/");
    if path.is_empty()
        || path.starts_with('/')
        || path.contains('\0')
        || path.len() > MAX_SYNC_URL_LENGTH
    {
        return Err(BrowserStorageSyncCloudStoreError::invalid_path(
            "Cloud object paths must be relative non-empty paths under the Actro browser sync root.",
        ));
    }
    if path != BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH
        && !path.starts_with(&format!("{BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH}/"))
    {
        return Err(BrowserStorageSyncCloudStoreError::invalid_path(
            "Cloud object path is outside the Actro browser sync root.",
        ));
    }
    if path
        .split('/')
        .any(|segment| segment.is_empty() || segment == "." || segment == "..")
    {
        return Err(BrowserStorageSyncCloudStoreError::invalid_path(
            "Cloud object path contains an unsafe path segment.",
        ));
    }
    Ok(path)
}

fn browser_storage_sync_cloud_memory_content_hash(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    let mut output = String::from("sha256:");
    for byte in digest {
        output.push(browser_storage_sync_cloud_hex_digit(byte >> 4));
        output.push(browser_storage_sync_cloud_hex_digit(byte & 0x0f));
    }
    output
}

fn browser_storage_sync_cloud_hex_digit(value: u8) -> char {
    match value {
        0..=9 => (b'0' + value) as char,
        10..=15 => (b'a' + (value - 10)) as char,
        _ => unreachable!("hex digit nibble out of range"),
    }
}

fn browser_storage_sync_cloud_planned_write(
    operation_index: usize,
    operation_type: &str,
    path: &str,
    expected_revision: Option<String>,
    body_json: String,
    collection: Option<String>,
    sequence: Option<i64>,
) -> BrowserStorageSyncCloudPlannedOperation {
    BrowserStorageSyncCloudPlannedOperation {
        operation_index: operation_index as u32,
        operation_type: operation_type.to_string(),
        path: path.to_string(),
        content_type: BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON.to_string(),
        expected_revision,
        body_json,
        collection,
        sequence,
        required: true,
        conflict_action: BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY.to_string(),
        write_reason: browser_storage_sync_cloud_planned_write_reason(operation_type).to_string(),
    }
}

fn browser_storage_sync_cloud_planned_write_reason(operation_type: &str) -> &'static str {
    match operation_type {
        "writeDevice" => "writeCloudDeviceDocument",
        "writeLog" => "appendCloudCollectionLog",
        "writeManifest" => "commitCloudManifestState",
        "writeSnapshot" => "writeCompactedSnapshot",
        _ => "plannedCloudWrite",
    }
}

