#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_compaction_round_summary(
    read_results: &[BrowserStorageSyncCloudReadOperationResult],
    write_results: &[BrowserStorageSyncCloudWriteOperationResult],
    delete_results: &[BrowserStorageSyncCloudWriteOperationResult],
    compatibility_preflight: Option<&BrowserStorageSyncCloudCompatibilityPreflightPlan>,
    compaction_plan: Option<&BrowserStorageSyncCloudCompactionPlan>,
    result_plan: Option<&BrowserStorageSyncCloudCompactionResultPlan>,
    completed: bool,
    manifest_committed: bool,
    cleanup_completed: bool,
    should_reread: bool,
    should_retry: bool,
    should_retry_cleanup: bool,
    client_action: &str,
    planning_error_kind: Option<&str>,
) -> BrowserStorageSyncCloudCompactionRoundSummary {
    let read_result_count = read_results.len().min(u32::MAX as usize) as u32;
    let successful_read_count = read_results
        .iter()
        .filter(|result| result.success)
        .count()
        .min(u32::MAX as usize) as u32;
    let failed_read_count = read_result_count.saturating_sub(successful_read_count);
    let write_result_count = write_results.len().min(u32::MAX as usize) as u32;
    let successful_write_count = write_results
        .iter()
        .filter(|result| result.success)
        .count()
        .min(u32::MAX as usize) as u32;
    let failed_write_count = write_result_count.saturating_sub(successful_write_count);
    let delete_result_count = delete_results.len().min(u32::MAX as usize) as u32;
    let successful_delete_count = delete_results
        .iter()
        .filter(|result| result.success)
        .count()
        .min(u32::MAX as usize) as u32;
    let failed_delete_count = delete_result_count.saturating_sub(successful_delete_count);

    let mut collections = BTreeSet::new();
    let mut write_reasons = BTreeSet::new();
    let mut delete_reasons = BTreeSet::new();
    let mut compacted_log_count = 0_u32;
    let mut retained_log_count = 0_u32;
    let mut deleted_log_count = 0_u32;
    if let Some(plan) = compaction_plan {
        for collection in &plan.compacted_collections {
            collections.insert(collection.collection.clone());
            compacted_log_count =
                compacted_log_count.saturating_add(collection.compacted_log_count);
            retained_log_count = retained_log_count.saturating_add(collection.retained_log_count);
            deleted_log_count = deleted_log_count.saturating_add(collection.deleted_log_count);
        }
        for operation in &plan.operations {
            if let Some(collection) = &operation.collection {
                collections.insert(collection.clone());
            }
            if !operation.write_reason.is_empty() {
                write_reasons.insert(operation.write_reason.clone());
            }
        }
        for operation in &plan.delete_operations {
            if let Some(collection) = &operation.collection {
                collections.insert(collection.clone());
            }
            if !operation.delete_reason.is_empty() {
                delete_reasons.insert(operation.delete_reason.clone());
            }
        }
    }

    let mut read_reasons = BTreeSet::new();
    let mut failed_read_error_kinds = BTreeSet::new();
    for result in read_results {
        if let Some(collection) = &result.collection {
            collections.insert(collection.clone());
        }
        if !result.read_reason.is_empty() {
            read_reasons.insert(result.read_reason.clone());
        }
        if !result.success {
            if let Some(error_kind) = &result.error_kind {
                failed_read_error_kinds.insert(error_kind.clone());
            }
        }
    }

    let mut failed_write_error_kinds = BTreeSet::new();
    for result in write_results {
        if !result.success {
            if let Some(error_kind) = &result.error_kind {
                failed_write_error_kinds.insert(error_kind.clone());
            }
        }
    }

    let mut failed_delete_error_kinds = BTreeSet::new();
    for result in delete_results {
        if !result.success {
            if let Some(error_kind) = &result.error_kind {
                failed_delete_error_kinds.insert(error_kind.clone());
            }
        }
    }

    let mut issue_reasons = BTreeSet::new();
    if let Some(plan) = result_plan {
        for issue in &plan.issues {
            issue_reasons.insert(issue.reason.clone());
            if let Some(collection) = &issue.collection {
                collections.insert(collection.clone());
            }
            if let Some(reason) = &issue.write_reason {
                write_reasons.insert(reason.clone());
            }
            if let Some(reason) = &issue.delete_reason {
                delete_reasons.insert(reason.clone());
            }
        }
    }

    let compatibility_blocked = compatibility_preflight
        .map(|plan| plan.should_block_sync)
        .unwrap_or(false);
    let summary_reason = planning_error_kind
        .map(str::to_string)
        .or_else(|| {
            result_plan.and_then(|plan| plan.issues.first().map(|issue| issue.reason.clone()))
        })
        .unwrap_or_else(|| {
            if compaction_plan
                .map(|plan| !plan.should_compact)
                .unwrap_or(false)
            {
                "nothingToCompact".to_string()
            } else if completed && cleanup_completed {
                "compactionAndCleanupCompleted".to_string()
            } else if completed && should_retry_cleanup {
                "compactionCommittedCleanupRetryRequired".to_string()
            } else if completed {
                "compactionCommittedCleanupIncomplete".to_string()
            } else if compatibility_blocked {
                "cloudCompatibilityBlocked".to_string()
            } else if should_reread {
                "rereadCloudStateRequired".to_string()
            } else if should_retry {
                "providerRetryRequired".to_string()
            } else {
                "compactionRoundIncomplete".to_string()
            }
        });

    BrowserStorageSyncCloudCompactionRoundSummary {
        read_result_count,
        successful_read_count,
        failed_read_count,
        write_result_count,
        successful_write_count,
        failed_write_count,
        delete_result_count,
        successful_delete_count,
        failed_delete_count,
        planned_write_count: compaction_plan
            .map(|plan| plan.operation_count)
            .unwrap_or(0),
        planned_delete_count: compaction_plan
            .map(|plan| plan.delete_operation_count)
            .unwrap_or(0),
        compacted_collection_count: compaction_plan
            .map(|plan| plan.compacted_collections.len().min(u32::MAX as usize) as u32)
            .unwrap_or(0),
        compacted_log_count,
        retained_log_count,
        deleted_log_count,
        conflict_count: result_plan.map(|plan| plan.conflict_count).unwrap_or(0),
        retryable_failure_count: result_plan
            .map(|plan| plan.retryable_failure_count)
            .unwrap_or(0),
        compatibility_blocked,
        completed,
        manifest_committed,
        cleanup_completed,
        should_reread,
        should_retry,
        should_retry_cleanup,
        summary_action: client_action.to_string(),
        summary_reason,
        collections: collections.into_iter().collect(),
        read_reasons: read_reasons.into_iter().collect(),
        write_reasons: write_reasons.into_iter().collect(),
        delete_reasons: delete_reasons.into_iter().collect(),
        successful_paths: result_plan
            .map(|plan| plan.successful_paths.clone())
            .unwrap_or_default(),
        deleted_paths: result_plan
            .map(|plan| plan.deleted_paths.clone())
            .unwrap_or_default(),
        failed_read_error_kinds: failed_read_error_kinds.into_iter().collect(),
        failed_write_error_kinds: failed_write_error_kinds.into_iter().collect(),
        failed_delete_error_kinds: failed_delete_error_kinds.into_iter().collect(),
        issue_reasons: issue_reasons.into_iter().collect(),
    }
}

