#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_pull_round_summary(
    read_results: &[BrowserStorageSyncCloudReadOperationResult],
    pull_plan: Option<&BrowserStorageSyncCloudPullPlan>,
    apply_plan: Option<&BrowserStorageSyncCloudPullApplyPlan>,
    completed: bool,
    should_apply_remote: bool,
    should_reread: bool,
    should_retry: bool,
    client_action: &str,
    planning_error_kind: Option<&str>,
) -> BrowserStorageSyncCloudPullRoundSummary {
    let read_result_count = read_results.len().min(u32::MAX as usize) as u32;
    let successful_read_count = read_results
        .iter()
        .filter(|result| result.success)
        .count()
        .min(u32::MAX as usize) as u32;
    let failed_read_count = read_result_count.saturating_sub(successful_read_count);
    let snapshot_read_count = read_results
        .iter()
        .filter(|result| result.operation_type == "readSnapshot")
        .count()
        .min(u32::MAX as usize) as u32;
    let log_list_read_count = read_results
        .iter()
        .filter(|result| result.operation_type == "listLogs")
        .count()
        .min(u32::MAX as usize) as u32;
    let log_object_read_count = read_results
        .iter()
        .filter(|result| result.operation_type == "readLog")
        .count()
        .min(u32::MAX as usize) as u32;
    let continuation_read_count = read_results
        .iter()
        .filter(|result| {
            result.operation_type == "listLogs"
                && result.read_reason == "continueProviderLogListing"
        })
        .count()
        .min(u32::MAX as usize) as u32;

    let mut collections = BTreeSet::<String>::new();
    if let Some(plan) = pull_plan {
        for collection in &plan.read_summary.active_collections {
            collections.insert(collection.clone());
        }
    }
    if let Some(plan) = apply_plan {
        for collection in &plan.collections {
            collections.insert(collection.clone());
        }
        for collection in &plan.apply_summary.skipped_snapshot_collections {
            collections.insert(collection.clone());
        }
        for collection in &plan.apply_summary.skipped_log_collections {
            collections.insert(collection.clone());
        }
    }
    for result in read_results {
        if let Some(collection) = &result.collection {
            collections.insert(collection.clone());
        }
    }

    let mut read_reasons = BTreeSet::new();
    let mut failed_read_error_kinds = BTreeSet::new();
    for result in read_results {
        if !result.read_reason.is_empty() {
            read_reasons.insert(result.read_reason.clone());
        }
        if !result.success {
            if let Some(error_kind) = &result.error_kind {
                failed_read_error_kinds.insert(error_kind.clone());
            }
        }
    }

    let summary_reason = planning_error_kind
        .map(str::to_string)
        .or_else(|| apply_plan.map(|plan| plan.apply_reason.clone()))
        .unwrap_or_else(|| {
            if completed && should_apply_remote {
                "remoteBatchContainsRecords".to_string()
            } else if completed {
                "noRemoteChanges".to_string()
            } else if should_reread {
                "rereadCloudStateRequired".to_string()
            } else if should_retry {
                "providerRetryRequired".to_string()
            } else {
                "pullRoundIncomplete".to_string()
            }
        });

    BrowserStorageSyncCloudPullRoundSummary {
        read_result_count,
        successful_read_count,
        failed_read_count,
        planned_read_count: pull_plan
            .map(|plan| plan.read_summary.operation_count)
            .unwrap_or(0),
        snapshot_read_count,
        log_list_read_count,
        log_object_read_count,
        continuation_read_count,
        imported_snapshot_count: apply_plan
            .map(|plan| plan.imported_snapshot_count)
            .unwrap_or(0),
        imported_log_count: apply_plan.map(|plan| plan.imported_log_count).unwrap_or(0),
        skipped_snapshot_count: apply_plan
            .map(|plan| plan.apply_summary.skipped_snapshot_count)
            .unwrap_or(0),
        skipped_log_count: apply_plan
            .map(|plan| plan.apply_summary.skipped_log_count)
            .unwrap_or(0),
        record_count: apply_plan.map(|plan| plan.record_count).unwrap_or(0),
        remote_apply_operation_count: apply_plan
            .map(|plan| plan.apply_summary.remote_apply_operation_count)
            .unwrap_or(0),
        completed,
        should_apply_remote,
        should_reread,
        should_retry,
        summary_action: client_action.to_string(),
        summary_reason,
        collections: collections.into_iter().collect(),
        read_reasons: read_reasons.into_iter().collect(),
        failed_read_error_kinds: failed_read_error_kinds.into_iter().collect(),
    }
}

