#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_cycle_round_summary(
    push_round: Option<&BrowserStorageSyncCloudPushRoundResult>,
    pull_round: Option<&BrowserStorageSyncCloudPullRoundResult>,
    client_plan: Option<&BrowserStorageSyncCloudCycleClientPlan>,
    completed: bool,
    should_ack_local: bool,
    should_apply_remote: bool,
    should_reread: bool,
    should_retry: bool,
    client_action: &str,
    planning_error_kind: Option<&str>,
) -> BrowserStorageSyncCloudCycleRoundSummary {
    let mut collections = BTreeSet::new();
    let mut diagnostic_reasons = BTreeSet::new();
    let mut failed_read_error_kinds = BTreeSet::new();
    let mut failed_write_error_kinds = BTreeSet::new();
    let mut issue_reasons = BTreeSet::new();

    let push_summary = push_round.map(|round| &round.round_summary);
    let pull_summary = pull_round.map(|round| &round.round_summary);

    if let Some(kind) = planning_error_kind {
        diagnostic_reasons.insert(kind.to_string());
    }

    if let Some(summary) = push_summary {
        for collection in &summary.touched_collections {
            collections.insert(collection.clone());
        }
        if !summary.summary_reason.is_empty() {
            diagnostic_reasons.insert(summary.summary_reason.clone());
        }
        for reason in &summary.issue_reasons {
            issue_reasons.insert(reason.clone());
            diagnostic_reasons.insert(reason.clone());
        }
        for error_kind in &summary.failed_read_error_kinds {
            failed_read_error_kinds.insert(error_kind.clone());
            diagnostic_reasons.insert(error_kind.clone());
        }
        for error_kind in &summary.failed_write_error_kinds {
            failed_write_error_kinds.insert(error_kind.clone());
            diagnostic_reasons.insert(error_kind.clone());
        }
    }

    if let Some(summary) = pull_summary {
        for collection in &summary.collections {
            collections.insert(collection.clone());
        }
        if !summary.summary_reason.is_empty() {
            diagnostic_reasons.insert(summary.summary_reason.clone());
        }
        for error_kind in &summary.failed_read_error_kinds {
            failed_read_error_kinds.insert(error_kind.clone());
            diagnostic_reasons.insert(error_kind.clone());
        }
    }

    let mut step_types = Vec::new();
    let mut step_reasons = BTreeSet::new();
    if let Some(plan) = client_plan {
        if let Some(reason) = &plan.retry_reason {
            diagnostic_reasons.insert(reason.clone());
        }
        for step in &plan.steps {
            step_types.push(step.step_type.clone());
            if let Some(reason) = &step.step_reason {
                step_reasons.insert(reason.clone());
                diagnostic_reasons.insert(reason.clone());
            }
        }
    }

    let summary_reason = planning_error_kind
        .map(str::to_string)
        .or_else(|| {
            push_round.and_then(|round| {
                if round.completed {
                    None
                } else {
                    Some(round.round_summary.summary_reason.clone())
                }
            })
        })
        .or_else(|| {
            pull_round.and_then(|round| {
                if round.completed {
                    None
                } else {
                    Some(round.round_summary.summary_reason.clone())
                }
            })
        })
        .unwrap_or_else(|| {
            if completed && should_ack_local && should_apply_remote {
                "localAckAndRemoteApplyPlanned".to_string()
            } else if completed && should_ack_local {
                "localAckPlanned".to_string()
            } else if completed && should_apply_remote {
                "remoteApplyPlanned".to_string()
            } else if completed {
                "cycleCompletedNoChanges".to_string()
            } else if should_reread {
                "rereadCloudStateRequired".to_string()
            } else if should_retry {
                "providerRetryRequired".to_string()
            } else {
                "cycleRoundIncomplete".to_string()
            }
        });
    diagnostic_reasons.insert(summary_reason.clone());

    let client_step_count = client_plan
        .map(|plan| plan.steps.len().min(u32::MAX as usize) as u32)
        .unwrap_or(0);
    let ack_step_count = client_plan
        .map(|plan| {
            plan.steps
                .iter()
                .filter(|step| step.step_type == "applyLocalAck")
                .count()
                .min(u32::MAX as usize) as u32
        })
        .unwrap_or(0);
    let remote_apply_step_count = client_plan
        .map(|plan| {
            plan.steps
                .iter()
                .filter(|step| step.step_type == "applyRemoteBatch")
                .count()
                .min(u32::MAX as usize) as u32
        })
        .unwrap_or(0);
    let reread_step_count = client_plan
        .map(|plan| {
            plan.steps
                .iter()
                .filter(|step| step.step_type == "rereadCloudState")
                .count()
                .min(u32::MAX as usize) as u32
        })
        .unwrap_or(0);
    let retry_step_count = client_plan
        .map(|plan| {
            plan.steps
                .iter()
                .filter(|step| step.step_type == "scheduleCloudCycleRetry")
                .count()
                .min(u32::MAX as usize) as u32
        })
        .unwrap_or(0);

    let push_read_result_count = push_summary
        .map(|summary| summary.read_result_count)
        .unwrap_or(0);
    let push_write_result_count = push_summary
        .map(|summary| summary.write_result_count)
        .unwrap_or(0);
    let pull_read_result_count = pull_summary
        .map(|summary| summary.read_result_count)
        .unwrap_or(0);
    let push_failed_read_count = push_summary
        .map(|summary| summary.failed_read_count)
        .unwrap_or(0);
    let pull_failed_read_count = pull_summary
        .map(|summary| summary.failed_read_count)
        .unwrap_or(0);
    let read_failure_count = push_failed_read_count.saturating_add(pull_failed_read_count);
    let write_failure_count = push_summary
        .map(|summary| summary.failed_write_count)
        .unwrap_or(0);
    let conflict_count = push_summary
        .map(|summary| summary.conflict_count)
        .unwrap_or(0);
    let retryable_failure_count = push_summary
        .map(|summary| summary.retryable_failure_count)
        .unwrap_or(0)
        .saturating_add(
            if pull_summary
                .map(|summary| summary.should_retry)
                .unwrap_or(false)
            {
                pull_failed_read_count
            } else {
                0
            },
        );

    BrowserStorageSyncCloudCycleRoundSummary {
        push_round_present: push_round.is_some(),
        pull_round_present: pull_round.is_some(),
        push_completed: push_round.map(|round| round.completed).unwrap_or(false),
        pull_completed: pull_round.map(|round| round.completed).unwrap_or(false),
        completed,
        should_ack_local,
        should_apply_remote,
        should_reread,
        should_retry,
        client_step_count,
        ack_step_count,
        remote_apply_step_count,
        reread_step_count,
        retry_step_count,
        push_read_result_count,
        push_write_result_count,
        pull_read_result_count,
        read_failure_count,
        write_failure_count,
        conflict_count,
        retryable_failure_count,
        imported_snapshot_count: pull_summary
            .map(|summary| summary.imported_snapshot_count)
            .unwrap_or(0),
        imported_log_count: pull_summary
            .map(|summary| summary.imported_log_count)
            .unwrap_or(0),
        skipped_snapshot_count: pull_summary
            .map(|summary| summary.skipped_snapshot_count)
            .unwrap_or(0),
        skipped_log_count: pull_summary
            .map(|summary| summary.skipped_log_count)
            .unwrap_or(0),
        remote_record_count: pull_summary
            .map(|summary| summary.record_count)
            .unwrap_or(0),
        remote_apply_operation_count: pull_summary
            .map(|summary| summary.remote_apply_operation_count)
            .unwrap_or(0),
        summary_action: client_action.to_string(),
        summary_reason,
        push_action: push_round
            .map(|round| round.client_action.clone())
            .unwrap_or_else(|| "none".to_string()),
        pull_action: pull_round
            .map(|round| round.client_action.clone())
            .unwrap_or_else(|| "none".to_string()),
        step_types,
        step_reasons: step_reasons.into_iter().collect(),
        collections: collections.into_iter().collect(),
        diagnostic_reasons: diagnostic_reasons.into_iter().collect(),
        failed_read_error_kinds: failed_read_error_kinds.into_iter().collect(),
        failed_write_error_kinds: failed_write_error_kinds.into_iter().collect(),
        issue_reasons: issue_reasons.into_iter().collect(),
    }
}

#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_cycle_round_result(
    scope: String,
    device_id: String,
    generated_at_unix_seconds: i64,
    push_round: Option<BrowserStorageSyncCloudPushRoundResult>,
    pull_round: Option<BrowserStorageSyncCloudPullRoundResult>,
    completed: bool,
    should_ack_local: bool,
    should_apply_remote: bool,
    should_reread: bool,
    should_retry: bool,
    client_action: &str,
    planning_error_kind: Option<String>,
    planning_error_message: Option<String>,
) -> BrowserStorageSyncCloudCycleRoundResult {
    let client_plan = browser_storage_sync_cloud_cycle_client_plan_from_parts(
        &scope,
        &device_id,
        generated_at_unix_seconds,
        push_round.as_ref(),
        pull_round.as_ref(),
        completed,
        should_ack_local,
        should_apply_remote,
        should_reread,
        should_retry,
        client_action,
        planning_error_kind.as_deref(),
    );
    let round_summary = browser_storage_sync_cloud_cycle_round_summary(
        push_round.as_ref(),
        pull_round.as_ref(),
        client_plan.as_ref(),
        completed,
        should_ack_local,
        should_apply_remote,
        should_reread,
        should_retry,
        client_action,
        planning_error_kind.as_deref(),
    );

    BrowserStorageSyncCloudCycleRoundResult {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cycleRound".to_string(),
        scope,
        device_id,
        generated_at_unix_seconds,
        round_summary,
        push_round,
        pull_round,
        client_plan,
        completed,
        should_ack_local,
        should_apply_remote,
        should_reread,
        should_retry,
        client_action: client_action.to_string(),
        planning_error_kind,
        planning_error_message,
        result_policy:
            "Run one provider-backed cloud sync cycle in Rust: optionally push local changes, stop before pull when the push round needs reread/retry/recovery, then run one pull round and return the local ack and remote apply actions. Multi-round retry timing, provider SDK calls, and UI recovery remain scheduler/product responsibilities."
                .to_string(),
    }
}

#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_cycle_client_plan_from_parts(
    scope: &str,
    device_id: &str,
    generated_at_unix_seconds: i64,
    push_round: Option<&BrowserStorageSyncCloudPushRoundResult>,
    pull_round: Option<&BrowserStorageSyncCloudPullRoundResult>,
    completed: bool,
    should_ack_local: bool,
    should_apply_remote: bool,
    should_reread: bool,
    should_retry: bool,
    client_action: &str,
    planning_error_kind: Option<&str>,
) -> Option<BrowserStorageSyncCloudCycleClientPlan> {
    let ack_plan = if should_ack_local {
        push_round
            .and_then(|round| round.result_plan.as_ref())
            .and_then(|plan| plan.ack_plan.clone())
    } else {
        None
    };
    let ack_batch_json = if should_ack_local {
        push_round
            .and_then(|round| round.result_plan.as_ref())
            .and_then(|plan| plan.ack_batch_json.clone())
    } else {
        None
    };
    let remote_apply_plan = if should_apply_remote {
        pull_round
            .and_then(|round| round.apply_plan.as_ref())
            .map(|plan| plan.remote_apply_plan.clone())
    } else {
        None
    };
    let remote_batch_json = if should_apply_remote {
        pull_round
            .and_then(|round| round.apply_plan.as_ref())
            .map(|plan| plan.remote_batch_json.clone())
    } else {
        None
    };
    let ack_operation_count = ack_plan
        .as_ref()
        .map(|plan| plan.operations.len())
        .unwrap_or(0);
    let ack_step_reason = push_round
        .and_then(|round| round.result_plan.as_ref())
        .and_then(|plan| plan.ack_reason.as_deref());
    let remote_operation_count = remote_apply_plan
        .as_ref()
        .map(|plan| plan.operations.len())
        .unwrap_or(0);
    let remote_step_reason = pull_round
        .and_then(|round| round.apply_plan.as_ref())
        .map(|plan| plan.apply_reason.as_str());
    let reread_operation_count = push_round
        .and_then(|round| round.result_plan.as_ref())
        .map(|plan| plan.reread_operations.len())
        .unwrap_or(0);
    let action = browser_storage_sync_cloud_cycle_client_action(
        completed,
        should_retry,
        should_reread,
        ack_operation_count,
        remote_operation_count,
    );
    let steps = browser_storage_sync_cloud_cycle_client_steps(
        ack_operation_count,
        remote_operation_count,
        reread_operation_count,
        completed,
        should_reread,
        should_retry,
        ack_step_reason,
        remote_step_reason,
    );
    let retry_reason = if completed {
        None
    } else {
        planning_error_kind
            .map(|kind| kind.to_string())
            .or_else(|| Some(client_action.to_string()))
    };

    Some(BrowserStorageSyncCloudCycleClientPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cycleClientPlan".to_string(),
        scope: normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        generated_at_unix_seconds: normalize_unix_seconds(generated_at_unix_seconds),
        action,
        steps,
        ack_plan,
        ack_batch_json,
        remote_apply_plan,
        remote_batch_json,
        should_retry_cycle: should_retry,
        should_reread,
        retry_reason,
        result_policy:
            "Flatten one cloud cycle round into native-executable client steps. Apply local ack after a committed cloud push, apply remote batches after pull planning, and keep retry/recovery scheduling outside SQLite and provider adapters."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_cycle_client_plan_value(cycle_round: &Value) -> Option<Value> {
    if let Some(client_plan) = cycle_round
        .get("clientPlan")
        .filter(|value| value.is_object())
    {
        return Some(client_plan.clone());
    }

    let scope = cycle_round
        .get("scope")
        .and_then(Value::as_str)
        .unwrap_or("default");
    let device_id = cycle_round
        .get("deviceId")
        .and_then(Value::as_str)
        .unwrap_or("unknown-device");
    let generated_at = cycle_round
        .get("generatedAtUnixSeconds")
        .and_then(Value::as_i64)
        .map(normalize_unix_seconds)
        .unwrap_or(MIN_UNIX_SECONDS);
    let completed = cycle_round
        .get("completed")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_ack_local = cycle_round
        .get("shouldAckLocal")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_apply_remote = cycle_round
        .get("shouldApplyRemote")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_reread = cycle_round
        .get("shouldReread")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_retry = cycle_round
        .get("shouldRetry")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let client_action = cycle_round
        .get("clientAction")
        .and_then(Value::as_str)
        .unwrap_or("recoverCloudCycle");
    let planning_error_kind = cycle_round.get("planningErrorKind").and_then(Value::as_str);
    let push_result_plan = cycle_round.pointer("/pushRound/resultPlan");
    let pull_apply_plan = cycle_round.pointer("/pullRound/applyPlan");
    let ack_plan = if should_ack_local {
        push_result_plan
            .and_then(|plan| plan.get("ackPlan"))
            .cloned()
    } else {
        None
    };
    let ack_batch_json = if should_ack_local {
        push_result_plan
            .and_then(|plan| plan.get("ackBatchJson"))
            .and_then(Value::as_str)
            .map(|value| value.to_string())
    } else {
        None
    };
    let remote_apply_plan = if should_apply_remote {
        pull_apply_plan
            .and_then(|plan| plan.get("remoteApplyPlan"))
            .cloned()
    } else {
        None
    };
    let remote_batch_json = if should_apply_remote {
        pull_apply_plan
            .and_then(|plan| plan.get("remoteBatchJson"))
            .and_then(Value::as_str)
            .map(|value| value.to_string())
    } else {
        None
    };
    let ack_operation_count = json_operation_count(ack_plan.as_ref());
    let ack_step_reason = push_result_plan
        .and_then(|plan| plan.get("ackReason"))
        .and_then(Value::as_str);
    let remote_operation_count = json_operation_count(remote_apply_plan.as_ref());
    let remote_step_reason = pull_apply_plan
        .and_then(|plan| plan.get("applyReason"))
        .and_then(Value::as_str);
    let reread_operation_count = push_result_plan
        .and_then(|plan| plan.get("rereadOperations"))
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    let action = browser_storage_sync_cloud_cycle_client_action(
        completed,
        should_retry,
        should_reread,
        ack_operation_count,
        remote_operation_count,
    );
    let steps = browser_storage_sync_cloud_cycle_client_steps(
        ack_operation_count,
        remote_operation_count,
        reread_operation_count,
        completed,
        should_reread,
        should_retry,
        ack_step_reason,
        remote_step_reason,
    );
    let retry_reason = if completed {
        None
    } else {
        planning_error_kind
            .map(|kind| kind.to_string())
            .or_else(|| Some(client_action.to_string()))
    };

    let mut plan = serde_json::Map::new();
    plan.insert(
        "version".to_string(),
        json!(BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION),
    );
    plan.insert(
        "storageSchemaVersion".to_string(),
        json!(BROWSER_STORAGE_SCHEMA_VERSION),
    );
    plan.insert(
        "cloudDataModelVersion".to_string(),
        json!(BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION),
    );
    plan.insert("planType".to_string(), json!("cycleClientPlan"));
    plan.insert(
        "scope".to_string(),
        json!(normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH)),
    );
    plan.insert(
        "deviceId".to_string(),
        json!(normalize_sync_text(
            device_id,
            "unknown-device",
            MAX_SYNC_ID_LENGTH
        )),
    );
    plan.insert("generatedAtUnixSeconds".to_string(), json!(generated_at));
    plan.insert("action".to_string(), json!(action));
    plan.insert("steps".to_string(), serde_json::to_value(steps).ok()?);
    if let Some(ack_plan) = ack_plan {
        plan.insert("ackPlan".to_string(), ack_plan);
    }
    if let Some(ack_batch_json) = ack_batch_json {
        plan.insert("ackBatchJson".to_string(), json!(ack_batch_json));
    }
    if let Some(remote_apply_plan) = remote_apply_plan {
        plan.insert("remoteApplyPlan".to_string(), remote_apply_plan);
    }
    if let Some(remote_batch_json) = remote_batch_json {
        plan.insert("remoteBatchJson".to_string(), json!(remote_batch_json));
    }
    plan.insert("shouldRetryCycle".to_string(), json!(should_retry));
    plan.insert("shouldReread".to_string(), json!(should_reread));
    if let Some(retry_reason) = retry_reason {
        plan.insert("retryReason".to_string(), json!(retry_reason));
    }
    plan.insert(
        "resultPolicy".to_string(),
        json!("Flatten one cloud cycle round into native-executable client steps. Apply local ack after a committed cloud push, apply remote batches after pull planning, and keep retry/recovery scheduling outside SQLite and provider adapters."),
    );
    Some(Value::Object(plan))
}

fn json_operation_count(plan: Option<&Value>) -> usize {
    plan.and_then(|plan| plan.get("operations"))
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0)
}

fn browser_storage_sync_cloud_cycle_status_policy_value(
    cycle_round: &Value,
    retry_attempt: u32,
) -> Option<BrowserStorageSyncCloudCycleStatusPolicy> {
    if !cycle_round.is_object() {
        return None;
    }

    let scope = cycle_round
        .get("scope")
        .and_then(Value::as_str)
        .unwrap_or("default");
    let device_id = cycle_round
        .get("deviceId")
        .and_then(Value::as_str)
        .unwrap_or("unknown-device");
    let generated_at = cycle_round
        .get("generatedAtUnixSeconds")
        .and_then(Value::as_i64)
        .map(normalize_unix_seconds)
        .unwrap_or(MIN_UNIX_SECONDS);
    let completed = cycle_round
        .get("completed")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_retry = cycle_round
        .get("shouldRetry")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_reread = cycle_round
        .get("shouldReread")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_ack_local = cycle_round
        .get("shouldAckLocal")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let should_apply_remote = cycle_round
        .get("shouldApplyRemote")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let client_action = cycle_round
        .get("clientAction")
        .and_then(Value::as_str)
        .unwrap_or("recoverCloudCycle");

    let mut diagnostic_reasons = Vec::new();
    browser_storage_sync_cloud_cycle_collect_reason(
        &mut diagnostic_reasons,
        cycle_round.get("planningErrorKind").and_then(Value::as_str),
    );
    browser_storage_sync_cloud_cycle_collect_reason(
        &mut diagnostic_reasons,
        cycle_round
            .pointer("/pushRound/planningErrorKind")
            .and_then(Value::as_str),
    );
    browser_storage_sync_cloud_cycle_collect_reason(
        &mut diagnostic_reasons,
        cycle_round
            .pointer("/pullRound/planningErrorKind")
            .and_then(Value::as_str),
    );
    let read_failure_count = browser_storage_sync_cloud_cycle_collect_read_failure_reasons(
        cycle_round,
        &mut diagnostic_reasons,
    );
    let write_failure_count = browser_storage_sync_cloud_cycle_collect_write_failure_reasons(
        cycle_round,
        &mut diagnostic_reasons,
    );
    let issue_retryable_count = browser_storage_sync_cloud_cycle_collect_issue_reasons(
        cycle_round,
        &mut diagnostic_reasons,
    );

    let conflict_count = cycle_round
        .pointer("/pushRound/resultPlan/conflictCount")
        .and_then(Value::as_u64)
        .map(|count| count.min(u64::from(u32::MAX)) as u32)
        .unwrap_or_else(|| {
            diagnostic_reasons
                .iter()
                .filter(|reason| reason.as_str() == "conflict")
                .count()
                .min(u32::MAX as usize) as u32
        });
    let result_retryable_failure_count = cycle_round
        .pointer("/pushRound/resultPlan/retryableFailureCount")
        .and_then(Value::as_u64)
        .map(|count| count.min(u64::from(u32::MAX)) as u32)
        .unwrap_or(0);
    let retryable_failure_count = result_retryable_failure_count.max(issue_retryable_count);

    diagnostic_reasons.sort();
    diagnostic_reasons.dedup();

    let classification = browser_storage_sync_cloud_cycle_status_classification(
        completed,
        should_retry,
        should_reread,
        client_action,
        &diagnostic_reasons,
    );
    let policy_should_retry =
        browser_storage_sync_cloud_cycle_policy_should_retry(&classification, should_retry);
    let (scheduler_action, provider_action, user_action, telemetry_level, reset_retry_attempt) =
        browser_storage_sync_cloud_cycle_status_actions(
            &classification,
            policy_should_retry,
            should_reread,
        );
    let retry_attempt = retry_attempt.min(16);
    let retry_delay_seconds = if policy_should_retry
        && matches!(
            scheduler_action.as_str(),
            "scheduleRetry" | "rereadCloudStateThenScheduleRetry"
        ) {
        Some(browser_storage_sync_retry_delay_seconds(retry_attempt))
    } else {
        None
    };

    Some(BrowserStorageSyncCloudCycleStatusPolicy {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudCycleStatusPolicy".to_string(),
        scope: normalize_sync_text(scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        generated_at_unix_seconds: generated_at,
        classification,
        completed,
        should_retry: policy_should_retry,
        should_reread,
        should_ack_local,
        should_apply_remote,
        client_action: normalize_sync_text(client_action, "recoverCloudCycle", MAX_SYNC_TEXT_LENGTH),
        scheduler_action,
        provider_action,
        user_action,
        telemetry_level,
        retry_attempt,
        retry_delay_seconds,
        retry_delay_ceiling_seconds: BROWSER_STORAGE_SYNC_RETRY_MAX_SECONDS,
        retry_jitter_percent: BROWSER_STORAGE_SYNC_RETRY_JITTER_PERCENT,
        reset_retry_attempt,
        read_failure_count,
        write_failure_count,
        conflict_count,
        retryable_failure_count,
        diagnostic_reasons,
        result_policy:
            "Classify one cloud-drive cycle round for platform schedulers without turning provider SDK calls or native SQLite execution into Rust-owned micro-steps."
                .to_string(),
    })
}

