fn browser_storage_sync_cloud_cycle_collect_read_failure_reasons(
    cycle_round: &Value,
    diagnostic_reasons: &mut Vec<String>,
) -> u32 {
    ["/pushRound/readResults", "/pullRound/readResults"]
        .into_iter()
        .map(|path| {
            cycle_round
                .pointer(path)
                .and_then(Value::as_array)
                .map(|results| {
                    results
                        .iter()
                        .filter(|result| {
                            let failed = !result
                                .get("success")
                                .and_then(Value::as_bool)
                                .unwrap_or(false);
                            if failed {
                                browser_storage_sync_cloud_cycle_collect_reason(
                                    diagnostic_reasons,
                                    result.get("errorKind").and_then(Value::as_str),
                                );
                            }
                            failed
                        })
                        .count()
                })
                .unwrap_or(0)
        })
        .sum::<usize>()
        .min(u32::MAX as usize) as u32
}

fn browser_storage_sync_cloud_cycle_collect_write_failure_reasons(
    cycle_round: &Value,
    diagnostic_reasons: &mut Vec<String>,
) -> u32 {
    cycle_round
        .pointer("/pushRound/writeResults")
        .and_then(Value::as_array)
        .map(|results| {
            results
                .iter()
                .filter(|result| {
                    let failed = !result
                        .get("success")
                        .and_then(Value::as_bool)
                        .unwrap_or(false);
                    if failed {
                        browser_storage_sync_cloud_cycle_collect_reason(
                            diagnostic_reasons,
                            result.get("errorKind").and_then(Value::as_str),
                        );
                    }
                    failed
                })
                .count()
        })
        .unwrap_or(0)
        .min(u32::MAX as usize) as u32
}

