fn browser_storage_sync_cloud_cycle_collect_reason(
    diagnostic_reasons: &mut Vec<String>,
    reason: Option<&str>,
) {
    let Some(reason) = reason else {
        return;
    };
    let normalized = browser_storage_sync_cloud_cycle_diagnostic_reason(reason);
    if !normalized.is_empty() {
        diagnostic_reasons.push(normalized);
    }
}

fn browser_storage_sync_cloud_cycle_diagnostic_reason(reason: &str) -> String {
    let normalized = normalize_cloud_error_kind(reason);
    if normalized != "providerFailure" {
        return normalized;
    }

    let compact = reason
        .trim()
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect::<String>();
    match compact.as_str() {
        "providerreadfailed" => "providerReadFailed",
        "invalidclouddocument" => "invalidCloudDocument",
        "invalidmanifest" => "invalidManifest",
        "invaliddevice" => "invalidDevice",
        "invalidpushplan" => "invalidPushPlan",
        "invalidpullplan" => "invalidPullPlan",
        "invalidpullapplyplan" => "invalidPullApplyPlan",
        "invalidmembershipplan" => "invalidMembershipPlan",
        "devicemismatch" => "deviceMismatch",
        "invaliddocument" => "invalidDocument",
        "missingobject" => "missingObject",
        "invalidresult" => "invalidResult",
        "providernotselected" => "providerNotSelected",
        "provideraccountmissing" => "providerAccountMissing",
        "providerconnectioninprogress" => "providerConnectionInProgress",
        "providerconnectionfailed" => "providerConnectionFailed",
        "providerdisconnected" => "providerDisconnected",
        "credentialexpired" => "credentialExpired",
        "credentialrevoked" => "credentialRevoked",
        "credentialunknown" => "credentialUnknown",
        "credentialmissing" => "credentialMissing",
        "cloudstorenotready" => "cloudStoreNotReady",
        "devicemembershiprevoked" => "deviceMembershipRevoked",
        "devicemembershipmissing" => "deviceMembershipMissing",
        "devicemembershipunknown" => "deviceMembershipUnknown",
        "capabilitypreflightblocked" => "capabilityPreflightBlocked",
        "requiresuseraction" => "requiresUserAction",
        "rootpath" => "rootPath",
        "revisionkind" => "revisionKind",
        "maxobjectbytes" => "maxObjectBytes",
        "supportsconditionalwrite" => "supportsConditionalWrite",
        "supportsprefixlist" => "supportsPrefixList",
        "supportspagedlist" => "supportsPagedList",
        "supportsconditionaldelete" => "supportsConditionalDelete",
        "supportsappfolder" => "supportsAppFolder",
        "supportsreadifchanged" => "supportsReadIfChanged",
        "adaptersnapshotincomplete" => "adapterSnapshotIncomplete",
        "capabilities" => "capabilities",
        "providercontractinvalid" => "providerContractInvalid",
        "providerconflictunsafe" => "providerConflictUnsafe",
        "providersetuprequired" => "providerSetupRequired",
        "providerlimittoosmall" => "providerLimitTooSmall",
        "clientupgraderequired" | "unsupportedstorageschemaversion" => "clientUpgradeRequired",
        _ => "providerFailure",
    }
    .to_string()
}

fn browser_storage_sync_cloud_cycle_status_classification(
    completed: bool,
    should_retry: bool,
    should_reread: bool,
    client_action: &str,
    diagnostic_reasons: &[String],
) -> String {
    if completed {
        return "success".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "clientUpgradeRequired")
        || client_action == "upgradeClient"
    {
        return "clientUpgradeRequired".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "unauthorized")
        || client_action == "recoverProviderCredentials"
    {
        return "providerAuthRequired".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "quotaExceeded")
        || client_action == "freeCloudStorageOrReduceRetention"
    {
        return "providerQuotaExceeded".to_string();
    }
    if diagnostic_reasons.iter().any(|reason| {
        matches!(
            reason.as_str(),
            "invalidCloudDocument"
                | "invalidDocument"
                | "invalidManifest"
                | "invalidDevice"
                | "invalidPushPlan"
                | "invalidPullPlan"
                | "invalidPullApplyPlan"
        )
    }) || client_action == "recoverCloudDocument"
    {
        return "cloudDocumentInvalid".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "deviceMismatch") {
        return "clientRequestRejected".to_string();
    }
    if diagnostic_reasons.iter().any(|reason| {
        matches!(
            reason.as_str(),
            "invalidPath" | "unsupported" | "invalidResult"
        )
    }) || client_action == "abortAndReportProviderBug"
    {
        return "providerAdapterUnsupported".to_string();
    }
    if should_reread
        || browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "conflict")
        || client_action == BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY
    {
        return "cloudConflict".to_string();
    }
    if should_retry
        || diagnostic_reasons.iter().any(|reason| {
            matches!(
                reason.as_str(),
                "network"
                    | "rateLimited"
                    | "provider"
                    | "providerFailure"
                    | "providerReadFailed"
                    | "missingObject"
            )
        })
    {
        return "providerUnavailable".to_string();
    }
    "cloudRecoveryRequired".to_string()
}

fn browser_storage_sync_cloud_membership_status_classification(
    completed: bool,
    should_retry: bool,
    should_reread: bool,
    client_action: &str,
    diagnostic_reasons: &[String],
) -> String {
    if completed {
        return "success".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "clientUpgradeRequired")
        || client_action == "upgradeClient"
    {
        return "clientUpgradeRequired".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "unauthorized")
        || client_action == "recoverProviderCredentials"
    {
        return "providerAuthRequired".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "quotaExceeded")
        || client_action == "freeCloudStorageOrReduceRetention"
    {
        return "providerQuotaExceeded".to_string();
    }
    if diagnostic_reasons.iter().any(|reason| {
        matches!(
            reason.as_str(),
            "invalidCloudDocument" | "invalidDocument" | "invalidManifest" | "invalidDevice"
        )
    }) || client_action == "recoverCloudDocument"
    {
        return "cloudDocumentInvalid".to_string();
    }
    if browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "invalidMembershipPlan")
        || client_action == "recoverCloudMembershipPlan"
    {
        return "clientRequestRejected".to_string();
    }
    if should_reread
        || browser_storage_sync_cloud_cycle_has_reason(diagnostic_reasons, "conflict")
        || client_action == BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY
    {
        return "cloudConflict".to_string();
    }
    if should_retry
        || diagnostic_reasons.iter().any(|reason| {
            matches!(
                reason.as_str(),
                "network" | "rateLimited" | "provider" | "providerFailure" | "providerReadFailed"
            )
        })
        || matches!(
            client_action,
            "retryCloudProviderReadWithBackoff"
                | "recoverCloudProviderRead"
                | "retrySameCloudMembershipPlanWithBackoff"
        )
    {
        return "providerUnavailable".to_string();
    }
    "membershipRoundIncomplete".to_string()
}

fn browser_storage_sync_cloud_cycle_has_reason(
    diagnostic_reasons: &[String],
    target: &str,
) -> bool {
    diagnostic_reasons
        .iter()
        .any(|reason| reason.as_str() == target)
}

fn browser_storage_sync_cloud_cycle_policy_should_retry(
    classification: &str,
    should_retry: bool,
) -> bool {
    should_retry && matches!(classification, "cloudConflict" | "providerUnavailable")
}

fn browser_storage_sync_cloud_cycle_status_actions(
    classification: &str,
    should_retry: bool,
    should_reread: bool,
) -> (String, String, String, String, bool) {
    let (scheduler_action, provider_action, user_action, telemetry_level, reset_retry_attempt) =
        match classification {
            "success" => ("idle", "none", "none", "info", true),
            "clientUpgradeRequired" => (
                "stopUntilClientUpdate",
                "none",
                "upgradeClient",
                "error",
                false,
            ),
            "providerAuthRequired" => (
                "waitForProviderCredentials",
                "reconnectProvider",
                "reconnectProvider",
                "warning",
                false,
            ),
            "providerQuotaExceeded" => (
                "waitForProviderStorage",
                "freeCloudStorageOrReduceRetention",
                "freeCloudStorageOrReduceRetention",
                "warning",
                false,
            ),
            "cloudDocumentInvalid" => (
                "stopUntilCloudRepair",
                "recoverCloudDocument",
                "recoverCloudData",
                "error",
                false,
            ),
            "providerAdapterUnsupported" => (
                "stopUntilProviderFix",
                "reportProviderBug",
                "reportProviderIssue",
                "error",
                false,
            ),
            "clientRequestRejected" => ("stopUntilNextChange", "none", "none", "warning", false),
            "cloudConflict" if should_retry && should_reread => (
                "rereadCloudStateThenScheduleRetry",
                "rereadCloudState",
                "none",
                "info",
                false,
            ),
            "cloudConflict" => (
                "rereadCloudState",
                "rereadCloudState",
                "none",
                "info",
                false,
            ),
            "providerUnavailable" if should_retry => (
                "scheduleRetry",
                "retryProviderOperation",
                "none",
                "warning",
                false,
            ),
            _ => (
                "stopUntilProviderRecovery",
                "recoverProvider",
                "reviewSyncStatus",
                "warning",
                false,
            ),
        };

    (
        scheduler_action.to_string(),
        provider_action.to_string(),
        user_action.to_string(),
        telemetry_level.to_string(),
        reset_retry_attempt,
    )
}

pub fn browser_storage_sync_cloud_cycle_schedule_state(
    status_policy_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudCycleScheduleState> {
    let policy =
        serde_json::from_str::<BrowserStorageSyncCloudCycleStatusPolicy>(status_policy_json)
            .ok()?;
    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let retry_attempt = policy.retry_attempt.min(16);
    let next_run_delay_seconds = browser_storage_sync_cloud_cycle_next_run_delay_seconds(&policy);
    let next_run_at_unix_seconds =
        next_run_delay_seconds.map(|delay| observed_at.saturating_add(i64::from(delay)));
    let next_retry_attempt = if policy.should_retry {
        retry_attempt.saturating_add(1).min(16)
    } else {
        0
    };
    let waiting_for_provider_credentials = policy.scheduler_action == "waitForProviderCredentials";
    let waiting_for_provider_storage = policy.scheduler_action == "waitForProviderStorage";
    let requires_user_action =
        browser_storage_sync_cloud_cycle_requires_user_action(&policy.user_action);
    let pending_cloud_reread =
        policy.should_reread || policy.scheduler_action.starts_with("rereadCloudState");

    Some(BrowserStorageSyncCloudCycleScheduleState {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudCycleScheduleState".to_string(),
        observed_at_unix_seconds: observed_at,
        scope: normalize_sync_text(&policy.scope, "default", MAX_SYNC_ID_LENGTH),
        device_id: normalize_sync_text(&policy.device_id, "unknown-device", MAX_SYNC_ID_LENGTH),
        classification: normalize_sync_text(
            &policy.classification,
            "cloudRecoveryRequired",
            MAX_SYNC_TEXT_LENGTH,
        ),
        should_retry: policy.should_retry,
        should_reread: policy.should_reread,
        client_action: normalize_sync_text(
            &policy.client_action,
            "recoverCloudCycle",
            MAX_SYNC_TEXT_LENGTH,
        ),
        scheduler_action: normalize_sync_text(
            &policy.scheduler_action,
            "stopUntilProviderRecovery",
            MAX_SYNC_TEXT_LENGTH,
        ),
        provider_action: normalize_sync_text(
            &policy.provider_action,
            "recoverProvider",
            MAX_SYNC_TEXT_LENGTH,
        ),
        user_action: normalize_sync_text(&policy.user_action, "none", MAX_SYNC_TEXT_LENGTH),
        telemetry_level: normalize_sync_text(&policy.telemetry_level, "warning", MAX_SYNC_TEXT_LENGTH),
        retry_attempt,
        next_retry_attempt,
        next_run_delay_seconds,
        next_run_at_unix_seconds,
        reset_retry_attempt: policy.reset_retry_attempt,
        waiting_for_provider_credentials,
        waiting_for_provider_storage,
        requires_user_action,
        pending_cloud_reread,
        diagnostic_reasons: policy.diagnostic_reasons,
        result_policy:
            "Derive platform-consumable cloud-drive cycle scheduling state from the Rust-owned cloud cycle status policy, keeping provider recovery and retry timing consistent across native schedulers."
                .to_string(),
    })
}

