fn browser_storage_sync_cloud_membership_attempt_plan_value(
    membership_round: &Value,
    retry_attempt: u32,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudMembershipAttemptPlan> {
    if !membership_round.is_object() {
        return None;
    }

    let status_policy =
        browser_storage_sync_cloud_membership_status_policy_value(membership_round, retry_attempt)?;
    let status_policy_json = serialize_json(&status_policy);
    let schedule_state = browser_storage_sync_cloud_membership_schedule_state(
        &status_policy_json,
        observed_at_unix_seconds,
    )?;
    let should_reread_cloud = schedule_state.pending_cloud_reread;
    let should_retry_membership = schedule_state.should_retry;
    let should_schedule_retry =
        should_retry_membership && schedule_state.next_run_at_unix_seconds.is_some();
    let should_run_provider_operation =
        browser_storage_sync_cloud_cycle_attempt_runs_provider_operation(
            &schedule_state.provider_action,
        );
    let should_wait_for_provider = schedule_state.waiting_for_provider_credentials
        || schedule_state.waiting_for_provider_storage;
    let requires_provider_recovery =
        browser_storage_sync_cloud_cycle_attempt_requires_provider_recovery(
            &schedule_state.provider_action,
        );
    let should_finish_membership = status_policy.completed;
    let should_continue_membership = !should_finish_membership
        && !should_wait_for_provider
        && !requires_provider_recovery
        && !schedule_state.requires_user_action
        && (should_reread_cloud || should_retry_membership || should_run_provider_operation);
    let should_stop_until_recovery = !should_finish_membership && !should_continue_membership;
    let attempt_action = browser_storage_sync_cloud_membership_attempt_action(
        should_finish_membership,
        should_reread_cloud,
        should_schedule_retry,
        should_stop_until_recovery,
        &schedule_state,
    );

    Some(BrowserStorageSyncCloudMembershipAttemptPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudMembershipAttemptPlan".to_string(),
        observed_at_unix_seconds: schedule_state.observed_at_unix_seconds,
        scope: schedule_state.scope,
        device_id: schedule_state.device_id,
        actor_device_id: schedule_state.actor_device_id,
        member_device_id: schedule_state.member_device_id,
        membership_action: schedule_state.membership_action,
        member_status: schedule_state.member_status,
        classification: schedule_state.classification,
        attempt_action,
        client_action: schedule_state.client_action,
        scheduler_action: schedule_state.scheduler_action,
        provider_action: schedule_state.provider_action,
        user_action: schedule_state.user_action,
        telemetry_level: schedule_state.telemetry_level,
        completed: status_policy.completed,
        should_finish_membership,
        should_continue_membership,
        should_reread_cloud,
        should_retry_membership,
        should_schedule_retry,
        should_run_provider_operation,
        should_wait_for_provider,
        requires_provider_recovery,
        requires_user_action: schedule_state.requires_user_action,
        should_stop_until_recovery,
        pending_cloud_reread: schedule_state.pending_cloud_reread,
        retry_attempt: schedule_state.retry_attempt,
        next_retry_attempt: schedule_state.next_retry_attempt,
        next_run_delay_seconds: schedule_state.next_run_delay_seconds,
        next_run_at_unix_seconds: schedule_state.next_run_at_unix_seconds,
        diagnostic_reasons: schedule_state.diagnostic_reasons,
        result_policy:
            "Compose the Rust-owned cloud membership status policy and schedule state into one provider-neutral connect/revoke attempt plan. Native adapters still execute provider SDK calls, OS scheduling, and membership UI."
                .to_string(),
    })
}

pub fn browser_storage_sync_cloud_provider_diagnostics(
    capability_preflight_json: &str,
    compatibility_preflight_json: &str,
    provider_error_classification_json: &str,
    cycle_status_policy_json: &str,
    schedule_state_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudProviderDiagnostics> {
    let capability_preflight =
        browser_storage_sync_cloud_provider_diagnostics_optional_json(capability_preflight_json)?;
    let compatibility_preflight = browser_storage_sync_cloud_provider_diagnostics_optional_json(
        compatibility_preflight_json,
    )?;
    let provider_error_classification =
        browser_storage_sync_cloud_provider_diagnostics_optional_json(
            provider_error_classification_json,
        )?;
    let cycle_status_policy =
        browser_storage_sync_cloud_provider_diagnostics_optional_json(cycle_status_policy_json)?;
    let schedule_state =
        browser_storage_sync_cloud_provider_diagnostics_optional_json(schedule_state_json)?;

    if capability_preflight.is_none()
        && compatibility_preflight.is_none()
        && provider_error_classification.is_none()
        && cycle_status_policy.is_none()
        && schedule_state.is_none()
    {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let mut sources = Vec::new();
    if let Some(value) = capability_preflight.as_ref() {
        sources.push(browser_storage_sync_cloud_provider_diagnostic_source(
            "capabilityPreflight",
            value,
        ));
    }
    if let Some(value) = compatibility_preflight.as_ref() {
        sources.push(browser_storage_sync_cloud_provider_diagnostic_source(
            "compatibilityPreflight",
            value,
        ));
    }
    if let Some(value) = provider_error_classification.as_ref() {
        sources.push(browser_storage_sync_cloud_provider_diagnostic_source(
            "providerErrorClassification",
            value,
        ));
    }
    if let Some(value) = cycle_status_policy.as_ref() {
        sources.push(browser_storage_sync_cloud_provider_diagnostic_source(
            "cycleStatusPolicy",
            value,
        ));
    }
    if let Some(value) = schedule_state.as_ref() {
        sources.push(browser_storage_sync_cloud_provider_diagnostic_source(
            "scheduleState",
            value,
        ));
    }

    let capability_source =
        browser_storage_sync_cloud_provider_diagnostic_find_source(&sources, "capabilityPreflight");
    let compatibility_source = browser_storage_sync_cloud_provider_diagnostic_find_source(
        &sources,
        "compatibilityPreflight",
    );
    let cycle_source =
        browser_storage_sync_cloud_provider_diagnostic_find_source(&sources, "cycleStatusPolicy");
    let provider_error_source = browser_storage_sync_cloud_provider_diagnostic_find_source(
        &sources,
        "providerErrorClassification",
    );
    let schedule_source =
        browser_storage_sync_cloud_provider_diagnostic_find_source(&sources, "scheduleState");

    let selected_source = if capability_source
        .map(|source| source.should_block_sync)
        .unwrap_or(false)
    {
        capability_source
    } else if compatibility_source
        .map(|source| source.should_block_sync)
        .unwrap_or(false)
    {
        compatibility_source
    } else if provider_error_source
        .filter(|source| {
            !browser_storage_sync_cloud_provider_diagnostics_ok_classification(
                &source.classification,
            )
        })
        .is_some()
    {
        provider_error_source
    } else if schedule_source
        .filter(|source| {
            !browser_storage_sync_cloud_provider_diagnostics_ok_classification(
                &source.classification,
            )
        })
        .is_some()
    {
        schedule_source
    } else if cycle_source
        .filter(|source| {
            !browser_storage_sync_cloud_provider_diagnostics_ok_classification(
                &source.classification,
            )
        })
        .is_some()
    {
        cycle_source
    } else if capability_source
        .filter(|source| source.classification == "degraded")
        .is_some()
    {
        capability_source
    } else {
        None
    };

    let classification = selected_source
        .map(|source| {
            if source.source == "capabilityPreflight" && source.classification == "degraded" {
                "providerDegraded".to_string()
            } else {
                source.classification.clone()
            }
        })
        .unwrap_or_else(|| "ready".to_string());
    let severity = browser_storage_sync_cloud_provider_diagnostics_severity(&classification);
    let client_action = selected_source
        .map(|source| source.client_action.clone())
        .unwrap_or_else(|| "continueCloudSync".to_string());
    let provider_action = selected_source
        .map(|source| source.provider_action.clone())
        .unwrap_or_else(|| "continueProviderSync".to_string());
    let user_action = selected_source
        .map(|source| source.user_action.clone())
        .unwrap_or_else(|| "none".to_string());
    let scheduler_action = browser_storage_sync_cloud_provider_diagnostics_scheduler_action(
        &classification,
        selected_source.map(|source| source.scheduler_action.as_str()),
    );
    let telemetry_level = browser_storage_sync_cloud_provider_diagnostics_telemetry_level(
        &classification,
        &severity,
        schedule_state.as_ref(),
        cycle_status_policy.as_ref(),
        provider_error_classification.as_ref(),
    );

    let waiting_for_provider_credentials =
        browser_storage_sync_cloud_provider_diagnostics_bool_from_sources(
            schedule_state.as_ref(),
            cycle_status_policy.as_ref(),
            "waitingForProviderCredentials",
            "providerAuthRequired",
        ) || provider_error_source
            .map(|source| source.classification == "providerAuthRequired")
            .unwrap_or(false);
    let waiting_for_provider_storage =
        browser_storage_sync_cloud_provider_diagnostics_bool_from_sources(
            schedule_state.as_ref(),
            cycle_status_policy.as_ref(),
            "waitingForProviderStorage",
            "providerQuotaExceeded",
        ) || provider_error_source
            .map(|source| {
                matches!(
                    source.classification.as_str(),
                    "providerQuotaExceeded" | "providerSetupRequired"
                )
            })
            .unwrap_or(false);
    let should_retry = schedule_state
        .as_ref()
        .or(cycle_status_policy.as_ref())
        .and_then(|value| value.get("shouldRetry"))
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || provider_error_classification
            .as_ref()
            .and_then(|value| value.get("shouldRetry"))
            .and_then(Value::as_bool)
            .unwrap_or(false);
    let should_reread = schedule_state
        .as_ref()
        .or(cycle_status_policy.as_ref())
        .and_then(|value| value.get("shouldReread"))
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || provider_error_classification
            .as_ref()
            .and_then(|value| {
                value
                    .get("shouldRereadCloud")
                    .or_else(|| value.get("shouldReread"))
            })
            .and_then(Value::as_bool)
            .unwrap_or(false);
    let pending_cloud_reread = schedule_state
        .as_ref()
        .and_then(|value| value.get("pendingCloudReread"))
        .and_then(Value::as_bool)
        .unwrap_or(should_reread)
        || provider_error_classification
            .as_ref()
            .and_then(|value| value.get("shouldRereadCloud"))
            .and_then(Value::as_bool)
            .unwrap_or(false);
    let requires_user_action = sources.iter().any(|source| source.requires_user_action)
        || browser_storage_sync_cloud_cycle_requires_user_action(&user_action);
    let should_block_sync = sources.iter().any(|source| source.should_block_sync)
        || waiting_for_provider_credentials
        || waiting_for_provider_storage
        || browser_storage_sync_cloud_provider_diagnostics_blocking_classification(&classification);

    let mut diagnostic_reasons = BTreeSet::new();
    let mut warnings = BTreeSet::new();
    for source in &sources {
        for reason in &source.diagnostic_reasons {
            diagnostic_reasons.insert(reason.clone());
        }
        for warning in &source.warnings {
            warnings.insert(warning.clone());
        }
    }
    if !browser_storage_sync_cloud_provider_diagnostics_ok_classification(&classification)
        && diagnostic_reasons.is_empty()
    {
        diagnostic_reasons.insert(classification.clone());
    }
    if classification == "providerDegraded" && warnings.is_empty() {
        warnings.insert("providerCapabilityDegraded".to_string());
    }

    Some(BrowserStorageSyncCloudProviderDiagnostics {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudProviderDiagnostics".to_string(),
        observed_at_unix_seconds: observed_at,
        provider_kind: capability_preflight
            .as_ref()
            .or(provider_error_classification.as_ref())
            .and_then(|value| json_string_field(value, "providerKind"))
            .unwrap_or_else(|| "unknown".to_string()),
        root_path: capability_preflight
            .as_ref()
            .and_then(|value| json_string_field(value, "rootPath"))
            .unwrap_or_default(),
        scope: schedule_state
            .as_ref()
            .or(cycle_status_policy.as_ref())
            .and_then(|value| json_string_field(value, "scope"))
            .unwrap_or_else(|| "default".to_string()),
        device_id: schedule_state
            .as_ref()
            .or(cycle_status_policy.as_ref())
            .and_then(|value| json_string_field(value, "deviceId"))
            .unwrap_or_else(|| "unknown-device".to_string()),
        classification,
        severity,
        should_allow_sync: !should_block_sync,
        should_block_sync,
        should_retry,
        should_reread,
        requires_user_action,
        waiting_for_provider_credentials,
        waiting_for_provider_storage,
        pending_cloud_reread,
        client_action,
        scheduler_action,
        provider_action,
        user_action,
        telemetry_level,
        capability_classification: capability_source
            .map(|source| source.classification.clone())
            .unwrap_or_else(|| "notObserved".to_string()),
        compatibility_classification: compatibility_source
            .map(|source| source.classification.clone())
            .unwrap_or_else(|| "notObserved".to_string()),
        provider_error_classification: provider_error_classification
            .as_ref()
            .and_then(|value| json_string_field(value, "classification"))
            .map(|classification| {
                normalize_sync_text(&classification, "notObserved", MAX_SYNC_TEXT_LENGTH)
            })
            .unwrap_or_else(|| "notObserved".to_string()),
        cycle_classification: cycle_source
            .map(|source| source.classification.clone())
            .unwrap_or_else(|| "notObserved".to_string()),
        schedule_classification: schedule_source
            .map(|source| source.classification.clone())
            .unwrap_or_else(|| "notObserved".to_string()),
        source_count: u32::try_from(sources.len()).unwrap_or(u32::MAX),
        sources,
        diagnostic_reasons: diagnostic_reasons.into_iter().collect(),
        warnings: warnings.into_iter().collect(),
        result_policy:
            "Summarize provider capability, cloud-file compatibility, provider error classification, cloud cycle status, and scheduler state in Rust so platform UI can display one provider-oriented sync diagnosis without reassembling priority rules or splitting provider SDK calls into per-operation FFI."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_provider_diagnostics_optional_json(
    input: &str,
) -> Option<Option<Value>> {
    let trimmed = input.trim();
    if trimmed.is_empty() || trimmed == "null" {
        return Some(None);
    }

    let value = serde_json::from_str::<Value>(trimmed).ok()?;
    if value.is_null() {
        Some(None)
    } else if value.is_object() {
        Some(Some(value))
    } else {
        None
    }
}

fn browser_storage_sync_cloud_provider_diagnostic_source(
    source: &str,
    value: &Value,
) -> BrowserStorageSyncCloudProviderDiagnosticSource {
    let raw_classification = json_string_field(value, "classification")
        .map(|classification| normalize_sync_text(&classification, "unknown", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "unknown".to_string());
    let classification = browser_storage_sync_cloud_provider_diagnostics_source_classification(
        source,
        &raw_classification,
    );
    let plan_type = json_string_field(value, "planType")
        .map(|plan_type| normalize_sync_text(&plan_type, source, MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| source.to_string());
    let client_action = browser_storage_sync_cloud_provider_diagnostics_string_field(
        value,
        "clientAction",
        &browser_storage_sync_cloud_provider_diagnostics_source_client_action(
            source,
            &classification,
        ),
    );
    let scheduler_action = browser_storage_sync_cloud_provider_diagnostics_string_field(
        value,
        "schedulerAction",
        "none",
    );
    let provider_action = browser_storage_sync_cloud_provider_diagnostics_string_field(
        value,
        "providerAction",
        "none",
    );
    let user_action =
        browser_storage_sync_cloud_provider_diagnostics_string_field(value, "userAction", "none");
    let requires_user_action = value
        .get("requiresUserAction")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| browser_storage_sync_cloud_cycle_requires_user_action(&user_action));
    let should_block_sync = value
        .get("shouldBlockSync")
        .and_then(Value::as_bool)
        .unwrap_or_else(|| {
            browser_storage_sync_cloud_provider_diagnostics_blocking_classification(&classification)
        });

    BrowserStorageSyncCloudProviderDiagnosticSource {
        source: source.to_string(),
        plan_type,
        severity: browser_storage_sync_cloud_provider_diagnostics_severity(&classification),
        should_block_sync,
        requires_user_action,
        client_action,
        scheduler_action,
        provider_action,
        user_action,
        diagnostic_reasons: browser_storage_sync_cloud_provider_diagnostics_source_reasons(
            value,
            &classification,
        ),
        warnings: browser_storage_sync_cloud_provider_diagnostics_source_warnings(value),
        classification,
    }
}

fn browser_storage_sync_cloud_provider_diagnostics_source_classification(
    source: &str,
    classification: &str,
) -> String {
    let mapped = if source == "providerErrorClassification" {
        match classification {
            "authExpired" => "providerAuthRequired",
            "quotaExceeded" => "providerQuotaExceeded",
            "cloudStateRereadRequired" => "cloudConflict",
            "adapterUnsupported" => "providerAdapterUnsupported",
            "storageSetupRequired" => "providerSetupRequired",
            "providerRecoveryRequired" | "recoveryRequired" => "cloudRecoveryRequired",
            other => other,
        }
    } else {
        classification
    };
    normalize_sync_text(mapped, "unknown", MAX_SYNC_TEXT_LENGTH)
}

fn browser_storage_sync_cloud_provider_diagnostics_source_client_action(
    source: &str,
    classification: &str,
) -> String {
    if source != "providerErrorClassification" {
        return "none".to_string();
    }

    match classification {
        "providerAuthRequired" => "recoverProviderCredentials",
        "providerQuotaExceeded" => "waitForProviderStorage",
        "providerSetupRequired" => "setupProviderStorage",
        "providerAdapterUnsupported" => "stopUntilProviderFix",
        "cloudConflict" => "rereadCloudState",
        "providerUnavailable" => "retryProviderOperation",
        "cloudRecoveryRequired" => "stopUntilProviderRecovery",
        "ready" | "success" | "none" => "continueCloudSync",
        _ => "recordProviderErrorClassification",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_diagnostic_find_source<'a>(
    sources: &'a [BrowserStorageSyncCloudProviderDiagnosticSource],
    source: &str,
) -> Option<&'a BrowserStorageSyncCloudProviderDiagnosticSource> {
    sources.iter().find(|candidate| candidate.source == source)
}

fn browser_storage_sync_cloud_provider_diagnostics_string_field(
    value: &Value,
    field: &str,
    default_value: &str,
) -> String {
    json_string_field(value, field)
        .map(|text| normalize_sync_text(&text, default_value, MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| default_value.to_string())
}

fn browser_storage_sync_cloud_provider_diagnostics_string_array_field(
    value: &Value,
    field: &str,
) -> Vec<String> {
    value
        .get(field)
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .filter_map(|item| {
                    normalize_optional_sync_text(Some(item.to_string()), MAX_SYNC_TEXT_LENGTH)
                })
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn browser_storage_sync_cloud_provider_diagnostics_source_reasons(
    value: &Value,
    classification: &str,
) -> Vec<String> {
    let mut reasons = BTreeSet::new();
    for reason in browser_storage_sync_cloud_provider_diagnostics_string_array_field(
        value,
        "diagnosticReasons",
    ) {
        reasons.insert(reason);
    }
    if let Some(reason) = json_string_field(value, "reason")
        .and_then(|reason| normalize_optional_sync_text(Some(reason), MAX_SYNC_TEXT_LENGTH))
        .filter(|reason| !matches!(reason.as_str(), "ready" | "compatible" | "success" | "none"))
    {
        reasons.insert(reason);
    }
    for capability in browser_storage_sync_cloud_provider_diagnostics_string_array_field(
        value,
        "missingRequiredCapabilities",
    ) {
        reasons.insert(format!("missingCapability:{capability}"));
    }
    for capability in browser_storage_sync_cloud_provider_diagnostics_string_array_field(
        value,
        "degradedCapabilities",
    ) {
        reasons.insert(format!("degradedCapability:{capability}"));
    }
    if reasons.is_empty()
        && !browser_storage_sync_cloud_provider_diagnostics_ok_classification(classification)
    {
        reasons.insert(classification.to_string());
    }
    reasons.into_iter().collect()
}

fn browser_storage_sync_cloud_provider_diagnostics_source_warnings(value: &Value) -> Vec<String> {
    let mut warnings = BTreeSet::new();
    for warning in
        browser_storage_sync_cloud_provider_diagnostics_string_array_field(value, "warnings")
    {
        warnings.insert(warning);
    }
    for capability in browser_storage_sync_cloud_provider_diagnostics_string_array_field(
        value,
        "degradedCapabilities",
    ) {
        warnings.insert(format!("degradedCapability:{capability}"));
    }
    warnings.into_iter().collect()
}

fn browser_storage_sync_cloud_provider_diagnostics_ok_classification(classification: &str) -> bool {
    matches!(
        classification,
        "ready" | "compatible" | "success" | "idle" | "none"
    )
}

fn browser_storage_sync_cloud_provider_diagnostics_blocking_classification(
    classification: &str,
) -> bool {
    matches!(
        classification,
        "clientRequestRejected"
            | "clientUpgradeRequired"
            | "cloudDataMigrationRequired"
            | "cloudDocumentInvalid"
            | "cloudRecoveryRequired"
            | "providerAdapterUnsupported"
            | "providerAuthRequired"
            | "providerConflictUnsafe"
            | "providerContractInvalid"
            | "providerLimitTooSmall"
            | "providerQuotaExceeded"
            | "providerSetupRequired"
    )
}

fn browser_storage_sync_cloud_provider_diagnostics_severity(classification: &str) -> String {
    match classification {
        "ready" | "compatible" | "success" | "idle" | "none" => "ok",
        "cloudConflict" => "info",
        "degraded" | "providerDegraded" | "providerUnavailable" | "clientRequestRejected" => {
            "warning"
        }
        _ if browser_storage_sync_cloud_provider_diagnostics_blocking_classification(
            classification,
        ) =>
        {
            "blocked"
        }
        _ => "warning",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_diagnostics_scheduler_action(
    classification: &str,
    source_scheduler_action: Option<&str>,
) -> String {
    if let Some(action) =
        source_scheduler_action.filter(|action| !action.trim().is_empty() && *action != "none")
    {
        return normalize_sync_text(action, "stopUntilProviderRecovery", MAX_SYNC_TEXT_LENGTH);
    }

    match classification {
        "ready" | "compatible" | "success" | "providerDegraded" => "idle",
        "clientUpgradeRequired" => "stopUntilClientUpdate",
        "cloudDataMigrationRequired" | "cloudDocumentInvalid" => "stopUntilCloudRepair",
        "providerAuthRequired" => "waitForProviderCredentials",
        "providerQuotaExceeded" => "waitForProviderStorage",
        "providerSetupRequired" => "stopUntilProviderSetup",
        "providerConflictUnsafe" | "providerLimitTooSmall" | "providerContractInvalid" => {
            "stopUntilProviderFix"
        }
        "providerUnavailable" => "scheduleRetry",
        "cloudConflict" => "rereadCloudState",
        "clientRequestRejected" => "stopUntilNextChange",
        _ => "stopUntilProviderRecovery",
    }
    .to_string()
}

fn browser_storage_sync_cloud_provider_diagnostics_telemetry_level(
    classification: &str,
    severity: &str,
    schedule_state: Option<&Value>,
    cycle_status_policy: Option<&Value>,
    provider_error_classification: Option<&Value>,
) -> String {
    schedule_state
        .filter(|value| {
            json_string_field(value, "classification")
                .map(|value_classification| value_classification == classification)
                .unwrap_or(false)
        })
        .and_then(|value| json_string_field(value, "telemetryLevel"))
        .or_else(|| {
            cycle_status_policy
                .filter(|value| {
                    json_string_field(value, "classification")
                        .map(|value_classification| value_classification == classification)
                        .unwrap_or(false)
                })
                .and_then(|value| json_string_field(value, "telemetryLevel"))
        })
        .or_else(|| {
            provider_error_classification
                .filter(|value| {
                    json_string_field(value, "classification")
                        .map(|value_classification| {
                            browser_storage_sync_cloud_provider_diagnostics_source_classification(
                                "providerErrorClassification",
                                &value_classification,
                            ) == classification
                        })
                        .unwrap_or(false)
                })
                .and_then(|value| json_string_field(value, "telemetryLevel"))
        })
        .map(|telemetry_level| normalize_sync_text(&telemetry_level, "info", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| match severity {
            "ok" | "info" => "info".to_string(),
            "blocked" => "error".to_string(),
            _ => "warning".to_string(),
        })
}

fn browser_storage_sync_cloud_provider_diagnostics_bool_from_sources(
    schedule_state: Option<&Value>,
    cycle_status_policy: Option<&Value>,
    schedule_field: &str,
    classification: &str,
) -> bool {
    schedule_state
        .and_then(|value| value.get(schedule_field))
        .and_then(Value::as_bool)
        .unwrap_or_else(|| {
            schedule_state
                .or(cycle_status_policy)
                .and_then(|value| json_string_field(value, "classification"))
                .map(|value_classification| value_classification == classification)
                .unwrap_or(false)
        })
}

pub fn browser_storage_sync_cloud_observability_event(
    provider_diagnostics_json: &str,
    attempt_plan_json: &str,
    loop_plan_json: &str,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudObservabilityEvent> {
    let provider_diagnostics =
        browser_storage_sync_cloud_provider_diagnostics_optional_json(provider_diagnostics_json)?;
    let attempt_plan =
        browser_storage_sync_cloud_provider_diagnostics_optional_json(attempt_plan_json)?;
    let loop_plan = browser_storage_sync_cloud_provider_diagnostics_optional_json(loop_plan_json)?;

    if provider_diagnostics.is_none() && attempt_plan.is_none() && loop_plan.is_none() {
        return None;
    }

    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let loop_final_attempt = loop_plan
        .as_ref()
        .and_then(|value| value.get("finalAttemptPlan"))
        .filter(|value| value.is_object());
    let classification = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            loop_plan.as_ref(),
            attempt_plan.as_ref(),
            provider_diagnostics.as_ref(),
        ],
        &["finalClassification", "classification"],
        "unknown",
    );
    let severity = provider_diagnostics
        .as_ref()
        .and_then(|value| json_string_field(value, "severity"))
        .map(|severity| normalize_sync_text(&severity, "warning", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| {
            browser_storage_sync_cloud_provider_diagnostics_severity(&classification)
        });
    let telemetry_level = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            provider_diagnostics.as_ref(),
            attempt_plan.as_ref(),
            loop_final_attempt,
        ],
        &["telemetryLevel"],
        match severity.as_str() {
            "ok" | "info" => "info",
            "blocked" => "error",
            _ => "warning",
        },
    );
    let final_action = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            loop_plan.as_ref(),
            attempt_plan.as_ref(),
            provider_diagnostics.as_ref(),
        ],
        &["finalAction", "attemptAction", "clientAction"],
        "recordCloudSyncStatus",
    );
    let client_action = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            attempt_plan.as_ref(),
            loop_final_attempt,
            provider_diagnostics.as_ref(),
        ],
        &["clientAction"],
        &final_action,
    );
    let scheduler_action = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            attempt_plan.as_ref(),
            loop_final_attempt,
            provider_diagnostics.as_ref(),
        ],
        &["schedulerAction"],
        "none",
    );
    let provider_action = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            attempt_plan.as_ref(),
            loop_final_attempt,
            provider_diagnostics.as_ref(),
        ],
        &["providerAction"],
        "none",
    );
    let user_action = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            attempt_plan.as_ref(),
            loop_final_attempt,
            provider_diagnostics.as_ref(),
        ],
        &["userAction"],
        "none",
    );
    let provider_kind = browser_storage_sync_cloud_observability_string_from_sources(
        &[provider_diagnostics.as_ref()],
        &["providerKind"],
        "unknown",
    );
    let scope = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            loop_plan.as_ref(),
            attempt_plan.as_ref(),
            provider_diagnostics.as_ref(),
        ],
        &["scope"],
        "default",
    );
    let device_id = browser_storage_sync_cloud_observability_string_from_sources(
        &[
            loop_plan.as_ref(),
            attempt_plan.as_ref(),
            provider_diagnostics.as_ref(),
        ],
        &["deviceId"],
        "unknown-device",
    );
    let root_path = browser_storage_sync_cloud_observability_string_from_sources(
        &[provider_diagnostics.as_ref()],
        &["rootPath"],
        "",
    );

    let should_retry = browser_storage_sync_cloud_observability_bool_from_sources(&[
        (loop_plan.as_ref(), "shouldScheduleRetry"),
        (attempt_plan.as_ref(), "shouldRetryCycle"),
        (loop_final_attempt, "shouldRetryCycle"),
        (provider_diagnostics.as_ref(), "shouldRetry"),
    ]);
    let should_reread = browser_storage_sync_cloud_observability_bool_from_sources(&[
        (attempt_plan.as_ref(), "shouldRereadCloud"),
        (loop_final_attempt, "shouldRereadCloud"),
        (provider_diagnostics.as_ref(), "shouldReread"),
    ]);
    let should_schedule_retry = browser_storage_sync_cloud_observability_bool_from_sources(&[
        (loop_plan.as_ref(), "shouldScheduleRetry"),
        (attempt_plan.as_ref(), "shouldScheduleRetry"),
        (loop_final_attempt, "shouldScheduleRetry"),
    ]);
    let should_stop_until_recovery = browser_storage_sync_cloud_observability_bool_from_sources(&[
        (loop_plan.as_ref(), "shouldStopUntilRecovery"),
        (attempt_plan.as_ref(), "shouldStopUntilRecovery"),
        (loop_final_attempt, "shouldStopUntilRecovery"),
        (provider_diagnostics.as_ref(), "shouldBlockSync"),
    ]);
    let requires_user_action =
        browser_storage_sync_cloud_observability_bool_from_sources(&[
            (attempt_plan.as_ref(), "requiresUserAction"),
            (loop_final_attempt, "requiresUserAction"),
            (provider_diagnostics.as_ref(), "requiresUserAction"),
        ]) || browser_storage_sync_cloud_cycle_requires_user_action(&user_action);
    let waiting_for_provider_credentials =
        browser_storage_sync_cloud_observability_bool_from_sources(&[(
            provider_diagnostics.as_ref(),
            "waitingForProviderCredentials",
        )]);
    let waiting_for_provider_storage = browser_storage_sync_cloud_observability_bool_from_sources(
        &[(provider_diagnostics.as_ref(), "waitingForProviderStorage")],
    );
    let pending_cloud_reread = browser_storage_sync_cloud_observability_bool_from_sources(&[
        (attempt_plan.as_ref(), "pendingCloudReread"),
        (loop_final_attempt, "pendingCloudReread"),
        (provider_diagnostics.as_ref(), "pendingCloudReread"),
    ]);
    let retry_attempt = browser_storage_sync_cloud_observability_u32_from_sources(
        &[attempt_plan.as_ref(), loop_final_attempt],
        "retryAttempt",
    );
    let next_retry_attempt = browser_storage_sync_cloud_observability_u32_from_sources(
        &[
            loop_plan.as_ref(),
            attempt_plan.as_ref(),
            loop_final_attempt,
        ],
        "nextRetryAttempt",
    );
    let next_run_delay_seconds = browser_storage_sync_cloud_observability_optional_u32_from_sources(
        &[attempt_plan.as_ref(), loop_final_attempt],
        "nextRunDelaySeconds",
    );
    let next_run_at_unix_seconds =
        browser_storage_sync_cloud_observability_optional_i64_from_sources(
            &[
                loop_plan.as_ref(),
                attempt_plan.as_ref(),
                loop_final_attempt,
            ],
            "nextRunAtUnixSeconds",
        );
    let round_count = browser_storage_sync_cloud_observability_u32_from_sources(
        &[loop_plan.as_ref()],
        "roundCount",
    );
    let max_attempts = browser_storage_sync_cloud_observability_u32_from_sources(
        &[loop_plan.as_ref()],
        "maxAttempts",
    );
    let source_count = browser_storage_sync_cloud_observability_u32_from_sources(
        &[provider_diagnostics.as_ref()],
        "sourceCount",
    );
    let diagnostic_reasons = browser_storage_sync_cloud_observability_collect_strings(
        &[
            provider_diagnostics.as_ref(),
            attempt_plan.as_ref(),
            loop_final_attempt,
            loop_plan.as_ref(),
        ],
        "diagnosticReasons",
        &classification,
    );
    let warnings = browser_storage_sync_cloud_observability_collect_strings(
        &[provider_diagnostics.as_ref()],
        "warnings",
        "",
    );
    let event_name = browser_storage_sync_cloud_observability_event_name(
        &classification,
        &severity,
        should_retry,
        should_reread,
        should_schedule_retry,
        should_stop_until_recovery,
        requires_user_action,
    );

    let mut redacted_attributes = BTreeMap::new();
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "eventName",
        &event_name,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "providerKind",
        &provider_kind,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "classification",
        &classification,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "severity",
        &severity,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "telemetryLevel",
        &telemetry_level,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "finalAction",
        &final_action,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "schedulerAction",
        &scheduler_action,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "providerAction",
        &provider_action,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "userAction",
        &user_action,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "shouldRetry",
        &should_retry.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "shouldReread",
        &should_reread.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "shouldScheduleRetry",
        &should_schedule_retry.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "shouldStopUntilRecovery",
        &should_stop_until_recovery.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "requiresUserAction",
        &requires_user_action.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "retryAttempt",
        &retry_attempt.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "nextRetryAttempt",
        &next_retry_attempt.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "roundCount",
        &round_count.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "maxAttempts",
        &max_attempts.to_string(),
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut redacted_attributes,
        "sourceCount",
        &source_count.to_string(),
    );
    if let Some(delay) = next_run_delay_seconds {
        browser_storage_sync_cloud_observability_insert_attr(
            &mut redacted_attributes,
            "nextRunDelaySeconds",
            &delay.to_string(),
        );
    }
    if let Some(next_run_at) = next_run_at_unix_seconds {
        browser_storage_sync_cloud_observability_insert_attr(
            &mut redacted_attributes,
            "nextRunAtUnixSeconds",
            &next_run_at.to_string(),
        );
    }
    if !diagnostic_reasons.is_empty() {
        browser_storage_sync_cloud_observability_insert_attr(
            &mut redacted_attributes,
            "diagnosticReasons",
            &diagnostic_reasons.join(","),
        );
    }
    if !warnings.is_empty() {
        browser_storage_sync_cloud_observability_insert_attr(
            &mut redacted_attributes,
            "warnings",
            &warnings.join(","),
        );
    }

    let mut local_attributes = BTreeMap::new();
    browser_storage_sync_cloud_observability_insert_attr(&mut local_attributes, "scope", &scope);
    browser_storage_sync_cloud_observability_insert_attr(
        &mut local_attributes,
        "deviceId",
        &device_id,
    );
    browser_storage_sync_cloud_observability_insert_attr(
        &mut local_attributes,
        "rootPath",
        &root_path,
    );
    let contains_local_identifiers = !local_attributes.is_empty();

    Some(BrowserStorageSyncCloudObservabilityEvent {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudObservabilityEvent".to_string(),
        observed_at_unix_seconds: observed_at,
        event_name,
        category: "browserSync.cloud".to_string(),
        severity,
        telemetry_level,
        classification,
        final_action,
        client_action,
        scheduler_action,
        provider_action,
        user_action,
        provider_kind,
        scope,
        device_id,
        should_record_locally: true,
        redacted_export_allowed: true,
        local_attributes_restricted: true,
        contains_local_identifiers,
        should_retry,
        should_reread,
        should_schedule_retry,
        should_stop_until_recovery,
        requires_user_action,
        waiting_for_provider_credentials,
        waiting_for_provider_storage,
        pending_cloud_reread,
        retry_attempt,
        next_retry_attempt,
        next_run_delay_seconds,
        next_run_at_unix_seconds,
        round_count,
        max_attempts,
        source_count,
        diagnostic_reasons,
        warnings,
        redacted_attributes,
        local_attributes,
        export_policy:
            "Record full cloud sync observability events locally. Export only redactedAttributes, and only through user-approved product telemetry or explicit local diagnostic export; localAttributes stay device-local by default."
                .to_string(),
        result_policy:
            "Summarize Rust-owned cloud diagnostics, attempt plans, and loop plans into one local/exportable observability event without adding a browser sync service or moving provider SDK execution into Rust."
                .to_string(),
    })
}

fn browser_storage_sync_cloud_observability_string_from_sources(
    sources: &[Option<&Value>],
    fields: &[&str],
    default_value: &str,
) -> String {
    for source in sources.iter().flatten() {
        for field in fields {
            if let Some(value) = json_string_field(source, field)
                .and_then(|value| normalize_optional_sync_text(Some(value), MAX_SYNC_TEXT_LENGTH))
                .filter(|value| !value.is_empty() && value != "null")
            {
                return value;
            }
        }
    }
    normalize_sync_text(default_value, "unknown", MAX_SYNC_TEXT_LENGTH)
}

fn browser_storage_sync_cloud_observability_bool_from_sources(
    sources: &[(Option<&Value>, &str)],
) -> bool {
    sources.iter().any(|(source, field)| {
        source
            .and_then(|value| value.get(*field))
            .and_then(Value::as_bool)
            .unwrap_or(false)
    })
}

fn browser_storage_sync_cloud_observability_u32_from_sources(
    sources: &[Option<&Value>],
    field: &str,
) -> u32 {
    browser_storage_sync_cloud_observability_optional_u32_from_sources(sources, field)
        .unwrap_or_default()
}

fn browser_storage_sync_cloud_observability_optional_u32_from_sources(
    sources: &[Option<&Value>],
    field: &str,
) -> Option<u32> {
    sources.iter().flatten().find_map(|source| {
        source
            .get(field)
            .and_then(Value::as_u64)
            .map(|value| value.min(u64::from(u32::MAX)) as u32)
    })
}

fn browser_storage_sync_cloud_observability_optional_i64_from_sources(
    sources: &[Option<&Value>],
    field: &str,
) -> Option<i64> {
    sources.iter().flatten().find_map(|source| {
        source
            .get(field)
            .and_then(Value::as_i64)
            .map(normalize_unix_seconds)
    })
}

fn browser_storage_sync_cloud_observability_collect_strings(
    sources: &[Option<&Value>],
    field: &str,
    fallback_classification: &str,
) -> Vec<String> {
    let mut values = BTreeSet::new();
    for source in sources.iter().flatten() {
        for item in
            browser_storage_sync_cloud_provider_diagnostics_string_array_field(source, field)
        {
            values.insert(item);
        }
    }
    if values.is_empty()
        && !fallback_classification.is_empty()
        && !browser_storage_sync_cloud_provider_diagnostics_ok_classification(
            fallback_classification,
        )
    {
        values.insert(fallback_classification.to_string());
    }
    values.into_iter().collect()
}

fn browser_storage_sync_cloud_observability_event_name(
    classification: &str,
    severity: &str,
    should_retry: bool,
    should_reread: bool,
    should_schedule_retry: bool,
    should_stop_until_recovery: bool,
    requires_user_action: bool,
) -> String {
    let event_name =
        if browser_storage_sync_cloud_provider_diagnostics_ok_classification(classification) {
            "browserSyncCloudReady"
        } else if requires_user_action {
            "browserSyncCloudUserActionRequired"
        } else if should_stop_until_recovery || severity == "blocked" {
            "browserSyncCloudBlocked"
        } else if should_schedule_retry || should_retry {
            "browserSyncCloudRetryScheduled"
        } else if should_reread {
            "browserSyncCloudRereadRequired"
        } else if classification == "cloudConflict" {
            "browserSyncCloudConflict"
        } else if classification == "providerUnavailable" {
            "browserSyncCloudProviderUnavailable"
        } else {
            "browserSyncCloudStatusChanged"
        };
    event_name.to_string()
}

fn browser_storage_sync_cloud_observability_insert_attr(
    attributes: &mut BTreeMap<String, String>,
    key: &str,
    value: &str,
) {
    if let Some(value) = normalize_optional_sync_text(Some(value.to_string()), MAX_SYNC_TEXT_LENGTH)
    {
        if !value.is_empty() {
            attributes.insert(key.to_string(), value);
        }
    }
}

fn browser_storage_sync_cloud_cycle_attempt_plan_value(
    cycle_round: &Value,
    retry_attempt: u32,
    observed_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncCloudCycleAttemptPlan> {
    if !cycle_round.is_object() {
        return None;
    }

    let client_plan_value = browser_storage_sync_cloud_cycle_client_plan_value(cycle_round)?;
    let status_policy =
        browser_storage_sync_cloud_cycle_status_policy_value(cycle_round, retry_attempt)?;
    let status_policy_json = serialize_json(&status_policy);
    let schedule_state = browser_storage_sync_cloud_cycle_schedule_state(
        &status_policy_json,
        observed_at_unix_seconds,
    )?;
    let client_plan_action = client_plan_value
        .get("action")
        .and_then(Value::as_str)
        .map(|action| normalize_sync_text(action, "recoverCloudCycle", MAX_SYNC_TEXT_LENGTH))
        .unwrap_or_else(|| "recoverCloudCycle".to_string());
    let steps = client_plan_value
        .get("steps")
        .cloned()
        .map(serde_json::from_value::<Vec<BrowserStorageSyncClientCycleStep>>)
        .transpose()
        .ok()?
        .unwrap_or_default();
    let should_apply_local_ack = status_policy.should_ack_local
        || browser_storage_sync_cloud_cycle_steps_has(&steps, "applyLocalAck");
    let should_apply_remote = status_policy.should_apply_remote
        || browser_storage_sync_cloud_cycle_steps_has(&steps, "applyRemoteBatch");
    let should_reread_cloud = schedule_state.pending_cloud_reread
        || browser_storage_sync_cloud_cycle_steps_has(&steps, "rereadCloudState");
    let should_retry_cycle = schedule_state.should_retry
        || browser_storage_sync_cloud_cycle_steps_has(&steps, "scheduleCloudCycleRetry");
    let should_schedule_retry =
        should_retry_cycle && schedule_state.next_run_at_unix_seconds.is_some();
    let should_run_provider_operation =
        browser_storage_sync_cloud_cycle_attempt_runs_provider_operation(
            &schedule_state.provider_action,
        );
    let should_wait_for_provider = schedule_state.waiting_for_provider_credentials
        || schedule_state.waiting_for_provider_storage;
    let requires_provider_recovery =
        browser_storage_sync_cloud_cycle_attempt_requires_provider_recovery(
            &schedule_state.provider_action,
        );
    let should_finish_cycle = status_policy.completed;
    let should_continue_loop = !should_finish_cycle
        && !should_wait_for_provider
        && !requires_provider_recovery
        && !schedule_state.requires_user_action
        && (should_apply_local_ack
            || should_apply_remote
            || should_reread_cloud
            || should_retry_cycle
            || should_run_provider_operation);
    let should_stop_until_recovery = !should_finish_cycle && !should_continue_loop;
    let attempt_action = browser_storage_sync_cloud_cycle_attempt_action(
        should_finish_cycle,
        should_apply_local_ack,
        should_apply_remote,
        should_reread_cloud,
        should_schedule_retry,
        should_stop_until_recovery,
        &client_plan_action,
        &schedule_state,
    );

    Some(BrowserStorageSyncCloudCycleAttemptPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudCycleAttemptPlan".to_string(),
        observed_at_unix_seconds: schedule_state.observed_at_unix_seconds,
        scope: schedule_state.scope,
        device_id: schedule_state.device_id,
        classification: schedule_state.classification,
        attempt_action,
        client_action: schedule_state.client_action,
        client_plan_action,
        scheduler_action: schedule_state.scheduler_action,
        provider_action: schedule_state.provider_action,
        user_action: schedule_state.user_action,
        telemetry_level: schedule_state.telemetry_level,
        completed: status_policy.completed,
        should_finish_cycle,
        should_continue_loop,
        should_apply_local_ack,
        should_apply_remote,
        should_reread_cloud,
        should_retry_cycle,
        should_schedule_retry,
        should_run_provider_operation,
        should_wait_for_provider,
        requires_provider_recovery,
        requires_user_action: schedule_state.requires_user_action,
        should_stop_until_recovery,
        pending_cloud_reread: schedule_state.pending_cloud_reread,
        retry_attempt: schedule_state.retry_attempt,
        next_retry_attempt: schedule_state.next_retry_attempt,
        next_run_delay_seconds: schedule_state.next_run_delay_seconds,
        next_run_at_unix_seconds: schedule_state.next_run_at_unix_seconds,
        steps,
        diagnostic_reasons: schedule_state.diagnostic_reasons,
        result_policy:
            "Compose the Rust-owned cloud cycle client plan, status policy, and schedule state into one provider-neutral attempt orchestration plan. Native adapters still execute provider SDK calls, OS scheduling, and SQLite apply work."
                .to_string(),
    })
}

pub fn browser_storage_sync_cloud_cycle_loop_plan(
    cycle_rounds_json: &str,
    retry_attempt: u32,
    observed_at_unix_seconds: i64,
    max_attempts: u32,
) -> Option<BrowserStorageSyncCloudCycleLoopPlan> {
    let value = serde_json::from_str::<Value>(cycle_rounds_json).ok()?;
    let rounds = parse_browser_storage_sync_cloud_cycle_loop_rounds(&value)?;
    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let max_attempts = browser_storage_sync_cloud_cycle_loop_max_attempts(max_attempts);
    let retry_attempt = retry_attempt.min(16);

    if rounds.is_empty() {
        return Some(browser_storage_sync_cloud_cycle_empty_loop_plan(
            observed_at,
            max_attempts,
            retry_attempt,
        ));
    }

    let mut attempts = Vec::new();
    let mut final_attempt_plan = None;
    let mut diagnostic_reasons = BTreeSet::new();

    for (index, round) in rounds.iter().enumerate() {
        let attempt_retry = retry_attempt
            .saturating_add(index.min(u32::MAX as usize) as u32)
            .min(16);
        let attempt =
            browser_storage_sync_cloud_cycle_attempt_plan_value(round, attempt_retry, observed_at)?;
        for reason in &attempt.diagnostic_reasons {
            diagnostic_reasons.insert(reason.clone());
        }
        attempts.push(browser_storage_sync_cloud_cycle_loop_attempt_summary(
            index, round, &attempt,
        ));
        final_attempt_plan = Some(attempt);
    }

    let final_attempt = final_attempt_plan.as_ref()?;
    let round_count = rounds.len().min(u32::MAX as usize) as u32;
    let completed = final_attempt.completed;
    let exhausted = !completed && round_count >= max_attempts;
    let blocked_by_native_apply =
        !completed && (final_attempt.should_apply_local_ack || final_attempt.should_apply_remote);
    let blocked_by_retry_backoff = !completed
        && final_attempt.should_schedule_retry
        && final_attempt.next_run_at_unix_seconds.is_some()
        && !blocked_by_native_apply;
    let should_continue_loop = !completed
        && final_attempt.should_continue_loop
        && !exhausted
        && !blocked_by_native_apply
        && !blocked_by_retry_backoff
        && !final_attempt.should_stop_until_recovery;
    let should_run_next_provider_round = should_continue_loop
        && final_attempt.should_run_provider_operation
        && final_attempt.next_run_delay_seconds.unwrap_or(0) == 0;
    let should_schedule_retry = !completed
        && final_attempt.should_schedule_retry
        && (blocked_by_retry_backoff || exhausted || blocked_by_native_apply);
    let should_stop_until_recovery =
        !completed && (final_attempt.should_stop_until_recovery || exhausted);
    let final_action = browser_storage_sync_cloud_cycle_loop_final_action(
        final_attempt,
        exhausted,
        blocked_by_native_apply,
        blocked_by_retry_backoff,
        should_run_next_provider_round,
    );
    let next_run_at_unix_seconds = if should_run_next_provider_round {
        None
    } else {
        final_attempt.next_run_at_unix_seconds
    };

    let final_classification = final_attempt.classification.clone();
    let next_retry_attempt = final_attempt.next_retry_attempt;
    let diagnostic_reasons = diagnostic_reasons.into_iter().collect::<Vec<_>>();
    let loop_summary = browser_storage_sync_cloud_cycle_loop_summary(
        &attempts,
        max_attempts,
        completed,
        exhausted,
        blocked_by_native_apply,
        blocked_by_retry_backoff,
        should_continue_loop,
        should_run_next_provider_round,
        should_schedule_retry,
        should_stop_until_recovery,
        &final_classification,
        &final_action,
        next_retry_attempt,
        next_run_at_unix_seconds,
        &diagnostic_reasons,
    );

    Some(BrowserStorageSyncCloudCycleLoopPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudCycleLoopPlan".to_string(),
        observed_at_unix_seconds: observed_at,
        scope: final_attempt.scope.clone(),
        device_id: final_attempt.device_id.clone(),
        round_count,
        max_attempts,
        loop_summary,
        completed,
        exhausted,
        blocked_by_native_apply,
        blocked_by_retry_backoff,
        should_continue_loop,
        should_run_next_provider_round,
        should_schedule_retry,
        should_stop_until_recovery,
        final_classification,
        final_action,
        next_retry_attempt,
        next_run_at_unix_seconds,
        attempts,
        final_attempt_plan,
        diagnostic_reasons,
        result_policy:
            "Plan a bounded cloud-drive sync loop from already-produced cycle rounds. Rust decides when another provider round is allowed, when native SQLite apply is a barrier, when retry backoff must hand control to the scheduler, and when provider/user recovery must stop the loop."
                .to_string(),
    })
}

fn parse_browser_storage_sync_cloud_cycle_loop_rounds(value: &Value) -> Option<Vec<Value>> {
    if let Some(rounds) = value.as_array() {
        return rounds
            .iter()
            .map(parse_browser_storage_sync_cloud_cycle_loop_round)
            .collect();
    }

    if let Some(rounds) = value.get("rounds").and_then(Value::as_array) {
        return rounds
            .iter()
            .map(parse_browser_storage_sync_cloud_cycle_loop_round)
            .collect();
    }

    if let Some(rounds) = value.get("cycleRounds").and_then(Value::as_array) {
        return rounds
            .iter()
            .map(parse_browser_storage_sync_cloud_cycle_loop_round)
            .collect();
    }

    if let Some(rounds) = value.get("attempts").and_then(Value::as_array) {
        return rounds
            .iter()
            .map(|attempt| {
                attempt
                    .get("round")
                    .or_else(|| attempt.get("cycleRound"))
                    .unwrap_or(attempt)
            })
            .map(parse_browser_storage_sync_cloud_cycle_loop_round)
            .collect();
    }

    Some(vec![parse_browser_storage_sync_cloud_cycle_loop_round(
        value,
    )?])
}

fn parse_browser_storage_sync_cloud_cycle_loop_round(value: &Value) -> Option<Value> {
    if value.is_object() {
        Some(value.clone())
    } else {
        None
    }
}

fn browser_storage_sync_cloud_cycle_loop_max_attempts(max_attempts: u32) -> u32 {
    if max_attempts == 0 {
        BROWSER_STORAGE_SYNC_CLOUD_DEFAULT_LOOP_MAX_ATTEMPTS
    } else {
        max_attempts.clamp(1, BROWSER_STORAGE_SYNC_CLOUD_MAX_LOOP_ATTEMPTS)
    }
}

fn browser_storage_sync_cloud_cycle_empty_loop_plan(
    observed_at: i64,
    max_attempts: u32,
    retry_attempt: u32,
) -> BrowserStorageSyncCloudCycleLoopPlan {
    let attempts = Vec::new();
    let diagnostic_reasons = Vec::new();
    let final_classification = "pending".to_string();
    let final_action = "runCloudCycleRound".to_string();
    let next_run_at_unix_seconds = Some(observed_at);
    let loop_summary = browser_storage_sync_cloud_cycle_loop_summary(
        &attempts,
        max_attempts,
        false,
        false,
        false,
        false,
        true,
        true,
        false,
        false,
        &final_classification,
        &final_action,
        retry_attempt,
        next_run_at_unix_seconds,
        &diagnostic_reasons,
    );

    BrowserStorageSyncCloudCycleLoopPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudCycleLoopPlan".to_string(),
        observed_at_unix_seconds: observed_at,
        scope: "default".to_string(),
        device_id: "unknown-device".to_string(),
        round_count: 0,
        max_attempts,
        loop_summary,
        completed: false,
        exhausted: false,
        blocked_by_native_apply: false,
        blocked_by_retry_backoff: false,
        should_continue_loop: true,
        should_run_next_provider_round: true,
        should_schedule_retry: false,
        should_stop_until_recovery: false,
        final_classification,
        final_action,
        next_retry_attempt: retry_attempt,
        next_run_at_unix_seconds,
        attempts,
        final_attempt_plan: None,
        diagnostic_reasons,
        result_policy:
            "Plan a bounded cloud-drive sync loop from already-produced cycle rounds. Rust decides when another provider round is allowed, when native SQLite apply is a barrier, when retry backoff must hand control to the scheduler, and when provider/user recovery must stop the loop."
                .to_string(),
    }
}

#[allow(clippy::too_many_arguments)]
fn browser_storage_sync_cloud_cycle_loop_summary(
    attempts: &[BrowserStorageSyncCloudCycleLoopAttemptSummary],
    max_attempts: u32,
    completed: bool,
    exhausted: bool,
    blocked_by_native_apply: bool,
    blocked_by_retry_backoff: bool,
    should_continue_loop: bool,
    should_run_next_provider_round: bool,
    should_schedule_retry: bool,
    should_stop_until_recovery: bool,
    final_classification: &str,
    final_action: &str,
    next_retry_attempt: u32,
    next_run_at_unix_seconds: Option<i64>,
    diagnostic_reasons: &[String],
) -> BrowserStorageSyncCloudCycleLoopSummary {
    let attempt_count = attempts.len().min(u32::MAX as usize) as u32;
    let completed_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.completed)
        .count()
        .min(u32::MAX as usize) as u32;
    let local_ack_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_apply_local_ack)
        .count()
        .min(u32::MAX as usize) as u32;
    let remote_apply_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_apply_remote)
        .count()
        .min(u32::MAX as usize) as u32;
    let reread_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_reread_cloud)
        .count()
        .min(u32::MAX as usize) as u32;
    let retry_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_retry_cycle)
        .count()
        .min(u32::MAX as usize) as u32;
    let scheduled_retry_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_schedule_retry)
        .count()
        .min(u32::MAX as usize) as u32;
    let provider_operation_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_run_provider_operation)
        .count()
        .min(u32::MAX as usize) as u32;
    let continue_loop_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_continue_loop)
        .count()
        .min(u32::MAX as usize) as u32;
    let stop_until_recovery_attempt_count = attempts
        .iter()
        .filter(|attempt| attempt.should_stop_until_recovery)
        .count()
        .min(u32::MAX as usize) as u32;
    let native_apply_barrier_count = attempts
        .iter()
        .filter(|attempt| attempt.should_apply_local_ack || attempt.should_apply_remote)
        .count()
        .min(u32::MAX as usize) as u32;

    let mut classifications = BTreeSet::new();
    let mut attempt_actions = BTreeSet::new();
    for attempt in attempts {
        classifications.insert(attempt.classification.clone());
        attempt_actions.insert(attempt.attempt_action.clone());
    }
    classifications.insert(final_classification.to_string());
    attempt_actions.insert(final_action.to_string());

    BrowserStorageSyncCloudCycleLoopSummary {
        attempt_count,
        max_attempts,
        completed_attempt_count,
        local_ack_attempt_count,
        remote_apply_attempt_count,
        reread_attempt_count,
        retry_attempt_count,
        scheduled_retry_attempt_count,
        provider_operation_attempt_count,
        continue_loop_attempt_count,
        stop_until_recovery_attempt_count,
        native_apply_barrier_count,
        completed,
        exhausted,
        blocked_by_native_apply,
        blocked_by_retry_backoff,
        should_continue_loop,
        should_run_next_provider_round,
        should_schedule_retry,
        should_stop_until_recovery,
        final_classification: final_classification.to_string(),
        final_action: final_action.to_string(),
        next_retry_attempt,
        next_run_at_unix_seconds,
        classifications: classifications.into_iter().collect(),
        attempt_actions: attempt_actions.into_iter().collect(),
        diagnostic_reasons: diagnostic_reasons.to_vec(),
    }
}

fn browser_storage_sync_cloud_cycle_loop_attempt_summary(
    index: usize,
    round: &Value,
    attempt: &BrowserStorageSyncCloudCycleAttemptPlan,
) -> BrowserStorageSyncCloudCycleLoopAttemptSummary {
    BrowserStorageSyncCloudCycleLoopAttemptSummary {
        attempt_index: index.min(u32::MAX as usize) as u32,
        round_generated_at_unix_seconds: round
            .get("generatedAtUnixSeconds")
            .and_then(Value::as_i64)
            .map(normalize_unix_seconds)
            .unwrap_or(attempt.observed_at_unix_seconds),
        classification: attempt.classification.clone(),
        attempt_action: attempt.attempt_action.clone(),
        completed: attempt.completed,
        should_apply_local_ack: attempt.should_apply_local_ack,
        should_apply_remote: attempt.should_apply_remote,
        should_reread_cloud: attempt.should_reread_cloud,
        should_retry_cycle: attempt.should_retry_cycle,
        should_schedule_retry: attempt.should_schedule_retry,
        should_run_provider_operation: attempt.should_run_provider_operation,
        should_continue_loop: attempt.should_continue_loop,
        should_stop_until_recovery: attempt.should_stop_until_recovery,
        next_run_at_unix_seconds: attempt.next_run_at_unix_seconds,
    }
}

fn browser_storage_sync_cloud_cycle_loop_final_action(
    final_attempt: &BrowserStorageSyncCloudCycleAttemptPlan,
    exhausted: bool,
    blocked_by_native_apply: bool,
    blocked_by_retry_backoff: bool,
    should_run_next_provider_round: bool,
) -> String {
    if final_attempt.completed
        || blocked_by_native_apply
        || final_attempt.should_stop_until_recovery
    {
        return final_attempt.attempt_action.clone();
    }
    if exhausted {
        return if final_attempt.should_schedule_retry {
            "scheduleCloudCycleRetryAfterMaxAttempts".to_string()
        } else {
            "stopCloudCycleAfterMaxAttempts".to_string()
        };
    }
    if blocked_by_retry_backoff {
        return final_attempt.attempt_action.clone();
    }
    if should_run_next_provider_round {
        return "runNextCloudCycleRound".to_string();
    }
    final_attempt.attempt_action.clone()
}

pub fn browser_storage_sync_cloud_membership_loop_plan(
    membership_rounds_json: &str,
    retry_attempt: u32,
    observed_at_unix_seconds: i64,
    max_attempts: u32,
) -> Option<BrowserStorageSyncCloudMembershipLoopPlan> {
    let value = serde_json::from_str::<Value>(membership_rounds_json).ok()?;
    let rounds = parse_browser_storage_sync_cloud_membership_loop_rounds(&value)?;
    let observed_at = normalize_unix_seconds(observed_at_unix_seconds);
    let max_attempts = browser_storage_sync_cloud_cycle_loop_max_attempts(max_attempts);
    let retry_attempt = retry_attempt.min(16);

    if rounds.is_empty() {
        return Some(browser_storage_sync_cloud_membership_empty_loop_plan(
            observed_at,
            max_attempts,
            retry_attempt,
        ));
    }

    let mut attempts = Vec::new();
    let mut final_attempt_plan = None;
    let mut diagnostic_reasons = BTreeSet::new();

    for (index, round) in rounds.iter().enumerate() {
        let attempt_retry = retry_attempt
            .saturating_add(index.min(u32::MAX as usize) as u32)
            .min(16);
        let attempt = browser_storage_sync_cloud_membership_attempt_plan_value(
            round,
            attempt_retry,
            observed_at,
        )?;
        for reason in &attempt.diagnostic_reasons {
            diagnostic_reasons.insert(reason.clone());
        }
        attempts.push(browser_storage_sync_cloud_membership_loop_attempt_summary(
            index, round, &attempt,
        ));
        final_attempt_plan = Some(attempt);
    }

    let final_attempt = final_attempt_plan.as_ref()?;
    let round_count = rounds.len().min(u32::MAX as usize) as u32;
    let completed = final_attempt.completed;
    let exhausted = !completed && round_count >= max_attempts;
    let blocked_by_retry_backoff = !completed
        && final_attempt.should_schedule_retry
        && final_attempt.next_run_at_unix_seconds.is_some();
    let should_continue_loop = !completed
        && final_attempt.should_continue_membership
        && !exhausted
        && !blocked_by_retry_backoff
        && !final_attempt.should_stop_until_recovery;
    let should_run_next_provider_round = should_continue_loop
        && final_attempt.should_run_provider_operation
        && final_attempt.next_run_delay_seconds.unwrap_or(0) == 0;
    let should_schedule_retry = !completed
        && final_attempt.should_schedule_retry
        && (blocked_by_retry_backoff || exhausted);
    let should_stop_until_recovery =
        !completed && (final_attempt.should_stop_until_recovery || exhausted);
    let final_action = browser_storage_sync_cloud_membership_loop_final_action(
        final_attempt,
        exhausted,
        blocked_by_retry_backoff,
        should_run_next_provider_round,
    );
    let next_run_at_unix_seconds = if should_run_next_provider_round {
        None
    } else {
        final_attempt.next_run_at_unix_seconds
    };
    let final_classification = final_attempt.classification.clone();
    let next_retry_attempt = final_attempt.next_retry_attempt;
    let diagnostic_reasons = diagnostic_reasons.into_iter().collect::<Vec<_>>();
    let loop_summary = browser_storage_sync_cloud_membership_loop_summary(
        &attempts,
        max_attempts,
        completed,
        exhausted,
        blocked_by_retry_backoff,
        should_continue_loop,
        should_run_next_provider_round,
        should_schedule_retry,
        should_stop_until_recovery,
        &final_classification,
        &final_action,
        next_retry_attempt,
        next_run_at_unix_seconds,
        &diagnostic_reasons,
    );

    Some(BrowserStorageSyncCloudMembershipLoopPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudMembershipLoopPlan".to_string(),
        observed_at_unix_seconds: observed_at,
        scope: final_attempt.scope.clone(),
        device_id: final_attempt.device_id.clone(),
        actor_device_id: final_attempt.actor_device_id.clone(),
        member_device_id: final_attempt.member_device_id.clone(),
        membership_action: final_attempt.membership_action.clone(),
        member_status: final_attempt.member_status.clone(),
        round_count,
        max_attempts,
        loop_summary,
        completed,
        exhausted,
        blocked_by_retry_backoff,
        should_continue_loop,
        should_run_next_provider_round,
        should_schedule_retry,
        should_stop_until_recovery,
        final_classification,
        final_action,
        next_retry_attempt,
        next_run_at_unix_seconds,
        attempts,
        final_attempt_plan,
        diagnostic_reasons,
        result_policy:
            "Plan a bounded cloud-drive membership loop from already-produced connect/revoke rounds. Rust decides when another provider membership round is allowed, when retry backoff must hand control to the scheduler, and when provider/user recovery must stop the loop."
                .to_string(),
    })
}

fn parse_browser_storage_sync_cloud_membership_loop_rounds(value: &Value) -> Option<Vec<Value>> {
    if let Some(rounds) = value.as_array() {
        return rounds
            .iter()
            .map(parse_browser_storage_sync_cloud_membership_loop_round)
            .collect();
    }

    if let Some(rounds) = value.get("rounds").and_then(Value::as_array) {
        return rounds
            .iter()
            .map(parse_browser_storage_sync_cloud_membership_loop_round)
            .collect();
    }

    if let Some(rounds) = value.get("membershipRounds").and_then(Value::as_array) {
        return rounds
            .iter()
            .map(parse_browser_storage_sync_cloud_membership_loop_round)
            .collect();
    }

    if let Some(rounds) = value.get("attempts").and_then(Value::as_array) {
        return rounds
            .iter()
            .map(|attempt| {
                attempt
                    .get("round")
                    .or_else(|| attempt.get("membershipRound"))
                    .unwrap_or(attempt)
            })
            .map(parse_browser_storage_sync_cloud_membership_loop_round)
            .collect();
    }

    Some(vec![
        parse_browser_storage_sync_cloud_membership_loop_round(value)?,
    ])
}

fn parse_browser_storage_sync_cloud_membership_loop_round(value: &Value) -> Option<Value> {
    if value.is_object() {
        Some(value.clone())
    } else {
        None
    }
}

fn browser_storage_sync_cloud_membership_empty_loop_plan(
    observed_at: i64,
    max_attempts: u32,
    retry_attempt: u32,
) -> BrowserStorageSyncCloudMembershipLoopPlan {
    let attempts = Vec::new();
    let diagnostic_reasons = Vec::new();
    let final_classification = "pending".to_string();
    let final_action = "runCloudMembershipRound".to_string();
    let next_run_at_unix_seconds = Some(observed_at);
    let loop_summary = browser_storage_sync_cloud_membership_loop_summary(
        &attempts,
        max_attempts,
        false,
        false,
        false,
        true,
        true,
        false,
        false,
        &final_classification,
        &final_action,
        retry_attempt,
        next_run_at_unix_seconds,
        &diagnostic_reasons,
    );

    BrowserStorageSyncCloudMembershipLoopPlan {
        version: BROWSER_STORAGE_SYNC_CLOUD_PLAN_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        cloud_data_model_version: BROWSER_STORAGE_SYNC_CLOUD_DATA_MODEL_VERSION,
        plan_type: "cloudMembershipLoopPlan".to_string(),
        observed_at_unix_seconds: observed_at,
        scope: "default".to_string(),
        device_id: "unknown-device".to_string(),
        actor_device_id: "unknown-device".to_string(),
        member_device_id: "unknown-device".to_string(),
        membership_action: "connect".to_string(),
        member_status: "pending".to_string(),
        round_count: 0,
        max_attempts,
        loop_summary,
        completed: false,
        exhausted: false,
        blocked_by_retry_backoff: false,
        should_continue_loop: true,
        should_run_next_provider_round: true,
        should_schedule_retry: false,
        should_stop_until_recovery: false,
        final_classification,
        final_action,
        next_retry_attempt: retry_attempt,
        next_run_at_unix_seconds,
        attempts,
        final_attempt_plan: None,
        diagnostic_reasons,
        result_policy:
            "Plan a bounded cloud-drive membership loop from already-produced connect/revoke rounds. Rust decides when another provider membership round is allowed, when retry backoff must hand control to the scheduler, and when provider/user recovery must stop the loop."
                .to_string(),
    }
}

