fn browser_storage_sync_cloud_compaction_issue_action(
    reason: &str,
    retryable: bool,
    operation_type: &str,
) -> &'static str {
    match reason {
        "conflict" => BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY,
        "unauthorized" => "recoverProviderCredentials",
        "quotaExceeded" => "freeCloudStorageOrReduceRetention",
        "deleteBeforeManifestCommit" | "invalidPath" | "unsupported" | "invalidResult" => {
            "abortAndReportProviderBug"
        }
        _ if operation_type == "deleteLog" && retryable => "retryCloudLogCleanup",
        _ if retryable => "retrySameCloudCompactionPlanWithBackoff",
        _ if operation_type == "deleteLog" => "reportCloudCleanupFailure",
        _ => "abortAndReportProviderFailure",
    }
}

fn browser_storage_sync_cloud_compaction_result_client_action(
    compaction_plan: &BrowserStorageSyncCloudCompactionPlan,
    completed: bool,
    cleanup_completed: bool,
    should_reread: bool,
    should_retry: bool,
    should_retry_cleanup: bool,
    issues: &[BrowserStorageSyncCloudCompactionResultIssue],
) -> String {
    if !compaction_plan.should_compact {
        return "nothingToCompact".to_string();
    }
    if issues.iter().any(|issue| issue.reason == "unauthorized") {
        return "recoverProviderCredentials".to_string();
    }
    if issues.iter().any(|issue| issue.reason == "quotaExceeded") {
        return "freeCloudStorageOrReduceRetention".to_string();
    }
    if should_reread {
        return BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY.to_string();
    }
    if should_retry {
        return "retrySameCloudCompactionPlanWithBackoff".to_string();
    }
    if !completed {
        return "abortAndReportProviderFailure".to_string();
    }
    if should_retry_cleanup {
        return "retryCloudLogCleanup".to_string();
    }
    if !cleanup_completed {
        return "reportCloudCleanupFailure".to_string();
    }
    "finishCompaction".to_string()
}

fn browser_storage_sync_cloud_cleanup_candidate_is_valid(
    operation: &BrowserStorageSyncCloudPlannedDeleteOperation,
) -> bool {
    operation.operation_type == "candidateDeleteLog"
        && !operation.required
        && operation
            .collection
            .as_deref()
            .and_then(normalize_sync_collection)
            .is_some()
        && browser_storage_sync_cloud_document_kind_from_path(&operation.path) == "log"
}

