fn browser_storage_sync_cloud_compaction_result_reread_operations(
    compaction_plan: &BrowserStorageSyncCloudCompactionPlan,
) -> Vec<BrowserStorageSyncCloudPlannedReadOperation> {
    let mut operations = vec![browser_storage_sync_cloud_planned_read(
        0,
        "readManifest",
        Some(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH.to_string()),
        None,
        None,
        None,
        "Option<BrowserStorageSyncCloudManifest>",
        true,
    )];
    for collection in &compaction_plan.compacted_collections {
        operations.push(browser_storage_sync_cloud_planned_read(
            operations.len(),
            "readSnapshot",
            Some(collection.snapshot_path.clone()),
            None,
            Some(collection.collection.clone()),
            None,
            "Option<BrowserStorageSyncCloudSnapshotObject>",
            true,
        ));
        operations.push(browser_storage_sync_cloud_planned_read(
            operations.len(),
            "listLogs",
            None,
            Some(browser_storage_sync_cloud_logs_prefix(&collection.collection)),
            Some(collection.collection.clone()),
            Some(MAX_BROWSER_STORAGE_SYNC_RECORDS as u32),
            "BrowserStorageSyncCloudListResult; provider adapters read matching log object bytes and pass normalized BrowserStorageSyncCloudLogObject values back to Rust",
            true,
        ));
    }
    operations
}

fn browser_storage_sync_cloud_ack_batch_from_push_plan(
    push_plan: &BrowserStorageSyncCloudPushPlan,
    synced_at_unix_seconds: i64,
) -> Option<BrowserStorageSyncAckBatch> {
    let synced_at = normalize_unix_seconds(synced_at_unix_seconds);
    let mut records = Vec::new();
    let mut cursors = Vec::new();

    for operation in &push_plan.operations {
        if operation.operation_type != "writeLog" {
            continue;
        }
        let log =
            serde_json::from_str::<BrowserStorageSyncCloudLogObject>(&operation.body_json).ok();
        let log = normalize_browser_storage_sync_cloud_log_object(log)?;
        if log.scope != push_plan.scope || log.device_id != push_plan.device_id {
            return None;
        }
        for record in log.batch.records {
            records.push(BrowserStorageSyncAckRecord {
                record_type: record.payload.record_type().as_str().to_string(),
                record_id: record.record_id,
                sync_revision: record.sync_revision,
            });
        }
        cursors.extend(log.batch.cursors);
    }

    records.sort_by(|left, right| {
        browser_storage_sync_collection_order(
            BrowserStorageSyncRecordType::parse(&left.record_type)
                .map(BrowserStorageSyncRecordType::collection)
                .unwrap_or(""),
        )
        .cmp(&browser_storage_sync_collection_order(
            BrowserStorageSyncRecordType::parse(&right.record_type)
                .map(BrowserStorageSyncRecordType::collection)
                .unwrap_or(""),
        ))
        .then_with(|| left.record_type.cmp(&right.record_type))
        .then_with(|| left.record_id.cmp(&right.record_id))
    });
    records.dedup_by(|left, right| {
        left.record_type == right.record_type && left.record_id == right.record_id
    });
    let cursors = merge_browser_storage_sync_cursors(Vec::new(), cursors, synced_at);

    normalize_browser_storage_sync_ack_batch(Some(BrowserStorageSyncAckBatch {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        scope: push_plan.scope.clone(),
        device_id: push_plan.device_id.clone(),
        synced_at_unix_seconds: synced_at,
        records,
        cursors,
    }))
}

fn normalize_cloud_error_kind(kind: &str) -> String {
    let compact = kind
        .trim()
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect::<String>();
    match compact.as_str() {
        "notfound" => "notFound".to_string(),
        "conflict" => "conflict".to_string(),
        "unauthorized" | "authrequired" | "forbidden" => "unauthorized".to_string(),
        "quotaexceeded" | "quota" => "quotaExceeded".to_string(),
        "ratelimited" | "toomanyrequests" => "rateLimited".to_string(),
        "network" | "transport" | "timeout" => "network".to_string(),
        "invalidpath" => "invalidPath".to_string(),
        "unsupported" => "unsupported".to_string(),
        "provider" | "providerfailure" => "provider".to_string(),
        _ => "providerFailure".to_string(),
    }
}

fn sync_transport_result(
    endpoint_type: String,
    status_code: i32,
    classification: &str,
    should_retry: bool,
    client_action: &str,
    response: Option<Value>,
    error_message: Option<String>,
) -> BrowserStorageSyncTransportResult {
    let status_policy =
        browser_storage_sync_status_policy(classification, should_retry, client_action, 0);

    BrowserStorageSyncTransportResult {
        version: BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
        storage_schema_version: BROWSER_STORAGE_SCHEMA_VERSION,
        endpoint_type,
        status_code,
        classification: classification.to_string(),
        should_retry,
        client_action: client_action.to_string(),
        status_policy,
        response,
        error_message,
    }
}

fn browser_storage_sync_classification_retries(classification: &str) -> bool {
    matches!(
        classification,
        "transportError" | "retryableBackoff" | "serverUnavailable"
    )
}

fn default_browser_storage_sync_client_action(
    classification: &str,
    should_retry: bool,
) -> &'static str {
    match classification {
        "success" => "buildClientCyclePlan",
        "credentialsUnavailable" => "refreshCredentials",
        "authRequired" => "refreshDeviceCredentials",
        "syncPreconditionFailed" => "pullThenRetry",
        "clientUpgradeRequired" => "upgradeClient",
        "clientPlanUnavailable" => "skipCycle",
        "protocolError" | "clientRequestRejected" | "unexpectedStatus" => "discardResponse",
        _ if should_retry => "retryWithBackoff",
        _ => "skipCycle",
    }
}

fn browser_storage_sync_retry_delay_seconds(retry_attempt: u32) -> u32 {
    let multiplier = 1_u32.checked_shl(retry_attempt.min(8)).unwrap_or(256);
    BROWSER_STORAGE_SYNC_RETRY_BASE_SECONDS
        .saturating_mul(multiplier)
        .min(BROWSER_STORAGE_SYNC_RETRY_MAX_SECONDS)
}

fn browser_storage_sync_default_scheduler_action() -> String {
    "idle".to_string()
}

fn browser_storage_sync_scheduler_last_result(last_result_json: &str) -> Option<Value> {
    let value = serde_json::from_str::<Value>(last_result_json).ok()?;
    if value.is_null() {
        None
    } else {
        Some(value)
    }
}

fn browser_storage_sync_scheduler_status_name(
    snapshot: &BrowserStorageSyncSchedulerStatusSnapshot,
) -> &'static str {
    if snapshot.waiting_for_credentials {
        "waitingForCredentials"
    } else if snapshot.requires_user_action {
        "requiresUserAction"
    } else if snapshot.scheduler_action == "scheduleRetry"
        && snapshot.next_run_delay_seconds.is_some()
    {
        "retryScheduled"
    } else if snapshot.pending_run_scheduled {
        "pending"
    } else {
        "idle"
    }
}

fn browser_storage_sync_apply_issue(
    operation_index: usize,
    operation: &BrowserStorageSyncOperation,
    reason: &str,
    message: Option<String>,
) -> BrowserStorageSyncApplyResultIssue {
    BrowserStorageSyncApplyResultIssue {
        operation_index,
        statement_key: operation.statement_key.clone(),
        collection: operation.collection.clone(),
        record_type: operation.record_type.clone(),
        record_id: operation.record_id.clone(),
        reason: reason.to_string(),
        message,
    }
}

fn browser_storage_sync_mark_synced_operation(
    record: BrowserStorageSyncAckRecord,
    device_id: &str,
    synced_at: i64,
) -> Option<BrowserStorageSyncOperation> {
    let record_type = BrowserStorageSyncRecordType::parse(&record.record_type)?;
    let record_id = record_type.normalize_record_id(&record.record_id)?;
    let sync_revision = record.sync_revision.max(0);

    Some(BrowserStorageSyncOperation {
        operation_type: "markSynced".to_string(),
        statement_key: record_type.mark_synced_statement_key().to_string(),
        collection: record_type.collection().to_string(),
        record_type: Some(record_type.as_str().to_string()),
        record_id: Some(record_id.clone()),
        conflict_policy: None,
        merge_policy: None,
        params: vec![
            json!(sync_revision),
            json!(synced_at),
            json!(device_id),
            json!(record_id),
            json!(sync_revision),
        ],
    })
}

fn normalize_browser_storage_sync_ack_record(
    record: BrowserStorageSyncAckRecord,
) -> Option<BrowserStorageSyncAckRecord> {
    let record_type = BrowserStorageSyncRecordType::parse(&record.record_type)?;
    let record_id = record_type.normalize_record_id(&record.record_id)?;
    Some(BrowserStorageSyncAckRecord {
        record_type: record_type.as_str().to_string(),
        record_id,
        sync_revision: record.sync_revision.max(0),
    })
}

fn normalize_browser_storage_sync_cursor(
    cursor: BrowserStorageSyncCursorUpdate,
    fallback_synced_at: i64,
) -> Option<BrowserStorageSyncCursorUpdate> {
    let collection = normalize_sync_collection(&cursor.collection)?;
    Some(BrowserStorageSyncCursorUpdate {
        collection,
        cursor: normalize_sync_text(&cursor.cursor, "", MAX_SYNC_TEXT_LENGTH),
        last_synced_at_unix_seconds: Some(
            cursor
                .last_synced_at_unix_seconds
                .map(normalize_unix_seconds)
                .unwrap_or(fallback_synced_at),
        ),
    })
}

fn parse_browser_storage_sync_cursors(
    cursors_json: &str,
) -> Option<Vec<BrowserStorageSyncCursorUpdate>> {
    if cursors_json.trim().is_empty() {
        return Some(Vec::new());
    }
    serde_json::from_str::<Vec<BrowserStorageSyncCursorUpdate>>(cursors_json).ok()
}

fn parse_optional_browser_storage_sync_push_request(
    push_request_json: &str,
) -> Option<Option<BrowserStorageSyncPushRequest>> {
    let trimmed = push_request_json.trim();
    if trimmed.is_empty() || trimmed == "null" {
        return Some(None);
    }
    serde_json::from_str::<BrowserStorageSyncPushRequest>(trimmed)
        .ok()
        .map(Some)
}

fn parse_browser_storage_sync_remote_apply_result(
    result_json: &str,
) -> Option<BrowserStorageSyncApplyResultSummary> {
    if result_json.trim().is_empty() || result_json.trim() == "null" {
        return None;
    }
    serde_json::from_str::<BrowserStorageSyncApplyResultSummary>(result_json).ok()
}

fn normalize_sync_pull_limit(limit: u32) -> u32 {
    let max = MAX_BROWSER_STORAGE_SYNC_RECORDS as u32;
    if limit == 0 {
        DEFAULT_SYNC_PULL_LIMIT
    } else {
        limit.min(max)
    }
}

fn browser_storage_sync_cursor_operation(
    cursor: BrowserStorageSyncCursorUpdate,
    scope: &str,
    synced_at: i64,
) -> Option<BrowserStorageSyncOperation> {
    let collection = normalize_sync_collection(&cursor.collection)?;
    let cursor_value = normalize_sync_text(&cursor.cursor, "", MAX_SYNC_TEXT_LENGTH);
    let last_synced_at = cursor
        .last_synced_at_unix_seconds
        .map(normalize_unix_seconds)
        .unwrap_or(synced_at);

    Some(BrowserStorageSyncOperation {
        operation_type: "upsertCursor".to_string(),
        statement_key: "upsertSyncCursor".to_string(),
        collection,
        record_type: None,
        record_id: None,
        conflict_policy: None,
        merge_policy: None,
        params: vec![
            json!(scope),
            json!(normalize_sync_collection(&cursor.collection)?),
            json!(cursor_value),
            json!(last_synced_at),
            json!(synced_at),
        ],
    })
}

fn browser_storage_sync_server_merge_operation(
    record: BrowserStorageSyncRecord,
    scope: &str,
    device_id: &str,
) -> Option<BrowserStorageSyncOperation> {
    let record_type = record.payload.record_type();
    let deleted_at = remote_apply_deleted_at(&record);
    let operation_type = if deleted_at.is_some() {
        "mergePushedTombstone"
    } else {
        "mergePushed"
    };
    let sync_revision = record.sync_revision.max(0);
    let record_id = record.payload.record_id();
    let params = record.payload.server_merge_params(
        scope,
        device_id,
        sync_revision,
        record.updated_at_unix_seconds,
        deleted_at,
    )?;

    Some(BrowserStorageSyncOperation {
        operation_type: operation_type.to_string(),
        statement_key: record_type.server_merge_statement_key().to_string(),
        collection: record_type.collection().to_string(),
        record_type: Some(record_type.as_str().to_string()),
        record_id: Some(record_id),
        conflict_policy: None,
        merge_policy: Some(record_type.collection_merge_policy().to_string()),
        params,
    })
}

fn browser_storage_sync_ack_record_from_server_merge_operation(
    operation: &BrowserStorageSyncOperation,
    accepted_sync_revision: Option<i64>,
) -> Option<BrowserStorageSyncAckRecord> {
    let record_type = operation.record_type.as_deref()?;
    let record_id = operation.record_id.as_deref()?;
    let sync_revision = accepted_sync_revision
        .or_else(|| operation.params.get(3)?.as_i64())
        .unwrap_or_default()
        .max(0);
    normalize_browser_storage_sync_ack_record(BrowserStorageSyncAckRecord {
        record_type: record_type.to_string(),
        record_id: record_id.to_string(),
        sync_revision,
    })
}

fn browser_storage_sync_remote_apply_operation(
    record: BrowserStorageSyncRecord,
    synced_at: i64,
) -> Option<BrowserStorageSyncOperation> {
    let record_type = record.payload.record_type();
    let deleted_at = remote_apply_deleted_at(&record);
    let operation_type = if deleted_at.is_some() {
        "applyRemoteTombstone"
    } else {
        "applyRemote"
    };
    let sync_revision = record.sync_revision.max(0);
    let origin_device_id = normalize_sync_text(
        &record.origin_device_id,
        "unknown-device",
        MAX_SYNC_ID_LENGTH,
    );
    let record_id = record.payload.record_id();
    let params = record.payload.remote_apply_params(
        sync_revision,
        &origin_device_id,
        synced_at,
        deleted_at,
    )?;

    Some(BrowserStorageSyncOperation {
        operation_type: operation_type.to_string(),
        statement_key: record_type.apply_remote_statement_key().to_string(),
        collection: record_type.collection().to_string(),
        record_type: Some(record_type.as_str().to_string()),
        record_id: Some(record_id),
        conflict_policy: Some(record_type.remote_apply_conflict_policy().to_string()),
        merge_policy: Some(record_type.collection_merge_policy().to_string()),
        params,
    })
}

fn remote_apply_deleted_at(record: &BrowserStorageSyncRecord) -> Option<i64> {
    match &record.payload {
        BrowserStorageSyncPayload::Bookmark(payload) if payload.is_deleted => record
            .deleted_at_unix_seconds
            .or(Some(payload.updated_at_unix_seconds)),
        _ => record.deleted_at_unix_seconds,
    }
}

fn browser_storage_sync_bookmark_folder_depths(
    records: &[BrowserStorageSyncRecord],
) -> Vec<(String, usize)> {
    let folders = records
        .iter()
        .filter_map(|record| match &record.payload {
            BrowserStorageSyncPayload::BookmarkFolder(payload) => {
                Some((payload.id.as_str(), payload.parent_id.as_deref()))
            }
            _ => None,
        })
        .collect::<Vec<_>>();

    folders
        .iter()
        .map(|(id, _)| {
            let mut depth = 0;
            let mut current = *id;
            while let Some((_, Some(parent_id))) =
                folders.iter().find(|(folder_id, _)| *folder_id == current)
            {
                depth += 1;
                current = parent_id;
                if depth > folders.len() {
                    break;
                }
            }
            ((*id).to_string(), depth)
        })
        .collect()
}

fn browser_storage_sync_apply_order(
    record: &BrowserStorageSyncRecord,
    folder_depths: &[(String, usize)],
) -> (u8, usize, i64, String) {
    let depth = match &record.payload {
        BrowserStorageSyncPayload::BookmarkFolder(payload) => folder_depths
            .iter()
            .find_map(|(id, depth)| (id == &payload.id).then_some(*depth))
            .unwrap_or(0),
        _ => 0,
    };
    (
        record.payload.apply_collection_order(),
        depth,
        record.updated_at_unix_seconds,
        record.record_id.clone(),
    )
}

fn parse_browser_storage_sync_dirty_rows(rows_json: &str) -> Option<Vec<Value>> {
    if rows_json.trim().is_empty() {
        return Some(Vec::new());
    }
    serde_json::from_str::<Vec<Value>>(rows_json).ok()
}

fn browser_storage_sync_record_from_dirty_row(row: Value) -> Option<BrowserStorageSyncRecord> {
    let row = row.as_object()?;
    let record_type = dirty_row_string(row, "record_type");
    let payload = match BrowserStorageSyncRecordType::parse(&record_type)? {
        BrowserStorageSyncRecordType::HistoryPage => {
            BrowserStorageSyncPayload::HistoryPage(BrowserStorageSyncHistoryPagePayload {
                address: dirty_row_string(row, "address"),
                title: dirty_row_string(row, "title"),
                visit_count: dirty_row_i32(row, "visit_count"),
                last_visited_at_unix_seconds: dirty_row_i64(row, "last_visited_at"),
                created_at_unix_seconds: dirty_row_i64(row, "created_at"),
                updated_at_unix_seconds: dirty_row_i64(row, "updated_at"),
                favicon: dirty_row_optional_string(row, "favicon"),
            })
        }
        BrowserStorageSyncRecordType::HistoryVisit => {
            BrowserStorageSyncPayload::HistoryVisit(BrowserStorageSyncHistoryVisitPayload {
                id: dirty_row_string(row, "id"),
                address: dirty_row_string(row, "address"),
                title: dirty_row_string(row, "title"),
                visited_at_unix_seconds: dirty_row_i64(row, "visited_at"),
                transition: dirty_row_optional_string(row, "transition"),
            })
        }
        BrowserStorageSyncRecordType::BookmarkFolder => {
            BrowserStorageSyncPayload::BookmarkFolder(BrowserStorageSyncBookmarkFolderPayload {
                id: dirty_row_string(row, "id"),
                parent_id: dirty_row_optional_string(row, "parent_id"),
                title: dirty_row_string(row, "title"),
                sort_order: dirty_row_i32(row, "sort_order"),
                created_at_unix_seconds: dirty_row_i64(row, "created_at"),
                updated_at_unix_seconds: dirty_row_i64(row, "updated_at"),
            })
        }
        BrowserStorageSyncRecordType::Bookmark => {
            BrowserStorageSyncPayload::Bookmark(BrowserStorageSyncBookmarkPayload {
                id: dirty_row_string(row, "id"),
                folder_id: dirty_row_optional_string(row, "folder_id"),
                title: dirty_row_string(row, "title"),
                address: dirty_row_string(row, "address"),
                created_at_unix_seconds: dirty_row_i64(row, "created_at"),
                updated_at_unix_seconds: dirty_row_i64(row, "updated_at"),
                sort_order: dirty_row_i32(row, "sort_order"),
                favicon: dirty_row_optional_string(row, "favicon"),
                owner_kind: dirty_row_optional_string(row, "owner_kind")
                    .unwrap_or_else(default_bookmark_owner_kind),
                owner_id: dirty_row_optional_string(row, "owner_id").unwrap_or_default(),
                is_deleted: dirty_row_bool(row, "is_deleted"),
            })
        }
        BrowserStorageSyncRecordType::Session => {
            BrowserStorageSyncPayload::Session(BrowserStorageSyncSessionPayload {
                id: dirty_row_string(row, "id"),
                active_tab_index: dirty_row_i32(row, "active_tab_index"),
                owner_kind: dirty_row_optional_string(row, "owner_kind")
                    .unwrap_or_else(default_session_owner_kind),
                owner_id: dirty_row_optional_string(row, "owner_id").unwrap_or_default(),
                surface_kind: dirty_row_optional_string(row, "surface_kind")
                    .unwrap_or_else(default_session_surface_kind),
                surface_id: dirty_row_optional_string(row, "surface_id")
                    .unwrap_or_else(default_session_surface_id),
                created_at_unix_seconds: dirty_row_i64(row, "created_at"),
                updated_at_unix_seconds: dirty_row_i64(row, "updated_at"),
            })
        }
        BrowserStorageSyncRecordType::SessionTab => {
            BrowserStorageSyncPayload::SessionTab(BrowserStorageSyncSessionTabPayload {
                session_id: dirty_row_string(row, "session_id"),
                tab_index: dirty_row_i32(row, "tab_index"),
                tab_id: dirty_row_string(row, "tab_id"),
                title: dirty_row_string(row, "title"),
                address: dirty_row_string(row, "address"),
                created_at_unix_seconds: dirty_row_i64(row, "created_at"),
                updated_at_unix_seconds: dirty_row_i64(row, "updated_at"),
            })
        }
    };

    normalize_browser_storage_sync_record(BrowserStorageSyncRecord {
        record_id: dirty_row_string(row, "record_id"),
        sync_revision: dirty_row_i64(row, "sync_revision"),
        sync_state: dirty_row_string(row, "sync_state"),
        origin_device_id: dirty_row_string(row, "origin_device_id"),
        updated_at_unix_seconds: dirty_row_i64(row, "updated_at"),
        deleted_at_unix_seconds: dirty_row_optional_i64(row, "deleted_at"),
        payload,
    })
}

fn dirty_row_string(row: &serde_json::Map<String, Value>, key: &str) -> String {
    dirty_row_optional_string(row, key).unwrap_or_default()
}

fn dirty_row_optional_string(row: &serde_json::Map<String, Value>, key: &str) -> Option<String> {
    match row.get(key)? {
        Value::String(value) => Some(value.trim().to_string()),
        Value::Number(value) => Some(value.to_string()),
        Value::Bool(value) => Some(if *value { "1" } else { "0" }.to_string()),
        _ => None,
    }
    .filter(|value| !value.is_empty())
}

fn dirty_row_i64(row: &serde_json::Map<String, Value>, key: &str) -> i64 {
    dirty_row_optional_i64(row, key).unwrap_or(0)
}

fn dirty_row_optional_i64(row: &serde_json::Map<String, Value>, key: &str) -> Option<i64> {
    match row.get(key)? {
        Value::Number(value) => value
            .as_i64()
            .or_else(|| value.as_u64().map(|value| value as i64)),
        Value::String(value) => value.trim().parse::<i64>().ok(),
        Value::Bool(value) => Some(if *value { 1 } else { 0 }),
        _ => None,
    }
}

fn dirty_row_i32(row: &serde_json::Map<String, Value>, key: &str) -> i32 {
    dirty_row_i64(row, key).clamp(i32::MIN as i64, i32::MAX as i64) as i32
}

fn dirty_row_bool(row: &serde_json::Map<String, Value>, key: &str) -> bool {
    match row.get(key) {
        Some(Value::Bool(value)) => *value,
        Some(Value::Number(value)) => value.as_i64().unwrap_or_default() != 0,
        Some(Value::String(value)) => {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes"
            )
        }
        _ => false,
    }
}

fn normalize_browser_storage_sync_record(
    record: BrowserStorageSyncRecord,
) -> Option<BrowserStorageSyncRecord> {
    let payload = normalize_browser_storage_sync_payload(record.payload)?;
    let record_id = payload.record_id();
    let updated_at_unix_seconds = payload.updated_at_unix_seconds();

    Some(BrowserStorageSyncRecord {
        record_id,
        sync_revision: record.sync_revision.max(0),
        sync_state: normalize_sync_state(&record.sync_state),
        origin_device_id: normalize_sync_text(
            &record.origin_device_id,
            "unknown-device",
            MAX_SYNC_ID_LENGTH,
        ),
        updated_at_unix_seconds,
        deleted_at_unix_seconds: record.deleted_at_unix_seconds.map(normalize_unix_seconds),
        payload,
    })
}

fn normalize_browser_storage_sync_payload(
    payload: BrowserStorageSyncPayload,
) -> Option<BrowserStorageSyncPayload> {
    match payload {
        BrowserStorageSyncPayload::HistoryPage(payload) => {
            let address = normalize_external_address(&payload.address)?;
            let updated_at_unix_seconds = normalize_unix_seconds(payload.updated_at_unix_seconds);
            Some(BrowserStorageSyncPayload::HistoryPage(
                BrowserStorageSyncHistoryPagePayload {
                    title: normalize_title(&payload.title, &address, "Visited Page"),
                    address,
                    visit_count: payload.visit_count.max(1),
                    last_visited_at_unix_seconds: normalize_unix_seconds(
                        payload.last_visited_at_unix_seconds,
                    ),
                    created_at_unix_seconds: normalize_unix_seconds(
                        payload.created_at_unix_seconds,
                    ),
                    updated_at_unix_seconds,
                    favicon: normalize_optional_sync_text(payload.favicon, MAX_SYNC_FAVICON_LENGTH),
                },
            ))
        }
        BrowserStorageSyncPayload::HistoryVisit(payload) => {
            let id = normalize_required_sync_id(&payload.id)?;
            let address = normalize_external_address(&payload.address)?;
            Some(BrowserStorageSyncPayload::HistoryVisit(
                BrowserStorageSyncHistoryVisitPayload {
                    id,
                    title: normalize_title(&payload.title, &address, "Visited Page"),
                    address,
                    visited_at_unix_seconds: normalize_unix_seconds(
                        payload.visited_at_unix_seconds,
                    ),
                    transition: normalize_optional_sync_text(payload.transition, 64),
                },
            ))
        }
        BrowserStorageSyncPayload::BookmarkFolder(payload) => {
            let id = normalize_required_sync_id(&payload.id)?;
            let parent_id = normalize_optional_sync_id(payload.parent_id)
                .filter(|parent_id| !parent_id.eq_ignore_ascii_case(&id));
            Some(BrowserStorageSyncPayload::BookmarkFolder(
                BrowserStorageSyncBookmarkFolderPayload {
                    id,
                    parent_id,
                    title: normalize_sync_text(&payload.title, "Bookmarks", MAX_TITLE_LENGTH),
                    sort_order: payload.sort_order.max(0),
                    created_at_unix_seconds: normalize_unix_seconds(
                        payload.created_at_unix_seconds,
                    ),
                    updated_at_unix_seconds: normalize_unix_seconds(
                        payload.updated_at_unix_seconds,
                    ),
                },
            ))
        }
        BrowserStorageSyncPayload::Bookmark(payload) => {
            let id = normalize_required_sync_id(&payload.id)?;
            let address = normalize_external_address(&payload.address)?;
            let owner_kind = normalize_bookmark_owner_kind(&payload.owner_kind);
            let owner_id = normalize_bookmark_owner_id(&owner_kind, &payload.owner_id);
            Some(BrowserStorageSyncPayload::Bookmark(
                BrowserStorageSyncBookmarkPayload {
                    id,
                    folder_id: normalize_optional_sync_id(payload.folder_id),
                    title: normalize_title(&payload.title, &address, "Bookmarked Page"),
                    address,
                    created_at_unix_seconds: normalize_unix_seconds(
                        payload.created_at_unix_seconds,
                    ),
                    updated_at_unix_seconds: normalize_unix_seconds(
                        payload.updated_at_unix_seconds,
                    ),
                    sort_order: payload.sort_order.max(0),
                    favicon: normalize_optional_sync_text(payload.favicon, MAX_SYNC_FAVICON_LENGTH),
                    owner_kind,
                    owner_id,
                    is_deleted: payload.is_deleted,
                },
            ))
        }
        BrowserStorageSyncPayload::Session(payload) => {
            let id = normalize_required_sync_id(&payload.id)?;
            let owner_kind = normalize_session_owner_kind(&payload.owner_kind);
            let owner_id = normalize_session_owner_id(&owner_kind, &payload.owner_id);
            let surface_kind = normalize_session_surface_kind(&payload.surface_kind);
            let surface_id = normalize_session_surface_id(&payload.surface_id);
            Some(BrowserStorageSyncPayload::Session(
                BrowserStorageSyncSessionPayload {
                    id,
                    active_tab_index: payload.active_tab_index.max(0),
                    owner_kind,
                    owner_id,
                    surface_kind,
                    surface_id,
                    created_at_unix_seconds: normalize_unix_seconds(
                        payload.created_at_unix_seconds,
                    ),
                    updated_at_unix_seconds: normalize_unix_seconds(
                        payload.updated_at_unix_seconds,
                    ),
                },
            ))
        }
        BrowserStorageSyncPayload::SessionTab(payload) => {
            let session_id = normalize_required_sync_id(&payload.session_id)?;
            let tab_index = payload.tab_index.max(0);
            let address = normalize_session_address(&payload.address)?;
            let tab_id = normalize_session_tab_id(&payload.tab_id, tab_index as usize, &address);
            Some(BrowserStorageSyncPayload::SessionTab(
                BrowserStorageSyncSessionTabPayload {
                    session_id,
                    tab_index,
                    tab_id,
                    title: normalize_text(&payload.title, "New Tab"),
                    address,
                    created_at_unix_seconds: normalize_unix_seconds(
                        payload.created_at_unix_seconds,
                    ),
                    updated_at_unix_seconds: normalize_unix_seconds(
                        payload.updated_at_unix_seconds,
                    ),
                },
            ))
        }
    }
}

impl BrowserStorageSyncPayload {
    fn record_type(&self) -> BrowserStorageSyncRecordType {
        match self {
            BrowserStorageSyncPayload::HistoryPage(_) => BrowserStorageSyncRecordType::HistoryPage,
            BrowserStorageSyncPayload::HistoryVisit(_) => {
                BrowserStorageSyncRecordType::HistoryVisit
            }
            BrowserStorageSyncPayload::BookmarkFolder(_) => {
                BrowserStorageSyncRecordType::BookmarkFolder
            }
            BrowserStorageSyncPayload::Bookmark(_) => BrowserStorageSyncRecordType::Bookmark,
            BrowserStorageSyncPayload::Session(_) => BrowserStorageSyncRecordType::Session,
            BrowserStorageSyncPayload::SessionTab(_) => BrowserStorageSyncRecordType::SessionTab,
        }
    }

    fn record_id(&self) -> String {
        match self {
            BrowserStorageSyncPayload::HistoryPage(payload) => payload.address.clone(),
            BrowserStorageSyncPayload::HistoryVisit(payload) => payload.id.clone(),
            BrowserStorageSyncPayload::BookmarkFolder(payload) => payload.id.clone(),
            BrowserStorageSyncPayload::Bookmark(payload) => payload.id.clone(),
            BrowserStorageSyncPayload::Session(payload) => payload.id.clone(),
            BrowserStorageSyncPayload::SessionTab(payload) => {
                format!("{}:{}", payload.session_id, payload.tab_id)
            }
        }
    }

    fn updated_at_unix_seconds(&self) -> i64 {
        match self {
            BrowserStorageSyncPayload::HistoryPage(payload) => payload.updated_at_unix_seconds,
            BrowserStorageSyncPayload::HistoryVisit(payload) => payload.visited_at_unix_seconds,
            BrowserStorageSyncPayload::BookmarkFolder(payload) => payload.updated_at_unix_seconds,
            BrowserStorageSyncPayload::Bookmark(payload) => payload.updated_at_unix_seconds,
            BrowserStorageSyncPayload::Session(payload) => payload.updated_at_unix_seconds,
            BrowserStorageSyncPayload::SessionTab(payload) => payload.updated_at_unix_seconds,
        }
    }

    fn collection_order(&self) -> u8 {
        match self {
            BrowserStorageSyncPayload::HistoryPage(_) => 0,
            BrowserStorageSyncPayload::HistoryVisit(_) => 1,
            BrowserStorageSyncPayload::BookmarkFolder(_) => 2,
            BrowserStorageSyncPayload::Bookmark(_) => 3,
            BrowserStorageSyncPayload::Session(_) => 4,
            BrowserStorageSyncPayload::SessionTab(_) => 5,
        }
    }

    fn apply_collection_order(&self) -> u8 {
        match self {
            BrowserStorageSyncPayload::HistoryPage(_) => 0,
            BrowserStorageSyncPayload::BookmarkFolder(_) => 1,
            BrowserStorageSyncPayload::Session(_) => 2,
            BrowserStorageSyncPayload::HistoryVisit(_) => 3,
            BrowserStorageSyncPayload::Bookmark(_) => 4,
            BrowserStorageSyncPayload::SessionTab(_) => 5,
        }
    }

    fn remote_apply_params(
        &self,
        sync_revision: i64,
        origin_device_id: &str,
        synced_at: i64,
        deleted_at: Option<i64>,
    ) -> Option<Vec<Value>> {
        let deleted_at = deleted_at.map(normalize_unix_seconds);
        match self {
            BrowserStorageSyncPayload::HistoryPage(payload) => Some(vec![
                json!(payload.address),
                json!(payload.title),
                json!(payload.visit_count.max(1)),
                json!(payload.last_visited_at_unix_seconds),
                json!(payload.created_at_unix_seconds),
                json!(payload.updated_at_unix_seconds),
                json!(payload.favicon),
                json!(sync_revision),
                json!(origin_device_id),
                json!(synced_at),
                json!(deleted_at),
            ]),
            BrowserStorageSyncPayload::HistoryVisit(payload) => Some(vec![
                json!(payload.id),
                json!(payload.address),
                json!(payload.title),
                json!(payload.visited_at_unix_seconds),
                json!(payload.transition),
                json!(sync_revision),
                json!(origin_device_id),
                json!(synced_at),
                json!(deleted_at),
            ]),
            BrowserStorageSyncPayload::BookmarkFolder(payload) => Some(vec![
                json!(payload.id),
                json!(payload.parent_id),
                json!(payload.title),
                json!(payload.sort_order.max(0)),
                json!(payload.created_at_unix_seconds),
                json!(payload.updated_at_unix_seconds),
                json!(sync_revision),
                json!(origin_device_id),
                json!(synced_at),
                json!(deleted_at),
            ]),
            BrowserStorageSyncPayload::Bookmark(payload) => Some(vec![
                json!(payload.id),
                json!(payload.folder_id),
                json!(payload.title),
                json!(payload.address),
                json!(payload.created_at_unix_seconds),
                json!(payload.updated_at_unix_seconds),
                json!(payload.sort_order.max(0)),
                json!(payload.favicon),
                json!(payload.owner_kind),
                json!(payload.owner_id),
                json!(if deleted_at.is_some() || payload.is_deleted {
                    1
                } else {
                    0
                }),
                json!(sync_revision),
                json!(origin_device_id),
                json!(synced_at),
                json!(deleted_at),
            ]),
            BrowserStorageSyncPayload::Session(payload) => Some(vec![
                json!(payload.id),
                json!(payload.active_tab_index.max(0)),
                json!(payload.owner_kind),
                json!(payload.owner_id),
                json!(payload.surface_kind),
                json!(payload.surface_id),
                json!(payload.created_at_unix_seconds),
                json!(payload.updated_at_unix_seconds),
                json!(sync_revision),
                json!(origin_device_id),
                json!(synced_at),
                json!(deleted_at),
            ]),
            BrowserStorageSyncPayload::SessionTab(payload) => Some(vec![
                json!(payload.session_id),
                json!(payload.tab_index.max(0)),
                json!(payload.tab_id),
                json!(payload.title),
                json!(payload.address),
                json!(payload.created_at_unix_seconds),
                json!(payload.updated_at_unix_seconds),
                json!(sync_revision),
                json!(origin_device_id),
                json!(synced_at),
                json!(deleted_at),
            ]),
        }
    }

    fn server_merge_params(
        &self,
        scope: &str,
        device_id: &str,
        sync_revision: i64,
        updated_at: i64,
        deleted_at: Option<i64>,
    ) -> Option<Vec<Value>> {
        let deleted_at = deleted_at.map(normalize_unix_seconds);
        let common = |identity: String| {
            vec![
                json!(scope),
                json!(device_id),
                json!(identity),
                json!(sync_revision.max(0)),
                json!(normalize_unix_seconds(updated_at)),
                json!(deleted_at),
            ]
        };

        match self {
            BrowserStorageSyncPayload::HistoryPage(payload) => {
                let mut params = common(payload.address.clone());
                params.extend([
                    json!(payload.title),
                    json!(payload.visit_count.max(1)),
                    json!(payload.last_visited_at_unix_seconds),
                    json!(payload.created_at_unix_seconds),
                    json!(payload.favicon),
                ]);
                Some(params)
            }
            BrowserStorageSyncPayload::HistoryVisit(payload) => {
                let mut params = common(payload.id.clone());
                params.extend([
                    json!(payload.address),
                    json!(payload.title),
                    json!(payload.visited_at_unix_seconds),
                    json!(payload.transition),
                ]);
                Some(params)
            }
            BrowserStorageSyncPayload::BookmarkFolder(payload) => {
                let mut params = common(payload.id.clone());
                params.extend([
                    json!(payload.parent_id),
                    json!(payload.title),
                    json!(payload.sort_order.max(0)),
                    json!(payload.created_at_unix_seconds),
                ]);
                Some(params)
            }
            BrowserStorageSyncPayload::Bookmark(payload) => {
                let mut params = common(payload.id.clone());
                params.extend([
                    json!(payload.folder_id),
                    json!(payload.title),
                    json!(payload.address),
                    json!(payload.created_at_unix_seconds),
                    json!(payload.sort_order.max(0)),
                    json!(payload.favicon),
                    json!(payload.owner_kind),
                    json!(payload.owner_id),
                    json!(if deleted_at.is_some() || payload.is_deleted {
                        1
                    } else {
                        0
                    }),
                ]);
                Some(params)
            }
            BrowserStorageSyncPayload::Session(payload) => {
                let mut params = common(payload.id.clone());
                params.extend([
                    json!(payload.active_tab_index.max(0)),
                    json!(payload.owner_kind),
                    json!(payload.owner_id),
                    json!(payload.surface_kind),
                    json!(payload.surface_id),
                    json!(payload.created_at_unix_seconds),
                ]);
                Some(params)
            }
            BrowserStorageSyncPayload::SessionTab(payload) => {
                let mut params = common(format!("{}:{}", payload.session_id, payload.tab_id));
                params.extend([
                    json!(payload.session_id),
                    json!(payload.tab_index.max(0)),
                    json!(payload.tab_id),
                    json!(payload.title),
                    json!(payload.address),
                    json!(payload.created_at_unix_seconds),
                ]);
                Some(params)
            }
        }
    }
}

