fn parse_browser_storage_session_active_tab_session_input(
    value: &Value,
    deleted_from_record: bool,
) -> Option<BrowserStorageSessionActiveTabConsistencySession> {
    let session_id = normalize_required_sync_id(&browser_storage_value_string(
        value,
        &["id", "sessionId", "session_id"],
    )?)?;
    let previous_active_tab_index = normalize_browser_storage_tab_index(browser_storage_value_i64(
        value,
        &["activeTabIndex", "active_tab_index", "index"],
    ));
    let owner_kind = normalize_session_owner_kind(
        &browser_storage_value_string(value, &["ownerKind", "owner_kind"]).unwrap_or_default(),
    );
    let owner_id = normalize_session_owner_id(
        &owner_kind,
        &browser_storage_value_string(value, &["ownerId", "owner_id"]).unwrap_or_default(),
    );
    let surface_kind = normalize_session_surface_kind(
        &browser_storage_value_string(value, &["surfaceKind", "surface_kind"]).unwrap_or_default(),
    );
    let surface_id = normalize_session_surface_id(
        &browser_storage_value_string(value, &["surfaceId", "surface_id"]).unwrap_or_default(),
    );

    Some(BrowserStorageSessionActiveTabConsistencySession {
        session_id,
        previous_active_tab_index,
        active_tab_index: previous_active_tab_index,
        active_tab_id: None,
        active_tab_count: 0,
        ordered_tab_ids: Vec::new(),
        owner_kind,
        owner_id,
        surface_kind,
        surface_id,
        created_at_unix_seconds: normalize_unix_seconds(
            browser_storage_value_i64(
                value,
                &[
                    "createdAtUnixSeconds",
                    "created_at_unix_seconds",
                    "createdAt",
                    "created_at",
                ],
            )
            .unwrap_or(0),
        ),
        updated_at_unix_seconds: normalize_unix_seconds(
            browser_storage_value_i64(
                value,
                &[
                    "updatedAtUnixSeconds",
                    "updated_at_unix_seconds",
                    "updatedAt",
                    "updated_at",
                ],
            )
            .unwrap_or(0),
        ),
        deleted: deleted_from_record || browser_storage_value_deleted(value),
        consistency_action: "pending".to_string(),
        consistency_reason: "pending".to_string(),
    })
}

fn browser_storage_session_active_tab_consistency_apply(
    session: &mut BrowserStorageSessionActiveTabConsistencySession,
    ordered_tab_ids: Vec<String>,
) {
    if session.deleted {
        session.active_tab_index = 0;
        session.active_tab_id = None;
        session.active_tab_count = 0;
        session.ordered_tab_ids = Vec::new();
        session.consistency_action = "ignoredDeletedSession".to_string();
        session.consistency_reason = "sessionTombstonePreserved".to_string();
        return;
    }

    session.active_tab_count = ordered_tab_ids.len();
    session.ordered_tab_ids = ordered_tab_ids;
    if session.ordered_tab_ids.is_empty() {
        session.active_tab_index = 0;
        session.active_tab_id = None;
        session.consistency_action = if session.previous_active_tab_index == 0 {
            "emptySession".to_string()
        } else {
            "clampedEmptySession".to_string()
        };
        session.consistency_reason = "activeSessionHasNoTabs".to_string();
        return;
    }

    let max_index = (session.ordered_tab_ids.len() - 1).min(i32::MAX as usize) as i32;
    let active_tab_index = session.previous_active_tab_index.clamp(0, max_index);
    session.active_tab_index = active_tab_index;
    session.active_tab_id = session
        .ordered_tab_ids
        .get(active_tab_index as usize)
        .cloned();
    session.consistency_action = if active_tab_index == session.previous_active_tab_index {
        "alreadyConsistent".to_string()
    } else {
        "clampedToAvailableTabs".to_string()
    };
    session.consistency_reason = if active_tab_index == session.previous_active_tab_index {
        "activeTabIndexWithinRange".to_string()
    } else {
        "activeTabIndexOutOfRange".to_string()
    };
}

