    #[test]
    fn browser_storage_bookmark_restore_placement_resolves_delete_restore_state_by_timestamp() {
        let plan = serde_json::from_str::<Value>(
            &browser_storage_bookmark_restore_placement_plan_json(
                r#"{
                    "folders": [{"id":"root","parentId":null}],
                    "currentBookmarks": [
                        {"id":"keep-active","folderId":"root","title":"Active","address":"https://example.com/active","createdAtUnixSeconds":1,"updatedAtUnixSeconds":30},
                        {"id":"delete-newer","folderId":"root","title":"Will Delete","address":"https://example.com/delete","createdAtUnixSeconds":1,"updatedAtUnixSeconds":10}
                    ],
                    "candidateBookmarks": [
                        {"id":"keep-active","folderId":"root","title":"Old Delete","address":"https://example.com/active","createdAtUnixSeconds":1,"updatedAtUnixSeconds":5,"deletedAtUnixSeconds":12},
                        {"id":"delete-newer","folderId":"root","title":"Deleted","address":"https://example.com/delete","createdAtUnixSeconds":1,"updatedAtUnixSeconds":20,"deletedAtUnixSeconds":40}
                    ]
                }"#,
            ),
        )
        .unwrap();

        assert_eq!(plan["activeBookmarkCount"], json!(1));
        assert_eq!(plan["stateConflictCount"], json!(2));
        assert_eq!(plan["staleBookmarkUpdateCount"], json!(1));
        assert_eq!(plan["stateConflicts"].as_array().unwrap().len(), 2);
        assert_eq!(
            plan["stateConflictSummary"]["summaryAction"],
            json!("mixedStateWins")
        );
        assert_eq!(
            plan["stateConflictSummary"]["summaryReason"],
            json!("mixedDeleteRestoreStateTimestamps")
        );
        assert_eq!(plan["stateConflictSummary"]["conflictCount"], json!(2));
        assert_eq!(plan["stateConflictSummary"]["activeWinnerCount"], json!(1));
        assert_eq!(plan["stateConflictSummary"]["deletedWinnerCount"], json!(1));
        assert_eq!(
            plan["stateConflictSummary"]["staleDeleteIgnoredCount"],
            json!(1)
        );
        assert_eq!(
            plan["stateConflictSummary"]["staleRestoreIgnoredCount"],
            json!(1)
        );
        assert_eq!(plan["stateConflictSummary"]["timestampTieCount"], json!(0));
        assert_eq!(
            plan["stateConflictSummary"]["affectedBookmarkIds"],
            json!(["delete-newer", "keep-active"])
        );
        assert_eq!(
            plan["stateConflictSummary"]["activeWinnerBookmarkIds"],
            json!(["keep-active"])
        );
        assert_eq!(
            plan["stateConflictSummary"]["deletedWinnerBookmarkIds"],
            json!(["delete-newer"])
        );
        assert_eq!(
            plan["stateConflictSummary"]["timestampTieBookmarkIds"],
            json!([])
        );

        let bookmarks = plan["normalizedBookmarks"].as_array().unwrap();
        let keep_active = bookmarks
            .iter()
            .find(|bookmark| bookmark["id"] == json!("keep-active"))
            .unwrap();
        let delete_newer = bookmarks
            .iter()
            .find(|bookmark| bookmark["id"] == json!("delete-newer"))
            .unwrap();
        assert_eq!(keep_active["deleted"], json!(false));
        assert_eq!(
            keep_active["stateConflictAction"],
            json!("staleDeleteIgnored")
        );
        assert_eq!(
            keep_active["stateConflictReason"],
            json!("olderDeleteStateTimestampIgnored")
        );
        assert_eq!(delete_newer["deleted"], json!(true));
        assert_eq!(delete_newer["deletedAtUnixSeconds"], json!(40));
        assert_eq!(
            delete_newer["stateConflictAction"],
            json!("newerDeleteWins")
        );
        assert_eq!(
            delete_newer["stateConflictReason"],
            json!("newerDeleteStateTimestamp")
        );

        let conflicts = plan["stateConflicts"].as_array().unwrap();
        let keep_active_conflict = conflicts
            .iter()
            .find(|conflict| conflict["bookmarkId"] == json!("keep-active"))
            .unwrap();
        let delete_newer_conflict = conflicts
            .iter()
            .find(|conflict| conflict["bookmarkId"] == json!("delete-newer"))
            .unwrap();
        assert_eq!(keep_active_conflict["action"], json!("staleDeleteIgnored"));
        assert_eq!(keep_active_conflict["timestampTie"], json!(false));
        assert_eq!(keep_active_conflict["winningDeleted"], json!(false));
        assert_eq!(keep_active_conflict["ignoredDeleted"], json!(true));
        assert_eq!(
            keep_active_conflict["winningStateTimestampUnixSeconds"],
            json!(30)
        );
        assert_eq!(
            keep_active_conflict["ignoredStateTimestampUnixSeconds"],
            json!(12)
        );
        assert_eq!(delete_newer_conflict["action"], json!("newerDeleteWins"));
        assert_eq!(delete_newer_conflict["timestampTie"], json!(false));
        assert_eq!(delete_newer_conflict["winningDeleted"], json!(true));
        assert_eq!(delete_newer_conflict["ignoredDeleted"], json!(false));
        assert_eq!(
            delete_newer_conflict["winningStateTimestampUnixSeconds"],
            json!(40)
        );
        assert_eq!(
            delete_newer_conflict["ignoredStateTimestampUnixSeconds"],
            json!(10)
        );
    }

