    #[test]
    fn browser_storage_bookmark_ownership_handles_tab_only_and_deleted_only_addresses() {
        let plan = serde_json::from_str::<Value>(&browser_storage_bookmark_ownership_plan_json(
            r#"[
                {"id":"tab-newer","title":"New","address":"https://example.com/tab","ownerKind":"tab","ownerId":"tab-b","createdAtUnixSeconds":2,"updatedAtUnixSeconds":30},
                {"id":"tab-older","title":"Old","address":"https://example.com/tab","ownerKind":"tab","ownerId":"tab-a","createdAtUnixSeconds":1,"updatedAtUnixSeconds":10},
                {"id":"deleted-only","title":"Gone","address":"https://example.com/gone","ownerKind":"user","createdAtUnixSeconds":1,"updatedAtUnixSeconds":5,"deletedAtUnixSeconds":6}
            ]"#,
        ))
        .unwrap();

        assert_eq!(plan["classification"], json!("deduplicatedWithTombstones"));
        assert_eq!(
            plan["ownershipSummary"]["summaryAction"],
            json!("deduplicatedWithTombstones")
        );
        assert_eq!(
            plan["ownershipSummary"]["summaryReason"],
            json!("duplicateAddressesAndTombstones")
        );
        assert_eq!(plan["ownershipSummary"]["addressCount"], json!(2));
        assert_eq!(plan["ownershipSummary"]["retainedAddressCount"], json!(1));
        assert_eq!(
            plan["ownershipSummary"]["tombstoneOnlyAddressCount"],
            json!(1)
        );
        assert_eq!(
            plan["ownershipSummary"]["newestUpdatedAtWinCount"],
            json!(1)
        );
        assert_eq!(
            plan["ownershipSummary"]["tabOwnedRetainedBookmarkIds"],
            json!(["tab-newer"])
        );
        assert_eq!(
            plan["ownershipSummary"]["tombstoneOnlyBookmarkIds"],
            json!(["deleted-only"])
        );
        assert_eq!(plan["tabOwnedRetainedCount"], json!(1));
        assert_eq!(plan["tombstoneAddressCount"], json!(1));
        let tab_decision = plan["addressDecisions"]
            .as_array()
            .unwrap()
            .iter()
            .find(|decision| decision["address"] == json!("https://example.com/tab"))
            .unwrap();
        assert_eq!(tab_decision["retainedBookmarkId"], json!("tab-newer"));
        assert_eq!(tab_decision["retentionReason"], json!("newestUpdatedAt"));
        assert_eq!(tab_decision["suppressedBookmarkIds"], json!(["tab-older"]));
        assert_eq!(tab_decision["duplicateCount"], json!(1));
        let deleted_decision = plan["addressDecisions"]
            .as_array()
            .unwrap()
            .iter()
            .find(|decision| decision["address"] == json!("https://example.com/gone"))
            .unwrap();
        assert_eq!(deleted_decision["action"], json!("tombstoneAddress"));
        assert_eq!(deleted_decision["retainedBookmarkId"], Value::Null);
        assert_eq!(deleted_decision["retentionReason"], json!("tombstoneOnly"));
        assert_eq!(deleted_decision["suppressedBookmarkIds"], json!([]));
    }

    #[test]
    fn browser_storage_bookmark_ownership_explains_same_priority_tie_breakers() {
        let plan = serde_json::from_str::<Value>(&browser_storage_bookmark_ownership_plan_json(
            r#"[
                {"id":"tab-created-a","title":"Created A","address":"https://example.com/created","ownerKind":"tab","ownerId":"tab-a","createdAtUnixSeconds":2,"updatedAtUnixSeconds":50},
                {"id":"tab-created-b","title":"Created B","address":"https://example.com/created","ownerKind":"tab","ownerId":"tab-b","createdAtUnixSeconds":1,"updatedAtUnixSeconds":50},
                {"id":"tab-a","title":"A","address":"https://example.com/id","ownerKind":"tab","ownerId":"tab-a","createdAtUnixSeconds":1,"updatedAtUnixSeconds":20},
                {"id":"tab-b","title":"B","address":"https://example.com/id","ownerKind":"tab","ownerId":"tab-b","createdAtUnixSeconds":1,"updatedAtUnixSeconds":20}
            ]"#,
        ))
        .unwrap();

        assert_eq!(plan["classification"], json!("deduplicated"));
        let decisions = plan["addressDecisions"].as_array().unwrap();
        let created_decision = decisions
            .iter()
            .find(|decision| decision["address"] == json!("https://example.com/created"))
            .unwrap();
        let id_decision = decisions
            .iter()
            .find(|decision| decision["address"] == json!("https://example.com/id"))
            .unwrap();
        assert_eq!(
            created_decision["retainedBookmarkId"],
            json!("tab-created-b")
        );
        assert_eq!(
            created_decision["retentionReason"],
            json!("earliestCreatedAt")
        );
        assert_eq!(
            created_decision["suppressedBookmarkIds"],
            json!(["tab-created-a"])
        );
        assert_eq!(id_decision["retainedBookmarkId"], json!("tab-a"));
        assert_eq!(id_decision["retentionReason"], json!("bookmarkIdTieBreak"));
        assert_eq!(id_decision["suppressedBookmarkIds"], json!(["tab-b"]));
        assert_eq!(
            plan["ownershipSummary"]["earliestCreatedAtTieBreakCount"],
            json!(1)
        );
        assert_eq!(
            plan["ownershipSummary"]["bookmarkIdTieBreakCount"],
            json!(1)
        );
        assert_eq!(
            plan["ownershipSummary"]["tieBreakBookmarkIds"],
            json!(["tab-a", "tab-created-b"])
        );
    }

    #[test]
    fn browser_storage_bookmark_ownership_accepts_sync_records_and_overlays_ids() {
        let plan = serde_json::from_str::<Value>(&browser_storage_bookmark_ownership_plan_json(
            r#"{"records":[
                {"recordType":"bookmark","payload":{"id":"bookmark-a","title":"Old","address":"https://example.com/a","ownerKind":"tab","ownerId":"tab-a","createdAtUnixSeconds":1,"updatedAtUnixSeconds":2}},
                {"recordType":"bookmark","payload":{"id":"bookmark-a","title":"New","address":"https://example.com/a","ownerKind":"tab","ownerId":"tab-a","createdAtUnixSeconds":1,"updatedAtUnixSeconds":3}},
                {"recordType":"bookmark","deletedAtUnixSeconds":8,"payload":{"id":"bookmark-b","title":"Gone","address":"https://example.com/b","ownerKind":"tab","ownerId":"tab-b","createdAtUnixSeconds":4,"updatedAtUnixSeconds":5}},
                {"recordType":"historyPage","payload":{"address":"https://example.com/ignored","title":"Ignored"}}
            ]}"#,
        ))
        .unwrap();

        assert_eq!(plan["classification"], json!("retainedWithTombstones"));
        assert_eq!(plan["normalizedBookmarkCount"], json!(2));
        assert_eq!(plan["retainedBookmarkCount"], json!(1));
        let retained = plan["normalizedBookmarks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|bookmark| bookmark["id"] == json!("bookmark-a"))
            .unwrap();
        assert_eq!(retained["title"], json!("New"));
        assert_eq!(retained["updatedAtUnixSeconds"], json!(3));
        assert_eq!(retained["ownershipAction"], json!("retainTabOwned"));
        let deleted = plan["normalizedBookmarks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|bookmark| bookmark["id"] == json!("bookmark-b"))
            .unwrap();
        assert_eq!(deleted["deleted"], json!(true));
        assert_eq!(deleted["reason"], json!("addressTombstoned"));
    }

