    #[test]
    fn browser_storage_session_active_tab_consistency_respects_tombstones() {
        let plan = serde_json::from_str::<Value>(
            &browser_storage_session_active_tab_consistency_plan_json(
                r#"{
                    "sessions": [
                        {"id":"session-a","activeTabIndex":1},
                        {"id":"session-b","activeTabIndex":1,"deletedAtUnixSeconds":10}
                    ],
                    "sessionTabs": [
                        {"sessionId":"session-a","tabId":"tab-a","tabIndex":0,"title":"A","address":"https://example.com/a"},
                        {"sessionId":"session-a","tabId":"tab-b","tabIndex":1,"title":"B","address":"https://example.com/b","deletedAtUnixSeconds":11},
                        {"sessionId":"session-b","tabId":"tab-c","tabIndex":0,"title":"C","address":"https://example.com/c"}
                    ]
                }"#,
            ),
        )
        .unwrap();
        assert_eq!(plan["classification"], json!("adjusted"));
        assert_eq!(plan["activeSessionCount"], json!(1));
        assert_eq!(plan["adjustedSessionCount"], json!(1));
        assert_eq!(
            plan["consistencySummary"]["summaryAction"],
            json!("clamped")
        );
        assert_eq!(
            plan["consistencySummary"]["tombstoneSessionCount"],
            json!(1)
        );
        assert_eq!(plan["consistencySummary"]["clampedSessionCount"], json!(1));
        assert_eq!(
            plan["consistencySummary"]["tombstoneSessionIds"],
            json!(["session-b"])
        );
        assert_eq!(
            plan["normalizedSessions"][0]["sessionId"],
            json!("session-a")
        );
        assert_eq!(plan["normalizedSessions"][0]["activeTabIndex"], json!(0));
        assert_eq!(plan["normalizedSessions"][0]["activeTabId"], json!("tab-a"));
        assert_eq!(plan["normalizedSessions"][1]["deleted"], json!(true));
        assert_eq!(
            plan["normalizedSessions"][1]["consistencyAction"],
            json!("ignoredDeletedSession")
        );
        assert_eq!(
            plan["normalizedSessions"][1]["consistencyReason"],
            json!("sessionTombstonePreserved")
        );
        assert_eq!(plan["normalizedSessions"][1]["orderedTabIds"], json!([]));

        let tombstone_only = serde_json::from_str::<Value>(
            &browser_storage_session_active_tab_consistency_plan_json(
                r#"{"sessions":[{"id":"session-gone","activeTabIndex":1,"deletedAtUnixSeconds":10}]}"#,
            ),
        )
        .unwrap();
        assert_eq!(tombstone_only["classification"], json!("empty"));
        assert_eq!(
            tombstone_only["consistencySummary"]["summaryAction"],
            json!("tombstoneOnly")
        );
        assert_eq!(
            tombstone_only["consistencySummary"]["summaryReason"],
            json!("allSessionsDeleted")
        );
        assert_eq!(
            tombstone_only["consistencySummary"]["tombstoneSessionIds"],
            json!(["session-gone"])
        );
    }

