    #[test]
    fn browser_storage_retention_pruning_prunes_history_overflow_and_visits() {
        let plan = serde_json::from_str::<Value>(&browser_storage_retention_pruning_plan_json(
            r#"{
                "maxHistoryPages": 2,
                "historyPages": [
                    {"address":"https://example.com/old","title":"Old","visitCount":3,"lastVisitedAtUnixSeconds":10,"createdAtUnixSeconds":1,"updatedAtUnixSeconds":10},
                    {"address":"https://example.com/mid","title":"Mid","visitCount":2,"lastVisitedAtUnixSeconds":20,"createdAtUnixSeconds":2,"updatedAtUnixSeconds":20},
                    {"address":"https://example.com/new","title":"New","visitCount":1,"lastVisitedAtUnixSeconds":30,"createdAtUnixSeconds":3,"updatedAtUnixSeconds":30},
                    {"address":"https://example.com/deleted","title":"Deleted","visitCount":1,"lastVisitedAtUnixSeconds":40,"deletedAtUnixSeconds":50}
                ],
                "historyVisits": [
                    {"id":"visit-old","address":"https://example.com/old","title":"Old","visitedAtUnixSeconds":11},
                    {"id":"visit-new","address":"https://example.com/new","title":"New","visitedAtUnixSeconds":31},
                    {"id":"visit-deleted","address":"https://example.com/old","title":"Gone","visitedAtUnixSeconds":12,"deletedAtUnixSeconds":13}
                ]
            }"#,
        ))
        .unwrap();

        assert_eq!(plan["classification"], json!("pruneHistory"));
        assert_eq!(plan["activeHistoryPageCount"], json!(3));
        assert_eq!(plan["prunedHistoryPageCount"], json!(1));
        assert_eq!(plan["activeHistoryVisitCount"], json!(2));
        assert_eq!(plan["prunedHistoryVisitCount"], json!(1));
        assert_eq!(
            plan["retentionSummary"]["summaryAction"],
            json!("pruneHistory")
        );
        assert_eq!(
            plan["retentionSummary"]["summaryReason"],
            json!("historyLimitsExceeded")
        );
        assert_eq!(
            plan["retentionSummary"]["normalizedHistoryPageCount"],
            json!(4)
        );
        assert_eq!(
            plan["retentionSummary"]["tombstoneHistoryPageCount"],
            json!(1)
        );
        assert_eq!(
            plan["retentionSummary"]["prunedHistoryPageAddresses"],
            json!(["https://example.com/old"])
        );
        assert_eq!(
            plan["retentionSummary"]["keptHistoryPageAddresses"],
            json!(["https://example.com/mid", "https://example.com/new"])
        );
        assert_eq!(
            plan["retentionSummary"]["tombstoneHistoryPageAddresses"],
            json!(["https://example.com/deleted"])
        );
        assert_eq!(
            plan["retentionSummary"]["prunedHistoryVisitIds"],
            json!(["visit-old"])
        );
        assert_eq!(
            plan["retentionSummary"]["tombstoneHistoryVisitIds"],
            json!(["visit-deleted"])
        );
        assert_eq!(plan["retentionSummary"]["pruneOperationCount"], json!(2));

        let pages = plan["normalizedHistoryPages"].as_array().unwrap();
        let old_page = pages
            .iter()
            .find(|page| page["address"] == json!("https://example.com/old"))
            .unwrap();
        assert_eq!(
            old_page["retentionAction"],
            json!("pruneHistoryPageOverflow")
        );
        assert_eq!(
            old_page["retentionReason"],
            json!("historyPageLimitExceeded")
        );
        let deleted_page = pages
            .iter()
            .find(|page| page["address"] == json!("https://example.com/deleted"))
            .unwrap();
        assert_eq!(deleted_page["retentionAction"], json!("preserveTombstone"));
        assert_eq!(deleted_page["retentionReason"], json!("tombstonePreserved"));

        let visits = plan["normalizedHistoryVisits"].as_array().unwrap();
        let old_visit = visits
            .iter()
            .find(|visit| visit["id"] == json!("visit-old"))
            .unwrap();
        assert_eq!(old_visit["retentionAction"], json!("pruneWithHistoryPage"));
        assert_eq!(
            old_visit["retentionReason"],
            json!("parentHistoryPagePruned")
        );
        let deleted_visit = visits
            .iter()
            .find(|visit| visit["id"] == json!("visit-deleted"))
            .unwrap();
        assert_eq!(deleted_visit["retentionAction"], json!("preserveTombstone"));
        assert_eq!(
            deleted_visit["retentionReason"],
            json!("tombstonePreserved")
        );
    }

    #[test]
    fn browser_storage_retention_pruning_applies_per_origin_device_history_windows() {
        let plan = serde_json::from_str::<Value>(&browser_storage_retention_pruning_plan_json(
            r#"{
                "maxHistoryPages": 10,
                "maxHistoryPagesPerOriginDevice": {
                    "device-a": 2,
                    "device-b": 1
                },
                "records": [
                    {"recordType":"historyPage","recordId":"https://example.com/a-old","syncRevision":1,"syncState":"remote","originDeviceId":"device-a","updatedAtUnixSeconds":10,"payload":{"address":"https://example.com/a-old","title":"A Old","visitCount":1,"lastVisitedAtUnixSeconds":10,"createdAtUnixSeconds":1,"updatedAtUnixSeconds":10}},
                    {"recordType":"historyPage","recordId":"https://example.com/a-mid","syncRevision":2,"syncState":"remote","originDeviceId":"device-a","updatedAtUnixSeconds":20,"payload":{"address":"https://example.com/a-mid","title":"A Mid","visitCount":1,"lastVisitedAtUnixSeconds":20,"createdAtUnixSeconds":2,"updatedAtUnixSeconds":20}},
                    {"recordType":"historyPage","recordId":"https://example.com/a-new","syncRevision":3,"syncState":"remote","originDeviceId":"device-a","updatedAtUnixSeconds":30,"payload":{"address":"https://example.com/a-new","title":"A New","visitCount":1,"lastVisitedAtUnixSeconds":30,"createdAtUnixSeconds":3,"updatedAtUnixSeconds":30}},
                    {"recordType":"historyPage","recordId":"https://example.com/b-old","syncRevision":4,"syncState":"remote","originDeviceId":"device-b","updatedAtUnixSeconds":15,"payload":{"address":"https://example.com/b-old","title":"B Old","visitCount":1,"lastVisitedAtUnixSeconds":15,"createdAtUnixSeconds":4,"updatedAtUnixSeconds":15}},
                    {"recordType":"historyPage","recordId":"https://example.com/b-new","syncRevision":5,"syncState":"remote","originDeviceId":"device-b","updatedAtUnixSeconds":25,"payload":{"address":"https://example.com/b-new","title":"B New","visitCount":1,"lastVisitedAtUnixSeconds":25,"createdAtUnixSeconds":5,"updatedAtUnixSeconds":25}},
                    {"recordType":"historyPage","recordId":"https://example.com/legacy","syncRevision":6,"syncState":"remote","originDeviceId":"","updatedAtUnixSeconds":5,"payload":{"address":"https://example.com/legacy","title":"Legacy","visitCount":1,"lastVisitedAtUnixSeconds":5,"createdAtUnixSeconds":6,"updatedAtUnixSeconds":5}},
                    {"recordType":"historyVisit","recordId":"visit-a-old","syncRevision":7,"syncState":"remote","originDeviceId":"device-a","updatedAtUnixSeconds":11,"payload":{"id":"visit-a-old","address":"https://example.com/a-old","title":"A Old","visitedAtUnixSeconds":11}},
                    {"recordType":"historyVisit","recordId":"visit-b-old","syncRevision":8,"syncState":"remote","originDeviceId":"device-b","updatedAtUnixSeconds":16,"payload":{"id":"visit-b-old","address":"https://example.com/b-old","title":"B Old","visitedAtUnixSeconds":16}}
                ]
            }"#,
        ))
        .unwrap();

        assert_eq!(plan["classification"], json!("pruneHistory"));
        assert_eq!(plan["maxHistoryPagesPerOriginDevice"]["device-a"], json!(2));
        assert_eq!(plan["maxHistoryPagesPerOriginDevice"]["device-b"], json!(1));
        assert_eq!(plan["prunedHistoryPageCount"], json!(2));
        assert_eq!(plan["prunedHistoryVisitCount"], json!(2));

        let pages = plan["normalizedHistoryPages"].as_array().unwrap();
        let a_old = pages
            .iter()
            .find(|page| page["address"] == json!("https://example.com/a-old"))
            .unwrap();
        let b_old = pages
            .iter()
            .find(|page| page["address"] == json!("https://example.com/b-old"))
            .unwrap();
        let legacy = pages
            .iter()
            .find(|page| page["address"] == json!("https://example.com/legacy"))
            .unwrap();
        assert_eq!(a_old["originDeviceId"], json!("device-a"));
        assert_eq!(
            a_old["retentionAction"],
            json!("pruneOriginDeviceHistoryPageOverflow")
        );
        assert_eq!(
            a_old["retentionReason"],
            json!("originDeviceHistoryPageLimitExceeded")
        );
        assert_eq!(
            b_old["retentionAction"],
            json!("pruneOriginDeviceHistoryPageOverflow")
        );
        assert_eq!(legacy["retentionAction"], json!("keep"));
        assert_eq!(legacy["retentionReason"], json!("withinHistoryPageLimits"));

        assert!(plan["pruneOperations"]
            .as_array()
            .unwrap()
            .iter()
            .any(|operation| {
                operation["recordId"] == json!("https://example.com/a-old")
                    && operation["reason"] == json!("originDeviceHistoryPageLimitExceeded")
            }));
        assert!(plan["normalizedHistoryVisits"]
            .as_array()
            .unwrap()
            .iter()
            .all(|visit| visit["retentionAction"] == json!("pruneWithHistoryPage")));
    }

    #[test]
