    #[test]
    fn rejects_non_authority_external_addresses() {
        let history = r#"{
            "version": 1,
            "items": [
                {"title":"Bad","address":"http:example.com","visitedAtUnixSeconds":1,"visitCount":1},
                {"title":"Good","address":"https://example.com","visitedAtUnixSeconds":2,"visitCount":1}
            ]
        }"#;
        let normalized = serde_json::from_str::<BrowserHistorySnapshot>(
            &normalize_history_snapshot_json(history),
        )
        .unwrap();

        assert_eq!(normalized.items.len(), 1);
        assert_eq!(normalized.items[0].address, "https://example.com/");

        let session = r#"{
            "version": 1,
            "activeTabIndex": 0,
            "tabs": [
                {"title":"Bad","address":"file:relative"},
                {"title":"Blank","address":"about:blank"}
            ]
        }"#;
        let normalized = serde_json::from_str::<BrowserSessionSnapshot>(
            &normalize_session_snapshot_json(session),
        )
        .unwrap();

        assert_eq!(normalized.tabs.len(), 1);
        assert_eq!(normalized.tabs[0].address, "about:blank");
    }

