    #[test]
    fn browser_storage_schema_migration_plan_matches_base_schema() {
        let normalize = |sql: &str| sql.split_whitespace().collect::<Vec<_>>().join(" ");

        let plan = browser_storage_schema_migration_plan();
        assert_eq!(plan.schema_version, BROWSER_STORAGE_SCHEMA_VERSION);
        assert!(!plan.add_columns.is_empty());
        assert!(!plan.idempotent_statements.is_empty());

        // The legacy tab_id backfill must run before every other addition so
        // migrated databases keep the historical column order.
        assert_eq!(plan.add_columns[0].table, "browser_session_tabs");
        assert_eq!(plan.add_columns[0].column, "tab_id");

        let mut seen_columns = std::collections::HashSet::new();
        for column in &plan.add_columns {
            assert!(
                BROWSER_STORAGE_TABLE_NAMES.contains(&column.table.as_str()),
                "migration plan targets unknown table {}",
                column.table
            );
            assert!(
                seen_columns.insert((column.table.clone(), column.column.clone())),
                "duplicate migration column {}.{}",
                column.table,
                column.column
            );

            let expected_prefix =
                format!("ALTER TABLE {} ADD COLUMN {} ", column.table, column.column);
            assert!(
                column.statement.starts_with(&expected_prefix),
                "malformed migration statement: {}",
                column.statement
            );
            let definition = &column.statement[expected_prefix.len()..];

            // Anti-drift: the (column, definition) pair, including default
            // value literals, must match the base CREATE TABLE definition so
            // migrated and freshly created databases stay identical.
            let create_prefix = format!("CREATE TABLE IF NOT EXISTS {} (", column.table);
            let create_table = BROWSER_STORAGE_SCHEMA_STATEMENTS
                .iter()
                .map(|statement| normalize(statement))
                .find(|statement| statement.starts_with(&create_prefix))
                .unwrap_or_else(|| panic!("missing base CREATE TABLE for {}", column.table));
            let inline_definition = format!("{} {}", column.column, definition);
            assert!(
                create_table.contains(&format!("{inline_definition},"))
                    || create_table.contains(&format!("{inline_definition} )")),
                "migration column {}.{} ({definition}) drifted from base schema: {create_table}",
                column.table,
                column.column
            );
        }

        let normalized_base: Vec<String> = BROWSER_STORAGE_SCHEMA_STATEMENTS
            .iter()
            .map(|statement| normalize(statement))
            .collect();
        for statement in &plan.idempotent_statements {
            assert!(
                statement.starts_with("CREATE INDEX IF NOT EXISTS")
                    || statement.starts_with("CREATE TABLE IF NOT EXISTS")
                    || statement.starts_with("INSERT OR REPLACE"),
                "migration statement is not idempotent: {statement}"
            );
        }

        // Statements shared with the base schema (cursor storage and version
        // stamp) must not drift from their base counterparts.
        for anchor in [
            "CREATE TABLE IF NOT EXISTS browser_sync_cursors",
            "CREATE INDEX IF NOT EXISTS idx_browser_sync_cursors_updated",
            "INSERT OR REPLACE INTO browser_schema_meta",
        ] {
            let plan_statement = plan
                .idempotent_statements
                .iter()
                .map(|statement| normalize(statement))
                .find(|statement| statement.starts_with(anchor))
                .unwrap_or_else(|| panic!("migration plan is missing statement: {anchor}"));
            assert!(
                normalized_base.contains(&plan_statement),
                "migration statement drifted from base schema: {plan_statement}"
            );
        }

        // The version stamp must encode the current schema version literal.
        let version_stamp = plan.idempotent_statements.last().unwrap();
        assert!(
            version_stamp.contains(&format!("'{BROWSER_STORAGE_SCHEMA_VERSION}'")),
            "schema version stamp drifted: {version_stamp}"
        );

        let json = browser_storage_schema_migration_plan_json();
        assert!(json.contains("\"schemaVersion\":6"));
        assert!(json.contains("\"addColumns\""));
        assert!(json.contains("\"idempotentStatements\""));
        assert!(json.contains(
            "ALTER TABLE browser_session_tabs ADD COLUMN tab_id TEXT NOT NULL DEFAULT ''"
        ));
    }

    #[test]
    fn browser_storage_data_model_contract_covers_real_records() {
        let contract = browser_storage_data_model();
        assert_eq!(contract.version, BROWSER_STORAGE_SYNC_CONTRACT_VERSION);
        assert_eq!(contract.data_schema_version, BROWSER_DATA_SCHEMA_VERSION);
        assert_eq!(
            contract.storage_schema_version,
            BROWSER_STORAGE_SCHEMA_VERSION
        );
        assert_eq!(contract.database_name, BROWSER_STORAGE_DATABASE_NAME);
        assert_eq!(contract.snapshot_models.len(), 3);
        assert_eq!(contract.sync_record_models.len(), 6);
        assert_eq!(contract.local_sync_cursor_table, "browser_sync_cursors");
        assert_eq!(
            contract.remote_apply_conflict_policy,
            BROWSER_STORAGE_SYNC_REMOTE_APPLY_CONFLICT_POLICY
        );

        let history_page = contract
            .sync_record_models
            .iter()
            .find(|record| record.record_type == "historyPage")
            .unwrap();
        assert_eq!(history_page.collection, "historyPages");
        assert_eq!(history_page.local_tables, vec!["browser_history_pages"]);
        assert_eq!(history_page.local_primary_key_columns, vec!["address"]);
        assert_eq!(history_page.stable_identity_fields, vec!["address"]);
        assert!(history_page
            .payload_fields
            .iter()
            .any(|field| field.name == "lastVisitedAtUnixSeconds"));

        let bookmark = contract
            .sync_record_models
            .iter()
            .find(|record| record.record_type == "bookmark")
            .unwrap();
        assert_eq!(bookmark.local_tables, vec!["browser_bookmarks"]);
        assert!(bookmark
            .payload_fields
            .iter()
            .any(|field| field.name == "isDeleted" && field.field_type == "bool"));
        assert!(bookmark.tombstone_policy.contains("isDeleted"));

        let session_tab = contract
            .sync_record_models
            .iter()
            .find(|record| record.record_type == "sessionTab")
            .unwrap();
        assert_eq!(session_tab.local_tables, vec!["browser_session_tabs"]);
        assert_eq!(
            session_tab.local_primary_key_columns,
            vec!["session_id", "tab_index"]
        );
        assert_eq!(
            session_tab.stable_identity_fields,
            vec!["sessionId", "tabId"]
        );
        assert_eq!(session_tab.ordering_fields, vec!["tabIndex"]);
        assert!(session_tab.record_id_rule.contains("sessionId:tabId"));

        assert!(contract
            .cursor_collections
            .contains(&"historyPages".to_string()));
        assert!(contract
            .cursor_collections
            .contains(&"sessionTabs".to_string()));

        let json = serde_json::from_str::<Value>(&browser_storage_data_model_json()).unwrap();
        assert_eq!(json["storageSchemaVersion"], BROWSER_STORAGE_SCHEMA_VERSION);
        assert_eq!(json["syncRecordModels"].as_array().unwrap().len(), 6);
        assert_eq!(json["snapshotModels"].as_array().unwrap().len(), 3);
        assert_eq!(
            json["tombstoneField"].as_str().unwrap(),
            "deletedAtUnixSeconds"
        );
    }

