    #[test]
    fn cloud_local_folder_compatibility_preflight_reads_real_files() {
        let root = TempCloudStoreRoot::new("local-folder-compatibility-preflight");
        let root_dir = root.path.to_string_lossy().to_string();

        let empty_preflight = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_local_folder_compatibility_preflight_json(&root_dir, 106),
        )
        .unwrap();
        assert_eq!(
            empty_preflight["planType"],
            json!("cloudCompatibilityPreflight")
        );
        assert_eq!(empty_preflight["classification"], json!("compatible"));
        assert_eq!(empty_preflight["documentCount"], json!(0));
        assert_eq!(empty_preflight["shouldBlockSync"], json!(false));

        let seed = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_local_folder_cycle_round_json(
                &root_dir,
                &serialize_json(&sample_bookmark_push_request_for("device-b")),
                "[]",
                "device-b",
                80,
                20,
            ),
        )
        .unwrap();
        assert_eq!(seed["completed"], json!(true));

        let compatible_preflight = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_local_folder_compatibility_preflight_json(&root_dir, 107),
        )
        .unwrap();
        assert_eq!(
            compatible_preflight["planType"],
            json!("cloudCompatibilityPreflight")
        );
        assert_eq!(compatible_preflight["classification"], json!("compatible"));
        assert_eq!(compatible_preflight["shouldBlockSync"], json!(false));
        assert!(
            compatible_preflight["documentCount"]
                .as_u64()
                .unwrap_or_default()
                >= 3,
            "expected manifest, device, and log documents"
        );
        assert_eq!(
            compatible_preflight["compatibleCount"],
            compatible_preflight["documentCount"]
        );
        assert!(compatible_preflight["documents"]
            .as_array()
            .unwrap()
            .iter()
            .any(
                |document| document["path"] == json!(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH)
                    && document["status"]["documentKind"] == json!("manifest")
            ));

        let manifest_path = root.path.join(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH);
        let mut manifest = serde_json::from_str::<Value>(
            &fs::read_to_string(&manifest_path).expect("read manifest"),
        )
        .unwrap();
        manifest["storageSchemaVersion"] = json!(BROWSER_STORAGE_SCHEMA_VERSION + 1);
        fs::write(&manifest_path, serialize_json(&manifest)).expect("write manifest");

        let blocked_preflight = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_local_folder_compatibility_preflight_json(&root_dir, 108),
        )
        .unwrap();
        assert_eq!(
            blocked_preflight["classification"],
            json!("clientUpgradeRequired")
        );
        assert_eq!(blocked_preflight["shouldBlockSync"], json!(true));
        assert_eq!(blocked_preflight["clientUpgradeRequiredCount"], json!(1));
        assert!(blocked_preflight["documents"]
            .as_array()
            .unwrap()
            .iter()
            .any(
                |document| document["path"] == json!(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH)
                    && document["status"]["classification"] == json!("clientUpgradeRequired")
            ));

        assert_eq!(
            browser_storage_sync_cloud_local_folder_compatibility_preflight_json("", 109),
            "null"
        );
    }

    #[test]
    fn cloud_memory_store_round_trips_objects_with_revision_conflicts() {
        let store = BrowserStorageSyncMemoryCloudStore::new();
        let capabilities = store.capabilities();
        assert_eq!(capabilities.provider_kind, "memory");
        assert!(capabilities.supports_conditional_write);
        assert!(capabilities.supports_conditional_delete);

        let first_write = block_on_immediate(store.write(BrowserStorageSyncCloudWriteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            bytes: br#"{"version":1}"#,
            expected_revision: None,
            content_type: Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON),
        }))
        .unwrap();
        let first_revision = first_write.metadata.revision.clone().unwrap();
        assert!(first_write.created);
        assert!(!first_write.replaced);
        assert_eq!(store.object_count(), 1);

        let read = block_on_immediate(store.read(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH))
            .unwrap()
            .unwrap();
        assert_eq!(read.bytes, br#"{"version":1}"#);
        assert_eq!(read.metadata.revision, Some(first_revision.clone()));
        assert!(read
            .metadata
            .content_hash
            .as_deref()
            .unwrap()
            .starts_with("sha256:"));

        let stale_write = block_on_immediate(store.write(BrowserStorageSyncCloudWriteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            bytes: br#"{"version":2}"#,
            expected_revision: Some("memory-stale"),
            content_type: Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON),
        }));
        assert_eq!(
            stale_write.unwrap_err().kind,
            BrowserStorageSyncCloudStoreErrorKind::Conflict
        );

        let second_write = block_on_immediate(store.write(BrowserStorageSyncCloudWriteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            bytes: br#"{"version":2}"#,
            expected_revision: Some(&first_revision),
            content_type: Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON),
        }))
        .unwrap();
        let second_revision = second_write.metadata.revision.clone().unwrap();
        assert!(!second_write.created);
        assert!(second_write.replaced);
        assert_ne!(first_revision, second_revision);

        let list = block_on_immediate(store.list(
            BROWSER_STORAGE_SYNC_CLOUD_ROOT_PATH,
            Some(BrowserStorageSyncCloudListPage {
                cursor: None,
                limit: Some(1),
            }),
        ))
        .unwrap();
        assert_eq!(list.objects.len(), 1);
        assert_eq!(
            list.objects[0].path,
            BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH
        );

        let stale_delete = block_on_immediate(store.delete(BrowserStorageSyncCloudDeleteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            expected_revision: Some(&first_revision),
        }));
        assert_eq!(
            stale_delete.unwrap_err().kind,
            BrowserStorageSyncCloudStoreErrorKind::Conflict
        );

        let delete = block_on_immediate(store.delete(BrowserStorageSyncCloudDeleteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            expected_revision: Some(&second_revision),
        }))
        .unwrap();
        assert!(delete.deleted);
        assert_eq!(store.object_count(), 0);
        assert!(
            block_on_immediate(store.read(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH))
                .unwrap()
                .is_none()
        );
    }

