    #[test]
    fn cloud_pull_round_reads_logs_and_builds_remote_apply_plan() {
        let store = BrowserStorageSyncMemoryCloudStore::new();
        let push_result = block_on_immediate(browser_storage_sync_cloud_run_push_round(
            &store,
            Some(sample_bookmark_push_request_for("device-b")),
        ))
        .unwrap();
        assert!(push_result.completed);

        let result = block_on_immediate(browser_storage_sync_cloud_run_pull_round(
            &store,
            "device-a",
            Some(Vec::new()),
            80,
            20,
        ))
        .unwrap();

        assert!(result.completed);
        assert!(result.should_apply_remote);
        assert!(!result.should_reread);
        assert!(!result.should_retry);
        assert_eq!(result.client_action, "applyRemoteBatch");
        assert_eq!(
            result.round_summary.read_result_count as usize,
            result.read_results.len()
        );
        assert_eq!(
            result.round_summary.successful_read_count,
            result.round_summary.read_result_count
        );
        assert_eq!(result.round_summary.failed_read_count, 0);
        assert_eq!(
            result.round_summary.log_list_read_count as usize,
            result
                .read_results
                .iter()
                .filter(|read_result| read_result.operation_type == "listLogs")
                .count()
        );
        assert_eq!(
            result.round_summary.log_object_read_count as usize,
            result
                .read_results
                .iter()
                .filter(|read_result| read_result.operation_type == "readLog")
                .count()
        );
        assert_eq!(result.round_summary.imported_log_count, 1);
        assert_eq!(result.round_summary.record_count, 1);
        assert_eq!(result.round_summary.summary_action, "applyRemoteBatch");
        assert_eq!(
            result.round_summary.summary_reason,
            "remoteBatchContainsRecords"
        );
        assert_eq!(
            result.round_summary.collections,
            vec!["bookmarks".to_string()]
        );
        assert!(result
            .read_results
            .iter()
            .all(|read_result| read_result.success));
        assert!(result.read_results.iter().any(|read_result| {
            read_result.operation_type == "listLogs"
                && read_result.collection.as_deref() == Some("bookmarks")
                && read_result.object_count == Some(1)
                && read_result.read_reason == "listLogsForLocalCursorGapOrRecovery"
        }));
        assert!(result.read_results.iter().any(|read_result| {
            read_result.operation_type == "readLog"
                && read_result.collection.as_deref() == Some("bookmarks")
                && read_result.exists
                && read_result.read_reason == "readListedCloudLogObject"
        }));
        let apply_plan = result.apply_plan.as_ref().unwrap();
        assert_eq!(apply_plan.imported_log_count, 1);
        assert_eq!(apply_plan.record_count, 1);
        assert_eq!(apply_plan.collections, vec!["bookmarks".to_string()]);
        assert_eq!(
            serde_json::from_str::<Value>(&apply_plan.remote_batch_json).unwrap()["records"][0]
                ["recordType"],
            json!("bookmark")
        );
    }

    #[test]
    fn cloud_pull_round_follows_log_pagination_continuations() {
        let store = BrowserStorageSyncMemoryCloudStore::new();
        for (index, device_id) in ["device-b", "device-c", "device-d"].iter().enumerate() {
            let push_result = block_on_immediate(browser_storage_sync_cloud_run_push_round(
                &store,
                Some(sample_bookmark_push_request_for_record(
                    device_id,
                    &format!("bookmark-page-{index}"),
                    &format!("https://example.com/page-{index}"),
                    10 + index as i64,
                )),
            ))
            .unwrap();
            assert!(push_result.completed);
        }

        let result = block_on_immediate(browser_storage_sync_cloud_run_pull_round(
            &store,
            "device-a",
            Some(Vec::new()),
            100,
            1,
        ))
        .unwrap();

        assert!(result.completed);
        assert!(result.should_apply_remote);
        let bookmark_list_reads = result
            .read_results
            .iter()
            .filter(|read_result| {
                read_result.operation_type == "listLogs"
                    && read_result.collection.as_deref() == Some("bookmarks")
            })
            .collect::<Vec<_>>();
        assert_eq!(bookmark_list_reads.len(), 3);
        assert_eq!(
            bookmark_list_reads[0].read_reason,
            "listLogsForLocalCursorGapOrRecovery"
        );
        assert_eq!(
            bookmark_list_reads[1].read_reason,
            "continueProviderLogListing"
        );
        assert_eq!(
            bookmark_list_reads[2].read_reason,
            "continueProviderLogListing"
        );
        assert!(bookmark_list_reads[0].next_cursor.is_some());
        assert!(bookmark_list_reads[1].next_cursor.is_some());
        assert!(bookmark_list_reads[2].next_cursor.is_none());
        assert_eq!(result.apply_plan.as_ref().unwrap().imported_log_count, 3);
        assert_eq!(result.apply_plan.as_ref().unwrap().record_count, 3);
        assert_eq!(result.round_summary.log_list_read_count, 3);
        assert_eq!(result.round_summary.continuation_read_count, 2);
        assert_eq!(result.round_summary.imported_log_count, 3);
        assert_eq!(result.round_summary.record_count, 3);
        assert_eq!(
            result.round_summary.read_reasons,
            vec![
                "continueProviderLogListing".to_string(),
                "listLogsForLocalCursorGapOrRecovery".to_string(),
                "readListedCloudLogObject".to_string(),
                "rereadManifestForCloudStateRefresh".to_string(),
            ]
        );
    }

    #[test]
    fn cloud_pull_continuation_plan_preserves_provider_page_cursors() {
        let mut manifest =
            browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 100);
        for state in &mut manifest.collections {
            if state.collection == "bookmarks" {
                state.latest_log_sequence = 3;
                state.high_watermark_cursor = "3".to_string();
            }
        }
        let pull_plan_json = browser_storage_sync_cloud_pull_plan_json(
            &serialize_json(&manifest),
            "device-a",
            "[]",
            100,
            1,
        );
        let pull_plan = serde_json::from_str::<Value>(&pull_plan_json).unwrap();
        let list_operation = pull_plan["operations"]
            .as_array()
            .unwrap()
            .iter()
            .find(|operation| operation["operationType"] == json!("listLogs"))
            .unwrap();
        let prefix = list_operation["prefix"].as_str().unwrap();
        let cursor = format!("{prefix}device-b-0000000000000001.json");
        let read_results = json!([
            {
                "operationIndex": list_operation["operationIndex"],
                "operationType": "listLogs",
                "path": prefix,
                "collection": "bookmarks",
                "success": true,
                "exists": true,
                "objectCount": 1,
                "nextCursor": cursor
            }
        ])
        .to_string();

        let continuation =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_pull_continuation_plan_json(
                &pull_plan_json,
                &read_results,
                101,
            ))
            .unwrap();
        assert_eq!(continuation["planType"], json!("pullContinuation"));
        assert_eq!(continuation["hasMore"], json!(true));
        assert_eq!(continuation["operationCount"], json!(1));
        assert_eq!(
            continuation["continuationSummary"]["readResultCount"],
            json!(1)
        );
        assert_eq!(
            continuation["continuationSummary"]["continuableListResultCount"],
            json!(1)
        );
        assert_eq!(
            continuation["continuationSummary"]["operationCount"],
            json!(1)
        );
        assert_eq!(continuation["continuationSummary"]["hasMore"], json!(true));
        assert_eq!(
            continuation["continuationSummary"]["summaryAction"],
            json!("continueProviderLogListing")
        );
        assert_eq!(
            continuation["continuationSummary"]["summaryReason"],
            json!("providerNextCursorAvailable")
        );
        assert_eq!(
            continuation["continuationSummary"]["collections"],
            json!(["bookmarks"])
        );
        assert_eq!(
            continuation["continuationSummary"]["readPrefixes"],
            json!([prefix])
        );
        assert_eq!(
            continuation["continuationSummary"]["pageCursors"],
            json!([cursor])
        );
        assert_eq!(
            continuation["continuationSummary"]["readReasons"],
            json!(["continueProviderLogListing"])
        );
        assert_eq!(
            continuation["continuationSummary"]["operationIndices"],
            json!([0])
        );
        let operation = &continuation["operations"].as_array().unwrap()[0];
        assert_eq!(operation["operationType"], json!("listLogs"));
        assert_eq!(operation["collection"], json!("bookmarks"));
        assert_eq!(operation["prefix"], json!(prefix));
        assert_eq!(operation["maxObjects"], json!(1));
        assert_eq!(operation["pageCursor"], json!(cursor));
        assert_eq!(operation["readReason"], json!("continueProviderLogListing"));

        let wrapped_results =
            json!({ "readResults": serde_json::from_str::<Value>(&read_results).unwrap() })
                .to_string();
        assert_eq!(
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_pull_continuation_plan_json(
                &pull_plan_json,
                &wrapped_results,
                102,
            ),)
            .unwrap()["operationCount"],
            json!(1)
        );

        let complete_results = json!([
            {
                "operationIndex": list_operation["operationIndex"],
                "operationType": "listLogs",
                "path": prefix,
                "collection": "bookmarks",
                "success": true,
                "exists": true,
                "objectCount": 1
            }
        ])
        .to_string();
        let complete =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_pull_continuation_plan_json(
                &pull_plan_json,
                &complete_results,
                103,
            ))
            .unwrap();
        assert_eq!(complete["hasMore"], json!(false));
        assert!(complete["operations"].as_array().unwrap().is_empty());
        assert_eq!(
            complete["continuationSummary"]["summaryAction"],
            json!("finishProviderLogListing")
        );
        assert_eq!(
            complete["continuationSummary"]["summaryReason"],
            json!("noProviderNextCursor")
        );
        assert_eq!(complete["continuationSummary"]["readResultCount"], json!(1));
        assert_eq!(complete["continuationSummary"]["operationCount"], json!(0));
        assert_eq!(complete["continuationSummary"]["hasMore"], json!(false));
        assert_eq!(
            browser_storage_sync_cloud_pull_continuation_plan_json("{bad", "[]", 104),
            "null"
        );
    }

    #[test]
    fn cloud_pull_round_skips_current_device_logs() {
        let store = BrowserStorageSyncMemoryCloudStore::new();
        let push_result = block_on_immediate(browser_storage_sync_cloud_run_push_round(
            &store,
            Some(sample_bookmark_push_request_for("device-a")),
        ))
        .unwrap();
        assert!(push_result.completed);

        let result = block_on_immediate(browser_storage_sync_cloud_run_pull_round(
            &store,
            "device-a",
            Some(Vec::new()),
            80,
            20,
        ))
        .unwrap();

        assert!(result.completed);
        assert!(!result.should_apply_remote);
        assert_eq!(result.client_action, "finishPullNoChanges");
        assert_eq!(result.round_summary.summary_action, "finishPullNoChanges");
        assert_eq!(
            result.round_summary.summary_reason,
            "onlySkippedCloudInputs"
        );
        assert_eq!(result.round_summary.imported_log_count, 0);
        assert_eq!(result.round_summary.skipped_log_count, 1);
        assert!(!result.round_summary.should_apply_remote);
        let apply_plan = result.apply_plan.as_ref().unwrap();
        assert_eq!(apply_plan.imported_log_count, 0);
        assert_eq!(apply_plan.skipped_current_device_log_count, 1);
        assert_eq!(apply_plan.apply_action, "finishPullNoChanges");
        assert_eq!(apply_plan.apply_reason, "onlySkippedCloudInputs");
        assert_eq!(apply_plan.skipped_logs.len(), 1);
        assert_eq!(apply_plan.skipped_logs[0].skip_reason, "currentDeviceLog");
        assert_eq!(apply_plan.skipped_logs[0].action, "skipSelfOriginatedLog");
        assert_eq!(apply_plan.skipped_logs[0].device_id, "device-a");
        assert_eq!(apply_plan.record_count, 0);
        assert!(apply_plan.remote_apply_plan.operations.is_empty());
    }

