    #[test]
    fn cloud_cycle_round_pushes_then_pulls_remote_changes() {
        let store = BrowserStorageSyncMemoryCloudStore::new();
        let seeded_remote = block_on_immediate(browser_storage_sync_cloud_run_push_round(
            &store,
            Some(sample_bookmark_push_request_for("device-b")),
        ))
        .unwrap();
        assert!(seeded_remote.completed);

        let result = block_on_immediate(browser_storage_sync_cloud_run_cycle_round(
            &store,
            Some(sample_bookmark_push_request_for("device-a")),
            Some(Vec::new()),
            "device-a",
            90,
            20,
        ))
        .unwrap();

        assert!(result.completed);
        assert!(result.should_ack_local);
        assert!(result.should_apply_remote);
        assert!(!result.should_reread);
        assert!(!result.should_retry);
        assert_eq!(result.client_action, "applyLocalAckThenRemoteBatch");

        let push_round = result.push_round.as_ref().unwrap();
        assert!(push_round.completed);
        assert!(push_round.should_ack_local);
        assert!(push_round.result_plan.as_ref().unwrap().ack_plan.is_some());

        let pull_round = result.pull_round.as_ref().unwrap();
        assert!(pull_round.completed);
        assert!(pull_round.should_apply_remote);
        let apply_plan = pull_round.apply_plan.as_ref().unwrap();
        assert_eq!(apply_plan.imported_log_count, 1);
        assert_eq!(apply_plan.skipped_current_device_log_count, 1);
        assert_eq!(apply_plan.record_count, 1);

        let client_plan = result.client_plan.as_ref().unwrap();
        assert_eq!(client_plan.action, "applyLocalAckThenRemoteBatch");
        assert!(client_plan.ack_plan.is_some());
        assert!(client_plan.ack_batch_json.is_some());
        assert!(client_plan.remote_apply_plan.is_some());
        assert!(client_plan.remote_batch_json.is_some());
        assert_eq!(
            client_plan
                .steps
                .iter()
                .map(|step| step.step_type.as_str())
                .collect::<Vec<_>>(),
            vec!["applyLocalAck", "applyRemoteBatch"]
        );
        assert_eq!(
            client_plan.steps[0].step_reason.as_deref(),
            Some("allRequiredCloudWritesSucceeded")
        );
        assert_eq!(
            client_plan.steps[1].step_reason.as_deref(),
            Some("remoteBatchContainsRecords")
        );

        assert!(result.round_summary.push_round_present);
        assert!(result.round_summary.pull_round_present);
        assert!(result.round_summary.push_completed);
        assert!(result.round_summary.pull_completed);
        assert!(result.round_summary.completed);
        assert!(result.round_summary.should_ack_local);
        assert!(result.round_summary.should_apply_remote);
        assert_eq!(
            result.round_summary.summary_action,
            "applyLocalAckThenRemoteBatch"
        );
        assert_eq!(
            result.round_summary.summary_reason,
            "localAckAndRemoteApplyPlanned"
        );
        assert_eq!(result.round_summary.client_step_count, 2);
        assert_eq!(result.round_summary.ack_step_count, 1);
        assert_eq!(result.round_summary.remote_apply_step_count, 1);
        assert_eq!(result.round_summary.imported_log_count, 1);
        assert_eq!(result.round_summary.skipped_log_count, 1);
        assert_eq!(result.round_summary.remote_record_count, 1);
        assert_eq!(
            result.round_summary.step_types,
            vec!["applyLocalAck".to_string(), "applyRemoteBatch".to_string()]
        );
        assert_eq!(result.round_summary.collections, vec!["bookmarks"]);
    }

    #[test]
    fn cloud_cycle_round_stops_pull_after_push_conflict() {
        let inner = BrowserStorageSyncMemoryCloudStore::new();
        let manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        block_on_immediate(inner.write(BrowserStorageSyncCloudWriteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            bytes: serialize_json(&manifest).as_bytes(),
            expected_revision: None,
            content_type: Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON),
        }))
        .unwrap();
        let store = ManifestConflictCloudStore::new(inner);

        let result = block_on_immediate(browser_storage_sync_cloud_run_cycle_round(
            &store,
            Some(sample_bookmark_push_request_for("device-a")),
            Some(Vec::new()),
            "device-a",
            90,
            20,
        ))
        .unwrap();

        assert!(!result.completed);
        assert!(!result.should_ack_local);
        assert!(!result.should_apply_remote);
        assert!(result.should_reread);
        assert!(result.should_retry);
        assert_eq!(
            result.client_action,
            BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY
        );
        assert!(result.push_round.as_ref().unwrap().result_plan.is_some());
        assert!(result.pull_round.is_none());

        let client_plan = result.client_plan.as_ref().unwrap();
        assert_eq!(client_plan.action, "rereadCloudStateThenRetry");
        assert!(client_plan.ack_plan.is_none());
        assert!(client_plan.remote_apply_plan.is_none());
        assert_eq!(
            client_plan
                .steps
                .iter()
                .map(|step| step.step_type.as_str())
                .collect::<Vec<_>>(),
            vec!["rereadCloudState", "scheduleCloudCycleRetry"]
        );
        assert_eq!(
            client_plan.retry_reason.as_deref(),
            Some("rereadManifestMergeAndRetry")
        );

        assert!(result.round_summary.push_round_present);
        assert!(!result.round_summary.pull_round_present);
        assert!(!result.round_summary.completed);
        assert!(result.round_summary.should_reread);
        assert!(result.round_summary.should_retry);
        assert_eq!(
            result.round_summary.summary_action,
            BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY
        );
        assert_eq!(result.round_summary.summary_reason, "conflict");
        assert_eq!(result.round_summary.conflict_count, 1);
        assert_eq!(result.round_summary.retryable_failure_count, 1);
        assert_eq!(result.round_summary.reread_step_count, 1);
        assert_eq!(result.round_summary.retry_step_count, 1);
        assert_eq!(
            result.round_summary.step_types,
            vec![
                "rereadCloudState".to_string(),
                "scheduleCloudCycleRetry".to_string()
            ]
        );
        assert_eq!(result.round_summary.issue_reasons, vec!["conflict"]);
    }

