    #[test]
    fn cloud_cycle_client_apply_result_json_builds_completed_envelope() {
        let cycle_round_json = sample_cloud_cycle_round_json_with_ack_and_remote_steps();
        let client_plan = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_cycle_client_plan_json(&cycle_round_json),
        )
        .unwrap();
        assert_eq!(
            client_plan["steps"]
                .as_array()
                .unwrap()
                .iter()
                .map(|step| step["stepType"].as_str().unwrap())
                .collect::<Vec<_>>(),
            vec!["applyLocalAck", "applyRemoteBatch"]
        );

        let remote_apply_result = r#"{
            "version": 1,
            "storageSchemaVersion": 6,
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 91,
            "appliedCount": 1,
            "skippedCount": 0,
            "failedCount": 0,
            "conflicts": [],
            "failures": []
        }"#;
        let envelope = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_cycle_client_apply_result_json(
                &cycle_round_json,
                r#"[
                    {"stepType": "applyLocalAck", "success": true, "error": null},
                    {"stepType": "applyRemoteBatch", "success": true, "error": null}
                ]"#,
                remote_apply_result,
            ),
        )
        .unwrap();

        assert_eq!(envelope["applied"], json!(true));
        assert_eq!(envelope["ackApplied"], json!(true));
        assert_eq!(envelope["remoteApplied"], json!(true));
        assert_eq!(envelope["failedStep"], json!(""));
        assert_eq!(envelope["scope"], client_plan["scope"]);
        assert_eq!(envelope["action"], client_plan["action"]);
        assert_eq!(envelope["remoteApplyResult"]["appliedCount"], json!(1),);
        let step_results = envelope["stepResults"].as_array().unwrap();
        assert_eq!(step_results.len(), 2);
        assert_eq!(step_results[0]["stepType"], json!("applyLocalAck"));
        assert_eq!(
            step_results[0]["operationCount"],
            client_plan["steps"][0]["operationCount"]
        );
        assert_eq!(step_results[0]["required"], json!(true));
        assert_eq!(step_results[0]["error"], Value::Null);
        assert_eq!(step_results[1]["stepType"], json!("applyRemoteBatch"));
        assert_eq!(step_results[1]["required"], json!(false));
        assert_eq!(envelope["clientPlan"], client_plan);
        assert_eq!(
            envelope["cycleRound"],
            serde_json::from_str::<Value>(&cycle_round_json).unwrap()
        );
    }

    #[test]
    fn cloud_cycle_client_apply_result_json_stops_at_failed_required_step() {
        let cycle_round_json = sample_cloud_cycle_round_json_with_ack_and_remote_steps();
        let envelope = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_cycle_client_apply_result_json(
                &cycle_round_json,
                r#"[{"stepType": "applyLocalAck", "success": false, "error": null}]"#,
                "null",
            ),
        )
        .unwrap();

        assert_eq!(envelope["applied"], json!(false));
        assert_eq!(envelope["ackApplied"], json!(false));
        assert_eq!(envelope["remoteApplied"], json!(false));
        assert_eq!(envelope["failedStep"], json!("applyLocalAck"));
        assert_eq!(envelope["remoteApplyResult"], Value::Null);
        let step_results = envelope["stepResults"].as_array().unwrap();
        assert_eq!(step_results.len(), 1);
        assert_eq!(step_results[0]["success"], json!(false));
        assert_eq!(step_results[0]["error"], json!("ack plan execution failed"));
    }

