    #[test]
    fn cloud_cycle_client_apply_result_json_reports_remote_apply_failures() {
        let cycle_round_json = sample_cloud_cycle_round_json_with_ack_and_remote_steps();
        let failed_remote_apply = r#"{
            "version": 1,
            "storageSchemaVersion": 6,
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 91,
            "appliedCount": 0,
            "skippedCount": 0,
            "failedCount": 1,
            "conflicts": [],
            "failures": [
                {
                    "operationIndex": 0,
                    "statementKey": "applyRemoteBookmark",
                    "collection": "bookmarks",
                    "reason": "executionError"
                }
            ]
        }"#;
        let envelope = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_cycle_client_apply_result_json(
                &cycle_round_json,
                r#"[
                    {"stepType": "applyLocalAck", "success": true, "error": null},
                    {"stepType": "applyRemoteBatch", "success": false, "error": null}
                ]"#,
                failed_remote_apply,
            ),
        )
        .unwrap();

        // applyRemoteBatch is not a required step, so the cycle still counts
        // as applied while the remote batch itself is reported as failed.
        assert_eq!(envelope["applied"], json!(true));
        assert_eq!(envelope["ackApplied"], json!(true));
        assert_eq!(envelope["remoteApplied"], json!(false));
        assert_eq!(envelope["failedStep"], json!(""));
        assert_eq!(envelope["remoteApplyResult"]["failedCount"], json!(1));
        let step_results = envelope["stepResults"].as_array().unwrap();
        assert_eq!(step_results[1]["success"], json!(false));
        assert_eq!(
            step_results[1]["error"],
            json!("remote apply result contains failures")
        );
    }

    #[test]
    fn invalid_cloud_cycle_client_apply_result_json_returns_null() {
        let cycle_round_json = sample_cloud_cycle_round_json_with_ack_and_remote_steps();
        assert_eq!(
            browser_storage_sync_cloud_cycle_client_apply_result_json("{bad", "[]", "null"),
            "null"
        );
        assert_eq!(
            browser_storage_sync_cloud_cycle_client_apply_result_json(
                &cycle_round_json,
                "{bad",
                "null"
            ),
            "null"
        );
        // More executed steps than the plan contains is inconsistent input.
        assert_eq!(
            browser_storage_sync_cloud_cycle_client_apply_result_json(
                &cycle_round_json,
                r#"[
                    {"stepType": "applyLocalAck", "success": true, "error": null},
                    {"stepType": "applyRemoteBatch", "success": true, "error": null},
                    {"stepType": "applyRemoteBatch", "success": true, "error": null}
                ]"#,
                "null"
            ),
            "null"
        );
        // Step results must line up with the planned execution order.
        assert_eq!(
            browser_storage_sync_cloud_cycle_client_apply_result_json(
                &cycle_round_json,
                r#"[{"stepType": "applyRemoteBatch", "success": true, "error": null}]"#,
                "null"
            ),
            "null"
        );
        // A step result without a boolean success flag is invalid.
        assert_eq!(
            browser_storage_sync_cloud_cycle_client_apply_result_json(
                &cycle_round_json,
                r#"[{"stepType": "applyLocalAck", "error": null}]"#,
                "null"
            ),
            "null"
        );
    }

