    #[test]
    fn cloud_provider_adapter_plan_classifies_ready_degraded_and_setup() {
        let local_folder_capabilities = browser_storage_sync_cloud_local_folder_capabilities_json();
        let ready_plan = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_provider_adapter_plan_json(&local_folder_capabilities, 100),
        )
        .unwrap();

        assert_eq!(ready_plan["planType"], json!("cloudProviderAdapterPlan"));
        assert_eq!(ready_plan["classification"], json!("ready"));
        assert_eq!(ready_plan["capabilityClassification"], json!("ready"));
        assert_eq!(ready_plan["adapterFamily"], json!("localFolder"));
        assert_eq!(ready_plan["productionReady"], json!(true));
        assert_eq!(ready_plan["shouldAllowSync"], json!(true));
        assert_eq!(ready_plan["shouldBlockSync"], json!(false));
        assert_eq!(
            ready_plan["objectLayout"]["manifestPath"],
            json!(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH)
        );
        assert!(ready_plan["requiredPrefixes"]
            .as_array()
            .unwrap()
            .iter()
            .any(|prefix| prefix["prefix"] == json!(BROWSER_STORAGE_SYNC_CLOUD_LOGS_PREFIX)));

        let mut degraded_capabilities = browser_storage_sync_cloud_local_folder_capabilities();
        degraded_capabilities.supports_prefix_list = false;
        let degraded_plan =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_provider_adapter_plan_json(
                &serialize_json(&json!({
                    "providerKind": "googleDrive",
                    "adapterFamily": "platformNative",
                    "capabilities": degraded_capabilities
                })),
                101,
            ))
            .unwrap();

        assert_eq!(degraded_plan["classification"], json!("degraded"));
        assert_eq!(degraded_plan["capabilityClassification"], json!("degraded"));
        assert_eq!(degraded_plan["requiresAdapterEmulation"], json!(true));
        assert_eq!(
            degraded_plan["providerAction"],
            json!("enableAdapterEmulation")
        );
        assert_eq!(degraded_plan["productionReady"], json!(true));

        let mut wrong_root_capabilities = browser_storage_sync_cloud_local_folder_capabilities();
        wrong_root_capabilities.root_path = "ActroWrong/BrowserSync".to_string();
        let setup_plan =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_provider_adapter_plan_json(
                &serialize_json(&wrong_root_capabilities),
                102,
            ))
            .unwrap();

        assert_eq!(setup_plan["classification"], json!("providerSetupRequired"));
        assert_eq!(setup_plan["shouldBlockSync"], json!(true));
        assert_eq!(
            setup_plan["rootPathAction"],
            json!("configureActroBrowserSyncRoot")
        );
        assert!(setup_plan["blockedReasons"]
            .as_array()
            .unwrap()
            .contains(&json!("rootPath")));
        assert_eq!(
            browser_storage_sync_cloud_provider_adapter_plan_json("{bad", 103),
            "null"
        );
    }

