    #[test]
    fn cloud_provider_connection_status_policy_classifies_provider_recovery() {
        let auth_snapshot = json!({
            "providerKind": "iCloudDrive",
            "providerAccountId": "icloud-user",
            "connectionState": "connected",
            "credentialState": "expired",
            "membershipStatus": "active",
            "cloudStoreReady": true
        });
        let auth_policy = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_provider_connection_status_policy_json(
                &serialize_json(&auth_snapshot),
                2,
                102,
            ),
        )
        .unwrap();

        assert_eq!(auth_policy["classification"], json!("authExpired"));
        assert_eq!(
            auth_policy["schedulerAction"],
            json!("waitForProviderCredentials")
        );
        assert_eq!(auth_policy["providerAction"], json!("reconnectProvider"));
        assert_eq!(auth_policy["userAction"], json!("reconnectProvider"));
        assert_eq!(auth_policy["shouldRetry"], json!(false));

        let retry_snapshot = json!({
            "providerKind": "oneDrive",
            "providerAccountId": "one-drive-user",
            "connectionState": "connecting",
            "credentialState": "available",
            "membershipStatus": "active",
            "cloudStoreReady": true,
            "lastProviderErrorKind": "network"
        });
        let retry_policy = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_provider_connection_status_policy_json(
                &serialize_json(&retry_snapshot),
                1,
                103,
            ),
        )
        .unwrap();

        assert_eq!(retry_policy["classification"], json!("providerUnavailable"));
        assert_eq!(retry_policy["schedulerAction"], json!("scheduleRetry"));
        assert_eq!(
            retry_policy["providerAction"],
            json!("retryProviderConnection")
        );
        assert_eq!(retry_policy["shouldRetry"], json!(true));
        assert_eq!(retry_policy["retryDelaySeconds"], json!(10));
        assert!(retry_policy["diagnosticReasons"]
            .as_array()
            .unwrap()
            .contains(&json!("network")));

        let unsupported_snapshot = json!({
            "providerKind": "customDrive",
            "connectionState": "connected",
            "credentialState": "available",
            "membershipStatus": "active",
            "capabilityPreflight": {
                "classification": "providerConflictUnsafe",
                "shouldAllowSync": false,
                "shouldBlockSync": true,
                "missingRequiredCapabilities": ["supportsConditionalWrite"]
            }
        });
        let unsupported_policy = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_provider_connection_status_policy_json(
                &serialize_json(&unsupported_snapshot),
                0,
                104,
            ),
        )
        .unwrap();

        assert_eq!(
            unsupported_policy["classification"],
            json!("adapterUnsupported")
        );
        assert_eq!(
            unsupported_policy["schedulerAction"],
            json!("stopUntilProviderFix")
        );
        assert_eq!(
            unsupported_policy["providerAction"],
            json!("reportProviderBug")
        );
        assert!(unsupported_policy["diagnosticReasons"]
            .as_array()
            .unwrap()
            .contains(&json!("supportsConditionalWrite")));
        assert_eq!(
            browser_storage_sync_cloud_provider_connection_status_policy_json("{bad", 0, 105),
            "null"
        );
    }

    #[test]
    fn cloud_provider_error_policy_classifies_reread_batch() {
        let policy =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_provider_error_policy_json())
                .unwrap();
        assert_eq!(
            policy["planType"],
            json!("cloudProviderErrorClassification")
        );
        assert!(policy["policyBoundary"]
            .as_str()
            .unwrap()
            .contains("coarse native/provider rounds"));
        assert!(policy["canonicalErrorKinds"]
            .as_array()
            .unwrap()
            .contains(&json!("conflict")));

        let result = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_provider_error_classification_json(
                &serialize_json(&json!({
                    "providerKind": "googleDrive",
                    "planType": "cloudPushWriteResults",
                    "writeResults": [
                        {
                            "operationIndex": 2,
                            "operationType": "writeManifest",
                            "path": BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
                            "success": false,
                            "providerStatusCode": 412,
                            "errorMessage": "etag mismatch"
                        },
                        {
                            "operationIndex": 3,
                            "operationType": "writeLog",
                            "path": browser_storage_sync_cloud_log_path("bookmarks", "device-a", 1),
                            "success": true,
                            "providerRevision": "ignored-success"
                        }
                    ]
                })),
                0,
                120,
            ),
        )
        .unwrap();

        assert_eq!(
            result["planType"],
            json!("cloudProviderErrorClassification")
        );
        assert_eq!(result["classification"], json!("cloudStateRereadRequired"));
        assert_eq!(result["failedCount"], json!(1));
        assert_eq!(result["conflictCount"], json!(1));
        assert_eq!(result["shouldRereadCloud"], json!(true));
        assert_eq!(result["schedulerAction"], json!("runCloudReread"));
        assert_eq!(result["providerAction"], json!("rereadCloudState"));
        assert_eq!(result["errors"][0]["canonicalErrorKind"], json!("conflict"));
        assert_eq!(result["errors"][0]["action"], json!("rereadCloudAndReplan"));
        assert_eq!(
            browser_storage_sync_cloud_provider_error_classification_json("{bad", 0, 121),
            "null"
        );
    }

    #[test]
    fn cloud_provider_error_classification_prioritizes_recovery_and_retry() {
        let auth = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_provider_error_classification_json(
                &serialize_json(&json!({
                    "providerKind": "iCloudDrive",
                    "errors": [
                        {
                            "operationIndex": 0,
                            "operationType": "readManifest",
                            "errorKind": "tokenExpired",
                            "message": "provider token expired"
                        },
                        {
                            "operationIndex": 1,
                            "operationType": "listLogs",
                            "providerStatusCode": 429,
                            "retryable": true
                        }
                    ]
                })),
                2,
                122,
            ),
        )
        .unwrap();

        assert_eq!(auth["classification"], json!("authExpired"));
        assert_eq!(auth["authFailureCount"], json!(1));
        assert_eq!(auth["requiresProviderRecovery"], json!(true));
        assert_eq!(auth["requiresUserAction"], json!(true));
        assert_eq!(auth["shouldRetry"], json!(false));
        assert_eq!(auth["providerAction"], json!("reconnectProvider"));
        assert_eq!(
            auth["errors"][0]["canonicalErrorKind"],
            json!("unauthorized")
        );

        let network = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_provider_error_classification_json(
                &serialize_json(&json!({
                    "providerKind": "oneDrive",
                    "operationResults": [
                        {
                            "operationIndex": 0,
                            "operationType": "listLogs",
                            "success": false,
                            "providerStatusCode": 503
                        }
                    ]
                })),
                1,
                123,
            ),
        )
        .unwrap();

        assert_eq!(network["classification"], json!("providerUnavailable"));
        assert_eq!(network["shouldRetry"], json!(true));
        assert_eq!(network["retryDelaySeconds"], json!(10));
        assert_eq!(network["schedulerAction"], json!("scheduleRetry"));
        assert_eq!(network["providerAction"], json!("retryProviderOperation"));
        assert_eq!(network["errors"][0]["canonicalErrorKind"], json!("network"));
    }

    #[test]
    fn cloud_cycle_status_policy_classifies_success_conflict_and_provider_retry() {
        let store = BrowserStorageSyncMemoryCloudStore::new();
        let success_round = block_on_immediate(browser_storage_sync_cloud_run_cycle_round(
            &store,
            Some(sample_bookmark_push_request_for("device-a")),
            Some(Vec::new()),
            "device-a",
            90,
            20,
        ))
        .unwrap();
        let success_policy =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cycle_status_policy_json(
                &serialize_json(&success_round),
                3,
            ))
            .unwrap();

        assert_eq!(success_policy["classification"], json!("success"));
        assert_eq!(success_policy["schedulerAction"], json!("idle"));
        assert_eq!(success_policy["providerAction"], json!("none"));
        assert_eq!(success_policy["resetRetryAttempt"], json!(true));
        assert_eq!(success_policy["retryDelaySeconds"], Value::Null);
        assert_eq!(
            success_policy["resultPolicy"],
            json!("Classify one cloud-drive cycle round for platform schedulers without turning provider SDK calls or native SQLite execution into Rust-owned micro-steps.")
        );

        let inner = BrowserStorageSyncMemoryCloudStore::new();
        let manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        block_on_immediate(inner.write(BrowserStorageSyncCloudWriteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            bytes: serialize_json(&manifest).as_bytes(),
            expected_revision: None,
            content_type: Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON),
        }))
        .unwrap();
        let conflict_store = ManifestConflictCloudStore::new(inner);
        let conflict_round = block_on_immediate(browser_storage_sync_cloud_run_cycle_round(
            &conflict_store,
            Some(sample_bookmark_push_request_for("device-a")),
            Some(Vec::new()),
            "device-a",
            90,
            20,
        ))
        .unwrap();
        let conflict_policy =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cycle_status_policy_json(
                &serialize_json(&conflict_round),
                2,
            ))
            .unwrap();

        assert_eq!(conflict_policy["classification"], json!("cloudConflict"));
        assert_eq!(
            conflict_policy["schedulerAction"],
            json!("rereadCloudStateThenScheduleRetry")
        );
        assert_eq!(conflict_policy["providerAction"], json!("rereadCloudState"));
        assert_eq!(conflict_policy["shouldRetry"], json!(true));
        assert_eq!(conflict_policy["retryDelaySeconds"], json!(20));
        assert_eq!(conflict_policy["conflictCount"], json!(1));
        assert_eq!(
            conflict_policy["diagnosticReasons"]
                .as_array()
                .unwrap()
                .iter()
                .map(|reason| reason.as_str().unwrap())
                .collect::<Vec<_>>(),
            vec!["conflict"]
        );

        let retry_round = block_on_immediate(browser_storage_sync_cloud_run_cycle_round(
            &FailingManifestReadCloudStore,
            None,
            Some(Vec::new()),
            "device-a",
            90,
            20,
        ))
        .unwrap();
        let retry_policy = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_cycle_status_policy_json(&serialize_json(&retry_round), 0),
        )
        .unwrap();

        assert_eq!(retry_policy["classification"], json!("providerUnavailable"));
        assert_eq!(retry_policy["schedulerAction"], json!("scheduleRetry"));
        assert_eq!(
            retry_policy["providerAction"],
            json!("retryProviderOperation")
        );
        assert_eq!(retry_policy["readFailureCount"], json!(1));
        assert_eq!(retry_policy["retryDelaySeconds"], json!(5));
        assert!(retry_policy["diagnosticReasons"]
            .as_array()
            .unwrap()
            .contains(&json!("network")));
        assert!(retry_policy["diagnosticReasons"]
            .as_array()
            .unwrap()
            .contains(&json!("providerReadFailed")));
        assert_eq!(
            browser_storage_sync_cloud_cycle_status_policy_json("{bad", 0),
            "null"
        );
    }

    #[test]
    fn cloud_cycle_status_policy_keeps_provider_recovery_out_of_server_terms() {
        let provider_auth_round = json!({
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 90,
            "completed": false,
            "shouldRetry": false,
            "shouldReread": false,
            "shouldAckLocal": false,
            "shouldApplyRemote": false,
            "clientAction": "recoverProviderCredentials",
            "pushRound": {
                "resultPlan": {
                    "issues": [
                        {
                            "reason": "unauthorized",
                            "retryable": false
                        }
                    ]
                }
            }
        });
        let provider_auth_policy =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cycle_status_policy_json(
                &serialize_json(&provider_auth_round),
                4,
            ))
            .unwrap();

        assert_eq!(
            provider_auth_policy["classification"],
            json!("providerAuthRequired")
        );
        assert_eq!(
            provider_auth_policy["schedulerAction"],
            json!("waitForProviderCredentials")
        );
        assert_eq!(
            provider_auth_policy["providerAction"],
            json!("reconnectProvider")
        );
        assert_eq!(
            provider_auth_policy["userAction"],
            json!("reconnectProvider")
        );
        assert_eq!(provider_auth_policy["shouldRetry"], json!(false));
        assert_eq!(provider_auth_policy["retryDelaySeconds"], Value::Null);

        let quota_round = json!({
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 90,
            "completed": false,
            "shouldRetry": false,
            "shouldReread": false,
            "shouldAckLocal": false,
            "shouldApplyRemote": false,
            "clientAction": "freeCloudStorageOrReduceRetention",
            "pushRound": {
                "writeResults": [
                    {
                        "operationIndex": 0,
                        "success": false,
                        "errorKind": "quotaExceeded"
                    }
                ]
            }
        });
        let quota_policy = serde_json::from_str::<Value>(
            &browser_storage_sync_cloud_cycle_status_policy_json(&serialize_json(&quota_round), 1),
        )
        .unwrap();

        assert_eq!(
            quota_policy["classification"],
            json!("providerQuotaExceeded")
        );
        assert_eq!(
            quota_policy["schedulerAction"],
            json!("waitForProviderStorage")
        );
        assert_eq!(
            quota_policy["userAction"],
            json!("freeCloudStorageOrReduceRetention")
        );
        assert_eq!(quota_policy["writeFailureCount"], json!(1));
        assert!(!serialize_json(&quota_policy).contains("serverUnavailable"));
    }

