        assert_eq!(empty_loop["finalAttemptPlan"], Value::Null);
        assert_eq!(empty_loop["loopSummary"]["attemptCount"], json!(0));
        assert_eq!(
            empty_loop["loopSummary"]["finalAction"],
            json!("runCloudCycleRound")
        );
