    #[test]
    fn cloud_cycle_loop_plan_bounds_conflict_retry_rounds() {
        let inner = BrowserStorageSyncMemoryCloudStore::new();
        let manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        block_on_immediate(inner.write(BrowserStorageSyncCloudWriteRequest {
            path: BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH,
            bytes: serialize_json(&manifest).as_bytes(),
            expected_revision: None,
            content_type: Some(BROWSER_STORAGE_SYNC_CLOUD_CONTENT_TYPE_JSON),
        }))
        .unwrap();
        let conflict_store = ManifestConflictCloudStore::new(inner);
        let conflict_round = block_on_immediate(browser_storage_sync_cloud_run_cycle_round(
            &conflict_store,
            Some(sample_bookmark_push_request_for("device-a")),
            Some(Vec::new()),
            "device-a",
            90,
            20,
        ))
        .unwrap();

        let pending_loop =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cycle_loop_plan_json(
                &serialize_json(&vec![conflict_round.clone()]),
                0,
                50_000,
                3,
            ))
            .unwrap();
        assert_eq!(pending_loop["finalClassification"], json!("cloudConflict"));
        assert_eq!(pending_loop["blockedByRetryBackoff"], json!(true));
        assert_eq!(pending_loop["exhausted"], json!(false));
        assert_eq!(
            pending_loop["finalAction"],
            json!("rereadCloudStateThenScheduleRetry")
        );
        assert_eq!(pending_loop["shouldScheduleRetry"], json!(true));
        assert_eq!(pending_loop["nextRunAtUnixSeconds"], json!(50_005));
        assert_eq!(pending_loop["loopSummary"]["rereadAttemptCount"], json!(1));
        assert_eq!(pending_loop["loopSummary"]["retryAttemptCount"], json!(1));
        assert_eq!(
            pending_loop["loopSummary"]["scheduledRetryAttemptCount"],
            json!(1)
        );
        assert_eq!(
            pending_loop["loopSummary"]["providerOperationAttemptCount"],
            json!(1)
        );
        assert_eq!(
            pending_loop["loopSummary"]["blockedByRetryBackoff"],
            json!(true)
        );
        assert_eq!(
            pending_loop["loopSummary"]["classifications"],
            json!(["cloudConflict"])
        );

        let exhausted_loop =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cycle_loop_plan_json(
                &serialize_json(&vec![conflict_round]),
                0,
                50_000,
                1,
            ))
            .unwrap();
        assert_eq!(exhausted_loop["exhausted"], json!(true));
        assert_eq!(
            exhausted_loop["finalAction"],
            json!("scheduleCloudCycleRetryAfterMaxAttempts")
        );
        assert_eq!(exhausted_loop["shouldContinueLoop"], json!(false));
        assert_eq!(exhausted_loop["shouldStopUntilRecovery"], json!(true));
        assert_eq!(exhausted_loop["loopSummary"]["exhausted"], json!(true));
        assert_eq!(
            exhausted_loop["loopSummary"]["shouldStopUntilRecovery"],
            json!(true)
        );
        assert_eq!(
            exhausted_loop["loopSummary"]["finalAction"],
            json!("scheduleCloudCycleRetryAfterMaxAttempts")
        );
        assert_eq!(
            browser_storage_sync_cloud_cycle_loop_plan_json("{bad", 0, 1, 3),
            "null"
        );
        assert_eq!(
            browser_storage_sync_cloud_cycle_loop_plan_json(r#"[1]"#, 0, 1, 3),
            "null"
        );
    }

