    #[test]
    fn cloud_pull_plan_lists_logs_and_snapshots_from_manifest_state() {
        let mut manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        for state in &mut manifest.collections {
            match state.collection.as_str() {
                "historyPages" => {
                    state.latest_log_sequence = 3;
                    state.latest_log_path = Some(
                        "Actro/BrowserSync/logs/historyPages/device-b-0000000000000003.json"
                            .to_string(),
                    );
                    state.high_watermark_cursor = "3".to_string();
                }
                "bookmarks" => {
                    state.latest_log_sequence = 2;
                    state.latest_log_path = Some(
                        "Actro/BrowserSync/logs/bookmarks/device-b-0000000000000002.json"
                            .to_string(),
                    );
                    state.high_watermark_cursor = "2".to_string();
                }
                "sessions" => {
                    state.latest_log_sequence = 4;
                    state.latest_log_path = Some(
                        "Actro/BrowserSync/logs/sessions/device-b-0000000000000004.json"
                            .to_string(),
                    );
                    state.snapshot_revision = 2;
                    state.high_watermark_cursor = "4".to_string();
                }
                _ => {}
            }
        }
        let cursors = serialize_json(&vec![
            BrowserStorageSyncCursorUpdate {
                collection: "historyPages".to_string(),
                cursor: "1".to_string(),
                last_synced_at_unix_seconds: Some(40),
            },
            BrowserStorageSyncCursorUpdate {
                collection: "bookmarks".to_string(),
                cursor: "2".to_string(),
                last_synced_at_unix_seconds: Some(40),
            },
        ]);

        let plan = serde_json::from_str::<Value>(&browser_storage_sync_cloud_pull_plan_json(
            &serialize_json(&manifest),
            "device-a",
            &cursors,
            90,
            25,
        ))
        .unwrap();

        assert_eq!(plan["planType"], json!("pullRead"));
        assert_eq!(
            plan["manifestPath"],
            json!(BROWSER_STORAGE_SYNC_CLOUD_MANIFEST_PATH)
        );
        assert_eq!(plan["maxLogObjectsPerCollection"], json!(25));
        assert_eq!(
            plan["conflictPolicy"],
            json!(BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY)
        );
        assert_eq!(plan["collections"].as_array().unwrap().len(), 6);
        assert_eq!(plan["readSummary"]["operationCount"], json!(3));
        assert_eq!(plan["readSummary"]["requiredReadCount"], json!(3));
        assert_eq!(plan["readSummary"]["collectionCount"], json!(6));
        assert_eq!(plan["readSummary"]["activeCollectionCount"], json!(2));
        assert_eq!(plan["readSummary"]["snapshotReadCount"], json!(1));
        assert_eq!(plan["readSummary"]["logListCount"], json!(2));
        assert_eq!(plan["readSummary"]["logObjectReadCount"], json!(0));
        assert_eq!(plan["readSummary"]["manifestReadCount"], json!(0));
        assert_eq!(plan["readSummary"]["deviceReadCount"], json!(0));
        assert_eq!(plan["readSummary"]["pageCursorCount"], json!(0));
        assert_eq!(
            plan["readSummary"]["summaryAction"],
            json!("readSnapshotsAndLogs")
        );
        assert_eq!(
            plan["readSummary"]["summaryReason"],
            json!("snapshotsAndLogListingsPlanned")
        );
        assert_eq!(
            plan["readSummary"]["activeCollections"],
            json!(["historyPages", "sessions"])
        );
        assert_eq!(
            plan["readSummary"]["snapshotCollections"],
            json!(["sessions"])
        );
        assert_eq!(
            plan["readSummary"]["logListCollections"],
            json!(["historyPages", "sessions"])
        );
        assert_eq!(
            plan["readSummary"]["readReasons"],
            json!([
                "listLogsForLocalCursorGapOrRecovery",
                "readSnapshotForInitialOrRecoveryState"
            ])
        );
        assert_eq!(
            plan["readSummary"]["readPaths"],
            json!(["Actro/BrowserSync/snapshots/sessions.json"])
        );
        assert_eq!(
            plan["readSummary"]["readPrefixes"],
            json!([
                "Actro/BrowserSync/logs/historyPages/",
                "Actro/BrowserSync/logs/sessions/"
            ])
        );

        let collections = plan["collections"].as_array().unwrap();
        let history_pages = collections
            .iter()
            .find(|state| state["collection"] == json!("historyPages"))
            .unwrap();
        assert_eq!(history_pages["localCursor"], json!("1"));
        assert_eq!(history_pages["remoteHighWatermarkCursor"], json!("3"));
        assert_eq!(history_pages["shouldReadSnapshot"], json!(false));
        assert_eq!(history_pages["shouldListLogs"], json!(true));
        assert_eq!(
            history_pages["logsPrefix"],
            json!("Actro/BrowserSync/logs/historyPages/")
        );

        let bookmarks = collections
            .iter()
            .find(|state| state["collection"] == json!("bookmarks"))
            .unwrap();
        assert_eq!(bookmarks["shouldReadSnapshot"], json!(false));
        assert_eq!(bookmarks["shouldListLogs"], json!(false));

        let sessions = collections
            .iter()
            .find(|state| state["collection"] == json!("sessions"))
            .unwrap();
        assert_eq!(sessions["localCursor"], json!(""));
        assert_eq!(sessions["snapshotRevision"], json!(2));
        assert_eq!(sessions["shouldReadSnapshot"], json!(true));
        assert_eq!(sessions["shouldListLogs"], json!(true));

        let operations = plan["operations"].as_array().unwrap();
        assert_eq!(operations.len(), 3);
        assert_eq!(operations[0]["operationType"], json!("listLogs"));
        assert_eq!(operations[0]["collection"], json!("historyPages"));
        assert_eq!(
            operations[0]["readReason"],
            json!("listLogsForLocalCursorGapOrRecovery")
        );
        assert_eq!(
            operations[0]["prefix"],
            json!("Actro/BrowserSync/logs/historyPages/")
        );
        assert_eq!(operations[0]["maxObjects"], json!(25));
        assert_eq!(operations[1]["operationType"], json!("readSnapshot"));
        assert_eq!(operations[1]["collection"], json!("sessions"));
        assert_eq!(
            operations[1]["readReason"],
            json!("readSnapshotForInitialOrRecoveryState")
        );
        assert_eq!(
            operations[1]["path"],
            json!("Actro/BrowserSync/snapshots/sessions.json")
        );
        assert_eq!(operations[2]["operationType"], json!("listLogs"));
        assert_eq!(operations[2]["collection"], json!("sessions"));
        assert_eq!(
            operations[2]["readReason"],
            json!("listLogsForLocalCursorGapOrRecovery")
        );
    }

