    #[test]
    fn cloud_high_watermark_plan_marks_lagging_and_cleanup_candidates() {
        let mut manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        manifest.retention.retain_log_sequences = 1;
        manifest.retention.compact_when_log_sequences_exceed = 2;
        for state in &mut manifest.collections {
            if state.collection == "historyPages" {
                state.latest_log_sequence = 5;
                state.snapshot_revision = 3;
                state.high_watermark_cursor = "5".to_string();
                state.snapshot_path = browser_storage_sync_cloud_snapshot_path("historyPages");
            } else if state.collection == "bookmarks" {
                state.latest_log_sequence = 2;
                state.high_watermark_cursor = "2".to_string();
            }
        }
        let history_logs = (1..=5)
            .map(|sequence| cloud_high_watermark_log_json("historyPages", "device-b", sequence))
            .collect::<Vec<_>>();
        let bookmark_log = cloud_high_watermark_log_json("bookmarks", "device-b", 2);
        let snapshot = cloud_high_watermark_snapshot_json("historyPages", 3);
        let logs_json = format!("[{},{}]", history_logs.join(","), bookmark_log);
        let cursors = serialize_json(&json!([
            {"collection":"historyPages","cursor":"3","lastSyncedAtUnixSeconds":70},
            {"collection":"bookmarks","cursor":"2","lastSyncedAtUnixSeconds":70}
        ]));

        let plan =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_high_watermark_plan_json(
                &serialize_json(&manifest),
                &format!("[{snapshot}]"),
                &logs_json,
                &cursors,
                "device-a",
                90,
            ))
            .unwrap();

        assert_eq!(plan["planType"], json!("cloudHighWatermarkRetention"));
        assert_eq!(
            plan["policyName"],
            json!(BROWSER_STORAGE_SYNC_CLOUD_HIGH_WATERMARK_POLICY)
        );
        assert_eq!(plan["allCurrent"], json!(false));
        assert_eq!(plan["shouldPull"], json!(true));
        assert_eq!(plan["shouldCleanup"], json!(true));
        assert_eq!(plan["shouldCompact"], json!(false));
        assert_eq!(plan["laggingCollectionCount"], json!(1));
        assert_eq!(plan["cleanupCandidateCount"], json!(2));

        let history = plan["collections"]
            .as_array()
            .unwrap()
            .iter()
            .find(|collection| collection["collection"] == json!("historyPages"))
            .unwrap();
        assert_eq!(history["localCursor"], json!("3"));
        assert_eq!(history["remoteHighWatermarkCursor"], json!("5"));
        assert_eq!(history["localCursorSequence"], json!(3));
        assert_eq!(history["remoteHighWatermarkSequence"], json!(5));
        assert_eq!(history["snapshotAvailable"], json!(true));
        assert_eq!(history["current"], json!(false));
        assert_eq!(history["lagging"], json!(true));
        assert_eq!(history["shouldListLogs"], json!(true));
        assert_eq!(history["cleanupCandidateCount"], json!(2));
        assert_eq!(history["reason"], json!("oldLogsCoveredBySnapshot"));

        let bookmarks = plan["collections"]
            .as_array()
            .unwrap()
            .iter()
            .find(|collection| collection["collection"] == json!("bookmarks"))
            .unwrap();
        assert_eq!(bookmarks["current"], json!(true));
        assert_eq!(bookmarks["lagging"], json!(false));
        assert_eq!(bookmarks["shouldPull"], json!(false));

        assert_eq!(
            plan["cleanupCandidates"][0]["operationType"],
            json!("candidateDeleteLog")
        );
        assert_eq!(
            plan["cleanupCandidates"][0]["deleteReason"],
            json!("coveredBySnapshotOutsideRetainedLogWindow")
        );
        assert_eq!(plan["cleanupCandidates"][0]["required"], json!(false));
        assert_eq!(
            plan["cleanupCandidates"][0]["path"],
            json!("Actro/BrowserSync/logs/historyPages/device-b-0000000000000001.json")
        );
        assert!(plan["resultPolicy"]
            .as_str()
            .unwrap()
            .contains("after Rust compaction/result planning has committed"));
    }

    #[test]
    fn cloud_high_watermark_plan_detects_missing_required_logs() {
        let mut manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        manifest.retention.retain_log_sequences = 1;
        manifest.retention.compact_when_log_sequences_exceed = 2;
        for state in &mut manifest.collections {
            if state.collection == "historyPages" {
                state.latest_log_sequence = 4;
                state.snapshot_revision = 1;
                state.high_watermark_cursor = "4".to_string();
            }
        }
        let log2 = cloud_high_watermark_log_json("historyPages", "device-b", 2);
        let log4 = cloud_high_watermark_log_json("historyPages", "device-b", 4);
        let snapshot = cloud_high_watermark_snapshot_json("historyPages", 1);
        let cursors = serialize_json(&json!([
            {"collection":"historyPages","cursor":"1","lastSyncedAtUnixSeconds":70}
        ]));

        let plan =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_high_watermark_plan_json(
                &serialize_json(&manifest),
                &format!("[{snapshot}]"),
                &format!("[{log2},{log4}]"),
                &cursors,
                "device-a",
                90,
            ))
            .unwrap();

        assert_eq!(plan["shouldCompact"], json!(false));
        assert_eq!(plan["missingRequiredLogCollectionCount"], json!(1));
        let history = plan["collections"]
            .as_array()
            .unwrap()
            .iter()
            .find(|collection| collection["collection"] == json!("historyPages"))
            .unwrap();
        assert_eq!(history["latestAvailableLogSequence"], json!(4));
        assert_eq!(history["contiguousLogFloorSequence"], json!(2));
        assert_eq!(history["contiguousLogThroughSequence"], json!(2));
        assert_eq!(history["missingRequiredLogs"], json!(true));
        assert_eq!(history["reason"], json!("missingRequiredLogs"));
    }

