    #[test]
    fn cloud_cleanup_result_plan_treats_missing_logs_as_success() {
        let high_watermark_plan_json = cloud_high_watermark_cleanup_plan_json();
        let high_watermark_plan = serde_json::from_str::<Value>(&high_watermark_plan_json).unwrap();
        let cleanup_candidates = high_watermark_plan["cleanupCandidates"].as_array().unwrap();
        let delete_results = serialize_json(&json!([
            {
                "operationIndex": cleanup_candidates[0]["operationIndex"],
                "operationType": cleanup_candidates[0]["operationType"],
                "path": cleanup_candidates[0]["path"],
                "success": true
            },
            {
                "operationIndex": cleanup_candidates[1]["operationIndex"],
                "operationType": cleanup_candidates[1]["operationType"],
                "path": cleanup_candidates[1]["path"],
                "success": false,
                "errorKind": "notFound",
                "retryable": false
            }
        ]));

        let plan =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cleanup_result_plan_json(
                &high_watermark_plan_json,
                &delete_results,
                100,
            ))
            .unwrap();

        assert_eq!(plan["planType"], json!("cloudCleanupResult"));
        assert_eq!(plan["cleanupRequested"], json!(true));
        assert_eq!(plan["cleanupCompleted"], json!(true));
        assert_eq!(plan["clientAction"], json!("finishCloudLogCleanup"));
        assert_eq!(plan["deleteSucceededCount"], json!(2));
        assert_eq!(plan["deleteFailedCount"], json!(0));
        assert_eq!(plan["deletedPaths"].as_array().unwrap().len(), 2);
        assert!(plan["cleanupRetryOperations"]
            .as_array()
            .unwrap()
            .is_empty());
        assert!(plan["rereadOperations"].as_array().unwrap().is_empty());
    }

    #[test]
    fn cloud_cleanup_result_plan_retries_transient_delete_failures() {
        let high_watermark_plan_json = cloud_high_watermark_cleanup_plan_json();
        let high_watermark_plan = serde_json::from_str::<Value>(&high_watermark_plan_json).unwrap();
        let cleanup_candidates = high_watermark_plan["cleanupCandidates"].as_array().unwrap();
        let delete_results = serialize_json(&json!([
            {
                "operationIndex": cleanup_candidates[0]["operationIndex"],
                "operationType": cleanup_candidates[0]["operationType"],
                "path": cleanup_candidates[0]["path"],
                "success": true
            },
            {
                "operationIndex": cleanup_candidates[1]["operationIndex"],
                "operationType": cleanup_candidates[1]["operationType"],
                "path": cleanup_candidates[1]["path"],
                "success": false,
                "errorKind": "network",
                "errorMessage": "temporary provider outage",
                "retryable": true
            }
        ]));

        let plan =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cleanup_result_plan_json(
                &high_watermark_plan_json,
                &delete_results,
                100,
            ))
            .unwrap();

        assert_eq!(plan["cleanupCompleted"], json!(false));
        assert_eq!(plan["shouldRetryCleanup"], json!(true));
        assert_eq!(plan["clientAction"], json!("retryCloudLogCleanup"));
        assert_eq!(plan["issues"][0]["reason"], json!("network"));
        assert_eq!(
            plan["issues"][0]["deleteReason"],
            json!("coveredBySnapshotOutsideRetainedLogWindow")
        );
        assert_eq!(plan["issues"][0]["action"], json!("retryCloudLogCleanup"));
        assert_eq!(
            plan["cleanupRetryOperations"][0]["path"],
            cleanup_candidates[1]["path"]
        );
        assert!(plan["rereadOperations"].as_array().unwrap().is_empty());
    }

    #[test]
    fn cloud_cleanup_result_plan_rereads_after_conflict() {
        let high_watermark_plan_json = cloud_high_watermark_cleanup_plan_json();
        let high_watermark_plan = serde_json::from_str::<Value>(&high_watermark_plan_json).unwrap();
        let cleanup_candidates = high_watermark_plan["cleanupCandidates"].as_array().unwrap();
        let delete_results = serialize_json(&json!([
            {
                "operationIndex": cleanup_candidates[0]["operationIndex"],
                "operationType": cleanup_candidates[0]["operationType"],
                "path": cleanup_candidates[0]["path"],
                "success": false,
                "errorKind": "conflict",
                "errorMessage": "stale provider revision",
                "retryable": true
            },
            {
                "operationIndex": cleanup_candidates[1]["operationIndex"],
                "operationType": cleanup_candidates[1]["operationType"],
                "path": cleanup_candidates[1]["path"],
                "success": true
            }
        ]));

        let plan =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_cleanup_result_plan_json(
                &high_watermark_plan_json,
                &delete_results,
                100,
            ))
            .unwrap();

        assert_eq!(plan["cleanupCompleted"], json!(false));
        assert_eq!(plan["shouldReread"], json!(true));
        assert_eq!(plan["shouldRetryCleanup"], json!(false));
        assert_eq!(
            plan["clientAction"],
            json!("rereadCloudRetentionStateAndRetryCleanup")
        );
        assert!(plan["cleanupRetryOperations"]
            .as_array()
            .unwrap()
            .is_empty());
        assert!(plan["rereadOperations"]
            .as_array()
            .unwrap()
            .iter()
            .any(|operation| operation["operationType"] == json!("readManifest")));
        assert!(plan["rereadOperations"]
            .as_array()
            .unwrap()
            .iter()
            .any(
                |operation| operation["operationType"] == json!("readSnapshot")
                    && operation["collection"] == json!("historyPages")
            ));
        assert!(plan["rereadOperations"]
            .as_array()
            .unwrap()
            .iter()
            .any(|operation| operation["operationType"] == json!("listLogs")
                && operation["collection"] == json!("historyPages")));
    }

