    fn cloud_high_watermark_cleanup_plan_json() -> String {
        let mut manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        manifest.retention.retain_log_sequences = 1;
        manifest.retention.compact_when_log_sequences_exceed = 2;
        for state in &mut manifest.collections {
            if state.collection == "historyPages" {
                state.latest_log_sequence = 5;
                state.snapshot_revision = 3;
                state.high_watermark_cursor = "5".to_string();
                state.snapshot_path = browser_storage_sync_cloud_snapshot_path("historyPages");
            }
        }
        let history_logs = (1..=5)
            .map(|sequence| cloud_high_watermark_log_json("historyPages", "device-b", sequence))
            .collect::<Vec<_>>();
        let snapshot = cloud_high_watermark_snapshot_json("historyPages", 3);
        let cursors = serialize_json(&json!([
            {"collection":"historyPages","cursor":"3","lastSyncedAtUnixSeconds":70}
        ]));

        browser_storage_sync_cloud_high_watermark_plan_json(
            &serialize_json(&manifest),
            &format!("[{snapshot}]"),
            &format!("[{}]", history_logs.join(",")),
            &cursors,
            "device-a",
            90,
        )
    }

    fn cloud_high_watermark_log_json(collection: &str, device_id: &str, sequence: i64) -> String {
        let batch = serialize_json(&json!({
            "version": BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
            "storageSchemaVersion": BROWSER_STORAGE_SCHEMA_VERSION,
            "scope": "profile-a",
            "deviceId": device_id,
            "generatedAtUnixSeconds": 40 + sequence,
            "records": [],
            "cursors": [
                {
                    "collection": collection,
                    "cursor": sequence.to_string(),
                    "lastSyncedAtUnixSeconds": 40 + sequence
                }
            ]
        }));
        browser_storage_sync_cloud_log_object_json(collection, sequence, &batch)
    }

    fn cloud_high_watermark_snapshot_json(collection: &str, cursor: i64) -> String {
        let batch = serialize_json(&json!({
            "version": BROWSER_STORAGE_SYNC_CONTRACT_VERSION,
            "storageSchemaVersion": BROWSER_STORAGE_SCHEMA_VERSION,
            "scope": "profile-a",
            "deviceId": "device-b",
            "generatedAtUnixSeconds": 80,
            "records": [],
            "cursors": [
                {
                    "collection": collection,
                    "cursor": cursor.to_string(),
                    "lastSyncedAtUnixSeconds": 80
                }
            ]
        }));
        browser_storage_sync_cloud_snapshot_object_json(collection, 80, &batch)
    }

    #[test]
    fn cloud_compaction_plan_writes_snapshot_manifest_and_deletes_old_logs() {
        let mut manifest = browser_storage_sync_cloud_default_manifest("profile-a", "device-a", 10);
        manifest.retention.retain_log_sequences = 1;
        manifest.retention.compact_when_log_sequences_exceed = 2;
        for state in &mut manifest.collections {
            if state.collection == "historyPages" {
                state.latest_log_sequence = 3;
                state.latest_log_path = Some(
                    "Actro/BrowserSync/logs/historyPages/device-b-0000000000000003.json"
                        .to_string(),
                );
                state.high_watermark_cursor = "3".to_string();
            }
        }
        let log_batch = |sequence: i64| {
            format!(
                r#"{{
                    "version": 1,
                    "storageSchemaVersion": 6,
                    "scope": "profile-a",
                    "deviceId": "device-b",
                    "generatedAtUnixSeconds": {},
                    "records": [
                        {{
                            "recordId": "https://example.com",
                            "syncRevision": {},
                            "syncState": "synced",
                            "originDeviceId": "device-b",
                            "updatedAtUnixSeconds": {},
                            "recordType": "historyPage",
                            "payload": {{
                                "address": "https://example.com",
                                "title": "Example {}",
                                "visitCount": {},
                                "lastVisitedAtUnixSeconds": {},
                                "createdAtUnixSeconds": 10,
                                "updatedAtUnixSeconds": {}
                            }}
                        }}
                    ],
                    "cursors": [
                        {{"collection":"historyPages","cursor":"{}","lastSyncedAtUnixSeconds":{}}}
                    ]
                }}"#,
                40 + sequence,
                sequence,
                40 + sequence,
                sequence,
                sequence,
                40 + sequence,
                40 + sequence,
                sequence,
                40 + sequence
            )
        };
        let log1 = browser_storage_sync_cloud_log_object_json("historyPages", 1, &log_batch(1));
        let log2 = browser_storage_sync_cloud_log_object_json("historyPages", 2, &log_batch(2));
        let log3 = browser_storage_sync_cloud_log_object_json("historyPages", 3, &log_batch(3));

        let plan = serde_json::from_str::<Value>(&browser_storage_sync_cloud_compaction_plan_json(
            &serialize_json(&manifest),
            "manifest-etag",
            "[]",
            &format!("[{log1},{log2},{log3}]"),
            "device-a",
            90,
        ))
        .unwrap();

        assert_eq!(plan["planType"], json!("snapshotCompaction"));
        assert_eq!(plan["shouldCompact"], json!(true));
        assert_eq!(plan["operationCount"], json!(2));
        assert_eq!(plan["deleteOperationCount"], json!(2));
        assert_eq!(
            plan["conflictPolicy"],
            json!(BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY)
        );
        assert_eq!(
            plan["operations"][0]["operationType"],
            json!("writeSnapshot")
        );
        assert_eq!(
            plan["operations"][0]["writeReason"],
            json!("writeCompactedSnapshot")
        );
        assert_eq!(plan["operations"][0]["collection"], json!("historyPages"));
        assert_eq!(
            plan["operations"][0]["path"],
            json!("Actro/BrowserSync/snapshots/historyPages.json")
        );
        assert_eq!(
            plan["operations"][1]["operationType"],
            json!("writeManifest")
        );
        assert_eq!(
            plan["operations"][1]["writeReason"],
            json!("commitCloudManifestState")
        );
        assert_eq!(
            plan["operations"][1]["expectedRevision"],
            json!("manifest-etag")
        );
        assert_eq!(
            plan["deleteOperations"][0]["path"],
            json!("Actro/BrowserSync/logs/historyPages/device-b-0000000000000001.json")
        );
        assert_eq!(
            plan["deleteOperations"][0]["deleteReason"],
            json!("compactedIntoSnapshotOutsideRetainedLogWindow")
        );
        assert_eq!(
            plan["deleteOperations"][1]["path"],
            json!("Actro/BrowserSync/logs/historyPages/device-b-0000000000000002.json")
        );
        assert_eq!(
            plan["compactedCollections"][0]["nextSnapshotRevision"],
            json!(3)
        );
        assert_eq!(
            plan["compactedCollections"][0]["retainedLogCount"],
            json!(1)
        );
        assert_eq!(plan["compactedCollections"][0]["deletedLogCount"], json!(2));

        let snapshot =
            serde_json::from_str::<Value>(plan["operations"][0]["bodyJson"].as_str().unwrap())
                .unwrap();
        assert_eq!(snapshot["records"].as_array().unwrap().len(), 1);
        assert_eq!(
            snapshot["records"][0]["payload"]["title"],
            json!("Example 3")
        );
        assert_eq!(snapshot["highWatermarks"][0]["cursor"], json!("3"));

        let next_manifest =
            serde_json::from_str::<Value>(plan["nextManifestJson"].as_str().unwrap()).unwrap();
        let history_state = next_manifest["collections"]
            .as_array()
            .unwrap()
            .iter()
            .find(|state| state["collection"] == json!("historyPages"))
            .unwrap();
        assert_eq!(history_state["snapshotRevision"], json!(3));
        assert_eq!(history_state["highWatermarkCursor"], json!("3"));
    }

