    #[test]
    fn cloud_compaction_result_plan_retries_cleanup_after_manifest_commit() {
        let compaction_plan = cloud_compaction_plan_fixture();
        let plan_value = serde_json::from_str::<Value>(&compaction_plan).unwrap();
        let write_results = plan_value["operations"]
            .as_array()
            .unwrap()
            .iter()
            .map(|operation| {
                json!({
                    "operationIndex": operation["operationIndex"],
                    "operationType": operation["operationType"],
                    "path": operation["path"],
                    "success": true,
                    "providerRevision": format!("{}-written", operation["operationIndex"]),
                })
            })
            .collect::<Vec<_>>();
        let delete_operations = plan_value["deleteOperations"].as_array().unwrap();
        let delete_results = json!([
            {
                "operationIndex": delete_operations[0]["operationIndex"],
                "operationType": delete_operations[0]["operationType"],
                "path": delete_operations[0]["path"],
                "success": true,
                "providerRevision": "deleted-1"
            },
            {
                "operationIndex": delete_operations[1]["operationIndex"],
                "operationType": delete_operations[1]["operationType"],
                "path": delete_operations[1]["path"],
                "success": false,
                "errorKind": "network",
                "errorMessage": "temporary provider outage",
                "retryable": true
            }
        ]);

        let result =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_compaction_result_plan_json(
                &compaction_plan,
                &serialize_json(&write_results),
                &serialize_json(&delete_results),
                100,
            ))
            .unwrap();

        assert_eq!(result["planType"], json!("snapshotCompactionResult"));
        assert_eq!(result["completed"], json!(true));
        assert_eq!(result["manifestCommitted"], json!(true));
        assert_eq!(result["cleanupCompleted"], json!(false));
        assert_eq!(result["shouldReread"], json!(false));
        assert_eq!(result["shouldRetryCleanup"], json!(true));
        assert_eq!(result["clientAction"], json!("retryCloudLogCleanup"));
        assert_eq!(result["succeededCount"], json!(2));
        assert_eq!(result["failedCount"], json!(0));
        assert_eq!(result["deleteSucceededCount"], json!(1));
        assert_eq!(result["deleteFailedCount"], json!(1));
        assert_eq!(result["manifestRevision"], json!("1-written"));
        assert_eq!(result["issues"][0]["operationType"], json!("deleteLog"));
        assert_eq!(result["issues"][0]["reason"], json!("network"));
        assert_eq!(
            result["issues"][0]["deleteReason"],
            json!("compactedIntoSnapshotOutsideRetainedLogWindow")
        );
        assert!(result["issues"][0].get("writeReason").is_none());
        assert_eq!(result["issues"][0]["action"], json!("retryCloudLogCleanup"));
        assert_eq!(
            result["cleanupRetryOperations"][0]["path"],
            delete_operations[1]["path"]
        );
        assert!(result["rereadOperations"].as_array().unwrap().is_empty());
    }

    #[test]
    fn cloud_compaction_result_plan_rereads_after_manifest_conflict() {
        let compaction_plan = cloud_compaction_plan_fixture();
        let plan_value = serde_json::from_str::<Value>(&compaction_plan).unwrap();
        let operations = plan_value["operations"].as_array().unwrap();
        let write_results = json!([
            {
                "operationIndex": operations[0]["operationIndex"],
                "operationType": operations[0]["operationType"],
                "path": operations[0]["path"],
                "success": true,
                "providerRevision": "snapshot-written"
            },
            {
                "operationIndex": operations[1]["operationIndex"],
                "operationType": operations[1]["operationType"],
                "path": operations[1]["path"],
                "success": false,
                "errorKind": "conflict",
                "errorMessage": "manifest changed",
                "retryable": true
            }
        ]);

        let result =
            serde_json::from_str::<Value>(&browser_storage_sync_cloud_compaction_result_plan_json(
                &compaction_plan,
                &serialize_json(&write_results),
                "[]",
                100,
            ))
            .unwrap();

        assert_eq!(result["completed"], json!(false));
        assert_eq!(result["manifestCommitted"], json!(false));
        assert_eq!(result["cleanupCompleted"], json!(false));
        assert_eq!(result["shouldReread"], json!(true));
        assert_eq!(result["shouldRetry"], json!(true));
        assert_eq!(
            result["clientAction"],
            json!(BROWSER_STORAGE_SYNC_CLOUD_CONFLICT_ACTION_REREAD_MERGE_RETRY)
        );
        assert_eq!(result["conflictCount"], json!(1));
        assert_eq!(result["issues"][0]["operationType"], json!("writeManifest"));
        assert_eq!(result["issues"][0]["reason"], json!("conflict"));
        assert_eq!(
            result["issues"][0]["writeReason"],
            json!("commitCloudManifestState")
        );
        assert!(result["issues"][0].get("deleteReason").is_none());
        assert!(result["cleanupRetryOperations"]
            .as_array()
            .unwrap()
            .is_empty());

        let reread_operations = result["rereadOperations"].as_array().unwrap();
        assert_eq!(reread_operations[0]["operationType"], json!("readManifest"));
        assert!(reread_operations.iter().any(|operation| {
            operation["operationType"] == json!("readSnapshot")
                && operation["collection"] == json!("historyPages")
        }));
        assert!(reread_operations.iter().any(|operation| {
            operation["operationType"] == json!("listLogs")
                && operation["collection"] == json!("historyPages")
        }));
    }

