    #[test]
    fn rejects_unsupported_browser_storage_schema_versions_json() {
        let unsupported_batch = r#"{
            "version": 1,
            "storageSchemaVersion": 5,
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 1,
            "records": [],
            "cursors": []
        }"#;
        assert_eq!(
            normalize_browser_storage_sync_batch_json(unsupported_batch),
            "null"
        );
        assert_eq!(
            browser_storage_sync_push_request_json(unsupported_batch),
            "null"
        );
        assert_eq!(
            browser_storage_sync_remote_apply_plan_json(unsupported_batch),
            "null"
        );

        let unsupported_ack = r#"{
            "version": 1,
            "storageSchemaVersion": 5,
            "scope": "profile-a",
            "deviceId": "device-a",
            "syncedAtUnixSeconds": 2,
            "records": [],
            "cursors": []
        }"#;
        assert_eq!(
            normalize_browser_storage_sync_ack_batch_json(unsupported_ack),
            "null"
        );
        assert_eq!(browser_storage_sync_ack_plan_json(unsupported_ack), "null");

        let current_batch = r#"{
            "version": 1,
            "storageSchemaVersion": 6,
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 3,
            "records": [],
            "cursors": []
        }"#;
        let current_ack = r#"{
            "version": 1,
            "storageSchemaVersion": 6,
            "scope": "profile-a",
            "deviceId": "device-a",
            "syncedAtUnixSeconds": 4,
            "records": [],
            "cursors": []
        }"#;
        let response = browser_storage_sync_cycle_response_json(current_batch, current_ack);
        assert_ne!(response, "null");
        let unsupported_response = response.replacen(
            r#""storageSchemaVersion":6"#,
            r#""storageSchemaVersion":5"#,
            1,
        );
        assert_eq!(
            normalize_browser_storage_sync_cycle_response_json(&unsupported_response),
            "null"
        );
        assert_eq!(
            browser_storage_sync_client_cycle_plan_json(&unsupported_response),
            "null"
        );

        let apply_plan = browser_storage_sync_remote_apply_plan_json(current_batch);
        assert_ne!(apply_plan, "null");
        let apply_result = r#"{
            "version": 1,
            "storageSchemaVersion": 6,
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 5,
            "results": [],
            "cursors": []
        }"#;
        assert_ne!(
            browser_storage_sync_remote_apply_result_json(&apply_plan, apply_result),
            "null"
        );
        let unsupported_apply_plan = apply_plan.replacen(
            r#""storageSchemaVersion":6"#,
            r#""storageSchemaVersion":5"#,
            1,
        );
        let unsupported_apply_result = apply_result.replace(
            r#""storageSchemaVersion": 6"#,
            r#""storageSchemaVersion": 5"#,
        );
        assert_eq!(
            browser_storage_sync_remote_apply_result_json(&unsupported_apply_plan, apply_result),
            "null"
        );
        assert_eq!(
            browser_storage_sync_remote_apply_result_json(&apply_plan, &unsupported_apply_result),
            "null"
        );

        let push_request = browser_storage_sync_push_request_json(current_batch);
        let merge_plan = browser_storage_sync_server_merge_plan_json(&push_request);
        assert_ne!(merge_plan, "null");
        let merge_result = r#"{
            "version": 1,
            "storageSchemaVersion": 6,
            "scope": "profile-a",
            "deviceId": "device-a",
            "generatedAtUnixSeconds": 6,
            "results": [],
            "cursors": []
        }"#;
        let unsupported_merge_plan = merge_plan.replacen(
            r#""storageSchemaVersion":6"#,
            r#""storageSchemaVersion":5"#,
            1,
        );
        let unsupported_merge_result = merge_result.replace(
            r#""storageSchemaVersion": 6"#,
            r#""storageSchemaVersion": 5"#,
        );
        assert_eq!(
            browser_storage_sync_server_merge_result_json(&unsupported_merge_plan, merge_result),
            "null"
        );
        assert_eq!(
            browser_storage_sync_server_merge_result_json(&merge_plan, &unsupported_merge_result),
            "null"
        );
    }

